import { Badge } from "~/components/ui/badge";
import { Checkbox } from "~/components/ui/checkbox";
import { Label } from "~/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "~/components/ui/select";

interface HashTagPreset {
  id: string;
  name: string;
  tags: string;
  description?: string | null;
}

interface QueueType {
  id: string;
  name: string;
  hashTagPreset?: HashTagPreset | null;
}

interface HashtagPresetToggleProps {
  presets: HashTagPreset[];
  selectedPresetId?: string | null;
  onSelect: (presetId: string | null, hashtags: string) => void;
  disabled?: boolean;
  showQueuePreset?: boolean;
  queueType?: QueueType | null;
  useHashtagPresets?: boolean;
  onUseHashtagPresetsChange?: (enabled: boolean) => void;
}

export function HashtagPresetToggle({
  presets,
  selectedPresetId,
  onSelect,
  disabled = false,
  showQueuePreset = false,
  queueType = null,
  useHashtagPresets = false,
  onUseHashtagPresetsChange,
}: HashtagPresetToggleProps) {
  const selectedPreset = presets.find((p) => p.id === selectedPresetId);

  const handlePresetChange = (value: string) => {
    if (value === "none") {
      onSelect(null, "");
    } else {
      const preset = presets.find((p) => p.id === value);
      onSelect(preset?.id ?? null, preset?.tags ?? "");
    }
  };

  const countHashtags = (tags: string): number => {
    return tags
      .split(/\s+/)
      .filter((tag) => tag.startsWith("#") && tag.length > 1).length;
  };

  return (
    <div className="space-y-4">
      {/* Toggle checkbox for hashtag presets */}
      <div className="flex items-center space-x-2">
        <Checkbox
          id="use-hashtag-presets"
          checked={useHashtagPresets}
          onCheckedChange={(checked) => onUseHashtagPresetsChange?.(!!checked)}
          disabled={disabled}
        />
        <Label
          htmlFor="use-hashtag-presets"
          className="cursor-pointer text-sm font-medium text-gray-700 dark:text-gray-300"
        >
          Use Hashtag Presets
        </Label>
      </div>

      {/* Show queue type's hashtag preset info when available */}
      {showQueuePreset && queueType?.hashTagPreset ? (
        <div
          className={`rounded-lg p-3 ${
            useHashtagPresets
              ? "border border-gray-200 bg-gray-50 dark:border-gray-700 dark:bg-gray-800"
              : "border border-green-200 bg-green-50 dark:border-green-800 dark:bg-green-900/20"
          }`}
        >
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <span className="text-sm font-medium text-gray-700 dark:text-gray-300">
                {useHashtagPresets ? "Queue Default:" : "Using Queue Default:"}
              </span>
              <Badge variant="secondary" className="text-xs">
                {queueType.hashTagPreset.name}
              </Badge>
              <span className="text-xs text-gray-500 dark:text-gray-400">
                ({countHashtags(queueType.hashTagPreset.tags)} tags)
              </span>
            </div>
          </div>
          {!useHashtagPresets ? (
            <div className="mt-2 flex flex-wrap gap-1">
              {queueType.hashTagPreset.tags
                .split(/\s+/)
                .filter((tag) => tag.startsWith("#") && tag.length > 1)
                .slice(0, 4)
                .map((tag, index) => (
                  <Badge
                    key={index}
                    variant="outline"
                    className="px-2 py-0.5 text-xs"
                  >
                    {tag}
                  </Badge>
                ))}
              {countHashtags(queueType.hashTagPreset.tags) > 4 ? (
                <Badge variant="outline" className="px-2 py-0.5 text-xs">
                  +{countHashtags(queueType.hashTagPreset.tags) - 4} more
                </Badge>
              ) : null}
            </div>
          ) : null}
        </div>
      ) : null}

      {/* Hashtag preset selector */}
      {useHashtagPresets ? (
        <div className="space-y-3">
          {presets.length === 0 ? (
            <div className="rounded-lg border border-yellow-200 bg-yellow-50 p-3 dark:border-yellow-800 dark:bg-yellow-900/20">
              <p className="text-sm text-yellow-700 dark:text-yellow-300">
                No hashtag presets available. Create some in Settings to reuse
                hashtags across your posts.
              </p>
            </div>
          ) : (
            <>
              <div className="space-y-2">
                <Label className="text-sm font-medium text-gray-700 dark:text-gray-300">
                  Choose Hashtag Preset
                </Label>
                <Select
                  value={selectedPresetId || "none"}
                  onValueChange={handlePresetChange}
                  disabled={disabled}
                >
                  <SelectTrigger className="w-full">
                    <SelectValue placeholder="Select a hashtag preset" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="none">
                      <span className="text-gray-500">No hashtag preset</span>
                    </SelectItem>
                    {presets.map((preset) => (
                      <SelectItem key={preset.id} value={preset.id}>
                        <div className="flex w-full items-center justify-between">
                          <span className="font-medium">{preset.name}</span>
                          <Badge variant="secondary" className="ml-2 text-xs">
                            {countHashtags(preset.tags)}
                          </Badge>
                        </div>
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              {/* Selected preset preview */}
              {selectedPreset ? (
                <div className="rounded-lg border border-gray-200 bg-gray-50 p-3 dark:border-gray-700 dark:bg-gray-800">
                  <div className="mb-2 flex items-center gap-2">
                    <span className="text-sm font-medium text-gray-700 dark:text-gray-300">
                      {selectedPreset.name}
                    </span>
                    <Badge variant="secondary" className="text-xs">
                      {countHashtags(selectedPreset.tags)} tags
                    </Badge>
                  </div>
                  {selectedPreset.description ? (
                    <p className="mb-2 text-xs text-gray-500 dark:text-gray-400">
                      {selectedPreset.description}
                    </p>
                  ) : null}
                  <div className="flex flex-wrap gap-1">
                    {selectedPreset.tags
                      .split(/\s+/)
                      .filter((tag) => tag.startsWith("#") && tag.length > 1)
                      .slice(0, 6)
                      .map((tag, index) => (
                        <Badge
                          key={index}
                          variant="outline"
                          className="px-2 py-0.5 text-xs"
                        >
                          {tag}
                        </Badge>
                      ))}
                    {countHashtags(selectedPreset.tags) > 6 ? (
                      <Badge variant="outline" className="px-2 py-0.5 text-xs">
                        +{countHashtags(selectedPreset.tags) - 6} more
                      </Badge>
                    ) : null}
                  </div>
                </div>
              ) : null}
            </>
          )}
        </div>
      ) : null}
    </div>
  );
}

import { useFetcher } from "@remix-run/react";
import { useState } from "react";

import { Button } from "~/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "~/components/ui/card";
import { Label } from "~/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "~/components/ui/select";
import { timeZonesList } from "~/lib/date";

interface TimezoneSettingsProps {
  timezone: string | null;
}

interface FetcherData {
  success?: boolean;
  error?: string;
}

export function TimezoneSettings({ timezone }: TimezoneSettingsProps) {
  const fetcher = useFetcher<FetcherData>();
  const [selectedTimezone, setSelectedTimezone] = useState(
    timezone || "Etc/UTC",
  );

  const isSubmitting = fetcher.state === "submitting";
  const hasChanged = selectedTimezone !== timezone;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const formData = new FormData();
    formData.set("_action", "update_timezone");
    formData.set("timezone", selectedTimezone);
    fetcher.submit(formData, { method: "post" });
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle>Timezone</CardTitle>
        <CardDescription>
          Set your timezone for scheduling posts
        </CardDescription>
      </CardHeader>
      <CardContent>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="timezone">Select Timezone</Label>
            <Select
              value={selectedTimezone}
              onValueChange={setSelectedTimezone}
              disabled={isSubmitting}
            >
              <SelectTrigger id="timezone">
                <SelectValue placeholder="Select a timezone" />
              </SelectTrigger>
              <SelectContent>
                {timeZonesList.map((tz) => (
                  <SelectItem key={tz} value={tz}>
                    {tz}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <Button
            type="submit"
            disabled={isSubmitting || !hasChanged}
            className="w-full"
          >
            {isSubmitting ? "Saving..." : "Save Timezone"}
          </Button>

          {fetcher.data?.success ? (
            <p className="text-sm text-green-600">
              Timezone updated successfully!
            </p>
          ) : null}
          {fetcher.data?.error ? (
            <p className="text-sm text-destructive">{fetcher.data.error}</p>
          ) : null}
        </form>
      </CardContent>
    </Card>
  );
}

import { useState } from "react";

import { Button } from "~/components/ui/button";
import { Input } from "~/components/ui/input";
import type { Asset } from "~/features/assets/types";
interface AssetBrowserProps {
  assets: Asset[];
  onAssetsSelected: (selectedAssets: Asset[]) => void;
  onClose: () => void;
}

export default function AssetBrowser({
  assets,
  onAssetsSelected,
  onClose,
}: AssetBrowserProps) {
  const [selectedAssets, setSelectedAssets] = useState<string[]>([]);
  const [searchTerm, setSearchTerm] = useState("");

  const filteredAssets = assets.filter((asset) => {
    const searchLower = searchTerm.toLowerCase();
    return (
      asset.title?.toLowerCase().includes(searchLower) ||
      asset.content?.toLowerCase().includes(searchLower) ||
      asset.tags?.some((tag) => tag.toLowerCase().includes(searchLower))
    );
  });

  const handleAssetSelect = (assetId: string) => {
    setSelectedAssets((prev) =>
      prev.includes(assetId)
        ? prev.filter((id) => id !== assetId)
        : [...prev, assetId],
    );
  };

  const handleSelectAll = () => {
    if (selectedAssets.length === filteredAssets.length) {
      setSelectedAssets([]);
    } else {
      setSelectedAssets(filteredAssets.map((asset) => asset.id));
    }
  };

  const handleConfirmSelection = () => {
    const selectedAssetObjects = assets.filter((asset) =>
      selectedAssets.includes(asset.id),
    );
    onAssetsSelected(selectedAssetObjects);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50">
      <div className="max-h-[90vh] w-full max-w-6xl overflow-hidden rounded-lg bg-white dark:bg-gray-800">
        <div className="border-b border-gray-200 p-6 dark:border-gray-700">
          <div className="flex items-center justify-between">
            <h2 className="text-xl font-semibold text-gray-900 dark:text-white">
              Select Assets
            </h2>
            <button
              onClick={onClose}
              className="text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200"
            >
              ×
            </button>
          </div>

          <div className="mt-4 flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
            <div className="relative max-w-md flex-1">
              <div className="pointer-events-none absolute inset-y-0 left-0 flex items-center pl-3">
                <svg
                  className="h-5 w-5 text-gray-400"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"
                  />
                </svg>
              </div>
              <Input
                type="text"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-10"
                placeholder="Search assets by title, content, or tags..."
              />
            </div>

            <div className="flex items-center gap-2">
              {filteredAssets.length > 0 ? (
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={handleSelectAll}
                >
                  {selectedAssets.length === filteredAssets.length
                    ? "Deselect All"
                    : "Select All"}
                </Button>
              ) : null}

              {selectedAssets.length > 0 ? (
                <Button
                  type="button"
                  onClick={handleConfirmSelection}
                  className="bg-blue-600 text-white hover:bg-blue-700"
                >
                  Add Selected ({selectedAssets.length})
                </Button>
              ) : null}
            </div>
          </div>
        </div>

        <div className="max-h-96 overflow-y-auto p-6">
          {filteredAssets.length === 0 ? (
            <div className="py-12 text-center">
              <div className="mx-auto max-w-md">
                <svg
                  className="mx-auto h-12 w-12 text-gray-400"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10"
                  />
                </svg>
                <h3 className="mt-4 text-lg font-medium text-gray-900 dark:text-gray-100">
                  {searchTerm
                    ? "No matching assets found"
                    : "No assets available"}
                </h3>
                <p className="mt-2 text-sm text-gray-500 dark:text-gray-400">
                  {searchTerm
                    ? "Try adjusting your search terms"
                    : "Create assets in the Templates section first"}
                </p>
              </div>
            </div>
          ) : (
            <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
              {filteredAssets.map((asset) => {
                const handleKeyDown = (e: React.KeyboardEvent) => {
                  if (e.key === "Enter" || e.key === " ") {
                    e.preventDefault();
                    handleAssetSelect(asset.id);
                  }
                };

                return (
                  <div
                    key={asset.id}
                    className={`cursor-pointer rounded-lg border p-4 transition-all hover:shadow-md ${
                      selectedAssets.includes(asset.id)
                        ? "border-blue-500 bg-blue-50 dark:bg-blue-900/20"
                        : "border-gray-200 bg-white dark:border-gray-700 dark:bg-gray-800"
                    }`}
                    onClick={() => handleAssetSelect(asset.id)}
                    onKeyDown={handleKeyDown}
                    role="button"
                    tabIndex={0}
                  >
                  <div className="flex items-start gap-3">
                    <input
                      type="checkbox"
                      checked={selectedAssets.includes(asset.id)}
                      onChange={() => handleAssetSelect(asset.id)}
                      className="mt-1 h-4 w-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                    />

                    <div className="min-w-0 flex-1">
                      <div className="mb-2 flex items-center gap-2">
                        {asset.assetType === "IMAGE" ? (
                          <img
                            src={asset.fileUrl ?? undefined}
                            alt={asset.title || "Asset"}
                            className="h-8 w-8 flex-shrink-0 rounded object-cover"
                          />
                        ) : (
                          <div className="flex h-8 w-8 flex-shrink-0 items-center justify-center rounded bg-gray-200 text-xs font-medium text-gray-600 dark:bg-gray-700 dark:text-gray-300">
                            T
                          </div>
                        )}

                        <span
                          className={`inline-flex items-center rounded-full px-2 py-1 text-xs font-medium ${
                            asset.assetType === "IMAGE"
                              ? "bg-purple-100 text-purple-800 dark:bg-purple-900 dark:text-purple-200"
                              : "bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200"
                          }`}
                        >
                          {asset.assetType}
                        </span>
                      </div>

                      <h3 className="truncate font-medium text-gray-900 dark:text-gray-100">
                        {asset.title || "Untitled"}
                      </h3>

                      {asset.assetType === "TEXT" && asset.content ? (
                        <p className="mt-1 line-clamp-2 text-sm text-gray-600 dark:text-gray-400">
                          {asset.content}
                        </p>
                      ) : null}

                      {asset.tags && asset.tags.length > 0 ? (
                        <div className="mt-2 flex flex-wrap gap-1">
                          {asset.tags.slice(0, 2).map((tag, index) => (
                            <span
                              key={index}
                              className="inline-flex items-center rounded-full bg-gray-100 px-2 py-1 text-xs font-medium text-gray-800 dark:bg-gray-700 dark:text-gray-200"
                            >
                              {tag}
                            </span>
                          ))}
                          {asset.tags.length > 2 ? (
                            <span className="inline-flex items-center rounded-full bg-gray-100 px-2 py-1 text-xs font-medium text-gray-800 dark:bg-gray-700 dark:text-gray-200">
                              +{asset.tags.length - 2}
                            </span>
                          ) : null}
                        </div>
                      ) : null}
                    </div>
                  </div>
                </div>
                );
              })}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

import MediaThumbnail from "~/components/ui/MediaThumbnail";
import { formatDate } from "~/lib/helpers";
interface Asset {
    id: string;
    assetType: string;
    fileUrl?: string;
    content?: string | null;
    title?: string | null;
    tags?: string[];
    createdAt: string | Date;
}

interface AssetsTabProps {
    assets: Asset[];
    selectedAssets: string[];
    searchInput: string;
    onSearchInputChange: (value: string) => void;
    onSearch: (e: React.FormEvent) => void;
    onAssetSelect: (assetId: string) => void;
    onSelectAllAssets: () => void;
    onBulkPostAssets: () => void;
    onBulkDeleteAssets: () => void;
    deleteFetcherState: "idle" | "submitting" | "loading";
    deleteFetcherForm: React.ComponentType<{
        children: React.ReactNode;
        method: string;
        className?: string;
    }>;
    onDeleteAsset: (e: React.MouseEvent<HTMLButtonElement>, assetId: string) => void;
}

export function AssetsTab({
    assets,
    selectedAssets,
    searchInput,
    onSearchInputChange,
    onSearch,
    onAssetSelect,
    onSelectAllAssets,
    onBulkPostAssets,
    onBulkDeleteAssets,
    deleteFetcherState,
    deleteFetcherForm: DeleteFetcherForm,
    onDeleteAsset,
}: AssetsTabProps) {
    return (
        <div>
            {/* Search and Controls */}
            <div className="mb-6 flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
                <form onSubmit={onSearch} className="flex max-w-md flex-1">
                    <div className="relative flex-1">
                        <div className="pointer-events-none absolute inset-y-0 left-0 flex items-center pl-3">
                            <svg
                                className="h-5 w-5 text-gray-400"
                                fill="none"
                                viewBox="0 0 24 24"
                                stroke="currentColor"
                            >
                                <path
                                    strokeLinecap="round"
                                    strokeLinejoin="round"
                                    strokeWidth={2}
                                    d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"
                                />
                            </svg>
                        </div>
                        <input
                            type="text"
                            value={searchInput}
                            onChange={(e) => onSearchInputChange(e.target.value)}
                            className="block w-full rounded-lg border border-gray-300 py-2 pl-10 pr-3 text-sm leading-6 placeholder-gray-400 focus:border-blue-500 focus:ring focus:ring-blue-500/50 dark:border-gray-700 dark:bg-gray-900 dark:focus:border-blue-500"
                            placeholder="Search assets by title, content, or tags..."
                        />
                    </div>
                    <button
                        type="submit"
                        className="ml-2 rounded-lg bg-blue-600 px-4 py-2 text-white hover:bg-blue-700"
                    >
                        Search
                    </button>
                </form>

                <div className="flex items-center gap-4">
                    {selectedAssets.length > 0 ? (
                        <button
                            onClick={onBulkPostAssets}
                            className="rounded-lg bg-green-600 px-4 py-2 text-white hover:bg-green-700"
                        >
                            Post Selected ({selectedAssets.length})
                        </button>
                    ) : null}
                    {selectedAssets.length > 0 ? (
                        <button
                            onClick={onBulkDeleteAssets}
                            disabled={deleteFetcherState !== "idle"}
                            className="rounded-lg bg-red-600 px-4 py-2 text-white hover:bg-red-700 disabled:cursor-not-allowed disabled:opacity-50"
                        >
                            {deleteFetcherState !== "idle"
                                ? "Deleting..."
                                : `Delete Selected (${selectedAssets.length})`}
                        </button>
                    ) : null}
                    {assets.length > 0 ? (
                        <button
                            onClick={onSelectAllAssets}
                            className="rounded-lg border border-gray-300 px-4 py-2 text-gray-700 hover:bg-gray-50 dark:border-gray-600 dark:text-gray-300 dark:hover:bg-gray-700"
                        >
                            {selectedAssets.length === assets.length
                                ? "Deselect All"
                                : "Select All"}
                        </button>
                    ) : null}
                </div>
            </div>

            {/* Assets List */}
            {assets.length === 0 ? (
                <div className="py-12 text-center">
                    <div className="mx-auto max-w-md">
                        <svg
                            className="mx-auto h-12 w-12 text-gray-400"
                            fill="none"
                            viewBox="0 0 24 24"
                            stroke="currentColor"
                        >
                            <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth={2}
                                d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10"
                            />
                        </svg>
                        <h3 className="mt-4 text-lg font-medium text-gray-900 dark:text-gray-100">
                            No assets yet
                        </h3>
                        <p className="mt-2 text-sm text-gray-500 dark:text-gray-400">
                            Create your first asset by adding text or uploading an
                            image
                        </p>
                    </div>
                </div>
            ) : (
                <div className="min-w-full overflow-x-auto rounded border border-gray-200 bg-white dark:border-gray-700 dark:bg-gray-800">
                    <table className="min-w-full whitespace-nowrap align-middle text-sm">
                        <thead>
                            <tr>
                                <th className="bg-gray-100/75 px-3 py-4 text-center font-semibold text-gray-900 dark:bg-gray-700/25 dark:text-gray-50">
                                    <input
                                        type="checkbox"
                                        checked={
                                            assets.length > 0
                                                ? selectedAssets.length === assets.length
                                                : false
                                        }
                                        onChange={onSelectAllAssets}
                                        className="h-4 w-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500 dark:border-gray-600 dark:bg-gray-700"
                                    />
                                </th>
                                <th className="bg-gray-100/75 px-3 py-4 text-left font-semibold text-gray-900 dark:bg-gray-700/25 dark:text-gray-50">
                                    Media
                                </th>
                                <th className="bg-gray-100/75 px-3 py-4 text-left font-semibold text-gray-900 dark:bg-gray-700/25 dark:text-gray-50">
                                    Title
                                </th>
                                <th className="bg-gray-100/75 px-3 py-4 text-left font-semibold text-gray-900 dark:bg-gray-700/25 dark:text-gray-50">
                                    Content
                                </th>
                                <th className="bg-gray-100/75 px-3 py-4 text-left font-semibold text-gray-900 dark:bg-gray-700/25 dark:text-gray-50">
                                    Tags
                                </th>
