import { useState, useCallback } from "react";
interface Asset {
    id: string;
    assetType: string;
    fileUrl?: string;
    content?: string;
    title?: string;
    tags?: string[];
}

interface UseAssetManagementOptions {
    assets: Asset[];
    onBulkDelete: (assetIds: string[]) => void;
    deleteFetcherState: "idle" | "submitting" | "loading";
}

export function useAssetManagement({
    assets,
    onBulkDelete,
    deleteFetcherState: _deleteFetcherState,
}: UseAssetManagementOptions) {
    const [selectedAssets, setSelectedAssets] = useState<string[]>([]);
    const [searchInput, setSearchInput] = useState("");

    const handleAssetSelect = useCallback((assetId: string) => {
        setSelectedAssets((prev) =>
            prev.includes(assetId)
                ? prev.filter((id) => id !== assetId)
                : [...prev, assetId],
        );
    }, []);

    const handleSelectAllAssets = useCallback(() => {
        if (selectedAssets.length === assets.length) {
            setSelectedAssets([]);
        } else {
            setSelectedAssets(assets.map((asset) => asset.id));
        }
    }, [assets, selectedAssets.length]);

    const handleBulkPostAssets = useCallback(() => {
        if (selectedAssets.length === 0) return;

        const selectedAssetData = assets.filter((asset) =>
            selectedAssets.includes(asset.id),
        );

        // Convert assets to repost format
        const assetData = selectedAssetData.map((asset) => ({
            caption: asset.assetType === "TEXT" ? asset.content : asset.title || "",
            fileUrl:
                asset.assetType === "IMAGE" || asset.assetType === "VIDEO"
                    ? asset.fileUrl
                    : null,
            queueType: "unassigned",
            scheduledFor: new Date(Date.now() + 60 * 60 * 1000)
                .toISOString()
                .slice(0, 16), // 1 hour from now
        }));

        // Store in sessionStorage and navigate
        sessionStorage.setItem("repostData", JSON.stringify(assetData));
        window.location.href = "/dashboard/bulkposts?mode=recycle";
    }, [assets, selectedAssets]);

    const handleBulkDeleteAssets = useCallback(() => {
        if (selectedAssets.length === 0) return;

        if (
            !confirm(
                `Are you sure you want to delete ${selectedAssets.length} selected asset${selectedAssets.length > 1 ? "s" : ""}?`,
            )
        ) {
            return;
        }

        onBulkDelete(selectedAssets);

        // Clear selected assets after submission
        setSelectedAssets([]);
    }, [selectedAssets, onBulkDelete]);

    const handleSearch = useCallback((e: React.FormEvent) => {
        e.preventDefault();
        const url = new URL(window.location.href);
        if (searchInput.trim()) {
            url.searchParams.set("search", searchInput.trim());
        } else {
            url.searchParams.delete("search");
        }
        url.searchParams.delete("page"); // Reset to first page when searching
        window.location.href = url.toString();
    }, [searchInput]);

    const handlePageChange = useCallback((newPage: number) => {
        // Clear selected assets when changing pages
        setSelectedAssets([]);

        const url = new URL(window.location.href);
        if (newPage === 1) {
            url.searchParams.delete("page");
        } else {
            url.searchParams.set("page", newPage.toString());
        }
        window.location.href = url.toString();
    }, []);

    return {
        selectedAssets,
        searchInput,
        setSearchInput,
        handleAssetSelect,
        handleSelectAllAssets,
        handleBulkPostAssets,
        handleBulkDeleteAssets,
        handleSearch,
        handlePageChange,
    };
}

import { useFetcher } from "@remix-run/react";
import { useCallback, useRef, useState } from "react";

import type { Asset } from "~/features/assets/types";
import { resizeImage } from "~/features/upload/image-resize";
import { uploadFile, uploadMultipleFiles } from "~/features/upload/upload.client";

interface UseAssetUploadOptions {
    onSuccess: (message: string) => void;
    onError: (message: string) => void;
}

export function useAssetUpload({
    onSuccess,
    onError,
}: UseAssetUploadOptions) {
    const assetFetcher = useFetcher<{ success?: boolean; asset?: Asset; assets?: Asset[]; error?: string }>();
    const [bulkUploadFiles, setBulkUploadFiles] = useState<File[]>([]);
    const [isProcessingImages, setIsProcessingImages] = useState(false);
    const [singleFileUploading, setSingleFileUploading] = useState(false);
    const [bulkFileUploading, setBulkFileUploading] = useState(false);
    const textAssetFormRef = useRef<HTMLFormElement>(null);
    const imageAssetFormRef = useRef<HTMLFormElement>(null);

    const handleSingleFileUpload = useCallback(async (
        e: React.FormEvent,
        form: HTMLFormElement,
    ) => {
        e.preventDefault();
        setSingleFileUploading(true);

        try {
            const formData = new FormData(form);
            const fileInput = form.querySelector(
                'input[type="file"]',
            ) as HTMLInputElement;
            const file = fileInput?.files?.[0];

            if (!file) {
                throw new Error("No file selected");
            }

            // Process file if it's an image
            const processedFile = file.type.startsWith("image/")
                ? await resizeImage(file)
                : file;

            // Upload file using new upload system
            const uploadResult = await uploadFile(processedFile);

            if (!uploadResult.success) {
                throw new Error(uploadResult.error || "Upload failed");
            }

            // Submit to server with upload result
            const serverFormData = new FormData();
            serverFormData.append("_action", formData.get("_action") as string);
            serverFormData.append("title", formData.get("title") as string);
            serverFormData.append("tags", formData.get("tags") as string);
            serverFormData.append("uploadResult", JSON.stringify(uploadResult));

            assetFetcher.submit(serverFormData, { method: "post" });
        } catch (error: unknown) {
            const { handleAsyncErrorWithMessage, getErrorMessage } = await import("~/lib/error-handler.client");
            const errorMessage = `Upload failed: ${getErrorMessage(error)}`;
            handleAsyncErrorWithMessage(
                error,
                errorMessage,
                {
                    component: "useAssetUpload",
                    action: "handleSingleFileUpload",
                },
                false, // Don't show toast, we call onError instead
            );
            onError(errorMessage);
        } finally {
            setSingleFileUploading(false);
        }
    }, [assetFetcher, onError]);

    const handleBulkFileUpload = useCallback(async () => {
        if (bulkUploadFiles.length === 0) return;

        setBulkFileUploading(true);

        try {
            // Upload all files using new upload system
            const uploadResults = await uploadMultipleFiles(bulkUploadFiles);

            // Check for failed uploads
            const failedUploads = uploadResults.filter((result) => !result.success);
            if (failedUploads.length > 0) {
                const errorMessages = failedUploads
                    .map((result) => result.error)
                    .join(", ");
                throw new Error(`Upload failed: ${errorMessages}`);
            }

            // Get form data for titles and tags
            const bulkForm = document.querySelector(
                "form[data-bulk-form]",
            ) as HTMLFormElement;
            if (!bulkForm) throw new Error("Bulk form not found");

            const formData = new FormData(bulkForm);
            const serverFormData = new FormData();
            serverFormData.append("_action", "bulk_create_media_assets");
            serverFormData.append("uploadResults", JSON.stringify(uploadResults));

            // Add titles and tags
            const titles = formData.getAll("titles");
            const tags = formData.getAll("tags");
            titles.forEach((title) =>
                serverFormData.append("titles", title as string),
            );
            tags.forEach((tag) => serverFormData.append("tags", tag as string));

            assetFetcher.submit(serverFormData, { method: "post" });
        } catch (error: unknown) {
            const { handleAsyncErrorWithMessage, getErrorMessage } = await import("~/lib/error-handler.client");
            const errorMessage = `Bulk upload failed: ${getErrorMessage(error)}`;
            handleAsyncErrorWithMessage(
                error,
                errorMessage,
                {
                    component: "useAssetUpload",
                    action: "handleBulkFileUpload",
                },
                false, // Don't show toast, we call onError instead
            );
            onError(errorMessage);
        } finally {
            setBulkFileUploading(false);
        }
    }, [bulkUploadFiles, assetFetcher, onError]);

    const handleBulkFileChange = useCallback(async (
        e: React.ChangeEvent<HTMLInputElement>,
    ) => {
        if (e.target.files) {
            const selectedFiles = Array.from(e.target.files);

            setIsProcessingImages(true);
            try {
                // Process files to remove metadata for privacy (images only)
                const processedFiles = await Promise.all(
                    selectedFiles.map(async (file) => {
                        if (file.type.startsWith("image/")) {
                            return await resizeImage(file);
                        }
                        // Videos are uploaded as-is (no processing needed for privacy)
                        return file;
                    }),
                );
                setBulkUploadFiles(processedFiles);
            } catch (error) {
                const { handleErrorSafely } = await import("~/lib/error-handler.client");
                handleErrorSafely(error, {
                    component: "useAssetUpload",
                    action: "handleBulkFileChange",
                }, () => {
                    // Fallback to original files if processing fails
                    setBulkUploadFiles(selectedFiles);
                });
            } finally {
                setIsProcessingImages(false);
            }
        }
    }, []);

    // Handle fetcher responses
    const handleFetcherResponse = useCallback(() => {
        if (assetFetcher.data?.success) {
            // Show toast message
            if (assetFetcher.data.asset) {
                onSuccess(
                    `${assetFetcher.data.asset.assetType.toLowerCase()} asset created successfully!`,
                );
            } else if (assetFetcher.data.assets) {
                onSuccess(
                    `${assetFetcher.data.assets.length} image assets uploaded successfully!`,
                );
            } else {
                onSuccess("Asset created successfully!");
            }

            // Clear forms
            if (textAssetFormRef.current) {
                textAssetFormRef.current.reset();
            }
            if (imageAssetFormRef.current) {
                imageAssetFormRef.current.reset();
            }

            // Clear bulk upload state
            setBulkUploadFiles([]);

            // Rehydrate page by reloading data
            window.location.reload();
        }
    }, [assetFetcher.data, onSuccess]);

    return {
        assetFetcher,
        bulkUploadFiles,
        isProcessingImages,
        singleFileUploading,
        bulkFileUploading,
        textAssetFormRef,
        imageAssetFormRef,
        handleSingleFileUpload,
        handleBulkFileUpload,
        handleBulkFileChange,
        handleFetcherResponse,
    };
}

import { nip19 } from "nostr-tools";

import type {
  CompleteProfileResult,
  GetCompleteProfileParams,
  MediaData,
  PrimalEvent,
  ProcessedProfile,
  ProfileData,
  StatsData,
} from "~/features/nostr/types";
import { npubToHex } from "~/lib/nostr";
import { connectToPrimalCache } from "~/lib/nostrwebsocket.server";

/**
 * Validates an npub string
 */
export function validateNpub(npub: string): boolean {
  try {
    const { type } = nip19.decode(npub);
    return type === "npub";
  } catch (e) {
    return false;
  }
}

/**
 * Fetches profile data from Primal API using WebSocket
 */
export async function fetchPrimalProfileData(
  npub: string,
): Promise<PrimalEvent[]> {
  try {
    const pubkey = npubToHex(npub);
    const responses = await connectToPrimalCache("user_profile", {
      pubkey,
    });
    return responses as PrimalEvent[];
  } catch (error) {
    console.error("Failed to fetch profile data from Primal cache:", error);
    // Return empty array to allow login to proceed without profile data
    return [];
  }
}

/**
 * Processes Primal API response to extract profile information
 */
export function processPrimalData(data: PrimalEvent[]): {
  profile: ProcessedProfile;
} {
  // Find the profile event (kind 0)
  const profileEvent = data.find(
    (event) =>
      Array.isArray(event) && event[0] === "EVENT" && event[2].kind === 0,
  );

  // Find the stats event (kind 10000105)
  const statsEvent = data.find(
    (event) =>
      Array.isArray(event) &&
      event[0] === "EVENT" &&
      event[2].kind === 10000105,
  );

  // Find the media resources event (kind 10000119)
  const mediaEvent = data.find(
    (event) =>
      Array.isArray(event) &&
      event[0] === "EVENT" &&
      event[2].kind === 10000119,
  );

  // Parse profile content
  const profile: ProfileData = profileEvent
    ? (JSON.parse(profileEvent[2].content) as ProfileData)
    : {};

  // Parse stats content
  const stats: StatsData = statsEvent ? (JSON.parse(statsEvent[2].content) as StatsData) : {};

  // Parse media content
  const media: MediaData = mediaEvent ? (JSON.parse(mediaEvent[2].content) as MediaData) : {};

  return {
    profile: {
      ...profile,
      followers_count: stats.followers_count || 0,
      following_count: stats.follows_count || 0,
      posts_count: stats.note_count || 0,
      zaps_count: stats.total_zap_count || 0,
      total_satszapped: stats.total_satszapped || 0,
      media,
    },
  };
}

export async function getCompleteProfile({
  npub,
}: GetCompleteProfileParams): Promise<CompleteProfileResult> {
  const primalData = await fetchPrimalProfileData(npub);

  // If no data returned, return empty profile
  if (!primalData || primalData.length === 0) {
    const emptyProfile: ProcessedProfile = {};
    return {
      nostrProfile: emptyProfile,
      lud16: undefined,
    };
  }

  const { profile } = processPrimalData(primalData);

  return {
    nostrProfile: profile,
    lud16: profile.lud16,
  };
}

/**
 * Nostr authentication service layer
 * Handles Nostr-based authentication flow
 */

import { validateEvent } from "nostr-tools";

import { getCompleteProfile } from "~/features/auth/profile.server";
import { createUserSession } from "~/features/auth/session.server";
import { AuthenticationError, ValidationError } from "~/lib/errors";
import { safeRedirect } from "~/lib/remix-utils";
import {
  createUser,
  getUserByNpub,
  updateUserProfile,
} from "~/models/user.server";

/**
 * Authenticate user via Nostr event signature
 */
export async function authenticateNostrUser(
  event: string,
  contentSign: string | null,
  redirectTo: string,
  request: Request,
) {
  if (!event || typeof event !== "string") {
    throw new ValidationError("Missing or invalid event");
  }

  // Parse the event JSON
  let parsedEvent: {
    id?: string;
    pubkey?: string;
    sig?: string;
    created_at?: number;
    kind?: number;
    content?: string;
    [key: string]: unknown;
  };
  try {
    parsedEvent = JSON.parse(event) as typeof parsedEvent;
  } catch (parseError) {
    throw new ValidationError("Invalid event JSON format", {
      error: parseError instanceof Error ? parseError.message : String(parseError),
    });
  }

  const safeRedirectTo = safeRedirect(redirectTo, `/dashboard`);

  // Verify the signature
  const isValid = validateEvent(parsedEvent);
  const createdAt = new Date((parsedEvent.created_at || 0) * 1000);
  const sixHoursAgo = new Date(Date.now() - 1000 * 60 * 60 * 6);

  if (
    isValid &&
    parsedEvent.content === contentSign &&
    createdAt >= sixHoursAgo &&
    parsedEvent.kind === 27235
  ) {
    // The signature is valid, so this is the real user
    // You can now create a session or token for the user
    let user = await getUserByNpub(parsedEvent.pubkey || "");
    const { nostrProfile } = await getCompleteProfile({
      npub: parsedEvent.pubkey || "",
    });

    if (!user) {
      user = await createUser(
        parsedEvent.pubkey || "",
        JSON.stringify(nostrProfile),
      );
    }

    const twelveHoursAgo = new Date(Date.now() - 1000 * 60 * 60 * 12);
    if (user.updatedAt < twelveHoursAgo) {
      await updateUserProfile({
        nostrProfile: JSON.stringify(nostrProfile),
        npub: parsedEvent.pubkey || "",
      });
    }

    return createUserSession({
      redirectTo: safeRedirectTo,
      remember: false,
      request,
      userId: user.id,
    });
  } else {
    // The signature is not valid
    throw new AuthenticationError("Invalid signature or expired event", {
      isValid,
      hasContentSign: !!contentSign,
      createdAt: parsedEvent.created_at,
      kind: parsedEvent.kind,
    });
  }
}

import { formatDate } from "~/lib/helpers";

import type { ChildReply } from "../hooks/useNotificationActions";
interface ChildRepliesPanelProps {
    isLoading: boolean;
    replies: ChildReply[];
    metadata: Record<string, unknown>;
}

export function ChildRepliesPanel({
    isLoading,
    replies,
    metadata,
}: ChildRepliesPanelProps) {
    if (isLoading) {
        return (
            <div className="mt-3 border-l-2 border-indigo-200 pl-3 dark:border-indigo-800">
                <div className="flex items-center gap-2 text-xs text-gray-500 dark:text-gray-400">
                    <svg className="h-4 w-4 animate-spin" fill="none" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                    Loading replies...
                </div>
            </div>
        );
    }

    if (replies.length === 0) {
        return (
            <div className="mt-3 border-l-2 border-indigo-200 pl-3 dark:border-indigo-800">
                <div className="text-xs text-gray-500 dark:text-gray-400">No replies yet</div>
            </div>
        );
    }

    return (
        <div className="mt-3 space-y-2 border-l-2 border-indigo-200 pl-3 dark:border-indigo-800">
            {replies.map((reply) => {
                const replyMetadata = metadata[reply.pubkey];
                let replyAuthorName = reply.pubkey.substring(0, 8) + "..." + reply.pubkey.slice(-4);
                let replyAuthorPicture = null;

                if (replyMetadata) {
                    try {
                        const metadataContent = replyMetadata && typeof replyMetadata === "object" && !Array.isArray(replyMetadata) && "content" in replyMetadata
                            ? (replyMetadata as { content?: unknown }).content
                            : null;
                        const profile = typeof metadataContent === "string"
                            ? (JSON.parse(metadataContent) as Record<string, unknown>)
                            : metadataContent && typeof metadataContent === "object" && !Array.isArray(metadataContent)
                                ? metadataContent as Record<string, unknown>
                                : null;
                        if (profile && typeof profile === "object") {
                            replyAuthorName = (profile as { display_name?: string; name?: string })?.display_name ?? 
                                            (profile as { name?: string })?.name ?? 
                                            replyAuthorName;
                            replyAuthorPicture = (profile as { picture?: string | null })?.picture ?? null;
                        }
                    } catch (e) {
                        // Ignore parsing errors
                    }
                }

                return (
                    <div key={reply.id} className="rounded-lg border border-gray-200 bg-gray-50 p-2 dark:border-gray-700 dark:bg-gray-800/50">
                        <div className="mb-1 flex items-center gap-2">
                            {replyAuthorPicture ? (
                                <img src={replyAuthorPicture} alt={replyAuthorName} className="h-6 w-6 rounded-full" />
                            ) : (
                                <div className="h-6 w-6 rounded-full bg-gray-300 dark:bg-gray-600" />
                            )}
                            <span className="text-xs font-semibold text-gray-900 dark:text-gray-100">{replyAuthorName}</span>
                            <span className="text-xs text-gray-500 dark:text-gray-400">
                                {formatDate(new Date(reply.created_at * 1000).toISOString())}
                            </span>
                        </div>
                        <p className="whitespace-pre-wrap break-words text-xs text-gray-700 dark:text-gray-300">
                            {reply.content}
                        </p>
                    </div>
                );
            })}
        </div>
    );
}

