 * Unsigned Nostr event
 */
export interface NostrEvent {
    content: string;
    created_at: number;
    kind: number;
    tags: string[][];
}

/**
 * Signed Nostr event with signature and metadata
 */
export interface SignedEvent {
    id: string;
    pubkey: string;
    created_at: number;
    kind: number;
    tags: string[][];
    content: string;
    sig: string;
}

