import { useNavigate } from "@remix-run/react";
import { useEffect, useRef, useState } from "react";
interface UsePaymentPollingProps {
  paymentId: string | null;
  onPaymentComplete: () => void;
}

/**
 * Custom hook for managing payment polling
 */
export function usePaymentPolling({
  paymentId: _paymentId,
  onPaymentComplete,
}: UsePaymentPollingProps) {
  const navigate = useNavigate();
  const [isPolling, setIsPolling] = useState(false);
  const [pollingInterval, setPollingInterval] = useState<NodeJS.Timeout | null>(
    null,
  );
  const shouldStopPolling = useRef(false);

  // Function to check payment status immediately
  const checkPaymentStatusNow = async (paymentId: string) => {
    try {
      const formData = new FormData();
      formData.append("paymentId", paymentId);

      const response = await fetch("/api/payment-status", {
        method: "POST",
        body: formData,
      });

      if (!response.ok) {
        return;
      }

      const responseText = await response.text();
      let data: { success?: boolean; paid?: boolean };
      try {
        data = JSON.parse(responseText) as { success?: boolean; paid?: boolean };
      } catch (_parseError) {
        return;
      }

      if (data.success && data.paid) {
        shouldStopPolling.current = true;
        setIsPolling(false);
        if (pollingInterval) {
          clearInterval(pollingInterval);
          setPollingInterval(null);
        }
        onPaymentComplete();
        setTimeout(() => {
          navigate("/dashboard", { replace: true });
        }, 2000);
      }
    } catch (_error) {
      // Silently handle errors
    }
  };

  // Start automatic payment polling
  const startPaymentPolling = (paymentId: string) => {
    // Clear any existing interval
    if (pollingInterval) {
      clearInterval(pollingInterval);
      setPollingInterval(null);
    }

    // Don't start if already polling
    if (isPolling) {
      return;
    }

    // Reset the stopping ref
    shouldStopPolling.current = false;
    setIsPolling(true);
    const interval = setInterval(async () => {
      if (shouldStopPolling.current) {
        clearInterval(interval);
        return;
      }

      try {
        const formData = new FormData();
        formData.append("paymentId", paymentId);

        const response = await fetch("/api/payment-status", {
          method: "POST",
          body: formData,
        });

        if (!response.ok) {
          return;
        }

        const responseText = await response.text();
        let data: { success?: boolean; paid?: boolean };
        try {
          data = JSON.parse(responseText) as { success?: boolean; paid?: boolean };
        } catch (_parseError) {
          return;
        }

        if (data.success && data.paid) {
          // Stop this specific interval immediately
          clearInterval(interval);
          setPollingInterval(null);
          setIsPolling(false);
          shouldStopPolling.current = true;
          onPaymentComplete();

          // Also clear the stored interval reference to prevent any issues
          if (pollingInterval && pollingInterval !== interval) {
            clearInterval(pollingInterval);
          }

          // Redirect to dashboard after showing success message
          setTimeout(() => {
            navigate("/dashboard", { replace: true });
          }, 2000);
        }
      } catch (_error) {
        // Silently handle polling errors
      }
    }, 5000); // Poll every 5 seconds

    setPollingInterval(interval);

    // Stop polling after 5 minutes
    setTimeout(
      () => {
        shouldStopPolling.current = true;
        if (interval) {
          clearInterval(interval);
          setPollingInterval(null);
          setIsPolling(false);
        }
      },
      5 * 60 * 1000,
    );
  };

  // Clean up polling on component unmount
  useEffect(() => {
    return () => {
      shouldStopPolling.current = true;
      if (pollingInterval) {
        clearInterval(pollingInterval);
      }
    };
  }, [pollingInterval]);

  return {
    isPolling,
    startPaymentPolling,
    checkPaymentStatusNow,
  };
}

import { useNavigate } from "@remix-run/react";
import { useEffect, useState } from "react";

import { usePaymentPolling } from "./usePaymentPolling";
interface InvoiceData {
  invoice: string;
  paymentHash: string;
  amount: number;
  amountUsd: number;
  paymentId: string;
  expiresAt: string;
  planName: string;
  planId: string;
}

interface ActionData {
  success?: boolean;
  paid?: boolean;
  invoice?: string;
  paymentHash?: string;
  amount?: number;
  amountUsd?: number;
  paymentId?: string;
  expiresAt?: string;
  planName?: string;
  planId?: string;
  error?: string;
}

interface UsePlansStateProps {
  user: { id: string; isEnabled: boolean } | null;
  actionData: ActionData | null;
}

/**
 * Custom hook for managing plans page state and operations
 */
export function usePlansState({ user, actionData }: UsePlansStateProps) {
  const navigate = useNavigate();
  const [showInvoice, setShowInvoice] = useState(false);
  const [invoiceData, setInvoiceData] = useState<InvoiceData | null>(null);
  const [paymentComplete, setPaymentComplete] = useState(false);
  const [selectedPlan, setSelectedPlan] = useState<string | null>(null);
  const [timeRemaining, setTimeRemaining] = useState<number>(0);

  const { isPolling, startPaymentPolling } =
    usePaymentPolling({
      paymentId: invoiceData?.paymentId ?? null,
      onPaymentComplete: () => {
        setPaymentComplete(true);
        setShowInvoice(false);
      },
    });

  // Handle action data (invoice creation or payment status)
  useEffect(() => {
    if (actionData?.success) {
      // Handle paid plan payment completion
      if (actionData.paid) {
        setPaymentComplete(true);
        setShowInvoice(false);
        setTimeout(() => {
          navigate("/dashboard", { replace: true });
        }, 2000);
        return;
      }

      // Handle paid plan invoice creation
      if (actionData.invoice && actionData.invoice !== "free_plan") {
        // Convert ActionData to InvoiceData (all required fields must be present)
        if (actionData.paymentHash && actionData.amount !== undefined && actionData.amountUsd !== undefined && 
            actionData.paymentId && actionData.expiresAt && actionData.planName && actionData.planId) {
          const invoice: InvoiceData = {
            invoice: actionData.invoice,
            paymentHash: actionData.paymentHash,
            amount: actionData.amount,
            amountUsd: actionData.amountUsd,
            paymentId: actionData.paymentId,
            expiresAt: actionData.expiresAt,
            planName: actionData.planName,
            planId: actionData.planId,
          };
          setInvoiceData(invoice);
          setShowInvoice(true);
          // Set initial time remaining
          setTimeRemaining(new Date(actionData.expiresAt).getTime() - Date.now());
          // Start automatic payment status polling
          startPaymentPolling(actionData.paymentId);
        }
      }
    }
  }, [actionData, navigate, startPaymentPolling]);

  // Countdown timer effect
  useEffect(() => {
    if (showInvoice && invoiceData) {
      const timer = setInterval(() => {
        const remaining =
          new Date(invoiceData.expiresAt).getTime() - Date.now();
        setTimeRemaining(Math.max(0, remaining));

        if (remaining <= 0) {
          clearInterval(timer);
          setShowInvoice(false);
        }
      }, 1000);

      return () => clearInterval(timer);
    }
  }, [showInvoice, invoiceData]);

  // Function to handle plan selection
  const handlePlanSelection = (
    event: React.MouseEvent<HTMLButtonElement>,
    planId: string,
  ) => {
    if (!user) {
      // Prevent form submission and redirect to login if not authenticated
      event.preventDefault();
      navigate("/login", { replace: true });
      return false;
    }
    setSelectedPlan(planId);
    return true;
  };

  // Function to copy invoice to clipboard
  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
  };

  return {
    showInvoice,
    invoiceData,
    paymentComplete,
    selectedPlan,
    timeRemaining,
    isPolling,
    setSelectedPlan,
    handlePlanSelection,
    copyToClipboard,
  };
}

