                                        // Handle repost fileUrl which should now be a single URL string
                                        if (Array.isArray(post.fileUrl)) {
                                            imageUrl = post.fileUrl[0];
                                        } else {
                                            imageUrl = post.fileUrl;
                                        }
                                    } else if (post.file) {
                                        // Handle regular file uploads - use previewData which includes type info
                                        const previewInfo = previewData.get(index);
                                        if (previewInfo) {
                                            return (
                                                <MediaThumbnail
                                                    src={previewInfo.url}
                                                    alt="Preview"
                                                    className="h-24 w-24 rounded object-cover"
                                                    onClick={() =>
                                                        handleMediaClick(previewInfo.url)
                                                    }
                                                    forceType={
                                                        previewInfo.isVideo ? "video" : "image"
                                                    }
                                                />
                                            );
                                        }
                                    }

                                    // Fallback for repost with fileUrl
                                    if (imageUrl && imageUrl.trim() !== "") {
                                        return (
                                            <MediaThumbnail
                                                src={imageUrl}
                                                alt="Preview"
                                                className="h-24 w-24 rounded object-cover"
                                                onClick={() => handleMediaClick(imageUrl)}
                                            />
                                        );
                                    } else {
                                        // Show TEXT placeholder for text-only posts
                                        return (
                                            <div className="flex h-24 w-24 items-center justify-center rounded bg-gray-200 text-xs font-medium text-gray-600 dark:bg-gray-700 dark:text-gray-300">
                                                TEXT
                                            </div>
                                        );
                                    }
                                })()}
                                <input type="file" name="files" hidden />
                            </td>
                            <td className="p-4">
                                <div className="space-y-2">
                                    <textarea
                                        name="captions"
                                        value={post.caption}
                                        onChange={(e) =>
                                            handleCaptionChange(index, e.target.value)
                                        }
                                        disabled={post.isKind6Repost}
                                        className={`w-full rounded-lg border p-2 text-gray-900 dark:bg-gray-800 dark:text-gray-100 ${post.isKind6Repost ? "cursor-not-allowed bg-gray-100 dark:bg-gray-700" : ""}`}
                                        rows={3}
                                        placeholder={
                                            post.isKind6Repost
                                                ? "Kind 6 reposts have no content..."
                                                : post.isQuotePost
                                                    ? "Add your comment to this quote post..."
                                                    : "Write your caption..."
                                        }
                                    />
                                    {(post.isKind6Repost || post.isQuotePost) &&
                                        post.originalCaption ? (
                                        <div className="rounded border bg-gray-50 p-2 text-xs text-gray-500 dark:bg-gray-800 dark:text-gray-400">
                                            <strong>Original:</strong>{" "}
                                            {post.originalCaption.length > 100
                                                ? post.originalCaption.substring(0, 100) + "..."
                                                : post.originalCaption}
                                        </div>
                                    ) : null}
                                </div>
                            </td>
                            <td className="p-4">
                                <div className="flex flex-wrap gap-1">
                                    {queueTypes.map((queue) => {
                                        const queueName =
                                            typeof queue === "string" ? queue : (queue.name || "");
                                        const queueColor =
                                            typeof queue === "object" ? queue.color : null;
                                        return (
                                            <button
                                                key={queueName}
                                                type="button"
                                                onClick={() => {
                                                    handleQueueTypeChange(index, queueName ?? "");
                                                }}
                                                className={`rounded-full px-3 py-1 text-xs ${getDynamicQueueStyle(queueColor ?? null, post.queueType === queueName)}`}
                                                style={{
                                                    backgroundColor: queueColor || undefined,
                                                    borderColor: queueColor || undefined,
                                                }}
                                            >
                                                {queueName}
                                            </button>
                                        );
                                    })}
                                </div>
                            </td>
                            <td className="p-4">
                                <input
                                    type="datetime-local"
                                    name="scheduledDates"
                                    value={post.scheduledFor}
                                    onChange={(e) =>
                                        handleDateChange(index, e.target.value)
                                    }
                                    className="rounded-lg border p-2 text-gray-900 dark:bg-gray-800 dark:text-gray-100"
                                />
                            </td>
                            <td className="p-4">
                                <div className="flex items-center">
                                    <input
                                        id={`bulk-recyclable-${index}`}
                                        type="checkbox"
                                        checked={post.isRecyclable || false}
                                        onChange={(e) =>
                                            handleIsRecyclableChange(index, e.target.checked)
                                        }
                                        className="h-4 w-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                                    />
                                    <label htmlFor={`bulk-recyclable-${index}`} className="ml-2 text-sm text-gray-700 dark:text-gray-300">
                                        Recyclable
                                    </label>
                                </div>
                            </td>
                            <td className="p-4">
                                <button
                                    type="button"
                                    onClick={() => handleRemovePost(index)}
                                    className="rounded bg-red-500 px-3 py-1 text-white hover:bg-red-600"
                                >
                                    Remove
                                </button>
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>
        </div>
    );
}

import { useState, useCallback } from "react";

import type { PostData, LongFormPostData, QueueType, UserData } from "~/features/posts/types";

import { MonthlyView } from "./MonthlyView";
import type { CalendarPost } from "./PostBlock.types";
import { RescheduleModal } from "./RescheduleModal";
import { WeeklyView } from "./WeeklyView";


interface RescheduleData {
  post: CalendarPost;
  newDateTime: Date;
  wasAutoScheduled: boolean;
  queueName: string | null;
  isEdit: boolean;
  isLongform: boolean;
}

interface CalendarProps {
  scheduledPosts: CalendarPost[];
  pastPosts?: CalendarPost[];
  user?: UserData | null;
  queueTypes?: QueueType[];
  isLongform?: boolean;
  isAll?: boolean;
}

export function Calendar({
  scheduledPosts,
  pastPosts = [],
  user,
  queueTypes,
  isLongform = false,
  isAll = false,
}: CalendarProps) {
  const [view, setView] = useState<"week" | "month">("week");
  const [currentDate, setCurrentDate] = useState(new Date());
  const [showRescheduleModal, setShowRescheduleModal] = useState(false);
  const [rescheduleData, setRescheduleData] = useState<RescheduleData | null>(null);

  const handlePostDrop = useCallback(
    (post: CalendarPost, newDateTime: Date) => {
      // Determine if this specific post is a longform post
      const postIsLongform = isAll ? Boolean(post.title && post.publishedAt) : isLongform;
      const wasAutoScheduled = postIsLongform ? false : !post.manual_override;

      setRescheduleData({
        post,
        newDateTime,
        wasAutoScheduled,
        queueName: postIsLongform ? null : post.queueType?.name ?? null,
        isEdit: false,
        isLongform: postIsLongform,
      });
      setShowRescheduleModal(true);
    },
    [isLongform, isAll],
  );

  const handlePostEdit = useCallback(
    (post: CalendarPost) => {
      // Determine if this specific post is a longform post
      const postIsLongform = isAll ? Boolean(post.title && post.publishedAt) : isLongform;
      const wasAutoScheduled = postIsLongform ? false : !post.manual_override;
      // For longform posts, use publishedAt instead of scheduledFor
      const currentDateTime = postIsLongform
        ? new Date(post.publishedAt as string)
        : new Date(Number(post.scheduledFor) * 1000);

      setRescheduleData({
        post,
        newDateTime: currentDateTime,
        wasAutoScheduled,
        queueName: postIsLongform ? null : post.queueType?.name ?? null,
        isEdit: true,
        isLongform: postIsLongform,
      });
      setShowRescheduleModal(true);
    },
    [isLongform, isAll],
  );

  return (
    <div className="flex h-full flex-col rounded-lg bg-white shadow dark:bg-gray-800">
      {/* Header with view toggle */}
      <div className="border-b border-gray-200 p-4 dark:border-gray-700">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-4">
            {/* Navigation */}
            <button
              onClick={() => {
                const newDate = new Date(currentDate);
                if (view === "week") {
                  newDate.setDate(newDate.getDate() - 7);
                } else {
                  newDate.setMonth(newDate.getMonth() - 1);
                }
                setCurrentDate(newDate);
              }}
              className="p-2 text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200"
            >
              <svg
                className="h-5 w-5"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M15 19l-7-7 7-7"
                />
              </svg>
            </button>

            <h2 className="text-lg font-semibold text-gray-900 dark:text-white">
              {view === "week"
                ? `Week of ${currentDate.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric", timeZone: user?.timezone ?? "Etc/UTC" })}`
                : currentDate.toLocaleDateString("en-US", {
                    month: "long",
                    year: "numeric",
                    timeZone: user?.timezone ?? "Etc/UTC",
                  })}
            </h2>

            <button
              onClick={() => {
                const newDate = new Date(currentDate);
                if (view === "week") {
                  newDate.setDate(newDate.getDate() + 7);
                } else {
                  newDate.setMonth(newDate.getMonth() + 1);
                }
                setCurrentDate(newDate);
              }}
              className="p-2 text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200"
            >
              <svg
                className="h-5 w-5"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M9 5l7 7-7 7"
                />
              </svg>
            </button>

            <button
              onClick={() => setCurrentDate(new Date())}
              className="px-3 py-1 text-sm text-blue-600 hover:text-blue-700 dark:text-blue-400 dark:hover:text-blue-300"
            >
              Today
            </button>
          </div>

          {/* View toggle */}
          <div className="flex items-center space-x-1 rounded-lg bg-gray-100 p-1 dark:bg-gray-700">
            <button
              onClick={() => setView("week")}
              className={`rounded-md px-3 py-1 text-sm font-medium ${
                view === "week"
                  ? "bg-white text-gray-900 shadow-sm dark:bg-gray-800 dark:text-white"
                  : "text-gray-600 hover:text-gray-900 dark:text-gray-300 dark:hover:text-white"
              }`}
            >
              Week
            </button>
            <button
              onClick={() => setView("month")}
              className={`rounded-md px-3 py-1 text-sm font-medium ${
                view === "month"
                  ? "bg-white text-gray-900 shadow-sm dark:bg-gray-800 dark:text-white"
                  : "text-gray-600 hover:text-gray-900 dark:text-gray-300 dark:hover:text-white"
              }`}
            >
              Month
            </button>
          </div>
        </div>
      </div>

      {/* Calendar content */}
      <div className="flex-1 min-h-0 overflow-hidden p-4">
        {view === "week" ? (
          <WeeklyView
            scheduledPosts={scheduledPosts}
            pastPosts={pastPosts}
            currentDate={currentDate}
            onPostDrop={handlePostDrop}
            onPostEdit={handlePostEdit}
            user={user}
            queueTypes={queueTypes}
            isLongform={isLongform}
            isAll={isAll}
          />
        ) : (
          <MonthlyView
            scheduledPosts={scheduledPosts}
            pastPosts={pastPosts}
            currentDate={currentDate}
            onPostDrop={handlePostDrop}
            onPostEdit={handlePostEdit}
            user={user}
            queueTypes={queueTypes}
            isLongform={isLongform}
            isAll={isAll}
          />
        )}
      </div>

      {/* Reschedule Modal */}
      {showRescheduleModal && rescheduleData ? (
        <RescheduleModal
          data={rescheduleData}
          user={user}
          queueTypes={queueTypes}
          onClose={() => {
            setShowRescheduleModal(false);
            setRescheduleData(null);
          }}
          onConfirm={() => {
            setShowRescheduleModal(false);
            setRescheduleData(null);
            // Optionally refresh the page or update state
            window.location.reload();
          }}
        />
      ) : null}
    </div>
  );
}

import MediaThumbnail from "~/components/ui/MediaThumbnail";
import { isVideoFile } from "~/lib/helpers";

import { PostBadges } from "./PostBadges";
import type { PostBlockBaseProps, QueueColorStyle } from "./PostBlock.types";
