      const userTimezone = user?.timezone ?? "UTC";
      const localDate = new Date(
        now.toLocaleString("en-US", { timeZone: userTimezone }),
      );

      // Schedule posts with 2-hour intervals by default
      localDate.setHours(
        localDate.getHours() + index * (Number(scheduleIntervals?.[0]) || 2),
      );

      return {
        id: draft.id,
        content: draft.content || draft.caption,
        caption: draft.caption,
        fileUrl: draft.fileUrl,
        postType: draft.postType,
        queueType: draft.queueType?.name ?? draft.queueType || "unassigned",
        scheduledFor: localDate
          .toLocaleString("en-US", {
            year: "numeric",
            month: "2-digit",
            day: "2-digit",
            hour: "2-digit",
            minute: "2-digit",
            hour12: false,
          })
          .replace(/(\d+)\/(\d+)\/(\d+),\s(\d+):(\d+)/, "$3-$1-$2T$4:$5"),
      };
    }),
  );

  const calculateQueueScheduleTime = async (queueTypeName: string, baseIndex = 0): Promise<string> => {
    if (queueTypeName === "unassigned") {
      return "";
    }

    try {
      const response = await fetch("/api/queue-schedule", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          queueTypeName,
          userId: user?.id,
        }),
      });

      if (response.ok) {
        const data = (await response.json()) as { scheduledTime?: string };
        const scheduledTime = data.scheduledTime;
        if (!scheduledTime) return;

        // For bulk posts, add interval offset based on index
        if (baseIndex > 0) {
          const queueType = queueTypes.find((qt) => {
            const name = typeof qt === "string" ? qt : qt.name;
            return name === queueTypeName;
          });

          if (queueType && typeof queueType === "object") {
            const baseDate = new Date(scheduledTime);

            if (queueType.scheduleType === "INTERVAL") {
              const config = queueType.scheduleConfig;
              let intervalHours = 4; // default

              if (config && isIntervalScheduleConfig(config)) {
                if (config.useGlobalInterval) {
                  const userInterval = user?.scheduleInterval?.[0];
                  intervalHours = typeof userInterval === "number" ? userInterval : (typeof userInterval === "string" ? Number(userInterval) : 4) || 4;
                } else {
                  intervalHours = config.intervalHours || 4;
                }
              }

              baseDate.setHours(
                baseDate.getHours() + baseIndex * intervalHours,
              );
            } else if (queueType.scheduleType === "FIXED_SLOTS") {
              const config = queueType.scheduleConfig;
              const slots = (config && isFixedSlotsScheduleConfig(config)) ? config.slots || [] : [];

              if (slots.length > 0) {
                // Sort slots to ensure consistent ordering
                const sortedSlots = slots
                  .map((slot: string) => {
                    const [hours, minutes] = slot.split(":").map(Number);
                    return {
                      slot,
                      hours,
                      minutes,
                      totalMinutes: hours * 60 + minutes,
                    };
                  })
                  .sort((a: { totalMinutes: number }, b: { totalMinutes: number }) => a.totalMinutes - b.totalMinutes);

                // Get the current slot index based on the base time
                const baseHours = baseDate.getHours();
                const baseMinutes = baseDate.getMinutes();
                const baseTotalMinutes = baseHours * 60 + baseMinutes;

                let currentSlotIndex = 0;
                for (let i = 0; i < sortedSlots.length; i++) {
                  if (sortedSlots[i].totalMinutes >= baseTotalMinutes) {
                    currentSlotIndex = i;
                    break;
                  }
                }

                // Calculate which slot this post should use
                const targetSlotIndex =
                  (currentSlotIndex + baseIndex) % sortedSlots.length;
                const targetSlot = sortedSlots[targetSlotIndex];

                // Calculate how many days to add
                const daysToAdd = Math.floor(
                  (currentSlotIndex + baseIndex) / sortedSlots.length,
                );

                // Set the time to the target slot
                baseDate.setHours(targetSlot.hours, targetSlot.minutes, 0, 0);
                baseDate.setDate(baseDate.getDate() + daysToAdd);
              }
            }

            // Format back to datetime-local format
            const year = baseDate.getFullYear();
            const month = String(baseDate.getMonth() + 1).padStart(2, "0");
            const day = String(baseDate.getDate()).padStart(2, "0");
            const hours = String(baseDate.getHours()).padStart(2, "0");
            const minutes = String(baseDate.getMinutes()).padStart(2, "0");

            return `${year}-${month}-${day}T${hours}:${minutes}`;
          }
        }

        return scheduledTime;
      }
    } catch (error) {
      const { handleErrorSafely } = await import("~/lib/error-handler.client");
      handleErrorSafely(error, {
        component: "DraftBulkResume",
        action: "calculateQueueScheduleTime",
      });
    }

    return "";
  };

  const handleQueueTypeChange = async (index: number, value: string | QueueType) => {
    const updatedPosts = [...posts];
    updatedPosts[index].queueType = value;

    // Auto-calculate schedule time if not unassigned
    const queueTypeName = typeof value === "string" ? value : value.name;
    if (queueTypeName !== "unassigned") {
      const scheduledTime = await calculateQueueScheduleTime(queueTypeName, 0);
      if (scheduledTime) {
        updatedPosts[index].scheduledFor = scheduledTime;
      }
    } else {
      updatedPosts[index].scheduledFor = "";
    }

    setPosts(updatedPosts);
  };

  const handleDateChange = (index: number, value: string) => {
    const updatedPosts = [...posts];
    updatedPosts[index].scheduledFor = value;
    setPosts(updatedPosts);
  };

  const handleScheduleIntervalClick = (interval: number) => {
    if (posts.length === 0) return;

    const updatedPosts = [...posts];
    const baseDate = new Date(updatedPosts[0].scheduledFor);

    updatedPosts.forEach((post, index) => {
      const newDate = new Date(baseDate);
      newDate.setHours(baseDate.getHours() + index * interval);

      const year = newDate.getFullYear();
      const month = String(newDate.getMonth() + 1).padStart(2, "0");
      const day = String(newDate.getDate()).padStart(2, "0");
      const hours = String(newDate.getHours()).padStart(2, "0");
      const minutes = String(newDate.getMinutes()).padStart(2, "0");

      post.scheduledFor = `${year}-${month}-${day}T${hours}:${minutes}`;
    });

    setPosts(updatedPosts);
  };

  const handleBulkQueueUpdate = async (queueType: QueueType | string) => {
    if (posts.length === 0) return;

    const updatedPosts = await Promise.all(
      posts.map(async (post, index) => {
        let scheduledFor = post.scheduledFor;

        // Auto-calculate schedule time if not unassigned
        const queueTypeName = typeof queueType === "string" ? queueType : queueType.name;
        if (queueTypeName !== "unassigned") {
          const calculatedTime = await calculateQueueScheduleTime(
            queueTypeName,
            index,
          );
          if (calculatedTime) {
            scheduledFor = calculatedTime;
          }
        } else {
          scheduledFor = "";
        }

        return {
          ...post,
          queueType,
          scheduledFor,
        };
      }),
    );

    setPosts(updatedPosts);
  };

  const handleSignAndResume = async () => {
    setIsSubmitting(true);
    try {
      const signedPosts = await Promise.all(
        posts.map(async (post) => {
          const userTimezone = user?.timezone ?? "UTC";
          let scheduledTime;

          if (userTimezone !== "UTC" && userTimezone !== "Etc/GMT") {
            const utcDate = new Date(post.scheduledFor);
            const userDate = new Date(post.scheduledFor).toLocaleString(
              "en-US",
              {
                timeZone: userTimezone,
              },
            );
            const userOffset =
              (new Date(userDate).getTime() - new Date(post.scheduledFor).getTime()) / 60000;
            utcDate.setMinutes(utcDate.getMinutes() - userOffset);
            scheduledTime = utcDate.getTime();
          } else {
            const dateObj = new Date(post.scheduledFor + "Z");
            scheduledTime = dateObj.getTime();
          }

          const scheduledForUnix = Math.floor(scheduledTime / 1000);

          // Get effective hashtags based on queue type
          let tagsString = "";
          try {
            const response = await fetch("/api/effective-hashtags", {
              method: "POST",
              headers: {
                "Content-Type": "application/json",
              },
              body: JSON.stringify({
                userId: user?.id,
                queueTypeName: post.queueType,
              }),
            });
            const data = (await response.json()) as { hashtags?: string };
            tagsString = data.hashtags || "";
          } catch (error) {
            const { handleErrorSafely } = await import("~/lib/error-handler.client");
            handleErrorSafely(error, {
              component: "DraftBulkResume",
              action: "getEffectiveHashtags",
            });
            // Fallback to user's default hashtags
            // Note: User doesn't have hashTags property - this would need to come from hashTagPresets relation
            tagsString = "";
          }

          const tagArray = tagsString
            .split(" ")
            .filter((tag) => tag.length > 0)
            .map((tag) => ["t", tag.replace("#", "")]);

          const contentToSign = user?.showHashTagsinPosts
            ? `${post.content || ""}\n${tagsString}`
            : (post.content || "");

          const { nostrEvent, signedEvent } = await signEventFn({
            content: contentToSign,
            created_at: scheduledForUnix,
            kind: 1,
            tags: tagArray,
          });

          return {
            id: post.id,
            content: post.content,
            caption: post.caption,
            queueType: post.queueType,
            scheduledFor: scheduledForUnix.toString(),
            signedEvent: JSON.stringify(signedEvent),
            nostrEvent: JSON.stringify(nostrEvent),
          };
        }),
      );

      const formData = new FormData();
      formData.append("_action", "bulkSignAndResume");
      signedPosts.forEach((post) => {
        formData.append("postIds", post.id);
        formData.append("contents", post.content || "");
        formData.append("captions", post.caption || "");
        const queueTypeValue = typeof post.queueType === "string" ? post.queueType : (post.queueType?.name ?? "");
        formData.append("queueTypes", queueTypeValue);
        formData.append("scheduledFors", post.scheduledFor || "");
        formData.append("signedEvents", post.signedEvent);
        formData.append("nostrEvents", post.nostrEvent);
      });

      fetcher.submit(formData, { method: "post", action: "/dashboard/drafts" });
    } catch (error) {
      console.error("Error signing drafts:", error);
      alert("Error signing drafts. Please try again.");
      setIsSubmitting(false);
    }
  };

  const getImageUrls = (fileUrl: string[] | null | undefined) => {
    if (!fileUrl || fileUrl.length === 0) return [];

    if (typeof fileUrl[0] === "string" && fileUrl[0].startsWith("[")) {
      try {
        return JSON.parse(fileUrl[0]) as string[];
      } catch (e) {
        console.error("Error parsing fileUrl:", e);
        return [];
      }
    }

    return fileUrl;
  };

  interface FetcherData {
    success?: boolean;
  }

  useEffect(() => {
    if ((fetcher.data as FetcherData | undefined)?.success) {
      onCancel(); // Close the modal and refresh
    }
  }, [fetcher.data, onCancel]);

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 to-gray-100 p-6 dark:from-gray-900 dark:to-gray-800">
      <div className="mx-auto max-w-7xl">
        {/* Header */}
        <div className="mb-8 text-center">
          <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
            Resume Draft Posts
          </h1>
          <p className="mt-2 text-gray-600 dark:text-gray-400">
            Configure and sign {posts.length} draft posts before scheduling
          </p>
        </div>

        {/* Schedule Interval Buttons */}
        {posts.length > 0 ? (
          <div className="mb-4 mt-4 flex justify-center">
            {scheduleIntervals
              ? scheduleIntervals.map((interval) => (
                  <button
                    key={interval}
                    type="button"
                    onClick={() => handleScheduleIntervalClick(typeof interval === "string" ? parseInt(interval, 10) : interval)}
                    disabled={isSubmitting}
                    className="mx-2 rounded-md bg-gray-100 px-4 py-2 text-sm font-medium text-gray-700 shadow-md transition-all hover:scale-105 hover:bg-gray-200 disabled:cursor-not-allowed disabled:opacity-50 disabled:hover:scale-100 dark:bg-gray-800 dark:text-gray-300 dark:hover:bg-gray-700"
                  >
                    +{interval}h
                  </button>
                ))
              : null}
          </div>
        ) : null}

        {/* Bulk Queue Selection */}
        {posts.length > 0 ? (
          <div className="mb-6">
            <h3 className="mb-3 text-sm font-medium text-gray-700 dark:text-gray-300">
              Bulk Queue Selection
            </h3>
            <div className="flex flex-wrap justify-center gap-2">
              {queueTypes.map((queue) => {
                const queueName =
                  typeof queue === "string" ? queue : queue.name;
                const queueColor =
                  typeof queue === "object" ? queue.color : null;
                return (
                  <button
                    key={queueName}
                    type="button"
                    onClick={() => handleBulkQueueUpdate(queueName)}
                    disabled={isSubmitting}
                    className={`rounded-full px-4 py-2 text-sm font-medium transition-all duration-200 hover:scale-105 disabled:cursor-not-allowed disabled:opacity-50 disabled:hover:scale-100 ${getSelectedQueueStyle(queueName, false)}`}
                    style={{
                      backgroundColor: queueColor || undefined,
                      borderColor: queueColor || undefined,
                    }}
                  >
                    {queueName}
                  </button>
                );
              })}
            </div>
            <p className="mt-2 text-center text-xs text-gray-500 dark:text-gray-400">
              Click a queue to update all posts
            </p>
          </div>
        ) : null}

        {/* Posts Configuration Table */}
        <div className="overflow-x-auto">
          <table className="w-full border-collapse">
            <thead>
              <tr className="border-b">
                <th className="p-4 text-left">Media</th>
                <th className="p-4 text-left">Content</th>
                <th className="p-4 text-left">Queue</th>
                <th className="p-4 text-left">Schedule</th>
              </tr>
            </thead>
            <tbody>
              {posts.map((post, index) => (
                <tr key={post.id} className="border-b">
                  <td className="p-4">
                    {post.fileUrl && post.fileUrl.length > 0 ? (
                      <img
                        src={getImageUrls(post.fileUrl)[0]}
                        alt="Preview"
                        className="h-24 w-24 rounded object-cover"
                      />
                    ) : (
                      <div className="flex h-24 w-24 items-center justify-center rounded bg-gray-100 text-xs font-medium text-gray-500 dark:bg-gray-700 dark:text-gray-400">
                        TEXT
                      </div>
                    )}
                  </td>
                  <td className="p-4">
                    <div className="max-h-20 overflow-y-auto">
                      <p className="text-sm text-gray-700 dark:text-gray-300">
                        {post.content?.substring(0, 150) || ""}
                        {(post.content?.length ?? 0) > 150 ? "..." : null}
                      </p>
                    </div>
                  </td>
                  <td className="p-4">
                    <div className="flex flex-wrap gap-1">
                      {queueTypes.map((queue) => {
                        const queueName =
                          typeof queue === "string" ? queue : queue.name;
                        const queueColor =
                          typeof queue === "object" ? queue.color : null;
                        return (
                          <button
                            key={queueName}
                            type="button"
                            onClick={() =>
                              handleQueueTypeChange(index, queueName)
                            }
                            disabled={isSubmitting}
                            className={`rounded-full px-3 py-1 text-xs font-medium transition-all duration-200 ${getSelectedQueueStyle(queueName, post.queueType === queueName)}`}
                            style={{
                              backgroundColor: queueColor || undefined,
                              borderColor: queueColor || undefined,
                            }}
                          >
                            {queueName}
                          </button>
                        );
                      })}
                    </div>
                  </td>
                  <td className="p-4">
                    <input
                      type="datetime-local"
                      value={post.scheduledFor}
                      onChange={(e) => handleDateChange(index, e.target.value)}
                      disabled={isSubmitting}
                      className="rounded-lg border p-2 text-gray-900 dark:bg-gray-800 dark:text-gray-100"
                    />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Action Buttons */}
        <div className="mt-8 flex justify-center gap-4">
          <button
            onClick={onCancel}
            disabled={isSubmitting}
            className="rounded-lg border border-gray-300 bg-white px-6 py-3 text-sm font-medium text-gray-700 shadow-sm transition-all hover:bg-gray-50 hover:shadow-md dark:border-gray-600 dark:bg-gray-800 dark:text-gray-300 dark:hover:bg-gray-700"
          >
            Cancel
          </button>
          <button
            onClick={handleSignAndResume}
            disabled={isSubmitting}
            className="rounded-lg bg-gradient-to-r from-green-500 to-green-600 px-8 py-3 text-sm font-medium text-white shadow-lg transition-all hover:from-green-600 hover:to-green-700 hover:shadow-xl disabled:cursor-not-allowed disabled:from-green-300 disabled:to-green-400"
          >
            {isSubmitting ? (
              <span className="flex items-center gap-2">
                <svg className="h-4 w-4 animate-spin" viewBox="0 0 24 24">
                  <circle
                    className="opacity-25"
                    cx="12"
                    cy="12"
                    r="10"
                    stroke="currentColor"
                    strokeWidth="4"
                    fill="none"
                  />
                  <path
                    className="opacity-75"
                    fill="currentColor"
                    d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                  />
                </svg>
                Signing & Scheduling...
              </span>
            ) : (
              `Sign & Schedule ${posts.length} Posts`
            )}
          </button>
        </div>
      </div>
    </div>
  );
}

/**
 * Drafts table component
 */

import { Link , useFetcher } from "@remix-run/react";

import { getQueueColor } from "~/features/posts/queueColors";
interface Post {
  id: string;
  caption?: string | null;
  createdAt: string;
  fileUrl?: string[] | null;
  queueType?: { name: string; color?: string | null } | null;
}

interface DraftsTableProps {
  posts: Post[];
  sortConfig: { key: string; direction: "asc" | "desc" };
  onRequestSort: (key: string) => void;
  selectedPosts: Set<string>;
  onToggleSelection: (postId: string) => void;
  onToggleSelectAll: () => void;
  onPostClick: (post: Post) => void;
  bulkDeleteState: string;
}

export function DraftsTable({
  posts,
  sortConfig,
  onRequestSort,
  selectedPosts,
  onToggleSelection,
  onToggleSelectAll,
  onPostClick,
  bulkDeleteState,
}: DraftsTableProps) {
  const deleteFetcher = useFetcher();

  const formatDate = (isoString: string) => {
    const date = new Date(isoString);
    return date.toLocaleString("en-US", {
      month: "2-digit",
      day: "2-digit",
      year: "numeric",
      hour: "numeric",
      minute: "2-digit",
      hour12: true,
    });
  };

  const getImageUrls = (fileUrl: string[] | null | undefined) => {
    if (!fileUrl || fileUrl.length === 0) return [];

    if (typeof fileUrl[0] === "string" && fileUrl[0].startsWith("[")) {
      try {
        return JSON.parse(fileUrl[0]) as string[];
      } catch (e) {
        console.error("Error parsing fileUrl:", e);
        return [];
      }
    }

    return fileUrl;
  };

  const SortableHeader = ({ key, label }: { key: string; label: string }) => (
    <th
      className="cursor-pointer bg-gray-100/75 px-3 py-4 text-left font-semibold text-gray-900 dark:bg-gray-700/25 dark:text-gray-50"
      onClick={() => onRequestSort(key)}
    >
      {label}{" "}
      {sortConfig.key === key
        ? sortConfig.direction === "asc"
          ? "↑"
          : "↓"
        : null}
    </th>
  );

  return (
    <div className="min-w-full overflow-x-auto rounded border border-gray-200 bg-white dark:border-gray-700 dark:bg-gray-800">
      <table className="min-w-full whitespace-nowrap align-middle text-sm">
        <thead>
          <tr>
            <th className="bg-gray-100/75 px-3 py-4 text-center font-semibold text-gray-900 dark:bg-gray-700/25 dark:text-gray-50">
              <input
                type="checkbox"
                checked={posts.length > 0 ? selectedPosts.size === posts.length : false}
                onChange={onToggleSelectAll}
                className="h-4 w-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500 dark:border-gray-600 dark:bg-gray-700"
              />
            </th>
            <th className="bg-gray-100/75 px-3 py-4 text-left font-semibold text-gray-900 dark:bg-gray-700/25 dark:text-gray-50">
              Media
            </th>
            <SortableHeader key="caption" label="Caption" />
            <SortableHeader key="createdAt" label="Created" />
            <th className="bg-gray-100/75 px-3 py-4 text-center font-semibold text-gray-900 dark:bg-gray-700/25 dark:text-gray-50">
              Queue
            </th>
            <th className="bg-gray-100/75 px-3 py-4 text-center font-semibold text-gray-900 dark:bg-gray-700/25 dark:text-gray-50">
              Status
            </th>
            <th className="bg-gray-100/75 px-3 py-4 text-center font-semibold text-gray-900 dark:bg-gray-700/25 dark:text-gray-50">
              Actions
            </th>
          </tr>
        </thead>
        <tbody>
          {posts.map((post) => (
            <tr
              key={post.id}
              className="cursor-pointer even:bg-gray-50 hover:bg-gray-100 dark:even:bg-gray-900/50 dark:hover:bg-gray-700/50"
              onClick={() => onPostClick(post)}
            >
              <td className="p-3 text-center">
                <input
                  type="checkbox"
                  checked={selectedPosts.has(post.id)}
                  onChange={() => onToggleSelection(post.id)}
                  onClick={(e) => e.stopPropagation()}
                  className="h-4 w-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500 dark:border-gray-600 dark:bg-gray-700"
                />
              </td>
              <td className="p-3">
                {post.fileUrl && post.fileUrl.length > 0 ? (
                  <img
                    src={getImageUrls(post.fileUrl)[0]}
                    alt="Post preview"
                    className="h-12 w-12 rounded object-cover"
                  />
                ) : (
                  <div className="flex h-12 w-12 items-center justify-center rounded bg-gray-100 text-xs font-medium text-gray-500 dark:bg-gray-700 dark:text-gray-400">
                    TEXT
                  </div>
                )}
              </td>
              <td className="p-3">
                <p className="font-medium">{post.caption || "—"}</p>
              </td>
              <td className="p-3">{formatDate(post.createdAt)}</td>
              <td className="p-3 text-center">
                {post.queueType?.color ? (
                  <div
                    className="inline-flex rounded-full border-2 px-3 py-1 text-xs font-semibold leading-4 shadow-sm"
                    style={{
                      backgroundColor: `${post.queueType.color}20`,
                      color: post.queueType.color,
                      borderColor: post.queueType.color,
                    }}
                  >
                    {post.queueType?.name ?? "unassigned"}
                  </div>
                ) : (
                  <div
                    className={`inline-flex rounded-full border-2 px-3 py-1 text-xs font-semibold leading-4 ${getQueueColor(post.queueType?.name ?? "unassigned").bg} ${getQueueColor(post.queueType?.name ?? "unassigned").text} ${getQueueColor(post.queueType?.name ?? "unassigned").border} shadow-sm`}
                  >
                    {post.queueType?.name ?? "unassigned"}
                  </div>
                )}
              </td>
              <td className="p-3 text-center">
                <div className="inline-flex rounded-full border border-transparent bg-orange-100 px-2 py-1 text-xs font-semibold leading-4 text-orange-900 dark:border-orange-900/75 dark:bg-orange-700/10 dark:text-orange-200">
                  Draft
                </div>
              </td>
              <td className="p-3 text-center">
                <div className="flex justify-center gap-2">
                  <Link
                    to={`/dashboard/drafts/edit/${post.id}`}
                    onClick={(e) => e.stopPropagation()}
                    className="inline-flex items-center justify-center gap-2 rounded-lg border border-blue-200 bg-white px-2 py-1 text-sm font-semibold leading-5 text-blue-800 hover:border-blue-300 hover:text-blue-900 hover:shadow-sm focus:ring focus:ring-blue-300/25 active:border-blue-200 active:shadow-none dark:border-blue-700 dark:bg-gray-800 dark:text-blue-300 dark:hover:border-blue-600 dark:hover:text-blue-200 dark:focus:ring-blue-600/40 dark:active:border-blue-700"
                  >
                    Edit
                  </Link>
                  <deleteFetcher.Form
                    method="post"
                    onClick={(e) => e.stopPropagation()}
                  >
                    <input type="hidden" name="postId" value={post.id} />
                    <input type="hidden" name="_action" value="delete" />
                    <button
                      type="submit"
                      disabled={
                        deleteFetcher.state !== "idle" ||
                        bulkDeleteState !== "idle"
                      }
                      className="inline-flex items-center justify-center gap-2 rounded-lg border border-red-200 bg-white px-2 py-1 text-sm font-semibold leading-5 text-red-800 hover:border-red-300 hover:text-red-900 hover:shadow-sm focus:ring focus:ring-red-300/25 active:border-red-200 active:shadow-none disabled:opacity-50 dark:border-red-700 dark:bg-gray-800 dark:text-red-300 dark:hover:border-red-600 dark:hover:text-red-200 dark:focus:ring-red-600/40 dark:active:border-red-700"
                    >
                      {deleteFetcher.state !== "idle" &&
                        deleteFetcher.formData?.get("postId") === post.id
                        ? "Deleting..."
                        : "Delete"}
                    </button>
                  </deleteFetcher.Form>
                </div>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

