import { useFetcher } from "@remix-run/react";
import { useState, useEffect } from "react";

import { EditLongFormFormFields } from "~/features/posts/components/EditLongFormFormFields";
import { EditorJSStyles } from "~/features/posts/components/EditorJSStyles";
import { EditPostFormFields } from "~/features/posts/components/EditPostFormFields";
import { useEditPostModal } from "~/features/posts/hooks/useEditPostModal";
import type { PostData, LongFormPostData, QueueType, HashTagPreset, UserData, PostFetcher } from "~/features/posts/types";
import { prepareEditPostSubmission } from "~/features/posts/utils/editPostSubmit.client";
interface EditPostModalProps {
  post: PostData | LongFormPostData;
  onClose: () => void;
  onConfirm: () => void;
  user?: UserData;
  queueTypes?: QueueType[];
  hashTagPresets?: HashTagPreset[];
}

interface FetcherData {
  success?: boolean;
  needsSigning?: boolean;
  error?: string;
}

export function EditPostModal({
  post,
  onClose,
  onConfirm,
  user,
  queueTypes = [],
  hashTagPresets = [],
}: EditPostModalProps) {
  const fetcher = useFetcher<FetcherData>();
  const [isSigningEvent, setIsSigningEvent] = useState(false);
  const [signingError, setSigningError] = useState<string | null>(null);

  // Determine if this is a longform post
  const isLongform = "title" in post && post.title !== undefined;

  // Use custom hook for form state management
  const {
    caption,
    setCaption,
    selectedQueueType,
    setSelectedQueueType,
    title,
    setTitle,
    summary,
    setSummary,
    content,
    setContent,
    image,
    setImage,
    scheduledFor,
    setScheduledFor,
    existingImages,
    newFiles,
    isUploadingImages,
    setIsUploadingImages,
    useHashtagPresets,
    setUseHashtagPresets,
    selectedHashtagPresetId,
    selectedHashtagPresetTags,
    manualHashtags,
    setManualHashtags,
    editorReady,
    handleFileChange,
    removeExistingImage,
    removeNewFile,
    handleHashtagPresetSelect,
    formatDateTimeForInput,
  } = useEditPostModal({
    post,
    user,
    hashTagPresets,
    isLongform,
  });


  useEffect(() => {
    if (fetcher.data?.success) {
      if (fetcher.data.needsSigning) {
        return; // Keep modal open for re-signing
      }
      onConfirm();
    }
    if (fetcher.data?.error) {
      setSigningError(fetcher.data.error);
    }
  }, [fetcher.data, onConfirm]);

  const handleSubmit = async () => {
    if (!post) return;

    try {
      setIsSigningEvent(true);
      setSigningError(null);
      setIsUploadingImages(true);

      const formData = await prepareEditPostSubmission({
        post,
        isLongform,
        caption,
        title,
        summary,
        content,
        image,
        existingImages,
        newFiles,
        selectedHashtagPresetTags,
        manualHashtags,
        useHashtagPresets,
        selectedQueueType,
        selectedHashtagPresetId,
        scheduledFor,
        user,
      });

      setIsUploadingImages(false);
      fetcher.submit(formData, { method: "post" });
    } catch (error: unknown) {
      console.error("Error re-signing event:", error);
      setIsSigningEvent(false);
      setIsUploadingImages(false);
      const errorMessage = error instanceof Error 
        ? error.message 
        : "Failed to sign event. Please try again.";
      setSigningError(errorMessage);
    }
  };

  if (!post) return null;

  return (
    <>
      {/* EditorJS Custom Styles */}
      {isLongform ? <EditorJSStyles /> : null}

      <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
        <div className="max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-lg bg-white shadow-xl dark:bg-gray-800">
          <div className="p-6">
            {/* Header */}
            <div className="mb-6 flex items-center justify-between">
              <h3 className="text-xl font-semibold text-gray-900 dark:text-white">
                Edit {isLongform ? "Article" : "Post"}
              </h3>
              <button
                onClick={onClose}
                className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-200"
              >
                <svg
                  className="h-6 w-6"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M6 18L18 6M6 6l12 12"
                  />
                </svg>
              </button>
            </div>

            <div className="space-y-6">
              {isLongform ? (
                <EditLongFormFormFields
                  title={title}
                  setTitle={setTitle}
                  summary={summary}
                  setSummary={setSummary}
                  image={image}
                  setImage={setImage}
                  editorReady={editorReady}
                />
              ) : (
                <EditPostFormFields
                  caption={caption}
                  setCaption={setCaption}
                  existingImages={existingImages}
                  newFiles={newFiles}
                  onFileChange={handleFileChange}
                  onRemoveExistingImage={removeExistingImage}
                  onRemoveNewFile={removeNewFile}
                  hashTagPresets={hashTagPresets}
                  useHashtagPresets={useHashtagPresets}
                  setUseHashtagPresets={setUseHashtagPresets}
                  selectedHashtagPresetId={selectedHashtagPresetId}
                  selectedHashtagPresetTags={selectedHashtagPresetTags}
                  onHashtagPresetSelect={handleHashtagPresetSelect}
                  manualHashtags={manualHashtags}
                  setManualHashtags={setManualHashtags}
                  selectedQueueType={selectedQueueType}
                  setSelectedQueueType={setSelectedQueueType}
                  queueTypes={queueTypes}
                />
              )}

              {/* Schedule Date */}
              <div>
                <label htmlFor="edit-post-scheduled-for" className="mb-2 block text-sm font-medium text-gray-700 dark:text-gray-300">
                  Scheduled For
                </label>
                <input
                  id="edit-post-scheduled-for"
                  type="datetime-local"
                  value={
                    scheduledFor ? formatDateTimeForInput(scheduledFor) : ""
                  }
                  onChange={(e) =>
                    setScheduledFor(
                      e.target.value ? new Date(e.target.value) : null,
                    )
                  }
                  className="w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-gray-900 focus:border-blue-500 focus:ring-2 focus:ring-blue-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
                />
              </div>

              {/* Re-signing notice */}
              <div className="rounded-lg border border-blue-200 bg-blue-50 p-4 dark:border-blue-800 dark:bg-blue-900/20">
                <div className="flex items-start space-x-2">
                  <svg
                    className="mt-0.5 h-5 w-5 flex-shrink-0 text-blue-600 dark:text-blue-400"
                    fill="currentColor"
                    viewBox="0 0 20 20"
                  >
                    <path
                      fillRule="evenodd"
                      d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z"
                      clipRule="evenodd"
                    />
                  </svg>
                  <div>
                    <div className="text-sm font-medium text-blue-800 dark:text-blue-200">
                      Editing this {isLongform ? "article" : "post"} requires
                      re-signing the Nostr event
                    </div>
                  </div>
                </div>
              </div>

              {/* Error display */}
              {fetcher.data?.error ?? signingError ? (
                <div className="rounded-lg border border-red-200 bg-red-50 p-4 dark:border-red-800 dark:bg-red-900/20">
                  <div className="text-sm text-red-800 dark:text-red-200">
                    {fetcher.data?.error ?? signingError}
                  </div>
                </div>
              ) : null}
            </div>

            {/* Actions */}
            <div className="mt-6 flex items-center justify-end space-x-3">
              <button
                onClick={onClose}
                className="px-4 py-2 text-sm font-medium text-gray-700 hover:text-gray-900 dark:text-gray-300 dark:hover:text-white"
              >
                Cancel
              </button>
              <button
                onClick={handleSubmit}
                disabled={
                  fetcher.state === "submitting" ||
                  isSigningEvent ||
                  isUploadingImages
                }
                className="rounded-lg bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-50"
              >
                {isUploadingImages
                  ? "Uploading Images..."
                  : isSigningEvent
                    ? "Signing Event..."
                    : fetcher.state === "submitting"
                      ? "Saving..."
                      : "Save Changes"}
              </button>
            </div>
          </div>
        </div>
      </div>
    </>
  );
}

import { useFetcher } from "@remix-run/react";
import { Plus, Edit2, Trash2, Hash } from "lucide-react";
import { useState } from "react";

import { Badge } from "~/components/ui/badge";
import { Button } from "~/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "~/components/ui/card";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "~/components/ui/dialog";
import { Input } from "~/components/ui/input";
import { Label } from "~/components/ui/label";
import { Textarea } from "~/components/ui/textarea";

interface HashTagPreset {
  id: string;
  name: string;
  tags: string;
  description?: string | null;
  createdAt: string;
  updatedAt: string;
}

interface HashtagPresetsSettingsProps {
  presets: HashTagPreset[];
}

interface FetcherData {
  success?: boolean;
  error?: string;
}

export function HashtagPresetsSettings({
  presets,
}: HashtagPresetsSettingsProps) {
  const fetcher = useFetcher<FetcherData>();
  const [isCreateDialogOpen, setIsCreateDialogOpen] = useState(false);
  const [isEditDialogOpen, setIsEditDialogOpen] = useState(false);
  const [editingPreset, setEditingPreset] = useState<HashTagPreset | null>(
    null,
  );

  const [createForm, setCreateForm] = useState({
    name: "",
    tags: "",
    description: "",
  });

  const [editForm, setEditForm] = useState({
    name: "",
    tags: "",
    description: "",
  });

  const isSubmitting = fetcher.state === "submitting";

  const handleCreateSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const formData = new FormData();
    formData.set("_action", "create_hashtag_preset");
    formData.set("name", createForm.name);
    formData.set("tags", createForm.tags);
    formData.set("description", createForm.description);

    fetcher.submit(formData, { method: "post" });
    setCreateForm({ name: "", tags: "", description: "" });
    setIsCreateDialogOpen(false);
  };

  const handleEditSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingPreset) return;

    const formData = new FormData();
    formData.set("_action", "update_hashtag_preset");
    formData.set("id", editingPreset.id);
    formData.set("name", editForm.name);
    formData.set("tags", editForm.tags);
    formData.set("description", editForm.description);

    fetcher.submit(formData, { method: "post" });
    setEditingPreset(null);
    setIsEditDialogOpen(false);
  };

  const handleDelete = (id: string) => {
    if (
      window.confirm("Are you sure you want to delete this hashtag preset?")
    ) {
      const formData = new FormData();
      formData.set("_action", "delete_hashtag_preset");
      formData.set("id", id);
      fetcher.submit(formData, { method: "post" });
    }
  };

  const openEditDialog = (preset: HashTagPreset) => {
    setEditingPreset(preset);
    setEditForm({
      name: preset.name,
      tags: preset.tags,
      description: preset.description || "",
    });
    setIsEditDialogOpen(true);
  };

  const countHashtags = (tags: string): number => {
    return tags
      .split(/\s+/)
      .filter((tag) => tag.startsWith("#") && tag.length > 1).length;
  };

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center justify-between">
          <div>
            <CardTitle className="flex items-center gap-2">
              <Hash className="h-5 w-5" />
              Hashtag Presets
            </CardTitle>
            <CardDescription>
              Create and manage reusable hashtag collections for your posts
            </CardDescription>
          </div>

          <Dialog
            open={isCreateDialogOpen}
            onOpenChange={setIsCreateDialogOpen}
          >
            <DialogTrigger asChild>
              <Button size="sm">
                <Plus className="mr-2 h-4 w-4" />
                New Preset
              </Button>
            </DialogTrigger>
            <DialogContent>
              <DialogHeader>
                <DialogTitle>Create Hashtag Preset</DialogTitle>
                <DialogDescription>
                  Create a new hashtag preset to reuse across your posts
                </DialogDescription>
              </DialogHeader>

              <form onSubmit={handleCreateSubmit} className="space-y-4">
                <div className="space-y-2">
                  <Label htmlFor="create-name">Preset Name</Label>
                  <Input
                    id="create-name"
                    value={createForm.name}
                    onChange={(e) =>
                      setCreateForm((prev) => ({
                        ...prev,
                        name: e.target.value,
                      }))
                    }
                    placeholder="e.g., Tech Posts, Travel Content"
                    required
                    disabled={isSubmitting}
                  />
                </div>

                <div className="space-y-2">
                  <Label htmlFor="create-tags">Hashtags</Label>
                  <Textarea
                    id="create-tags"
                    value={createForm.tags}
                    onChange={(e) =>
                      setCreateForm((prev) => ({
                        ...prev,
                        tags: e.target.value,
                      }))
                    }
                    placeholder="#bitcoin #nostr #technology #coding"
                    required
                    disabled={isSubmitting}
                    rows={3}
                  />
                  <p className="text-xs text-muted-foreground">
                    Separate hashtags with spaces. Each hashtag should start
                    with #
                  </p>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="create-description">
                    Description (optional)
                  </Label>
                  <Input
                    id="create-description"
                    value={createForm.description}
                    onChange={(e) =>
                      setCreateForm((prev) => ({
                        ...prev,
                        description: e.target.value,
                      }))
                    }
                    placeholder="Brief description of when to use this preset"
                    disabled={isSubmitting}
                  />
                </div>

                <div className="flex justify-end gap-2">
                  <Button
                    type="button"
                    variant="outline"
                    onClick={() => setIsCreateDialogOpen(false)}
                    disabled={isSubmitting}
                  >
                    Cancel
                  </Button>
                  <Button type="submit" disabled={isSubmitting}>
                    {isSubmitting ? "Creating..." : "Create Preset"}
                  </Button>
                </div>
              </form>
            </DialogContent>
          </Dialog>
        </div>
      </CardHeader>

      <CardContent>
        {presets.length === 0 ? (
          <div className="py-8 text-center text-muted-foreground">
            <Hash className="mx-auto mb-4 h-12 w-12 opacity-50" />
            <p className="mb-2 text-lg font-medium">No hashtag presets yet</p>
            <p className="mb-4 text-sm">
              Create your first hashtag preset to organize and reuse hashtags
              across your posts
            </p>
            <Button onClick={() => setIsCreateDialogOpen(true)}>
              <Plus className="mr-2 h-4 w-4" />
              Create First Preset
            </Button>
          </div>
        ) : (
          <div className="space-y-4">
            {presets.map((preset) => (
              <div
                key={preset.id}
                className="flex items-start justify-between rounded-lg border p-4 transition-colors hover:bg-accent/50"
              >
                <div className="min-w-0 flex-1">
                  <div className="mb-2 flex items-center gap-2">
                    <h3 className="text-sm font-medium">{preset.name}</h3>
                    <Badge variant="secondary" className="text-xs">
                      {countHashtags(preset.tags)} tags
                    </Badge>
                  </div>

                  {preset.description ? (
                    <p className="mb-2 text-xs text-muted-foreground">
                      {preset.description}
                    </p>
                  ) : null}

                  <div className="flex flex-wrap gap-1">
                    {preset.tags
                      .split(/\s+/)
                      .filter((tag) => tag.startsWith("#") && tag.length > 1)
                      .map((tag, index) => (
                        <Badge
                          key={index}
                          variant="outline"
                          className="px-2 py-0 text-xs"
                        >
                          {tag}
                        </Badge>
                      ))}
                  </div>
                </div>

                <div className="ml-4 flex items-center gap-1">
                  <Button
                    size="sm"
                    variant="ghost"
                    onClick={() => openEditDialog(preset)}
                    disabled={isSubmitting}
                  >
                    <Edit2 className="h-4 w-4" />
                  </Button>
                  <Button
                    size="sm"
                    variant="ghost"
                    onClick={() => handleDelete(preset.id)}
                    disabled={isSubmitting}
                    className="text-destructive hover:text-destructive"
                  >
                    <Trash2 className="h-4 w-4" />
                  </Button>
                </div>
              </div>
            ))}
          </div>
        )}

        {fetcher.data?.success ? (
          <p className="mt-4 text-sm text-green-600">
            Hashtag preset updated successfully!
          </p>
        ) : null}
        {fetcher.data?.error ? (
          <p className="mt-4 text-sm text-destructive">{fetcher.data.error}</p>
        ) : null}
      </CardContent>

      {/* Edit Dialog */}
      <Dialog open={isEditDialogOpen} onOpenChange={setIsEditDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Edit Hashtag Preset</DialogTitle>
            <DialogDescription>Update your hashtag preset</DialogDescription>
          </DialogHeader>

          <form onSubmit={handleEditSubmit} className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="edit-name">Preset Name</Label>
              <Input
                id="edit-name"
                value={editForm.name}
                onChange={(e) =>
                  setEditForm((prev) => ({ ...prev, name: e.target.value }))
                }
                placeholder="e.g., Tech Posts, Travel Content"
                required
                disabled={isSubmitting}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="edit-tags">Hashtags</Label>
              <Textarea
                id="edit-tags"
                value={editForm.tags}
                onChange={(e) =>
                  setEditForm((prev) => ({ ...prev, tags: e.target.value }))
                }
                placeholder="#bitcoin #nostr #technology #coding"
                required
                disabled={isSubmitting}
                rows={3}
              />
              <p className="text-xs text-muted-foreground">
                Separate hashtags with spaces. Each hashtag should start with #
              </p>
            </div>

            <div className="space-y-2">
              <Label htmlFor="edit-description">Description (optional)</Label>
              <Input
                id="edit-description"
                value={editForm.description}
                onChange={(e) =>
                  setEditForm((prev) => ({
                    ...prev,
                    description: e.target.value,
                  }))
                }
                placeholder="Brief description of when to use this preset"
                disabled={isSubmitting}
              />
            </div>

            <div className="flex justify-end gap-2">
              <Button
                type="button"
                variant="outline"
                onClick={() => setIsEditDialogOpen(false)}
                disabled={isSubmitting}
              >
                Cancel
              </Button>
              <Button type="submit" disabled={isSubmitting}>
                {isSubmitting ? "Saving..." : "Save Changes"}
              </Button>
            </div>
          </form>
        </DialogContent>
      </Dialog>
    </Card>
  );
}

import { useFetcher } from "@remix-run/react";
import { useState, useEffect, useCallback } from "react";
import { toast } from "react-hot-toast";

import { getDynamicQueueStyle } from "~/features/posts/queueColors";
import type { QueueType } from "~/features/posts/types";
import { resizeImage } from "~/features/upload/image-resize";
import { useOptionalUser } from "~/lib/remix-utils";

interface PreparedEventData {
  content: string;
  type: "image";
  queueType: string;
}

interface ImagePostProps {
  files: File[];
  setFiles: React.Dispatch<React.SetStateAction<File[]>>;
  setShowImagePreview: (show: boolean) => void;
  setPreparedImageEvent: (data: PreparedEventData[]) => void;
  queueTypes?: (string | QueueType)[];
  onQueueTypeChange?: (queueType: string) => void;
}

export default function ImagePost({
  files,
  setFiles,
  setShowImagePreview,
  setPreparedImageEvent,
  queueTypes = [],
  onQueueTypeChange,
}: ImagePostProps) {
  interface FetcherData {
    success?: boolean;
    fileUrls?: { fileUrl: string; scheduledFor: string; queueType: string }[];
    error?: string;
  }

  const fetcher = useFetcher<FetcherData>();
  const user = useOptionalUser();

  const scheduleIntervals = user?.scheduleInterval;
  const [scheduledFor, setScheduledFor] = useState("");
  const [timeError, setTimeError] = useState("");
  const [isRecyclable, setIsRecyclable] = useState(false);

  // Determine initial queue selection - default to "unassigned"
  const getInitialQueue = () => {
    return "unassigned";
  };

  const [selectedQueue, setSelectedQueue] = useState(getInitialQueue());

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFiles = e.target.files ? Array.from(e.target.files) : [];

    // Process files to remove metadata for privacy
    try {
      const processedFiles = await Promise.all(
        selectedFiles.map(async (file) => {
          if (file.type.startsWith("image/")) {
            return await resizeImage(file);
          }
          return file;
        }),
      );
      setFiles((prev: File[]) => [...prev, ...processedFiles]);
    } catch (error) {
      const { handleAsyncErrorWithMessage } = await import("~/lib/error-handler.client");
      handleAsyncErrorWithMessage(
        error,
        "Error processing images. Using original files.",
        {
          component: "ImagePost",
          action: "handleFileChange",
        },
        false, // Don't show toast, we call toast.error instead
      );
      toast.error("Error processing images. Using original files.");
      setFiles((prev: File[]) => [...prev, ...selectedFiles]);
    }
  };

  const handleDrop = async (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    const droppedFiles = Array.from(e.dataTransfer.files);
    if (droppedFiles.length > 0) {
      // Check if files are images
      const imageFiles = droppedFiles.filter((file) =>
        file.type.startsWith("image/"),
      );
      if (imageFiles.length === 0) {
        toast.error("Please drop only image files");
        return;
      }

      // Process files to remove metadata for privacy
      try {
        const processedFiles = await Promise.all(
          imageFiles.map(async (file) => await resizeImage(file)),
        );
        setFiles((prev: File[]) => [...prev, ...processedFiles]);
      } catch (error) {
        const { handleAsyncErrorWithMessage } = await import("~/lib/error-handler.client");
        handleAsyncErrorWithMessage(
          error,
          "Error processing images. Using original files.",
          {
            component: "ImagePost",
            action: "handleDrop",
          },
          false, // Don't show toast, we call toast.error instead
        );
        toast.error("Error processing images. Using original files.");
        setFiles((prev: File[]) => [...prev, ...imageFiles]);
      }
    }
  };

  const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
  };

  const handleImagePreview = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();

    // Check if scheduledFor is empty
    if (!scheduledFor) {
      setTimeError("Please set a scheduled time before uploading");
      toast.error("Please set a scheduled time before uploading");
      return;
    }

    setTimeError("");
    const form = e.target as HTMLFormElement;
    const formData = new FormData(form);
    formData.set("_action", "upload-images-preview");
    formData.set("queueType", selectedQueue);
    // Set isRecyclable checkbox state
    if (isRecyclable) {
      formData.set("isRecyclable", "on");
    }

    // Remove any existing files from formData
    formData.delete("files");

    // Append each file individually to formData
    files.forEach((file) => {
      formData.append("files", file);
    });

    fetcher.submit(formData, {
      method: "post",
      encType: "multipart/form-data",
    });
  };

  const calculateQueueScheduleTime = useCallback(async (queueTypeName: string) => {
    if (queueTypeName === "unassigned") {
      setScheduledFor("");
      return;
    }

    // Find the queue type object to get its ID
    const selectedQueueType = queueTypes.find(qt => 
      (typeof qt === "string" ? qt : qt.name) === queueTypeName
    );
    const queueTypeId = typeof selectedQueueType === "object" ? selectedQueueType.id : null;

    try {
      const response = await fetch("/api/queue-schedule", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          queueTypeId,
          queueTypeName, // Keep for backward compatibility
          userId: user?.id,
        }),
      });

      if (response.ok) {
        const data = (await response.json()) as { scheduledTime?: string };
        const scheduledTime = data.scheduledTime;
        if (scheduledTime) {
          setScheduledFor(scheduledTime);
        }
        setTimeError("");
      }
    } catch (error) {
      console.error("Error calculating schedule time:", error);
    }
  }, [queueTypes, user?.id]);

  useEffect(() => {
    if (selectedQueue !== "unassigned") {
      void calculateQueueScheduleTime(selectedQueue);
    }
    // Notify parent component of queue type change
    if (onQueueTypeChange) {
      onQueueTypeChange(selectedQueue);
    }
  }, [selectedQueue, onQueueTypeChange, calculateQueueScheduleTime]);

  const handleScheduleIntervalClick = (intervalHours: string | number) => {
    // Find the currently selected queue type
    const selectedQueueType = queueTypes.find(qt => 
      (typeof qt === "string" ? qt : qt.name) === selectedQueue
    );

    // If this is a fixed slot queue, use the API to get the next scheduled time instead
    if (selectedQueueType && typeof selectedQueueType === "object" && selectedQueueType.scheduleType === "FIXED_SLOTS") {
      // For fixed slot queues, recalculate the schedule time instead of adding hours
      calculateQueueScheduleTime(selectedQueue);
      return;
    }

    const now = new Date();
    const intervalHoursNum = typeof intervalHours === "string" ? parseInt(intervalHours, 10) : intervalHours;
    const hoursLater = new Date(
      now.getTime() + intervalHoursNum * 60 * 60 * 1000,
    );

    // Format the date in the user's timezone
    const userTimezone = user?.timezone ?? "UTC";
    const formattedDate = hoursLater.toLocaleString("en-US", {
      timeZone: userTimezone,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      hour12: false,
    });

    // Parse the formatted date back into components
    const [datePart, timePart] = formattedDate.split(", ");
    const [month, day, year] = datePart.split("/");
    const [hours, minutes] = timePart.split(":");

    // Create the datetime-local format (YYYY-MM-DDTHH:mm)
    const formattedForInput = `${year}-${month}-${day}T${hours}:${minutes}`;

    setScheduledFor(formattedForInput);
    setTimeError("");
  };

  // Handle fetcher success data
  if (fetcher.data?.success && fetcher.data?.fileUrls) {
    toast.success("Images uploaded successfully!");

    const preparedData: PreparedEventData[] = fetcher.data.fileUrls.map((url: { fileUrl: string; scheduledFor: string; queueType: string }) => {
      return {
        content: url.fileUrl,
        type: "image",
        queueType: url.queueType || selectedQueue, // Include queue type information
      };
    });

    setShowImagePreview(true);
    setPreparedImageEvent(preparedData);
    setFiles([]);
  }

  // Add error handling
  if (fetcher.data?.success === false && fetcher.data?.error) {
    toast.error(fetcher.data.error);
  }

  const isUploaded = Boolean(fetcher.data?.success && fetcher.data?.fileUrls);

  return (
    <fetcher.Form
      method="post"
      className="w-full"
      encType="multipart/form-data"
      onSubmit={handleImagePreview}
    >
      <input type="hidden" name="_action" value="upload-images-preview" />
      <label
        className={`block ${isUploaded ? "cursor-not-allowed" : "cursor-pointer"}`}
      >
        <input
          type="file"
          name="files"
          className="hidden"
          accept="image/*"
          multiple
          onChange={handleFileChange}
          disabled={fetcher.state !== "idle" || isUploaded}
        />
        <div
          className={`rounded-lg border-2 border-dashed border-gray-300 p-12 text-center ${!isUploaded && "hover:border-gray-400"}`}
          onDrop={!isUploaded ? handleDrop : undefined}
          onDragOver={!isUploaded ? handleDragOver : undefined}
        >
          {files.length > 0 ? (
            <div className="flex flex-wrap gap-4">
              {files.map((file, index) => (
                <div key={index} className="relative">
                  <img
                    src={URL.createObjectURL(file)}
                    alt="Preview"
                    className="h-32 w-32 object-cover"
                  />
                  <button
                    type="button"
                    onClick={() =>
                      setFiles(files.filter((_, i) => i !== index))
                    }
                    className="absolute -right-2 -top-2 rounded-full bg-red-500 p-1 text-white hover:bg-red-600"
                    disabled={fetcher.state !== "idle"}
                  >
                    ×
                  </button>
                </div>
              ))}
              <div className="flex h-32 w-32 items-center justify-center border-2 border-dashed border-gray-300 hover:border-gray-400">
                <span className="text-4xl text-gray-500">+</span>
              </div>
            </div>
          ) : (
            <div className="flex flex-col items-center gap-4">
              <div className="text-green-500">
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  className="h-12 w-12"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12"
                  />
                </svg>
              </div>
              <div>
                <p className="text-xl font-medium text-gray-900 dark:text-gray-100">
                  Click to upload or drag and drop
                </p>
                <p className="mt-1 text-sm text-gray-500">
                  Multiple images (max 100MB total)
                </p>
              </div>
            </div>
          )}
        </div>
      </label>
      <div className="mt-4">
        <textarea
          name="caption"
          className="w-full rounded-lg border p-4 text-gray-900"
          placeholder="Add a caption to your image(s)..."
          rows={3}
          disabled={fetcher.state !== "idle" || isUploaded}
        />
      </div>
      <div className="mt-4 flex items-center justify-between gap-4">
        <div className="flex flex-col gap-2">
          <div className="mb-2">
            <label htmlFor="queue-type-selector" className="mb-2 block text-sm font-medium text-gray-700 dark:text-gray-300">
              Queue Type
            </label>
            <div className="flex flex-wrap gap-2">
              {/* Unassigned option */}
              <button
                type="button"
                onClick={() => setSelectedQueue("unassigned")}
                disabled={fetcher.state !== "idle" || isUploaded}
                className={`rounded-full px-4 py-2 text-sm ${getDynamicQueueStyle(null, selectedQueue === "unassigned")} disabled:cursor-not-allowed disabled:opacity-50`}
              >
                Unassigned
              </button>

              {/* Queue types */}
              {queueTypes
                .filter((queue) => {
                  const isEnabled =
                    typeof queue === "object"
                      ? queue.isEnabled !== false
                      : true;
                  return isEnabled;
                })
                .map((queue) => {
                  const queueName =
                    typeof queue === "string" ? queue : queue.name;
                  const queueColor =
                    typeof queue === "object" ? queue.color : null;
                  return (
                    <button
                      key={queueName}
                      type="button"
                      onClick={() => setSelectedQueue(queueName ?? "")}
                      disabled={fetcher.state !== "idle" || isUploaded}
                      className={`rounded-full px-4 py-2 text-sm ${getDynamicQueueStyle(queueColor ?? null, selectedQueue === queueName)} disabled:cursor-not-allowed disabled:opacity-50`}
                      style={{
                        backgroundColor: queueColor || undefined,
                        borderColor: queueColor || undefined,
                      }}
                    >
                      {queueName}
                    </button>
                  );
                })}
            </div>
            <input type="hidden" name="queueType" value={selectedQueue} />
          </div>
          <div className="mb-2 flex items-center gap-2">
            <input
              type="checkbox"
              id="isRecyclable"
              name="isRecyclable"
              checked={isRecyclable}
              onChange={(e) => setIsRecyclable(e.target.checked)}
              disabled={fetcher.state !== "idle" || isUploaded}
              className="h-4 w-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500"
            />
            <label
              htmlFor="isRecyclable"
              className="text-sm text-gray-700 dark:text-gray-300"
            >
              Make this post recyclable
            </label>
          </div>
          <div className="flex items-center gap-4">
            <input
              type="datetime-local"
              name="scheduledFor"
              value={scheduledFor}
              onChange={(e) => {
                setScheduledFor(e.target.value);
                setTimeError("");
              }}
              className={`rounded-md border ${timeError ? "border-red-500" : "border-gray-300"} p-2 text-gray-900`}
              disabled={fetcher.state !== "idle" || isUploaded}
            />
          </div>
          {timeError ? (
            <p className="text-sm text-red-500">{timeError}</p>
          ) : null}
          <div className="flex flex-wrap gap-2">
            {(() => {
              // Find the currently selected queue type
              const selectedQueueType = queueTypes.find(qt => 
                (typeof qt === "string" ? qt : qt.name) === selectedQueue
              );

              // For fixed slot queues, show a different UI
              if (selectedQueueType && typeof selectedQueueType === "object" && selectedQueueType.scheduleType === "FIXED_SLOTS") {
                return (
                  <button
                    type="button"
                    onClick={() => calculateQueueScheduleTime(selectedQueue)}
                    className="rounded-md bg-blue-100 px-2.5 py-1.5 text-xs font-medium text-blue-700 hover:bg-blue-200 dark:bg-blue-800 dark:text-blue-300 dark:hover:bg-blue-700"
                    disabled={fetcher.state !== "idle" || isUploaded}
                  >
                    Next Slot
                  </button>
                );
              }

              // For interval-based queues, show the hour buttons
              return scheduleIntervals
                ? scheduleIntervals.map((interval) => (
                    <button
                      key={interval}
                      type="button"
                      onClick={() => handleScheduleIntervalClick(interval)}
                      className="rounded-md bg-gray-100 px-2.5 py-1.5 text-xs font-medium text-gray-700 hover:bg-gray-200 dark:bg-gray-800 dark:text-gray-300 dark:hover:bg-gray-700"
                      disabled={fetcher.state !== "idle" || isUploaded}
                    >
                      +{interval}h
                    </button>
                  ))
                : null;
            })()
            }
          </div>
        </div>
        <button
          type="submit"
          className="rounded-lg bg-green-500 px-8 py-4 text-white hover:bg-green-600 disabled:opacity-50"
          disabled={
            fetcher.state !== "idle" || isUploaded || files.length === 0
          }
        >
          {fetcher.state !== "idle" ? "Uploading..." : "Upload Images →"}
        </button>
      </div>
    </fetcher.Form>
  );
}

import { useFetcher, Link } from "@remix-run/react";
import { useState } from "react";

import { Badge } from "~/components/ui/badge";
import { Button } from "~/components/ui/button";
import type { EditorJSBlock } from "~/features/posts/types/editorjs.types";
import { handleErrorSafely } from "~/lib/error-handler.client";
import type { LongFormPost } from "~/models/longformpost.server";
interface LongFormDetailsModalProps {
  post: LongFormPost;
  onClose: () => void;
  type: "draft" | "scheduled" | "posted";
  showSignedEvent?: boolean;
  userTimezone?: string;
}

export default function LongFormDetailsModal({
  post,
  onClose,
  type,
  showSignedEvent = false,
  userTimezone = "UTC",
}: LongFormDetailsModalProps) {
  const [showEventData, setShowEventData] = useState(false);
  const deleteFetcher = useFetcher();

  const convertEditorJSToHTML = (content: string) => {
    if (!content || content.trim() === "") {
      return '<p class="text-gray-500 italic">No content available</p>';
    }

    try {
      const editorData = JSON.parse(content) as { blocks?: EditorJSBlock[] };

      if (!editorData.blocks || !Array.isArray(editorData.blocks)) {
        return '<p class="text-gray-500 italic">No content blocks found</p>';
      }

      let html = "";

      editorData.blocks.forEach((block: EditorJSBlock) => {
        switch (block.type) {
          case "header": {
            const levelValue = block.data.level;
            const level = typeof levelValue === "number" ? levelValue : 3;
            const levelStr = String(level);
            const textValue = block.data.text;
            const text = typeof textValue === "string" ? textValue : "";
            html += `<h${levelStr} class="text-${level === 2 ? "2xl" : level === 3 ? "xl" : "lg"} font-bold mb-4 text-gray-900 dark:text-white">${text}</h${levelStr}>`;
            break;
          }
          case "paragraph": {
            const textValue = block.data.text;
            const text = typeof textValue === "string" ? textValue : "";
            html += `<p class="mb-4 text-gray-700 dark:text-gray-300 leading-relaxed">${text}</p>`;
            break;
          }
          case "list": {
            const listType = block.data.style === "ordered" ? "ol" : "ul";
            const listClass =
              block.data.style === "ordered" ? "list-decimal" : "list-disc";
            html += `<${listType} class="${listClass} ml-6 mb-4 text-gray-700 dark:text-gray-300">`;
            if (Array.isArray(block.data.items)) {
              block.data.items.forEach((item: string) => {
                html += `<li class="mb-1">${item}</li>`;
              });
            }
            html += `</${listType}>`;
            break;
          }
          case "quote": {
            const textValue = block.data.text;
            const text = typeof textValue === "string" ? textValue : "";
            const captionValue = block.data.caption;
            const caption = typeof captionValue === "string" ? captionValue : "";
            html += `<blockquote class="border-l-4 border-blue-500 pl-4 py-2 mb-4 italic text-gray-600 dark:text-gray-400 bg-gray-50 dark:bg-gray-800 rounded-r">
              <p>${text}</p>
              ${caption ? `<footer class="text-sm mt-2">— ${caption}</footer>` : ""}
            </blockquote>`;
            break;
          }
          case "code": {
            const codeValue = block.data.code;
            const code = typeof codeValue === "string" ? codeValue : "";
            html += `<pre class="bg-gray-900 dark:bg-gray-800 text-green-400 p-4 rounded-lg mb-4 overflow-x-auto"><code>${code}</code></pre>`;
            break;
          }
          case "linkTool": {
            const link = typeof block.data.link === "string" ? block.data.link : "";
            const meta = block.data.meta && typeof block.data.meta === "object" ? block.data.meta as { title?: string; description?: string } : null;
            html += `<div class="border border-gray-200 dark:border-gray-700 rounded-lg p-4 mb-4">
              <a href="${link}" target="_blank" rel="noopener noreferrer" class="text-blue-600 dark:text-blue-400 hover:underline">
                <div class="font-semibold">${meta?.title ?? link}</div>
                ${meta?.description ? `<div class="text-gray-600 dark:text-gray-400 text-sm mt-1">${meta.description}</div>` : ""}
              </a>
            </div>`;
            break;
          }
          case "embed": {
            const embed = typeof block.data.embed === "string" ? block.data.embed : "";
            html += `<div class="mb-4">
              <iframe src="${embed}" class="w-full aspect-video rounded-lg" frameborder="0" allowfullscreen></iframe>
            </div>`;
            break;
          }
          case "image": {
            const file = block.data.file && typeof block.data.file === "object" ? block.data.file as { url?: string } : null;
            const url = typeof block.data.url === "string" ? block.data.url : "";
            const imageUrl = file?.url ?? url;
            const caption = typeof block.data.caption === "string" ? block.data.caption : "";
            if (imageUrl) {
              html += `<figure class="mb-6">
                <img src="${imageUrl}" alt="${caption}" class="w-full rounded-lg shadow-sm" style="max-height: 500px; object-fit: contain;" />
                ${caption ? `<figcaption class="text-center text-sm text-gray-600 dark:text-gray-400 mt-2 italic">${caption}</figcaption>` : ""}
              </figure>`;
            }
            break;
          }
          default:
            if (typeof block.data.text === "string") {
              html += `<p class="mb-4 text-gray-700 dark:text-gray-300">${block.data.text}</p>`;
            } else {
              const file = block.data.file && typeof block.data.file === "object" ? block.data.file as { url?: string } : null;
              if (file?.url) {
                // Handle any other block types that might have images
                html += `<div class="mb-4">
                  <img src="${file.url}" alt="" class="w-full rounded-lg" style="max-height: 400px; object-fit: contain;" />
                </div>`;
              }
            }
        }
      });

      return (
        html ||
        '<p class="text-gray-500 italic">Content could not be rendered</p>'
      );
    } catch (error) {
      handleErrorSafely(error, {
        component: "LongFormDetailsModal",
        action: "parseEditorJSContent",
      });
      // Try to display as plain text if JSON parsing fails
      const plainTextContent = content.replace(/<[^>]*>/g, "");
      return `<p class="text-gray-700 dark:text-gray-300">${plainTextContent || "Content parsing failed"}</p>`;
    }
  };

  const formatDate = (dateInput?: string | Date | number) => {
    if (!dateInput) return "—";

    let date: Date;

    // Handle different input formats
    if (typeof dateInput === "string") {
      // Check if it's a Unix timestamp string
      const unixTimestamp = parseInt(dateInput);
      if (!isNaN(unixTimestamp) && dateInput.length <= 13) {
        // Unix timestamp (seconds or milliseconds)
        date = new Date(unixTimestamp * (dateInput.length <= 10 ? 1000 : 1));
      } else {
        // ISO string
        date = new Date(dateInput);
      }
    } else if (typeof dateInput === "number") {
      // Unix timestamp (seconds or milliseconds)
      date = new Date(
        dateInput * (dateInput.toString().length <= 10 ? 1000 : 1),
      );
    } else {
      // Date object
      date = new Date(dateInput);
    }

    return date.toLocaleString("en-US", {
      timeZone: userTimezone,
      month: "2-digit",
      day: "2-digit",
      year: "numeric",
      hour: "numeric",
      minute: "2-digit",
      hour12: true,
    });
  };

  const getReadingTime = (content?: string) => {
    if (!content) return "0 min read";

    try {
      let wordCount = 0;

      // If it's JSON (EditorJS format), extract text from blocks
      if (content.startsWith("{")) {
        const editorData = JSON.parse(content) as { blocks?: EditorJSBlock[] };
        editorData.blocks?.forEach((block: EditorJSBlock) => {
          if (block.type === "paragraph" || block.type === "header") {
            const text = typeof block.data.text === "string" ? block.data.text.replace(/<[^>]*>/g, "") : "";
            wordCount += text
              .split(/\s+/)
              .filter((word: string) => word.length > 0).length;
          } else if (block.type === "list") {
            const items = Array.isArray(block.data.items) ? block.data.items : [];
            items.forEach((item: unknown) => {
              const text = typeof item === "string" ? item.replace(/<[^>]*>/g, "") : "";
              wordCount += text
                .split(/\s+/)
                .filter((word: string) => word.length > 0).length;
            });
          }
        });
      } else {
        // Plain text or markdown
        const text = content.replace(/<[^>]*>/g, "");
        wordCount = text.split(/\s+/).filter((word) => word.length > 0).length;
      }

      const readingTime = Math.ceil(wordCount / 200); // Average 200 words per minute
      return `${readingTime} min read`;
    } catch {
      return "— min read";
    }
  };

  const getStatusBadge = () => {
    if (type === "draft") {
      return (
        <Badge
          variant="secondary"
          className="bg-orange-100 text-orange-900 dark:bg-orange-700/10 dark:text-orange-200"
        >
          Draft
        </Badge>
      );
    } else if (type === "scheduled") {
      return (
        <Badge
          variant="secondary"
          className="bg-blue-100 text-blue-900 dark:bg-blue-700/10 dark:text-blue-200"
        >
          Scheduled
        </Badge>
      );
    } else {
      return (
        <Badge
          variant="secondary"
          className="bg-green-100 text-green-900 dark:bg-green-700/10 dark:text-green-200"
        >
          Published
        </Badge>
      );
    }
  };

  const getModalTitle = () => {
    if (type === "draft") return "Draft Article";
    if (type === "scheduled") return "Scheduled Article";
    return "Published Article";
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm">
      <div className="mx-4 flex max-h-[90vh] w-full max-w-5xl flex-col overflow-hidden rounded-xl bg-white shadow-2xl dark:bg-gray-900">
        {/* Header */}
        <div className="sticky top-0 z-10 border-b border-gray-200 bg-white/95 px-6 py-4 backdrop-blur-sm dark:border-gray-700 dark:bg-gray-900/95">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <h2 className="text-xl font-semibold text-gray-900 dark:text-white">
                {getModalTitle()}
              </h2>
              {getStatusBadge()}
            </div>
            <button
              onClick={onClose}
              className="flex h-8 w-8 items-center justify-center rounded-full text-gray-400 transition-colors hover:bg-gray-100 hover:text-gray-600 dark:hover:bg-gray-800 dark:hover:text-gray-300"
            >
              ✕
            </button>
          </div>
        </div>

        {/* Content */}
        <div className="flex flex-1 overflow-hidden">
          {/* Preview Panel */}
          <div className="flex-1 overflow-y-auto">
            {/* Article Preview - Primal/NOSTR style */}
            <div className="mx-auto max-w-3xl p-6">
              {/* Author Header */}
              <div className="mb-4 flex items-center gap-3">
                <div className="flex h-12 w-12 items-center justify-center rounded-full bg-gradient-to-br from-blue-500 to-purple-600 text-lg font-semibold text-white">
                  A
                </div>
                <div>
                  <div className="font-semibold text-gray-900 dark:text-white">
                    You
                  </div>
                </div>
                <div className="ml-auto">
                  <svg
                    className="h-6 w-6 text-gray-400"
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M12 5v.01M12 12v.01M12 19v.01M12 6a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2z"
                    />
                  </svg>
                </div>
              </div>

              {/* Date and Reading Time */}
              <div className="mb-4 flex items-center gap-2 text-sm text-gray-500 dark:text-gray-400">
                <span>
                  {formatDate(
                    type === "posted"
                      ? (post.publishedAt || undefined)
                      : type === "scheduled"
                        ? (post.scheduledFor || undefined)
                        : (post.createdAt || undefined),
                  )}
                </span>
                <span>•</span>
                <span>{getReadingTime(post.content || undefined)}</span>
                <span>•</span>
                <span>via SmartFlow</span>
                <div className="ml-auto">
                  <svg
                    className="h-5 w-5"
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z"
                    />
                  </svg>
                </div>
              </div>

              {/* Title */}
              <h1 className="mb-6 text-3xl font-bold leading-tight text-gray-900 dark:text-white">
                {post.title || "Untitled Article"}
              </h1>

              {/* Cover Image */}
              {post.image ? (
                <div className="mb-6 overflow-hidden rounded-2xl">
                  <img
                    src={post.image}
                    alt="Cover"
                    className="h-80 w-full object-cover"
                  />
                </div>
              ) : null}

              {/* Summary */}
              {post.summary ? (
                <div className="mb-6 rounded-xl bg-gray-50 p-6 dark:bg-gray-800">
                  <p className="text-lg font-medium leading-relaxed text-gray-700 dark:text-gray-300">
                    {post.summary}
                  </p>
                </div>
              ) : null}

              {/* Content */}
              <div
                className="prose prose-lg dark:prose-invert max-w-none text-gray-900 dark:text-white"
                style={{
                  fontSize: "1.1rem",
                  lineHeight: "1.7",
                  color: "inherit",
                }}
                dangerouslySetInnerHTML={{
                  __html: convertEditorJSToHTML(post.content || ""),
                }}
              />

              {/* Tags */}
              {post.tags && post.tags.length > 0 ? (
                <div className="mt-8 flex items-center gap-2 border-t border-gray-200 pt-6 dark:border-gray-700">
                  {post.tags.map((tag) => (
                    <span
                      key={tag}
                      className="cursor-pointer text-sm text-blue-600 hover:underline dark:text-blue-400"
                    >
                      #{tag}
                    </span>
                  ))}
                </div>
              ) : null}
            </div>
          </div>

          {/* Details Sidebar */}
          <div className="w-80 overflow-y-auto border-l border-gray-200 dark:border-gray-700">
            <div className="space-y-6 p-6">
              <div>
                <h3 className="mb-3 text-sm font-medium text-gray-700 dark:text-gray-300">
                  Article Details
                </h3>
                <div className="space-y-4">
                  <div>
                    <span className="text-xs text-gray-500 dark:text-gray-400">
                      Status
                    </span>
                    <div className="mt-1">{getStatusBadge()}</div>
                  </div>

                  <div>
                    <span className="text-xs text-gray-500 dark:text-gray-400">
                      {type === "posted"
                        ? "Published"
                        : type === "scheduled"
                          ? "Scheduled For"
                          : "Created"}
                    </span>
                    <p className="mt-1 text-sm text-gray-900 dark:text-white">
                      {formatDate(
                        type === "posted"
                          ? (post.publishedAt || undefined)
                          : type === "scheduled"
                            ? (post.scheduledFor || undefined)
                            : (post.createdAt || undefined),
                      )}
                    </p>
                  </div>

                  <div>
                    <span className="text-xs text-gray-500 dark:text-gray-400">
                      Reading Time
                    </span>
                    <p className="mt-1 text-sm text-gray-900 dark:text-white">
                      {getReadingTime(post.content || undefined)}
                    </p>
                  </div>

                  {post.tags && post.tags.length > 0 ? (
                    <div>
                      <span className="text-xs text-gray-500 dark:text-gray-400">
                        Tags
                      </span>
                      <div className="mt-1 flex flex-wrap gap-1">
                        {post.tags.map((tag) => (
                          <span
                            key={tag}
                            className="rounded bg-gray-100 px-2 py-1 text-xs text-gray-700 dark:bg-gray-800 dark:text-gray-300"
                          >
                            #{tag}
                          </span>
                        ))}
                      </div>
                    </div>
                  ) : null}
                </div>
              </div>

              {/* Signed Event Data */}
              {showSignedEvent && post.signedEvent ? (
                <div>
                  <div className="mb-3 flex items-center justify-between">
                    <h3 className="text-sm font-medium text-gray-700 dark:text-gray-300">
                      Signed Event Data
                    </h3>
                    <button
                      onClick={() => setShowEventData(!showEventData)}
                      className="text-xs text-blue-600 hover:underline dark:text-blue-400"
                    >
                      {showEventData ? "Hide" : "Show"}
                    </button>
                  </div>
                  {showEventData ? (
                    <div className="rounded-lg bg-gray-100 p-3 dark:bg-gray-800">
                      <pre className="max-h-64 overflow-auto whitespace-pre-wrap break-words text-xs text-gray-800 dark:text-gray-200">
                        {JSON.stringify(post.signedEvent, null, 2)}
                      </pre>
                    </div>
                  ) : null}
                </div>
              ) : null}
            </div>
          </div>
        </div>

        {/* Footer */}
        <div className="sticky bottom-0 border-t border-gray-200 bg-white/95 px-6 py-4 backdrop-blur-sm dark:border-gray-700 dark:bg-gray-900/95">
          <div className="flex items-center justify-between">
            <div className="flex gap-3">
              {type === "posted" &&
                (post.nostrEventId || (post.signedEvent && typeof post.signedEvent === "object" && "id" in post.signedEvent ? (post.signedEvent as { id?: string }).id : undefined)) ? (
                <Link
                  to={`https://primal.net/a/${post.nostrEventId || (post.signedEvent && typeof post.signedEvent === "object" && "id" in post.signedEvent ? (post.signedEvent as { id?: string }).id : "")}`}
                  target="_blank"
                  rel="noreferrer"
                  className="inline-flex items-center rounded-lg bg-gray-900 px-4 py-2 text-sm font-medium text-white transition-colors hover:bg-gray-800 focus:outline-none focus:ring-2 focus:ring-gray-500 focus:ring-offset-2 dark:bg-gray-700 dark:hover:bg-gray-600"
                >
                  View Article
                </Link>
              ) : null}

              {type === "draft" ? (
                <Link
                  to={`/dashboard/drafts/longform/edit/${post.id}`}
                  className="inline-flex items-center rounded-lg border border-blue-200 bg-white px-4 py-2 text-sm font-medium text-blue-800 transition-colors hover:bg-blue-50 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 dark:border-blue-700 dark:bg-gray-800 dark:text-blue-300 dark:hover:bg-blue-950/50"
                >
                  Edit Draft
                </Link>
              ) : null}
            </div>

            <div className="flex gap-3">
              <deleteFetcher.Form
                method="post"
                onClick={(e) => e.stopPropagation()}
              >
                <input type="hidden" name="postId" value={post.id} />
                <input type="hidden" name="_action" value="deleteLongForm" />
                <button
                  type="submit"
                  disabled={deleteFetcher.state !== "idle"}
                  className="inline-flex items-center rounded-lg border border-red-300 bg-white px-4 py-2 text-sm font-medium text-red-700 transition-colors hover:bg-red-50 focus:outline-none focus:ring-2 focus:ring-red-500 focus:ring-offset-2 disabled:opacity-50 dark:border-red-600 dark:bg-gray-800 dark:text-red-400 dark:hover:bg-red-950/50"
                >
                  {deleteFetcher.state !== "idle" &&
                    deleteFetcher.formData?.get("postId") === post.id
                    ? "Deleting..."
                    : "Delete"}
                </button>
              </deleteFetcher.Form>

              <Button onClick={onClose}>Close</Button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useFetcher, Link } from "@remix-run/react";
import type { FetcherWithComponents } from "@remix-run/react";
import { useState, useEffect } from "react";

import type { PostFetcher } from "~/features/posts/types";
// Helper to safely access formData from a fetcher
function getFetcherFormData(fetcher: PostFetcher | undefined): FormData | null | undefined {
  return (fetcher as { formData?: FormData | null })?.formData;
}
import type { EditorJSBlock } from "~/features/posts/types/editorjs.types";
import type { LongFormPost } from "~/models/longformpost.server";

interface LongFormListingProps {
  posts: LongFormPost[];
  type: "draft" | "scheduled" | "posted";
  onPostSelect?: (post: LongFormPost) => void;
  searchTerm?: string;
  onSearchChange?: (term: string) => void;
  userTimezone?: string;
  longformRepostFetcher?: PostFetcher;
  longformQuoteFetcher?: PostFetcher;
  onEditPost?: (post: LongFormPost) => void;
  onReschedulePost?: (post: LongFormPost) => void;
}

export default function LongFormListing({
  posts,
  type,
  onPostSelect,
  searchTerm = "",
  onSearchChange,
  userTimezone = "UTC",
  longformRepostFetcher,
  longformQuoteFetcher,
  onEditPost,
  onReschedulePost,
}: LongFormListingProps) {
  const [sortConfig, setSortConfig] = useState({
    key:
      type === "posted"
        ? "publishedAt"
        : type === "scheduled"
          ? "scheduledFor"
          : "createdAt",
    direction:
      type === "posted" ? "desc" : type === "scheduled" ? "asc" : "desc",
  });
  const [selectedPosts, setSelectedPosts] = useState(new Set<string>());
  const [countdowns, setCountdowns] = useState<Record<string, string>>({});
  const deleteFetcher = useFetcher();
  interface BulkDeleteFetcherData {
    success?: boolean;
  }
  const bulkDeleteFetcher = useFetcher<BulkDeleteFetcherData>();

  const sortedPosts = [...posts].sort((a, b) => {
    let aValue, bValue;

    if (sortConfig.key === "publishedAt") {
      aValue = a.publishedAt ? new Date(a.publishedAt).getTime() : 0;
      bValue = b.publishedAt ? new Date(b.publishedAt).getTime() : 0;
    } else if (sortConfig.key === "scheduledFor") {
      // Handle scheduledFor as Unix timestamp string
      aValue = a.scheduledFor ? parseInt(a.scheduledFor) * 1000 : 0;
      bValue = b.scheduledFor ? parseInt(b.scheduledFor) * 1000 : 0;
    } else if (sortConfig.key === "createdAt") {
      aValue = new Date(a.createdAt).getTime();
      bValue = new Date(b.createdAt).getTime();
    } else {
      const aVal = a[sortConfig.key as keyof LongFormPost];
      const bVal = b[sortConfig.key as keyof LongFormPost];

      if (typeof aVal === "string" && typeof bVal === "string") {
        return sortConfig.direction === "asc"
          ? aVal.localeCompare(bVal)
          : bVal.localeCompare(aVal);
      }

      aValue = typeof aVal === "number" ? aVal : 0;
      bValue = typeof bVal === "number" ? bVal : 0;
    }

    return sortConfig.direction === "asc" ? aValue - bValue : bValue - aValue;
  });

  const filteredPosts = sortedPosts.filter(
    (post) =>
      post.title?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      post.summary?.toLowerCase().includes(searchTerm.toLowerCase()),
  );

  const requestSort = (key: string) => {
    setSortConfig((current) => ({
      key,
      direction:
        current.key === key && current.direction === "asc" ? "desc" : "asc",
    }));
  };

  const formatDate = (dateInput?: string | Date | number) => {
    if (!dateInput) return "—";

    let date: Date;

    // Handle different input formats
    if (typeof dateInput === "string") {
      // Check if it's a Unix timestamp string
      const unixTimestamp = parseInt(dateInput);
      if (!isNaN(unixTimestamp) && dateInput.length <= 13) {
        // Unix timestamp (seconds or milliseconds)
        date = new Date(unixTimestamp * (dateInput.length <= 10 ? 1000 : 1));
      } else {
        // ISO string
        date = new Date(dateInput);
      }
    } else if (typeof dateInput === "number") {
      // Unix timestamp (seconds or milliseconds)
      date = new Date(
        dateInput * (dateInput.toString().length <= 10 ? 1000 : 1),
      );
    } else {
      // Date object
      date = new Date(dateInput);
    }

    return date.toLocaleString("en-US", {
      timeZone: userTimezone,
      month: "2-digit",
      day: "2-digit",
      year: "numeric",
      hour: "numeric",
      minute: "2-digit",
      hour12: true,
    });
  };

  const getReadingTime = (content?: string) => {
    if (!content) return "0 min read";

    try {
      let wordCount = 0;

      // If it's JSON (EditorJS format), extract text from blocks
      if (content.startsWith("{")) {
        const editorData = JSON.parse(content) as { blocks?: EditorJSBlock[] };
        editorData.blocks?.forEach((block: EditorJSBlock) => {
          if (block.type === "paragraph" || block.type === "header") {
            const text = typeof block.data.text === "string" ? block.data.text.replace(/<[^>]*>/g, "") : "";
            wordCount += text
              .split(/\s+/)
              .filter((word: string) => word.length > 0).length;
          } else if (block.type === "list") {
            const items = Array.isArray(block.data.items) ? block.data.items : [];
            items.forEach((item: unknown) => {
              const text = typeof item === "string" ? item.replace(/<[^>]*>/g, "") : "";
              wordCount += text
                .split(/\s+/)
                .filter((word: string) => word.length > 0).length;
            });
          }
        });
      } else {
        // Plain text or markdown
        const text = content.replace(/<[^>]*>/g, "");
        wordCount = text.split(/\s+/).filter((word) => word.length > 0).length;
      }

      const readingTime = Math.ceil(wordCount / 200); // Average 200 words per minute
      return `${readingTime} min read`;
    } catch {
      return "— min read";
    }
  };

  const togglePostSelection = (postId: string) => {
    setSelectedPosts((prev) => {
      const newSet = new Set(prev);
      if (newSet.has(postId)) {
        newSet.delete(postId);
      } else {
        newSet.add(postId);
      }
      return newSet;
    });
  };

  const toggleSelectAll = () => {
    if (selectedPosts.size === filteredPosts.length) {
      setSelectedPosts(new Set());
    } else {
      setSelectedPosts(new Set(filteredPosts.map((post) => post.id)));
    }
  };

  const handleBulkDelete = () => {
    if (selectedPosts.size === 0) return;

    const formData = new FormData();
    formData.append("_action", "bulkDeleteLongForm");
    formData.append("postIds", JSON.stringify(Array.from(selectedPosts)));

    bulkDeleteFetcher.submit(formData, { method: "post" });
  };

  // Countdown functionality for scheduled posts
  useEffect(() => {
    if (type !== "scheduled") return;

    const updateCountdowns = () => {
      // Get current time in user's timezone
      const now = new Date(
        new Date().toLocaleString("en-US", { timeZone: userTimezone }),
      ).getTime();
      const newCountdowns: Record<string, string> = {};

      posts.forEach((post) => {
        if (!post.scheduledFor) return;

        // Handle scheduledFor as Unix timestamp string (similar to regular posts)
        const utcTime = parseInt(post.scheduledFor) * 1000;
        const userTime = new Date(utcTime).toLocaleString("en-US", {
          timeZone: userTimezone,
        });
        const scheduledTime = new Date(userTime).getTime();

        const distance = scheduledTime - now;

        if (distance > 0) {
          const days = Math.floor(distance / (1000 * 60 * 60 * 24));
          const hours = Math.floor(
            (distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60),
          );
          const minutes = Math.floor(
            (distance % (1000 * 60 * 60)) / (1000 * 60),
          );

          newCountdowns[post.id] = `${days}d ${hours}h ${minutes}m`;
        } else {
          newCountdowns[post.id] = "Due now";
        }
      });

      setCountdowns(newCountdowns);
    };

    // Update immediately on mount
    updateCountdowns();

    const timer = setInterval(updateCountdowns, 60000); // Update every minute

    return () => clearInterval(timer);
  }, [posts, userTimezone, type]);

  useEffect(() => {
    if (bulkDeleteFetcher.data?.success) {
      setSelectedPosts(new Set());
    }
  }, [bulkDeleteFetcher.data]);

  const getStatusBadge = (post: LongFormPost) => {
    if (type === "draft") {
      return (
        <div className="inline-flex rounded-full border border-transparent bg-orange-100 px-2 py-1 text-xs font-semibold leading-4 text-orange-900 dark:border-orange-900/75 dark:bg-orange-700/10 dark:text-orange-200">
          Draft
        </div>
      );
    } else if (type === "scheduled") {
      return (
        <div className="inline-flex rounded-full border border-transparent bg-blue-100 px-2 py-1 text-xs font-semibold leading-4 text-blue-900 dark:border-blue-900/75 dark:bg-blue-700/10 dark:text-blue-200">
          Scheduled
        </div>
      );
    } else {
      return (
        <div className="inline-flex rounded-full border border-transparent bg-green-100 px-2 py-1 text-xs font-semibold leading-4 text-green-900 dark:border-green-900/75 dark:bg-green-700/10 dark:text-green-200">
          Published
        </div>
      );
    }
  };

  return (
    <div>
      {/* Search Bar */}
      {onSearchChange ? (
        <div className="mb-5 mt-5 flex flex-col gap-3 text-center sm:flex-row sm:items-center sm:justify-between sm:text-left">
          <div>
            <h4 className="text-sm font-medium text-gray-500 dark:text-gray-400">
              You have{" "}
              <span className="text-blue-600 dark:text-blue-400">
                {filteredPosts.length} longform {type} posts
              </span>
            </h4>
          </div>
          <div className="flex items-center gap-2">
            <div className="relative w-full">
              <div className="pointer-events-none absolute inset-y-0 left-0 my-px ml-px flex w-10 items-center justify-center rounded-l text-gray-500">
                <svg
                  className="hi-mini hi-magnifying-glass inline-block size-5"
                  xmlns="http://www.w3.org/2000/svg"
                  viewBox="0 0 20 20"
                  fill="currentColor"
                  aria-hidden="true"
                >
                  <path
                    fillRule="evenodd"
                    d="M9 3.5a5.5 5.5 0 100 11 5.5 5.5 0 000-11zM2 9a7 7 0 1112.452 4.391l3.328 3.329a.75.75 0 11-1.06 1.06l-3.329-3.328A7 7 0 012 9z"
                    clipRule="evenodd"
                  />
                </svg>
              </div>
              <input
                type="text"
                value={searchTerm}
                onChange={(e) => onSearchChange(e.target.value)}
                className="block w-full rounded-lg border border-gray-200 py-2 pl-10 pr-3 text-sm leading-6 placeholder-gray-400 focus:border-blue-500 focus:ring focus:ring-blue-500/50 dark:border-gray-700 dark:bg-gray-900 dark:focus:border-blue-500"
                placeholder="Search longform posts..."
              />
            </div>
          </div>
        </div>
      ) : null}

      {/* Bulk Actions */}
      {selectedPosts.size > 0 ? (
        <div className="mb-4 flex items-center justify-between rounded-lg border border-blue-200 bg-blue-50 p-4 dark:border-blue-700 dark:bg-blue-900/50">
          <span className="text-sm font-medium text-blue-800 dark:text-blue-200">
            {selectedPosts.size} post{selectedPosts.size !== 1 ? "s" : ""}{" "}
            selected
          </span>
          <div className="flex gap-2">
            {type === "draft" ? (
              <Link
                to="/dashboard/newlongformpost"
                className="inline-flex items-center justify-center gap-2 rounded-lg border border-blue-200 bg-white px-3 py-2 text-sm font-semibold leading-5 text-blue-800 hover:border-blue-300 hover:text-blue-900 hover:shadow-sm focus:ring focus:ring-blue-300/25 active:border-blue-200 active:shadow-none dark:border-blue-700 dark:bg-gray-800 dark:text-blue-300 dark:hover:border-blue-600 dark:hover:text-blue-200 dark:focus:ring-blue-600/40 dark:active:border-blue-700"
              >
                Create New
              </Link>
            ) : null}
            <button
              onClick={handleBulkDelete}
              disabled={bulkDeleteFetcher.state !== "idle"}
              className="inline-flex items-center justify-center gap-2 rounded-lg border border-red-200 bg-white px-3 py-2 text-sm font-semibold leading-5 text-red-800 hover:border-red-300 hover:text-red-900 hover:shadow-sm focus:ring focus:ring-red-300/25 active:border-red-200 active:shadow-none disabled:opacity-50 dark:border-red-700 dark:bg-gray-800 dark:text-red-300 dark:hover:border-red-600 dark:hover:text-red-200 dark:focus:ring-red-600/40 dark:active:border-red-700"
            >
              {bulkDeleteFetcher.state !== "idle"
                ? "Deleting..."
                : `Delete ${selectedPosts.size} post${selectedPosts.size !== 1 ? "s" : ""}`}
            </button>
          </div>
        </div>
      ) : null}

      {/* Posts Table */}
      <div className="min-w-full overflow-x-auto rounded border border-gray-200 bg-white dark:border-gray-700 dark:bg-gray-800">
        <table className="min-w-full whitespace-nowrap align-middle text-sm">
          <thead>
            <tr>
              <th className="bg-gray-100/75 px-3 py-4 text-center font-semibold text-gray-900 dark:bg-gray-700/25 dark:text-gray-50">
                <input
                  type="checkbox"
                  checked={
                    filteredPosts.length > 0
                      ? selectedPosts.size === filteredPosts.length
                      : false
                  }
                  onChange={toggleSelectAll}
                  className="h-4 w-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500 dark:border-gray-600 dark:bg-gray-700"
                />
              </th>
              <th className="bg-gray-100/75 px-3 py-4 text-left font-semibold text-gray-900 dark:bg-gray-700/25 dark:text-gray-50">
                Cover
              </th>
              <th
                className="cursor-pointer bg-gray-100/75 px-3 py-4 text-left font-semibold text-gray-900 dark:bg-gray-700/25 dark:text-gray-50"
                onClick={() => requestSort("title")}
              >
                Title{" "}
                {sortConfig.key === "title"
                  ? sortConfig.direction === "asc"
                    ? "↑"
                    : "↓"
                  : null}
              </th>
              <th className="bg-gray-100/75 px-3 py-4 text-left font-semibold text-gray-900 dark:bg-gray-700/25 dark:text-gray-50">
                Summary
              </th>
              <th
                className="cursor-pointer bg-gray-100/75 px-3 py-4 text-left font-semibold text-gray-900 dark:bg-gray-700/25 dark:text-gray-50"
                onClick={() =>
                  requestSort(
                    type === "posted"
                      ? "publishedAt"
                      : type === "scheduled"
                        ? "scheduledFor"
                        : "createdAt",
                  )
                }
              >
                {type === "posted"
                  ? "Published"
                  : type === "scheduled"
                    ? "Scheduled For"
                    : "Created"}{" "}
                {sortConfig.key ===
                (type === "posted"
                  ? "publishedAt"
                  : type === "scheduled"
                    ? "scheduledFor"
                    : "createdAt")
                  ? sortConfig.direction === "asc"
                    ? "↑"
                    : "↓"
                  : null}
              </th>
              <th className="bg-gray-100/75 px-3 py-4 text-center font-semibold text-gray-900 dark:bg-gray-700/25 dark:text-gray-50">
                Reading Time
              </th>
              {type === "scheduled" ? (
                <th className="bg-gray-100/75 px-3 py-4 text-center font-semibold text-gray-900 dark:bg-gray-700/25 dark:text-gray-50">
                  Time Remaining
                </th>
              ) : null}
              <th className="bg-gray-100/75 px-3 py-4 text-center font-semibold text-gray-900 dark:bg-gray-700/25 dark:text-gray-50">
                Status
              </th>
              <th className="bg-gray-100/75 px-3 py-4 text-center font-semibold text-gray-900 dark:bg-gray-700/25 dark:text-gray-50">
                Actions
              </th>
            </tr>
          </thead>

          <tbody>
            {filteredPosts.map((post) => (
              <tr
                key={post.id}
                className="cursor-pointer even:bg-gray-50 hover:bg-gray-100 dark:even:bg-gray-900/50 dark:hover:bg-gray-700/50"
                onClick={() => onPostSelect?.(post)}
              >
                <td className="p-3 text-center">
                  <input
                    type="checkbox"
                    checked={selectedPosts.has(post.id)}
                    onChange={() => togglePostSelection(post.id)}
                    onClick={(e) => e.stopPropagation()}
                    className="h-4 w-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500 dark:border-gray-600 dark:bg-gray-700"
                  />
                </td>
                <td className="p-3">
                  {post.image ? (
                    <img
                      src={post.image}
                      alt="Cover"
                      className="h-12 w-16 rounded object-cover"
                    />
                  ) : (
                    <div className="flex h-12 w-16 items-center justify-center rounded bg-gray-100 text-xs font-medium text-gray-500 dark:bg-gray-700 dark:text-gray-400">
                      ARTICLE
                    </div>
                  )}
                </td>
                <td className="p-3">
                  <p className="font-medium">
                    {post.title && post.title.length > 40
                      ? post.title.substring(0, 40) + "..."
                      : post.title || "Untitled"}
                  </p>
                </td>
                <td className="max-w-xs p-3">
                  <p className="line-clamp-2 text-sm text-gray-600 dark:text-gray-400">
                    {post.summary && post.summary.length > 60
                      ? post.summary.substring(0, 60) + "..."
                      : post.summary || "No summary"}
                  </p>
                </td>
                <td className="p-3">
                  {formatDate(
                    type === "posted"
                      ? (post.publishedAt || undefined)
                      : type === "scheduled"
                        ? (post.scheduledFor || undefined)
                        : (post.createdAt || undefined),
                  )}
                </td>
                <td className="p-3 text-center">
                  <span className="text-sm text-gray-500 dark:text-gray-400">
                    {getReadingTime(post.content || undefined)}
                  </span>
                </td>
                {type === "scheduled" ? (
                  <td className="p-3 text-center">
                    <div className="text-sm font-medium text-blue-600 dark:text-blue-400">
                      {countdowns[post.id] || "—"}
                    </div>
                  </td>
                ) : null}
                <td className="p-3 text-center">{getStatusBadge(post)}</td>
                <td className="p-3 text-center">
                  <div className="flex justify-center gap-2">
                    {type === "draft" ? (
                      <Link
                        to={`/dashboard/drafts/longform/edit/${post.id}`}
                        onClick={(e) => e.stopPropagation()}
                        className="inline-flex items-center justify-center gap-2 rounded-lg border border-blue-200 bg-white px-2 py-1 text-sm font-semibold leading-5 text-blue-800 hover:border-blue-300 hover:text-blue-900 hover:shadow-sm focus:ring focus:ring-blue-300/25 active:border-blue-200 active:shadow-none dark:border-blue-700 dark:bg-gray-800 dark:text-blue-300 dark:hover:border-blue-600 dark:hover:text-blue-200 dark:focus:ring-blue-600/40 dark:active:border-blue-700"
                      >
                        Edit
                      </Link>
                    ) : null}
                    {type === "scheduled" && onEditPost ? (
                      <>
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            onEditPost(post);
                          }}
                          className="inline-flex items-center justify-center gap-2 rounded-lg border border-blue-200 bg-white px-2 py-1 text-sm font-semibold leading-5 text-blue-800 hover:border-blue-300 hover:text-blue-900 hover:shadow-sm focus:ring focus:ring-blue-300/25 active:border-blue-200 active:shadow-none dark:border-blue-700 dark:bg-gray-800 dark:text-blue-300 dark:hover:border-blue-600 dark:hover:text-blue-200 dark:focus:ring-blue-600/40 dark:active:border-blue-700"
                        >
                          Edit
                        </button>
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            if (onReschedulePost) {
                              onReschedulePost(post);
                            }
                          }}
                          className="inline-flex items-center justify-center gap-2 rounded-lg border border-green-200 bg-white px-2 py-1 text-sm font-semibold leading-5 text-green-800 hover:border-green-300 hover:text-green-900 hover:shadow-sm focus:ring focus:ring-green-300/25 active:border-green-200 active:shadow-none dark:border-green-700 dark:bg-gray-800 dark:text-green-300 dark:hover:border-green-600 dark:hover:text-green-200 dark:focus:ring-green-600/40 dark:active:border-green-700"
                        >
                          Reschedule
                        </button>
                      </>
                    ) : null}
                    {type === "posted" &&
                    (post.nostrEventId || (post.signedEvent && typeof post.signedEvent === "object" && "id" in post.signedEvent ? (post.signedEvent as { id?: string }).id : undefined)) ? (
                      <>
                        <Link
                          to={`https://primal.net/a/${post.nostrEventId || (post.signedEvent && typeof post.signedEvent === "object" && "id" in post.signedEvent ? (post.signedEvent as { id?: string }).id : "")}`}
                          target="_blank"
                          rel="noreferrer"
                          onClick={(e) => e.stopPropagation()}
                          className="font-montserrat inline-block rounded-full bg-black/50 px-4 py-1 text-sm text-white transition-colors duration-200 hover:bg-black/70"
                        >
                          View Article
                        </Link>
                        {longformRepostFetcher ? (() => {
                          const fetcher = longformRepostFetcher;
                          const formData = getFetcherFormData(fetcher);
                          return (
                            <fetcher.Form
                            method="post"
                            onClick={(e) => e.stopPropagation()}
                          >
                            <input
                              type="hidden"
                              name="postId"
                              value={post.id}
                            />
                            <input
                              type="hidden"
                              name="_action"
                              value="longformRepost"
                            />
                            <button
                              type="submit"
                              disabled={
                                fetcher.state !== "idle" ||
                                (formData ? (formData.get("postId") as string | null) === post.id : false)
                              }
                              className="inline-flex items-center justify-center gap-2 rounded-lg border border-purple-200 bg-white px-2 py-1 text-sm font-semibold leading-5 text-purple-800 hover:border-purple-300 hover:text-purple-900 hover:shadow-sm focus:ring focus:ring-purple-300/25 active:border-purple-200 active:shadow-none disabled:opacity-50 dark:border-purple-700 dark:bg-gray-800 dark:text-purple-300 dark:hover:border-purple-600 dark:hover:text-purple-200 dark:focus:ring-purple-600/40 dark:active:border-purple-700"
                            >
                              {fetcher.state !== "idle" &&
                              (formData ? (formData.get("postId") as string | null) === post.id : false)
                                ? "Reposting..."
                                : "Repost"}
                            </button>
                          </fetcher.Form>
                          );
                        })() : null}
                        {longformQuoteFetcher ? (() => {
                          const fetcher = longformQuoteFetcher;
                          const formData = getFetcherFormData(fetcher);
                          return (
                            <fetcher.Form
                            method="post"
                            onClick={(e) => e.stopPropagation()}
                          >
                            <input
                              type="hidden"
                              name="postId"
                              value={post.id}
                            />
                            <input
                              type="hidden"
                              name="_action"
                              value="longformQuote"
                            />
                            <button
                              type="submit"
                              disabled={
                                fetcher.state !== "idle" ||
                                (formData ? (formData.get("postId") as string | null) === post.id : false)
                              }
                              className="inline-flex items-center justify-center gap-2 rounded-lg border border-green-200 bg-white px-2 py-1 text-sm font-semibold leading-5 text-green-800 hover:border-green-300 hover:text-green-900 hover:shadow-sm focus:ring focus:ring-green-300/25 active:border-green-200 active:shadow-none disabled:opacity-50 dark:border-green-700 dark:bg-gray-800 dark:text-green-300 dark:hover:border-green-600 dark:hover:text-green-200 dark:focus:ring-green-600/40 dark:active:border-green-700"
                            >
                              {fetcher.state !== "idle" &&
                              (fetcher.formData ? (fetcher.formData.get("postId") as string | null) === post.id : false)
                                ? "Quoting..."
                                : "Quote Post"}
                            </button>
                          </fetcher.Form>
                          );
                        })() : null}
                      </>
                    ) : null}
                    <deleteFetcher.Form
                      method="post"
                      onClick={(e) => e.stopPropagation()}
                    >
                      <input type="hidden" name="postId" value={post.id} />
                      <input
                        type="hidden"
                        name="_action"
                        value="deleteLongForm"
                      />
                      <button
                        type="submit"
                        disabled={
                          deleteFetcher.state !== "idle" ||
                          bulkDeleteFetcher.state !== "idle"
                        }
                        className="inline-flex items-center justify-center gap-2 rounded-lg border border-red-200 bg-white px-2 py-1 text-sm font-semibold leading-5 text-red-800 hover:border-red-300 hover:text-red-900 hover:shadow-sm focus:ring focus:ring-red-300/25 active:border-red-200 active:shadow-none disabled:opacity-50 dark:border-red-700 dark:bg-gray-800 dark:text-red-300 dark:hover:border-red-600 dark:hover:text-red-200 dark:focus:ring-red-600/40 dark:active:border-red-700"
                      >
                        {deleteFetcher.state !== "idle" &&
                        deleteFetcher.formData?.get("postId") === post.id
                          ? "Deleting..."
                          : "Delete"}
                      </button>
                    </deleteFetcher.Form>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

import { useFetcher } from "@remix-run/react";
import { useState, useEffect } from "react";

import { Badge } from "~/components/ui/badge";
import { Button } from "~/components/ui/button";
import { Input } from "~/components/ui/input";
import { Label } from "~/components/ui/label";
import { Textarea } from "~/components/ui/textarea";
import AssetBrowser from "~/features/assets/components/AssetBrowser";
import type { Asset } from "~/features/assets/types";
import {
  signLongFormEvent,
  convertEditorJSToMarkdown,
  generateArticleIdentifier,
} from "~/lib/nostr";

import { useCoverImageUpload } from "../useCoverImageUpload";
import { useLongFormEditor } from "../useLongFormEditor";
import { useLongFormScheduling } from "../useLongFormScheduling";

import { LongFormActionButtons } from "./LongFormActionButtons";
import { LongFormCoverImage } from "./LongFormCoverImage";
import { LongFormEditorStyles } from "./LongFormEditorStyles";
import { LongFormPublishingOptions } from "./LongFormPublishingOptions";

interface QueueType {
  id?: string;
  name: string;
  color?: string | null;
  hashtags?: string | null;
  scheduleType?: string;
  isEnabled?: boolean;
}

interface HashTagPreset {
  id: string;
  name: string;
  tags: string;
  description?: string | null;
}

interface InitialData {
  title?: string;
  summary?: string;
  content?: string;
  image?: string;
  tags?: string[];
  queueType?: { name: string };
}

interface LongFormPostProps {
  queueTypes?: (string | QueueType)[];
  scheduleIntervals?: number[];
  userTags?: string;
  assets?: Asset[];
  uploadProvider?: string | null;
  userTimezone?: string;
  onQueueTypeChange?: (name: string) => void;
  onPreview?: (data: { title: string; summary: string; content: string; image: string }) => void;
  initialData?: InitialData | null;
  isEditing?: boolean;
  hashTagPresets?: HashTagPreset[];
  useHashtagPresets?: boolean;
  selectedHashtagPresetId?: string | null;
  selectedHashtags?: string;
  onUseHashtagPresetsChange?: (value: boolean) => void;
  onHashtagPresetChange?: (presetId: string | null, hashtags: string) => void;
}

export default function LongFormPost({
  queueTypes = [],
  scheduleIntervals = [],
  userTags = "",
  assets = [],
  uploadProvider = null,
  userTimezone = "UTC",
  onQueueTypeChange,
  onPreview,
  initialData = null,
  isEditing = false,
  hashTagPresets = [],
  useHashtagPresets = false,
  selectedHashtagPresetId = null,
  selectedHashtags = "",
  onUseHashtagPresetsChange,
  onHashtagPresetChange,
}: LongFormPostProps) {
  const fetcher = useFetcher();
  const [title, setTitle] = useState(initialData?.title ?? "");
  const [summary, setSummary] = useState(initialData?.summary ?? "");
  const [content, setContent] = useState(initialData?.content ?? "");
  const [customTags, setCustomTags] = useState(
    initialData?.tags?.join(", ") || "",
  );
  const [showAssetBrowser, setShowAssetBrowser] = useState("");

  // Use extracted hooks
  const {
    editorReady,
    loadInitialData,
    insertAssetIntoEditor,
    generateSummaryFromContent,
  } = useLongFormEditor({
    uploadProvider,
    onContentChange: setContent,
  });

  const {
    image,
    setImage,
    uploadError,
    uploadFetcherState,
    handleImageUpload,
    handleCoverImageAssets,
    handleFetcherData,
    handleFetcherStateChange,
  } = useCoverImageUpload({
    uploadProvider,
    initialImage: initialData?.image ?? "",
  });

  const {
    selectedQueueType,
    scheduledFor,
    setScheduledFor,
    displayedHashtags,
    updateDisplayedHashtags,
    handleScheduleIntervalClick,
    calculateQueueScheduleTime,
  } = useLongFormScheduling({
    queueTypes,
    scheduleIntervals,
    userTags,
    userTimezone,
    initialQueueType: initialData?.queueType?.name ?? "Unassigned",
    onQueueTypeChange,
  });

  // Handle upload fetcher responses
  useEffect(() => {
    handleFetcherData();
  }, [handleFetcherData]);

  // Clear upload errors when fetcher state changes
  useEffect(() => {
    handleFetcherStateChange();
  }, [handleFetcherStateChange]);

  // Handle initial data loading - wait for both editor ready and initial data
  useEffect(() => {
    if (editorReady && initialData?.content) {
      const timeoutId = setTimeout(() => {
        void loadInitialData(initialData.content!);
      }, 100);
      return () => clearTimeout(timeoutId);
    }
  }, [editorReady, initialData?.content, loadInitialData]);

  const handleAssetBrowserSelect = (selectedAssets: Asset[]) => {
    if (showAssetBrowser === "cover") {
      handleCoverImageAssets(selectedAssets.map(asset => ({
        assetType: asset.assetType,
        fileUrl: asset.fileUrl || undefined,
      })));
    } else {
      void insertAssetIntoEditor(selectedAssets.map(asset => ({
        assetType: asset.assetType,
        fileUrl: asset.fileUrl || undefined,
        content: asset.content || undefined,
        title: asset.title || undefined,
      })));
    }
    setShowAssetBrowser("");
  };

  const handleGenerateSummary = () => {
    const generatedSummary = generateSummaryFromContent(content);
    if (generatedSummary) {
      setSummary(generatedSummary);
    }
  };

  const handleSchedule = async (actionType: "schedule" | "publish") => {
    if (!title.trim() || !content.trim()) {
      return;
    }

    try {
      let markdownContent;
      try {
        const editorData = JSON.parse(content) as { blocks?: EditorJSBlock[] };
        markdownContent = convertEditorJSToMarkdown(editorData);
      } catch {
        markdownContent = content;
      }

      const finalSummary = summary || generateSummaryFromContent(content);
      const identifier = generateArticleIdentifier(title);

      let scheduledTimestamp;
      if (actionType === "schedule" && scheduledFor) {
        const scheduledTime = new Date(scheduledFor);
        scheduledTimestamp = Math.floor(scheduledTime.getTime() / 1000);
      }

      // Get effective hashtags - prioritize manual selection over queue defaults
      let effectiveHashtags = "";

      if (useHashtagPresets) {
        // Manual hashtag presets are enabled
        if (selectedHashtags) {
          // Use manually selected hashtag preset
          effectiveHashtags = selectedHashtags;
        }
        // If useHashtagPresets is true but no manual preset selected, use no hashtags
      } else {
        // Manual hashtag presets are disabled, use displayed hashtags (queue defaults)
        effectiveHashtags = displayedHashtags || "";
      }

      const hashtagsFromQueue = effectiveHashtags
        ? effectiveHashtags
          .split(" ")
          .map((tag) => tag.replace("#", "").trim())
          .filter(Boolean)
        : [];
      const customTagsList = customTags
        ? customTags
          .split(",")
          .map((tag) => tag.trim())
          .filter(Boolean)
        : [];
      // Combine and deduplicate tags (case insensitive)
      const allTags = [...hashtagsFromQueue, ...customTagsList];
      const uniqueTags = allTags.filter(
        (tag, index) =>
          allTags.findIndex((t) => t.toLowerCase() === tag.toLowerCase()) ===
          index,
      );

      const eventData = {
        title,
        content: markdownContent,
        summary: finalSummary,
        image,
        tags: uniqueTags,
        identifier,
        publishedAt:
          actionType === "publish"
            ? Math.floor(Date.now() / 1000)
            : scheduledTimestamp,
      };

      const { nostrEvent, signedEvent } = await signLongFormEvent(eventData);

      const form = document.createElement("form");
      form.method = "POST";
      form.style.display = "none";

      const fields: [string, string][] = [
        [
          "_action",
          actionType === "schedule" ? "schedule-longform" : "publish",
        ],
        ["title", title],
        ["content", content],
        ["summary", finalSummary],
        ["image", image],
        ["tags", uniqueTags.join(",")],
        ["queueType", selectedQueueType],
        [
          "scheduledFor",
          scheduledTimestamp ? scheduledTimestamp.toString() : "",
        ],
        ["signedEvent", JSON.stringify(signedEvent)],
        ["nostrEvent", JSON.stringify(nostrEvent)],
      ];

      fields.forEach(([name, value]) => {
        const input = document.createElement("input");
        input.type = "hidden";
        input.name = name;
        input.value = value || "";
        form.appendChild(input);
      });

      document.body.appendChild(form);
      form.submit();
    } catch (error) {
      const { handleAsyncError } = await import("~/lib/error-handler.client");
      handleAsyncError(error, {
        component: "LongFormPost",
        action: "handleSubmit",
      }, false); // Don't show toast, let component handle it
    }
  };

  const isFormValid = !!(title.trim() && summary.trim() && content.trim() && image);

  return (
    <>
      <LongFormEditorStyles />

      <div className="space-y-6">
        <div>
          <Label htmlFor="title">Title *</Label>
          <Input
            id="title"
            name="title"
            type="text"
            required
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="Enter your post title"
            className="mt-1"
          />
        </div>

        <div>
          <Label htmlFor="summary">Summary *</Label>
          <div className="mt-1 flex gap-2">
            <Textarea
              id="summary"
              name="summary"
              required
              value={summary}
              onChange={(e) => setSummary(e.target.value)}
              placeholder="Brief description of your post"
              rows={3}
              className="flex-1"
            />
            <Button
              type="button"
              variant="outline"
              onClick={handleGenerateSummary}
              disabled={!content}
              className="whitespace-nowrap"
            >
              Auto-generate
            </Button>
          </div>
        </div>

        <LongFormCoverImage
          image={image}
          uploadError={uploadError}
          uploadProvider={uploadProvider}
          uploadFetcherState={uploadFetcherState}
          onImageUpload={handleImageUpload}
          onRemove={() => setImage("")}
          onOpenAssetBrowser={() => setShowAssetBrowser("cover")}
        />

        <div>
          <div className="mb-1 flex items-center justify-between">
