                    Queue Type
                  </h3>
                  <span
                    className={`inline-flex items-center rounded-full px-3 py-1 text-sm font-medium capitalize ${getQueueColor(queueType.name, queueType.color).bg} ${getQueueColor(queueType.name, queueType.color).text}`}
