import { useState, useEffect, useCallback } from "react";

import { Button } from "~/components/ui/button";
import { Input } from "~/components/ui/input";
import { Label } from "~/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "~/components/ui/select";
import { getDynamicQueueStyle } from "~/features/posts/queueColors";
import type { QueueType } from "~/features/posts/types";

interface SchedulingControlsProps {
  queueTypes?: QueueType[];
  scheduleIntervals?: number[];
  selectedQueueType: string;
  scheduledFor: string;
  onQueueTypeChange: (queueType: string) => void;
  onScheduleChange: (scheduledFor: string) => void;
  userTimezone?: string;
  userId?: string;
}

export default function SchedulingControls({
  queueTypes = [],
  scheduleIntervals = [],
  selectedQueueType,
  scheduledFor,
  onQueueTypeChange,
  onScheduleChange,
  userTimezone = "UTC",
  userId,
}: SchedulingControlsProps) {
  const [localScheduledFor, setLocalScheduledFor] = useState(scheduledFor);

  const calculateQueueScheduleTime = useCallback(async (queueTypeName: string) => {
    if (queueTypeName === "unassigned") {
      setLocalScheduledFor("");
      onScheduleChange("");
      return;
    }

    // Find the queue type object to get its ID
    const selectedQueueType = queueTypes.find(qt => 
      (typeof qt === "string" ? qt : qt.name) === queueTypeName
    );
    const queueTypeId = typeof selectedQueueType === "object" ? selectedQueueType.id : null;

    try {
      const response = await fetch("/api/queue-schedule", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          queueTypeId,
          queueTypeName, // Keep for backward compatibility
          userId,
        }),
      });

      if (response.ok) {
        const data = (await response.json()) as { scheduledTime?: string };
        const scheduledTime = data.scheduledTime;
        if (scheduledTime) {
          setLocalScheduledFor(scheduledTime);
          onScheduleChange(scheduledTime);
        }
      }
    } catch (error) {
      const { handleErrorSafely } = await import("~/lib/error-handler.client");
      handleErrorSafely(error, {
        component: "SchedulingControls",
        action: "calculateScheduleTime",
      });
    }
  }, [queueTypes, userId, onScheduleChange]);

  useEffect(() => {
    if (selectedQueueType !== "unassigned") {
      void calculateQueueScheduleTime(selectedQueueType);
    }
  }, [selectedQueueType, calculateQueueScheduleTime]);

  const handleScheduleIntervalClick = (intervalHours: string) => {
    const now = new Date();
    const hoursLater = new Date(
      now.getTime() + parseInt(intervalHours) * 60 * 60 * 1000,
    );

    const formattedDate = hoursLater.toLocaleString("en-US", {
      timeZone: userTimezone,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
      hour12: false,
    });

    const [datePart, timePart] = formattedDate.split(", ");
    const [month, day, year] = datePart.split("/");
    const datetimeLocal = `${year}-${month.padStart(2, "0")}-${day.padStart(2, "0")}T${timePart}`;

    setLocalScheduledFor(datetimeLocal);
    onScheduleChange(datetimeLocal);
  };

  const handleQueueChange = (value: string) => {
    onQueueTypeChange(value);
  };

  const handleDateTimeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setLocalScheduledFor(e.target.value);
    onScheduleChange(e.target.value);
  };

  const selectedQueueColor =
    selectedQueueType !== "unassigned"
      ? getDynamicQueueStyle(selectedQueueType, false)
      : "bg-gray-100 text-gray-800";

  return (
    <div className="space-y-4">
      <div>
        <Label htmlFor="queueType">Queue Type</Label>
        <Select value={selectedQueueType} onValueChange={handleQueueChange}>
          <SelectTrigger className={`w-full ${selectedQueueColor}`}>
            <SelectValue placeholder="Select a queue type" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="unassigned">Unassigned</SelectItem>
            {queueTypes.map((queue) => (
              <SelectItem key={queue.name} value={queue.name}>
                {queue.name}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      <div>
        <Label htmlFor="scheduledFor">Schedule for later</Label>
        <Input
          id="scheduledFor"
          name="scheduledFor"
          type="datetime-local"
          value={localScheduledFor}
          onChange={handleDateTimeChange}
          className="w-full"
        />
      </div>

      {scheduleIntervals && scheduleIntervals.length > 0 ? (
        <div>
          <Label>Quick Schedule</Label>
          <div className="mt-2 flex flex-wrap gap-2">
            {scheduleIntervals.map((interval) => (
              <Button
                key={interval}
                type="button"
                variant="outline"
                size="sm"
                onClick={() => {
                  const hoursFromNow = interval;
                  const newDate = new Date();
                  newDate.setHours(newDate.getHours() + hoursFromNow);
                  const formattedDate = newDate.toISOString().slice(0, 16);
                  setLocalScheduledFor(formattedDate);
                  onScheduleChange(formattedDate);
                }}
              >
                {interval} hour{interval !== 1 ? "s" : ""}
              </Button>
            ))}
          </div>
        </div>
      ) : null}
    </div>
  );
}

import { useFetcher } from "@remix-run/react";
import { useEffect, useState } from "react";

import type { PostData, LongFormPostData, UserData, QueueType } from "~/features/posts/types";
import { handleErrorSafely } from "~/lib/error-handler.client";
import { signEventFn } from "~/lib/nostr";

interface SimpleRescheduleModalProps {
  post: PostData | LongFormPostData;
  onClose: () => void;
  onConfirm: () => void;
  user?: UserData;
  queueTypes?: QueueType[];
}

export function SimpleRescheduleModal({
  post,
  onClose,
  onConfirm,
  user,
  queueTypes = [],
}: SimpleRescheduleModalProps) {
  interface FetcherData {
    success?: boolean;
    error?: string;
    needsSigning?: boolean;
  }
  const fetcher = useFetcher<FetcherData>();
  const [isSigningEvent, setIsSigningEvent] = useState(false);
  const [signingError, setSigningError] = useState<string | null>(null);
  const [scheduledFor, setScheduledFor] = useState<Date | null>(null);
  const [selectedQueueType, setSelectedQueueType] = useState<string>("");
  const [validationError, setValidationError] = useState<string | null>(null);

  // Determine if this is a longform post
  const isLongform = "title" in post && post.title !== undefined;

  useEffect(() => {
    if (post) {
      if (isLongform && "publishedAt" in post) {
        setScheduledFor(post.publishedAt ? new Date(post.publishedAt) : null);
      } else if (!isLongform && "scheduledFor" in post) {
        setScheduledFor(
          post.scheduledFor
            ? new Date(parseInt(post.scheduledFor) * 1000)
            : null,
        );
        setSelectedQueueType(post.queueType?.id ?? "");
      }
    }
  }, [post, isLongform]);

  useEffect(() => {
    if (fetcher.data?.success) {
      if (fetcher.data.needsSigning) {
        return; // Keep modal open for re-signing
      }
      onConfirm();
    }
    if (fetcher.data?.error) {
      setSigningError(fetcher.data.error);
    }
  }, [fetcher.data, onConfirm]);

  const formatDateTimeForInput = (date: Date) => {
    const userTimezone = user?.timezone ?? "UTC";
    const dateInUserTz = new Date(
      date.toLocaleString("en-US", { timeZone: userTimezone }),
    );
    const year = dateInUserTz.getFullYear();
    const month = String(dateInUserTz.getMonth() + 1).padStart(2, "0");
    const day = String(dateInUserTz.getDate()).padStart(2, "0");
    const hours = String(dateInUserTz.getHours()).padStart(2, "0");
    const minutes = String(dateInUserTz.getMinutes()).padStart(2, "0");
    return `${year}-${month}-${day}T${hours}:${minutes}`;
  };

  const validateDateTime = (dateTime: Date | null) => {
    if (!dateTime) {
      setValidationError("Please select a date and time");
      return false;
    }

    const now = new Date();
    const userTimezone = user?.timezone ?? "UTC";
    const nowInUserTz = new Date(
      now.toLocaleString("en-US", { timeZone: userTimezone }),
    );

    if (dateTime <= nowInUserTz) {
      setValidationError("Cannot schedule posts in the past");
      return false;
    }

    setValidationError(null);
    return true;
  };

  const handleDateTimeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newValue = e.target.value ? new Date(e.target.value) : null;
    setScheduledFor(newValue);
    validateDateTime(newValue);
  };

  const handleSubmit = async () => {
    if (!post || !scheduledFor) return;

    if (!validateDateTime(scheduledFor)) {
      return;
    }

    try {
      setIsSigningEvent(true);
      setSigningError(null);

      const newTimeUnix = Math.floor(scheduledFor.getTime() / 1000);

      // Use the exact same content and tags from the original signed event
      const originalSignedEvent = post.signedEvent;
      const originalNostrEvent = post.nostrEvent;

      if (!originalSignedEvent || !originalNostrEvent) {
        throw new Error(
          "Original event not found. Cannot reschedule unsigned posts.",
        );
      }

      // Re-sign with the same content but new timestamp
      const { nostrEvent, signedEvent } = await signEventFn({
        content: originalSignedEvent.content, // Use exact same content
        created_at: newTimeUnix, // Only change the timestamp
        kind: originalSignedEvent.kind || (isLongform ? 30023 : 1),
        tags: originalSignedEvent.tags || [], // Use exact same tags
      });

      // Submit the reschedule action with signed event
      const formData = new FormData();
      formData.append(
        "_action",
        isLongform ? "rescheduleLongform" : "reschedule",
      );
      formData.append("postId", post.id);
      formData.append("newTime", newTimeUnix.toString());
      formData.append("signedEvent", JSON.stringify(signedEvent));
      formData.append("nostrEvent", JSON.stringify(nostrEvent));

      if (!isLongform) {
        formData.append("overrideQueue", "false");
        if (selectedQueueType) {
          formData.append("queueTypeId", selectedQueueType);
        }
      }

      fetcher.submit(formData, { method: "post" });
    } catch (error: unknown) {
      const { handleAsyncErrorWithMessage, getErrorMessage } = await import("~/lib/error-handler.client");
      handleAsyncErrorWithMessage(
        error,
        "Failed to sign event. Please try again.",
        {
          component: "SimpleRescheduleModal",
          action: "handleReschedule",
        },
        false, // Don't show toast, we set signingError instead
      );
      setIsSigningEvent(false);
      setSigningError(getErrorMessage(error) || "Failed to sign event. Please try again.");
    }
  };

  const getFirstImage = () => {
    if (post && "fileUrl" in post && post.fileUrl && post.fileUrl.length > 0) {
      try {
        const firstFileUrl = post.fileUrl[0];
        if (typeof firstFileUrl === "string") {
          try {
            const parsed = JSON.parse(firstFileUrl) as string[] | string;
            return Array.isArray(parsed) ? parsed[0] : firstFileUrl;
          } catch {
            return firstFileUrl;
          }
        }
        return firstFileUrl;
      } catch (error) {
        handleErrorSafely(error, {
          component: "SimpleRescheduleModal",
          action: "getFirstImage",
        });
        return null;
      }
    }
    return null;
  };

  const formatDateTime = (date: Date) => {
    const userTimezone = user?.timezone ?? "UTC";
    return date.toLocaleDateString("en-US", {
      weekday: "long",
      month: "long",
      day: "numeric",
      hour: "2-digit",
      minute: "2-digit",
      timeZone: userTimezone,
    });
  };

  if (!post) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
      <div className="w-full max-w-md rounded-lg bg-white shadow-xl dark:bg-gray-800">
        <div className="p-6">
          {/* Header */}
          <div className="mb-4 flex items-center justify-between">
            <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
              Reschedule {isLongform ? "Article" : "Post"}
            </h3>
            <button
              onClick={onClose}
              className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-200"
            >
              <svg
                className="h-6 w-6"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M6 18L18 6M6 6l12 12"
                />
              </svg>
            </button>
          </div>

          {/* Content */}
          <div className="space-y-4">
            {/* Post preview */}
            <div className="rounded-lg bg-gray-50 p-3 dark:bg-gray-700">
              <div className="mb-2 text-sm font-medium text-gray-900 dark:text-white">
                {isLongform ? "Article" : "Post"} Preview:
              </div>

              {/* Show image thumbnail if available */}
              {getFirstImage() ? (
                <div className="mb-2">
                  <div className="h-20 w-full overflow-hidden rounded-md">
                    <img
                      src={getFirstImage()!}
                      alt="Post preview"
                      className="h-full w-full object-cover"
                      loading="lazy"
                    />
                  </div>
                </div>
              ) : null}

              <div className="text-sm text-gray-600 dark:text-gray-300">
                {isLongform && "title" in post
                  ? post.title || "Untitled Article"
                  : "caption" in post ? (post.caption || "No caption") : "No caption"}
                {"fileUrl" in post && post.fileUrl && post.fileUrl.length > 0 ? (
                  <span className="ml-2 text-xs text-gray-500">
                    ({post.fileUrl.length} file
                    {post.fileUrl.length > 1 ? "s" : ""})
                  </span>
                ) : null}
              </div>
            </div>

            {/* New time */}
            <div className="space-y-2">
              <label htmlFor="simple-reschedule-datetime" className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                New scheduled time:
              </label>
              <div className="flex items-center space-x-2">
                <svg
                  className="h-4 w-4 text-gray-400"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"
                  />
                </svg>
                <input
                  id="simple-reschedule-datetime"
                  type="datetime-local"
                  value={
                    scheduledFor ? formatDateTimeForInput(scheduledFor) : ""
                  }
                  onChange={handleDateTimeChange}
                  className="flex-1 rounded-md border border-gray-300 bg-white px-3 py-2 text-sm text-gray-900 focus:border-blue-500 focus:ring-2 focus:ring-blue-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
                />
              </div>
              {scheduledFor ? (
                <div className="text-xs text-gray-500 dark:text-gray-400">
                  {formatDateTime(scheduledFor)}
                </div>
              ) : null}
            </div>

            {/* Queue Type Selection for regular posts */}
            {!isLongform ? (
              <div className="space-y-2">
                <label htmlFor="simple-reschedule-queue-type" className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                  Queue Type:
                </label>
                <select
                  id="simple-reschedule-queue-type"
                  value={selectedQueueType}
                  onChange={(e) => setSelectedQueueType(e.target.value)}
                  className="w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm text-gray-900 focus:border-blue-500 focus:ring-2 focus:ring-blue-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
                >
                  <option value="">Manual (No Queue)</option>
                  {queueTypes.map((queueType) => (
                    <option key={queueType.id} value={queueType.id}>
                      {queueType.name}
                    </option>
                  ))}
                </select>
                <div className="text-xs text-gray-500 dark:text-gray-400">
                  {selectedQueueType
                    ? "Post will be managed by the selected queue type"
                    : "Post will be manually scheduled"}
                </div>
              </div>
            ) : null}

            {/* Re-signing warning */}
            <div className="rounded-lg border border-blue-200 bg-blue-50 p-3 dark:border-blue-800 dark:bg-blue-900/20">
              <div className="flex items-start space-x-2">
                <svg
                  className="mt-0.5 h-5 w-5 flex-shrink-0 text-blue-600 dark:text-blue-400"
                  fill="currentColor"
                  viewBox="0 0 20 20"
                >
                  <path
                    fillRule="evenodd"
                    d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z"
                    clipRule="evenodd"
                  />
                </svg>
                <div>
                  <div className="text-sm font-medium text-blue-800 dark:text-blue-200">
                    Rescheduling this {isLongform ? "article" : "post"} requires
                    re-signing the Nostr event
                  </div>
                </div>
              </div>
            </div>

            {/* Validation error */}
            {validationError ? (
              <div className="rounded-lg border border-red-200 bg-red-50 p-3 dark:border-red-800 dark:bg-red-900/20">
                <div className="text-sm text-red-800 dark:text-red-200">
                  {validationError}
                </div>
              </div>
            ) : null}

            {/* Error display */}
            {fetcher.data?.error ?? signingError ? (
              <div className="rounded-lg border border-red-200 bg-red-50 p-3 dark:border-red-800 dark:bg-red-900/20">
                <div className="text-sm text-red-800 dark:text-red-200">
                  {fetcher.data?.error ?? signingError}
                </div>
              </div>
            ) : null}
          </div>

          {/* Actions */}
          <div className="mt-6 flex items-center justify-end space-x-3">
            <button
              onClick={onClose}
              className="px-4 py-2 text-sm font-medium text-gray-700 hover:text-gray-900 dark:text-gray-300 dark:hover:text-white"
            >
              Cancel
            </button>
            <button
              onClick={handleSubmit}
              disabled={
                fetcher.state === "submitting" ||
                isSigningEvent ||
                !!validationError
              }
              className="rounded-lg bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-50"
            >
              {isSigningEvent
                ? "Signing Event..."
                : fetcher.state === "submitting"
                  ? "Rescheduling..."
                  : "Confirm Reschedule"}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useFetcher } from "@remix-run/react";
import { useState, useRef } from "react";
import { toast } from "react-hot-toast";

import { HashtagPresetToggle } from "~/components/dashboard/HashtagPresetToggle";
import { Button } from "~/components/ui/button";
import { Input } from "~/components/ui/input";
import { Label } from "~/components/ui/label";
import { Textarea } from "~/components/ui/textarea";
import AssetBrowser from "~/features/assets/components/AssetBrowser";
import type { Asset } from "~/features/assets/types";
import { QueueSelector } from "~/features/posts/components/QueueSelector";
import { SchedulingSection } from "~/features/posts/components/SchedulingSection";
import { usePostScheduling } from "~/features/posts/hooks/usePostScheduling";
import type { QueueType } from "~/features/posts/types";
import { signEventFn } from "~/lib/nostr";
import { useOptionalUser } from "~/lib/remix-utils";
interface TextPostProps {
  queueTypes?: (string | QueueType)[];
  assets?: Asset[];
  hashTagPresets?: { id: string; name: string; tags: string }[];
  onQueueTypeChange?: (queueType: string) => void;
  selectedHashTagPresetId?: string | null | undefined;
  onHashtagPresetChange?: (presetId: string | null, hashtags: string) => void;
}

export default function TextPost({
  queueTypes = [],
  assets = [],
  hashTagPresets = [],
  onQueueTypeChange,
  selectedHashTagPresetId,
  onHashtagPresetChange,
}: TextPostProps) {
  const fetcher = useFetcher();
  const user = useOptionalUser();
  // Note: User doesn't have hashTags property - this would need to come from hashTagPresets relation
  const tags: string[] = [];
  const [contentError, setContentError] = useState("");
  const [showAssetBrowser, setShowAssetBrowser] = useState(false);
  const [content, setContent] = useState("");
  const [isRecyclable, setIsRecyclable] = useState(false);
  const [useHashtagPresets, setUseHashtagPresets] = useState(false);
  const [selectedHashtagPresetId, setSelectedHashtagPresetId] = useState<string | undefined>(
    selectedHashTagPresetId ? selectedHashTagPresetId : undefined,
  );
  const [selectedHashtags, setSelectedHashtags] = useState("");
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  // Use the shared scheduling hook
  const {
    selectedQueue,
    setSelectedQueue,
    scheduledFor,
    setScheduledFor,
    calculateQueueScheduleTime,
    handleScheduleIntervalClick,
    scheduleIntervals,
  } = usePostScheduling({
    queueTypes,
    scheduleIntervals: user?.scheduleInterval as number[] | undefined,
    userTimezone: user?.timezone ?? undefined,
    initialQueue: "unassigned",
    onQueueTypeChange,
  });

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const form = e.target as HTMLFormElement;
    const formData = new FormData(form);
    const contentValue = formData.get("content");
    const scheduledFor = formData.get("scheduledFor");
    const submitter = (e.nativeEvent as SubmitEvent).submitter as HTMLButtonElement;
    const submitType = submitter?.value ?? "";

    // Ensure queueType is set from current state
    formData.set("queueType", selectedQueue);
    // Set isRecyclable checkbox state
    if (isRecyclable) {
      formData.set("isRecyclable", "on");
    }
    // Add hashtag preset selection
    if (useHashtagPresets && selectedHashtagPresetId) {
      formData.set("hashTagPresetId", selectedHashtagPresetId);
      formData.set("useHashtagPresets", "on");
    }

    // Check if content is empty (except for draft saves)
    if (
      submitType !== "draft-text" &&
      (!contentValue || (typeof contentValue === "string" && contentValue.trim() === ""))
    ) {
      setContentError("Post content cannot be empty");
      toast.error("Post content cannot be empty");
      return;
    }

    setContentError("");

    try {
      // For draft saves, we don't need to sign the event
      if (submitType === "draft-text") {
        formData.set("_action", submitType);
        fetcher.submit(formData, { method: "post" });
        return;
      }

      const userTimezone = user?.timezone ?? "UTC";
      let scheduledTime;

      if (submitType === "post-text") {
        scheduledTime = Date.now();
      } else {
        const scheduledForStr = typeof scheduledFor === "string" ? scheduledFor : "";

        // Only convert timezone if not UTC/Etc/GMT
        if (userTimezone !== "UTC" && userTimezone !== "Etc/GMT") {
          const utcDate = new Date(scheduledForStr);

          // Get timezone offset in minutes between user timezone and UTC
          const userDateStr = new Date(scheduledForStr).toLocaleString("en-US", {
            timeZone: userTimezone,
          });
          const userDate = new Date(userDateStr);
          const scheduledDate = new Date(scheduledForStr);
          const userOffset =
            (userDate.getTime() - scheduledDate.getTime()) / 60000;

          // Adjust the date by the offset
          utcDate.setMinutes(utcDate.getMinutes() - userOffset);
          scheduledTime = utcDate.getTime();
        } else {
          // Parse date string and ensure it's in UTC
          const dateObj = new Date(scheduledForStr + "Z");
          scheduledTime = dateObj.getTime();
        }
      }

      const scheduledForUnix = Math.floor(scheduledTime / 1000);

      // Get effective hashtags - prioritize manual selection over queue defaults
      let effectiveHashtags = "";

      if (useHashtagPresets) {
        // Manual hashtag presets are enabled
        if (selectedHashtags) {
          // Use manually selected hashtag preset
          effectiveHashtags = selectedHashtags;
        }
        // If useHashtagPresets is true but no manual preset selected, use no hashtags
        // This ensures manual hashtag preset selection overrides queue defaults
      } else {
        // Manual hashtag presets are disabled, use queue type's default hashtags
        // Find the queue type object to get its ID
        const selectedQueueType = queueTypes.find(qt => 
          (typeof qt === "string" ? qt : qt.name) === selectedQueue
        );
        const queueTypeId = typeof selectedQueueType === "object" ? selectedQueueType.id : null;

        try {
          const response = await fetch("/api/effective-hashtags", {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
            },
            body: JSON.stringify({
              userId: user?.id,
              queueTypeId,
              queueTypeName: selectedQueue, // Keep for backward compatibility
            }),
          });

          if (response.ok) {
            const data = (await response.json()) as { hashtags?: string };
            effectiveHashtags = data.hashtags || "";
          } else {
            // Fallback to user's default hashtags
            effectiveHashtags = Array.isArray(tags)
              ? tags.join(" ")
              : tags || "";
          }
        } catch (error) {
          const { handleErrorSafely } = await import("~/lib/error-handler.client");
          handleErrorSafely(error, {
            component: "TextPost",
            action: "fetchEffectiveHashtags",
          });
          // Fallback to user's default hashtags
          effectiveHashtags = Array.isArray(tags) ? tags.join(" ") : tags || "";
        }
      }

      const tagArray = effectiveHashtags
        .split(" ")
        .filter((tag) => tag.length > 0)
        .map((tag) => ["t", tag.replace("#", "")]);

      const contentToSign = user?.showHashTagsinPosts
        ? `${typeof contentValue === "string" ? contentValue : ""}\n${effectiveHashtags}`
        : (typeof contentValue === "string" ? contentValue : "");

      const { nostrEvent, signedEvent } = await signEventFn({
        content: contentToSign,
        created_at: scheduledForUnix,
        kind: 1,
        tags: tagArray,
      });

      formData.append("nostrEvent", JSON.stringify(nostrEvent));
      formData.append("signedEvent", JSON.stringify(signedEvent));
      formData.append("scheduledFor", scheduledForUnix.toString());
      formData.set("_action", submitType);

      fetcher.submit(formData, { method: "post" });
    } catch (error) {
      const { handleAsyncError } = await import("~/lib/error-handler.client");
      handleAsyncError(error, {
        component: "TextPost",
        action: "handleSubmit",
      }, false); // Don't show toast, let component handle it
    }
  };


  const handleHashtagPresetSelect = (
    presetId: string | null,
    hashtags: string,
  ) => {
    setSelectedHashtagPresetId(presetId ?? undefined);
    setSelectedHashtags(hashtags);
    if (onHashtagPresetChange) {
      onHashtagPresetChange(presetId, hashtags);
    }
  };

  const handleAssetsSelected = (selectedAssets: Asset[]) => {
    // Separate text assets and image assets
    const textAssets: string[] = [];
    const imageAssets: string[] = [];

    selectedAssets.forEach((asset) => {
      if (asset.assetType === "TEXT") {
        const textContent = asset.content || asset.title || "";
        if (textContent) {
          textAssets.push(textContent);
        }
      } else if (asset.assetType === "IMAGE") {
        const imageUrl = asset.fileUrl || "";
        if (imageUrl) {
          imageAssets.push(imageUrl);
        }
      }
    });

    // Combine text assets first, then image URLs
    const allAssets = [...textAssets, ...imageAssets];
    const newContent = allAssets.join("\n");

    // Always append assets below existing content
    const updatedContent = content ? content + "\n" + newContent : newContent;
    setContent(updatedContent);

    // Update the textarea value
    if (textareaRef.current) {
      textareaRef.current.value = updatedContent;
    }
  };

  return (
    <fetcher.Form method="post" className="w-full" onSubmit={handleSubmit}>
      <div className="relative">
        <Textarea
          ref={textareaRef}
          name="content"
          className={contentError ? "border-red-500" : ""}
          placeholder="Start writing your post here..."
          rows={6}
          disabled={fetcher.state !== "idle"}
          value={content}
          onChange={(e) => {
            setContent(e.target.value);
            setContentError("");
          }}
        />
        <Button
          type="button"
          variant="outline"
          size="sm"
          onClick={() => setShowAssetBrowser(true)}
          disabled={fetcher.state !== "idle"}
          className="absolute right-2 top-2"
        >
          <svg
            xmlns="http://www.w3.org/2000/svg"
            className="mr-1 h-4 w-4"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
