/**
 * File Upload Handler for Bulk Posts
 * 
 * Handles file selection, validation, and processing for bulk uploads
 */

import type { BulkPostsHandlerDeps } from "~/features/posts/types";
import { resizeImage } from "~/features/upload/image-resize";
import { logClientError } from "~/lib/error-handler.client";
import { isVideoFile } from "~/utils/media-helpers";
// File size limits
const MAX_IMAGE_SIZE = 10 * 1024 * 1024; // 10MB for images
const MAX_VIDEO_SIZE = 100 * 1024 * 1024; // 100MB for videos
const MAX_TOTAL_SIZE = 100 * 1024 * 1024; // 100MB total

/**
 * Handle file selection and processing for bulk uploads
 */
export function handleFileChange(
  e: React.ChangeEvent<HTMLInputElement>,
  deps: Pick<
    BulkPostsHandlerDeps,
    | "posts"
    | "setPosts"
    | "user"
    | "scheduleIntervals"
    | "setIsProcessing"
    | "setProcessingProgress"
    | "setFirstItemTimeManuallyChanged"
  >,
): Promise<void> {
  const {
    posts,
    setPosts,
    user,
    scheduleIntervals,
    setIsProcessing,
    setProcessingProgress,
    setFirstItemTimeManuallyChanged,
  } = deps;
  const selectedFiles = Array.from(e.target.files || []);

  // Check total size
  const totalSize = selectedFiles.reduce((sum, file) => sum + file.size, 0);
  if (totalSize > MAX_TOTAL_SIZE) {
    alert("Total file size exceeds 100MB. Please select smaller files.");
    return;
  }

  // Check individual file size limits
  for (const file of selectedFiles) {
    const isVideo = isVideoFile(file);
    if (isVideo && file.size > MAX_VIDEO_SIZE) {
      alert(
        `Video file ${file.name} exceeds 100MB limit. Please select a smaller file.`,
      );
      return;
    } else if (!isVideo && file.size > MAX_IMAGE_SIZE) {
      alert(
        `Image file ${file.name} exceeds 10MB limit. Please select a smaller file.`,
      );
      return;
    }
  }

  setIsProcessing(true);
  setProcessingProgress({ current: 0, total: selectedFiles.length });

  // Process files in chunks to prevent memory overload
  const CHUNK_SIZE = 10;
  const processedFiles: File[] = [];

  try {
    for (let i = 0; i < selectedFiles.length; i += CHUNK_SIZE) {
      const chunk = selectedFiles.slice(i, i + CHUNK_SIZE);
      const chunkProcessed = await Promise.all(
        chunk.map(async (file) => {
          // For image files, resize and process. For video files, use as is.
          if (isVideoFile(file)) {
            return file; // Return video files as-is
          } else {
            // Process image files - resize and remove metadata
            const resized = await resizeImage(file);
            return resized;
          }
        }),
      );
      processedFiles.push(...chunkProcessed);

      // Update progress
      setProcessingProgress({
        current: i + chunk.length,
        total: selectedFiles.length,
      });

      // Allow browser to breathe between chunks
      await new Promise((resolve) => setTimeout(resolve, 100));
    }
  } catch (error) {
    logClientError(
      error instanceof Error ? error : new Error(String(error)),
      {
        component: "bulkposts",
        action: "handleFileChange",
        fileCount: selectedFiles.length,
      },
    );
    alert("Error processing media files. Please try again.");
    setIsProcessing(false);
    return;
  }

  const newPosts = processedFiles.map((file, index) => {
    // Get current date in user's timezone
    const now = new Date();
    const userTimezone = user?.timezone;

    const localDate = new Date(
      now.toLocaleString("en-US", { timeZone: userTimezone }),
    );

    // Add index+4 hours to schedule 4 post per hour (default)
    localDate.setHours(
      localDate.getHours() + (index + Number(scheduleIntervals?.[0] || 4)),
    );

    return {
      file,
      caption: "",
      queueType: "unassigned",
      isRecyclable: false,
      scheduledFor: localDate
        .toLocaleString("en-US", {
          year: "numeric",
          month: "2-digit",
          day: "2-digit",
          hour: "2-digit",
          minute: "2-digit",
          hour12: false,
        })
        .replace(/(\d+)\/(\d+)\/(\d+),\s(\d+):(\d+)/, "$3-$1-$2T$4:$5"),
    };
  });

  setPosts([...posts, ...newPosts]);
  setIsProcessing(false);
  // Reset flag when new files are uploaded
  setFirstItemTimeManuallyChanged(false);
}

/**
 * Hashtag Handler for Bulk Posts
 * 
 * Handles hashtag management and display based on queue type
 */

import type { QueueType } from "~/features/posts/types";
import { logClientError } from "~/lib/error-handler.client";

/**
 * Update displayed hashtags based on queue type
 */
export async function updateDisplayedHashtags(
  queueTypeName: string,
  queueTypes: QueueType[],
  tags: string[],
  setSelectedQueueType: (type: string) => void,
  setDisplayedHashtags: (hashtags: string | string[]) => void,
): Promise<void> {
  setSelectedQueueType(queueTypeName);

  if (queueTypeName === "unassigned") {
    setDisplayedHashtags(tags);
    return;
  }

  // Find the queue type object to get its ID
  const selectedQueueType = queueTypes.find(
    (qt) => (typeof qt === "string" ? qt : qt.name) === queueTypeName,
  );
  const queueTypeId =
    typeof selectedQueueType === "object" ? selectedQueueType.id : null;

  try {
    const response = await fetch("/api/effective-hashtags", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        queueTypeId,
        queueTypeName: queueTypeName, // Keep for backward compatibility
      }),
    });

    if (response.ok) {
      const data = (await response.json()) as { hashtags?: string | string[] };
      setDisplayedHashtags(data.hashtags || tags);
    } else {
      setDisplayedHashtags(tags);
    }
  } catch (error) {
    logClientError(
      error instanceof Error ? error : new Error(String(error)),
      {
        component: "bulkposts",
        action: "updateDisplayedHashtags",
        queueTypeName,
      },
    );
    setDisplayedHashtags(tags);
  }
}

/**
 * Queue Type Handlers for Bulk Posts
 * 
 * Handles queue type changes for individual and bulk posts
 */

import type { BulkPost, BulkPostsHandlerDeps, QueueType } from "~/features/posts/types";
import {
  isIntervalScheduleConfig,
  isFixedSlotsScheduleConfig,
} from "~/features/posts/types";
import { logClientError } from "~/lib/error-handler.client";

import { updateDisplayedHashtags } from "./hashtag.handler";

/**
 * Handle queue type change for a single post
 */
export function handleQueueTypeChange(
  index: number,
  value: string,
  deps: Pick<
    BulkPostsHandlerDeps,
    | "posts"
    | "setPosts"
    | "queueTypes"
    | "tags"
    | "user"
    | "setDisplayedHashtags"
    | "setSelectedQueueType"
  >,
): Promise<void> {
  const {
    posts,
    setPosts,
    queueTypes,
    tags,
    user,
    setDisplayedHashtags,
    setSelectedQueueType,
  } = deps;
  const updatedPosts = [...posts];
  updatedPosts[index].queueType = value;

  // Find the queue type object to get its ID
  const selectedQueueType = queueTypes.find(
    (qt) => (typeof qt === "string" ? qt : qt.name) === value,
  );
  const queueTypeId =
    typeof selectedQueueType === "object" ? selectedQueueType.id : null;

  // Auto-calculate schedule time if not unassigned
  if (value !== "unassigned" && queueTypeId) {
    try {
      const requestBody = {
        queueTypeId,
        queueTypeName: value, // Keep for backward compatibility
        userId: user?.id,
      };

      const response = await fetch("/api/queue-schedule", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(requestBody),
      });

      if (response.ok) {
        const responseData = (await response.json()) as { scheduledTime?: string };
        const { scheduledTime } = responseData;
        if (scheduledTime) {
          updatedPosts[index].scheduledFor = scheduledTime;
        }
      }
    } catch (error) {
      logClientError(
        error instanceof Error ? error : new Error(String(error)),
        {
          component: "bulkposts",
          action: "handleQueueTypeChange",
          queueType: value,
        },
      );
    }
  } else {
    updatedPosts[index].scheduledFor = "";
  }

  setPosts(updatedPosts);

  // Update displayed hashtags if this is the predominant queue type
  const queueTypeCounts: Record<string, number> = {};
  updatedPosts.forEach((post) => {
    queueTypeCounts[post.queueType] =
      (queueTypeCounts[post.queueType] || 0) + 1;
  });

  const mostUsedQueueType = Object.keys(queueTypeCounts).reduce(
    (a, b) => (queueTypeCounts[a] > queueTypeCounts[b] ? a : b),
    "unassigned",
  );

  if (mostUsedQueueType !== value) {
    await updateDisplayedHashtags(
      mostUsedQueueType,
      queueTypes,
      tags,
      setSelectedQueueType,
      setDisplayedHashtags,
    );
  }
}

/**
 * Handle bulk queue update for all posts
 */
export function handleBulkQueueUpdate(
  queueType: string,
  deps: Pick<
    BulkPostsHandlerDeps,
    | "posts"
    | "setPosts"
    | "queueTypes"
    | "tags"
    | "user"
    | "setDisplayedHashtags"
    | "setSelectedQueueType"
    | "firstItemTimeManuallyChanged"
  >,
): Promise<void> {
  const {
    posts,
    setPosts,
    queueTypes,
    tags,
    user,
    setDisplayedHashtags,
    setSelectedQueueType,
    firstItemTimeManuallyChanged,
  } = deps;

  if (posts.length === 0) return;

  // Update displayed hashtags
  await updateDisplayedHashtags(
    queueType,
    queueTypes,
    tags,
    setSelectedQueueType,
    setDisplayedHashtags,
  );

  // Get the base schedule time from the API (this is the next available time after last scheduled post)
  let baseTime: string | null = null;
  if (queueType !== "unassigned") {
    // If first item time was manually changed, use it as base
    if (firstItemTimeManuallyChanged && posts[0].scheduledFor) {
      baseTime = posts[0].scheduledFor;
    } else {
      // Original behavior - fetch from API
      const selectedQueueType = queueTypes.find(
        (qt) => (typeof qt === "string" ? qt : qt.name) === queueType,
      );
      const queueTypeId =
        typeof selectedQueueType === "object" ? selectedQueueType.id : null;

      const requestBody = {
        queueTypeId,
        queueTypeName: queueType, // Keep for backward compatibility
        userId: user?.id,
      };

      const response = await fetch("/api/queue-schedule", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(requestBody),
      });

      if (response.ok) {
        const responseData = (await response.json()) as { scheduledTime?: string };
        const { scheduledTime } = responseData;
        baseTime = scheduledTime;
      }
    }
  }

  // Find the queue type configuration for bulk scheduling
  const queueTypeConfig = queueTypes.find(
    (qt) => qt.name === queueType,
  );

  const updatedPosts = posts.map((post, index) => {
    let scheduledFor = post.scheduledFor;

    // Auto-calculate schedule time if not unassigned
    if (queueType !== "unassigned" && baseTime && queueTypeConfig) {
      // Calculate each post's time based on the base time + offsets
      const baseDate = new Date(baseTime);
      let calculatedTime = "";

      if (queueTypeConfig.scheduleType === "INTERVAL") {
        const config = queueTypeConfig.scheduleConfig;
        let intervalHours = 4; // default

        if (config && isIntervalScheduleConfig(config)) {
          if (config.useGlobalInterval) {
            intervalHours = user?.scheduleInterval?.[0] || 4;
          } else {
            intervalHours = config.intervalHours || 4;
          }
        }

        // Add interval * index to base time
        const newDate = new Date(baseDate);
        newDate.setHours(newDate.getHours() + index * intervalHours);

        // Format back to datetime-local format
        const year = newDate.getFullYear();
        const month = String(newDate.getMonth() + 1).padStart(2, "0");
        const day = String(newDate.getDate()).padStart(2, "0");
        const hours = String(newDate.getHours()).padStart(2, "0");
        const minutes = String(newDate.getMinutes()).padStart(2, "0");

        calculatedTime = `${year}-${month}-${day}T${hours}:${minutes}`;
      } else if (queueTypeConfig.scheduleType === "FIXED_SLOTS") {
        const config = queueTypeConfig.scheduleConfig;
        const slots =
          config && isFixedSlotsScheduleConfig(config) ? config.slots : [];

        if (slots.length > 0) {
          // Sort slots to ensure consistent ordering
          const sortedSlots = slots
            .map((slot) => {
              const [hours, minutes] = slot.split(":").map(Number);
              return {
                slot,
                hours,
                minutes,
                totalMinutes: hours * 60 + minutes,
              };
            })
            .sort((a, b) => a.totalMinutes - b.totalMinutes);

          // Get the current slot index based on the base time
          const baseHours = baseDate.getHours();
          const baseMinutes = baseDate.getMinutes();
          const baseTotalMinutes = baseHours * 60 + baseMinutes;

          let currentSlotIndex = 0;
          for (let i = 0; i < sortedSlots.length; i++) {
            if (sortedSlots[i].totalMinutes >= baseTotalMinutes) {
              currentSlotIndex = i;
              break;
            }
          }

          // Calculate which slot this post should use
          const targetSlotIndex =
            (currentSlotIndex + index) % sortedSlots.length;
          const targetSlot = sortedSlots[targetSlotIndex];

          // Calculate how many days to add
          const daysToAdd = Math.floor(
            (currentSlotIndex + index) / sortedSlots.length,
          );

          // Set the time to the target slot
          const newDate = new Date(baseDate);
          newDate.setHours(targetSlot.hours, targetSlot.minutes, 0, 0);
          newDate.setDate(newDate.getDate() + daysToAdd);

          // Format back to datetime-local format
          const year = newDate.getFullYear();
          const month = String(newDate.getMonth() + 1).padStart(2, "0");
          const day = String(newDate.getDate()).padStart(2, "0");
          const hours = String(newDate.getHours()).padStart(2, "0");
          const minutes = String(newDate.getMinutes()).padStart(2, "0");

          calculatedTime = `${year}-${month}-${day}T${hours}:${minutes}`;
        }
      }

      if (calculatedTime) {
        scheduledFor = calculatedTime;
      }
    } else if (queueType === "unassigned") {
      scheduledFor = "";
    }

    return {
      ...post,
      queueType,
      scheduledFor,
    };
  });

  setPosts(updatedPosts);
}

import { useFetcher } from "@remix-run/react";
import { useState, useEffect } from "react";

import type { PostData, LongFormPostData } from "~/features/posts/types";
interface UseDashboardStateProps {
  scheduledPosts: PostData[];
  userTimezone?: string | null;
}

/**
 * Custom hook for managing dashboard state and operations
 */
export function useDashboardState({
  scheduledPosts,
  userTimezone,
}: UseDashboardStateProps) {
  const [sortConfig, setSortConfig] = useState({
    key: "scheduledFor",
    direction: "asc" as "asc" | "desc",
  });
  const [searchTerm, setSearchTerm] = useState("");
  const [countdowns, setCountdowns] = useState<Record<string, string>>({});
  const [selectedPost, setSelectedPost] = useState<PostData | null>(null);
  const [selectedPosts, setSelectedPosts] = useState<Set<string>>(new Set());
  const [selectedMedia, setSelectedMedia] = useState<string | null>(null);
  const [isMediaModalOpen, setIsMediaModalOpen] = useState(false);

  const [selectedLongFormPost, setSelectedLongFormPost] = useState<LongFormPostData | null>(null);
  const [showEditModal, setShowEditModal] = useState(false);
  const [showRescheduleModal, setShowRescheduleModal] = useState(false);
  const [postToEdit, setPostToEdit] = useState<PostData | LongFormPostData | null>(null);
  const [postToReschedule, setPostToReschedule] = useState<PostData | LongFormPostData | null>(null);
  interface FetcherData {
    success?: boolean;
  }
  const bulkDeleteFetcher = useFetcher<FetcherData>();

  // Update countdowns
  useEffect(() => {
    const updateCountdowns = () => {
      const tz = userTimezone || "UTC";
      const now = new Date(
        new Date().toLocaleString("en-US", { timeZone: tz }),
      ).getTime();
      const newCountdowns: Record<string, string> = {};

      scheduledPosts.forEach((post) => {
        const scheduledFor = post.scheduledFor;
        const scheduledForValue = typeof scheduledFor === "string" || typeof scheduledFor === "number" ? scheduledFor : "0";
        const utcTime = parseInt(String(scheduledForValue || 0)) * 1000;
        const userTime = new Date(utcTime).toLocaleString("en-US", {
          timeZone: tz,
        });
        const scheduledTime = new Date(userTime).getTime();
        const distance = scheduledTime - now;

        if (distance > 0) {
          const days = Math.floor(distance / (1000 * 60 * 60 * 24));
          const hours = Math.floor(
            (distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60),
          );
          const minutes = Math.floor(
            (distance % (1000 * 60 * 60)) / (1000 * 60),
          );
          newCountdowns[post.id] = `${days}d ${hours}h ${minutes}m`;
        } else {
          newCountdowns[post.id] = "Due now";
        }
      });

      setCountdowns(newCountdowns);
    };

    updateCountdowns();
    const timer = setInterval(updateCountdowns, 60000);
    return () => clearInterval(timer);
  }, [scheduledPosts, userTimezone]);

  // Clear selected posts after bulk delete
  useEffect(() => {
    if (bulkDeleteFetcher.data?.success) {
      setSelectedPosts(new Set());
    }
  }, [bulkDeleteFetcher.data]);

  // Sort posts
  const sortedPosts = [...scheduledPosts].sort((a, b) => {
    if (sortConfig.key === "scheduledFor") {
      const aScheduled = a.scheduledFor;
      const bScheduled = b.scheduledFor;
      const aValue = typeof aScheduled === "string" || typeof aScheduled === "number" ? aScheduled : "0";
      const bValue = typeof bScheduled === "string" || typeof bScheduled === "number" ? bScheduled : "0";
      const dateA = parseInt(String(aValue)) * 1000;
      const dateB = parseInt(String(bValue)) * 1000;
      return sortConfig.direction === "asc" ? dateA - dateB : dateB - dateA;
    }
    // For other keys, access safely
    const key = sortConfig.key as keyof PostData;
    const aValue = a[key] as string | number | undefined;
    const bValue = b[key] as string | number | undefined;
    if (aValue === undefined || bValue === undefined) return 0;
    if (aValue < bValue)
      return sortConfig.direction === "asc" ? -1 : 1;
    if (aValue > bValue)
      return sortConfig.direction === "asc" ? 1 : -1;
    return 0;
  });

  // Filter posts
  const filteredPosts = sortedPosts.filter((post) =>
    post.caption?.toLowerCase().includes(searchTerm.toLowerCase()),
  );

  const requestSort = (key: string) => {
    setSortConfig((current) => ({
      key,
      direction:
        current.key === key && current.direction === "asc" ? "desc" : "asc",
    }));
  };

  const togglePostSelection = (postId: string) => {
    setSelectedPosts((prev) => {
      const newSet = new Set(prev);
      if (newSet.has(postId)) {
        newSet.delete(postId);
      } else {
        newSet.add(postId);
      }
      return newSet;
    });
  };

  const toggleSelectAll = () => {
    if (selectedPosts.size === filteredPosts.length) {
      setSelectedPosts(new Set());
    } else {
      setSelectedPosts(new Set(filteredPosts.map((post) => post.id)));
    }
  };

  const handleBulkDelete = () => {
    if (selectedPosts.size === 0) return;

    const formData = new FormData();
    formData.append("_action", "bulkDelete");
    formData.append("postIds", JSON.stringify(Array.from(selectedPosts)));

    bulkDeleteFetcher.submit(formData, { method: "post" });
  };

  const handleMediaClick = (mediaSrc: string) => {
    setSelectedMedia(mediaSrc);
    setIsMediaModalOpen(true);
  };

  const handleCloseMediaModal = () => {
    setIsMediaModalOpen(false);
    setSelectedMedia(null);
  };

  const handleEditPost = (post: PostData | LongFormPostData) => {
    setPostToEdit(post);
    setShowEditModal(true);
  };

  const handleReschedulePost = (post: PostData | LongFormPostData) => {
    setPostToReschedule(post);
    setShowRescheduleModal(true);
  };

  const handleCloseEditModal = () => {
    setShowEditModal(false);
    setPostToEdit(null);
  };

  const handleCloseRescheduleModal = () => {
    setShowRescheduleModal(false);
    setPostToReschedule(null);
  };

  const handleModalSuccess = () => {
    window.location.reload();
  };

  return {
    sortConfig,
    searchTerm,
    countdowns,
    selectedPost,
    selectedPosts,
    selectedMedia,
    isMediaModalOpen,
    selectedLongFormPost,
    showEditModal,
    showRescheduleModal,
    postToEdit,
    postToReschedule,
    filteredPosts,
    bulkDeleteFetcher,
    requestSort,
    setSearchTerm,
    setSelectedPost,
    setSelectedLongFormPost,
    togglePostSelection,
    toggleSelectAll,
    handleBulkDelete,
    handleMediaClick,
    handleCloseMediaModal,
    handleEditPost,
    handleReschedulePost,
    handleCloseEditModal,
    handleCloseRescheduleModal,
    handleModalSuccess,
  };
}

import { useFetcher } from "@remix-run/react";
import { useState, useEffect, useCallback } from "react";

import { signDraftForScheduling } from "~/features/posts/services/draft-sign.server";
import type { UserData, HashTagPreset, PostData } from "~/features/posts/types";
import { useOptionalUser } from "~/lib/remix-utils";

interface Post {
  content?: string | null;
  caption?: string | null;
  queueType?: { name: string } | null;
  hashTagPresetId?: string | null;
  fileUrl?: string[] | null;
}

interface UseDraftEditStateProps {
  post: Post;
  user: UserData;
  hashTagPresets: HashTagPreset[];
}

/**
 * Custom hook for managing draft edit state and operations
 */
export function useDraftEditState({
  post,
  user,
  hashTagPresets,
}: UseDraftEditStateProps) {
  const fetcher = useFetcher();
  const currentUser = useOptionalUser();
  const [content, setContent] = useState(post.content || "");
  const [caption] = useState(post.caption || "");
  const [selectedQueue, setSelectedQueue] = useState(
    (typeof post.queueType === "object" && post.queueType?.name) || (typeof post.queueType === "string" ? post.queueType : "unassigned"),
  );
  const [scheduledFor, setScheduledFor] = useState("");
  const [showResumeModal, setShowResumeModal] = useState(false);
  const [useHashtagPresets, setUseHashtagPresets] = useState(
    !!post.hashTagPresetId,
  );
  const [selectedHashtagPresetId, setSelectedHashtagPresetId] = useState(
    post.hashTagPresetId || null,
  );
  const [selectedHashtags, setSelectedHashtags] = useState("");

  const isSubmitting = fetcher.state !== "idle";

  const handleResumeClick = () => {
    if (!scheduledFor) {
      alert("Please set a schedule time first");
      return;
    }
    setShowResumeModal(true);
  };

  const calculateQueueScheduleTime = useCallback(async (queueTypeName: string) => {
    if (queueTypeName === "unassigned") {
      setScheduledFor("");
      return;
    }

    try {
      const response = await fetch("/api/queue-schedule", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          queueTypeName,
          userId: currentUser?.id,
        }),
      });

      if (response.ok) {
        const data = (await response.json()) as { scheduledTime?: string };
        const scheduledTime = data.scheduledTime;
        if (scheduledTime) {
          setScheduledFor(scheduledTime);
        }
      }
    } catch (error) {
      console.error("Error calculating schedule time:", error);
    }
  }, [currentUser?.id]);

  const handleSignAndResume = async () => {
    try {
      // Convert currentUser (User | null | undefined) to UserData | null
      const currentUserData: UserData | null = currentUser ? {
        id: currentUser.id,
        npub: currentUser.npub,
        timezone: currentUser.timezone || null,
        scheduleInterval: currentUser.scheduleInterval ? currentUser.scheduleInterval.map(Number).filter(n => !isNaN(n)) : undefined,
        userRelays: currentUser.userRelays,
        showHashTagsinPosts: currentUser.showHashTagsinPosts,
        isEnabled: currentUser.isEnabled,
      } : null;

      const result = await signDraftForScheduling({
        content,
        caption,
        scheduledFor,
        selectedQueue,
        useHashtagPresets,
        selectedHashtags,
        user,
        currentUser: currentUserData,
        post: post as unknown as PostData,
      });

      const formData = new FormData();
      formData.append("_action", "resume");
      formData.append("content", content);
      formData.append("caption", caption || content);
      formData.append("queueType", selectedQueue);
      formData.append("scheduledFor", result.scheduledForUnix.toString());
      formData.append("signedEvent", JSON.stringify(result.signedEvent));
      formData.append("nostrEvent", JSON.stringify(result.nostrEvent));

      // Add hashtag preset data
      if (useHashtagPresets && selectedHashtagPresetId) {
        formData.append("hashTagPresetId", selectedHashtagPresetId);
        formData.append("useHashtagPresets", "on");
      }

      fetcher.submit(formData, { method: "post" });
      setShowResumeModal(false);
    } catch (error) {
      console.error("Error signing event:", error);
      alert("Error signing the post. Please try again.");
    }
  };

  const handleHashtagPresetSelect = (presetId: string, hashtags: string) => {
    setSelectedHashtagPresetId(presetId);
    setSelectedHashtags(hashtags);
  };

  useEffect(() => {
    if (selectedQueue !== "unassigned") {
      void calculateQueueScheduleTime(selectedQueue);
    } else {
      setScheduledFor("");
    }
  }, [selectedQueue, calculateQueueScheduleTime]);

  // Initialize hashtag preset data on component mount
  useEffect(() => {
    if (post.hashTagPresetId && hashTagPresets.length > 0) {
      const preset = hashTagPresets.find((p) => p.id === post.hashTagPresetId);
      if (preset) {
        setSelectedHashtags(preset.tags || "");
      }
    }
  }, [post.hashTagPresetId, hashTagPresets]);

  return {
    content,
    selectedQueue,
    scheduledFor,
    showResumeModal,
    useHashtagPresets,
    selectedHashtagPresetId,
    isSubmitting,
    fetcher,
    setContent,
    setSelectedQueue,
    setScheduledFor,
    setShowResumeModal,
    setUseHashtagPresets,
    handleResumeClick,
    handleSignAndResume,
    handleHashtagPresetSelect,
  };
}

import { useState, useEffect, useRef } from "react";
import { toast } from "react-hot-toast";

import type { PostData, LongFormPostData, UserData, HashTagPreset } from "~/features/posts/types";
import type { EditorJSInstance as EditorJSInstanceType, EditorJSAPI } from "~/features/posts/types/editorjs.types";
import { resizeImage } from "~/features/upload/image-resize";
import { uploadMultipleFiles } from "~/features/upload/upload.client";
import { logClientError } from "~/lib/error-handler.client";
import {
  signEventFn,
  convertEditorJSToMarkdown,
  convertMarkdownToEditorJS,
} from "~/lib/nostr";

interface UseEditPostModalProps {
  post: PostData | LongFormPostData;
  user?: UserData;
  hashTagPresets?: HashTagPreset[];
  isLongform: boolean;
}

export function useEditPostModal({
  post,
  user,
  hashTagPresets = [],
  isLongform,
}: UseEditPostModalProps) {
  // Form fields for regular posts
  const [caption, setCaption] = useState("caption" in post ? (post.caption || "") : "");
  const [selectedQueueType, setSelectedQueueType] = useState(
    post?.queueType?.id ?? "",
  );

  // Form fields for longform posts
  const [title, setTitle] = useState("title" in post ? (post.title || "") : "");
  const [summary, setSummary] = useState("summary" in post ? (post.summary || "") : "");
  const [content, setContent] = useState("");
  const [image, setImage] = useState("image" in post ? (post.image || "") : "");

  // Schedule fields
  const [scheduledFor, setScheduledFor] = useState<Date | null>(null);

  // Image/media handling
  const [existingImages, setExistingImages] = useState<string[]>([]);
  const [newFiles, setNewFiles] = useState<File[]>([]);
  const [isUploadingImages, setIsUploadingImages] = useState(false);

  // Hashtag preset handling
  const [useHashtagPresets, setUseHashtagPresets] = useState(false);
  const [selectedHashtagPresetId, setSelectedHashtagPresetId] = useState<
    string | null
  >(null);
  const [selectedHashtagPresetTags, setSelectedHashtagPresetTags] =
    useState("");
  const [manualHashtags, setManualHashtags] = useState("");

  // EditorJS state for longform content
  const editorRef = useRef<EditorJSInstanceType | null>(null);
  const editorInitialized = useRef(false);
  const [editorReady, setEditorReady] = useState(false);

  // Initialize form fields from post
  useEffect(() => {
    if (post) {
      if (isLongform && "title" in post) {
        setTitle(post.title || "");
        setSummary(post.summary || "");
        setImage(post.image || "");
        setContent(post.content || "");
        setScheduledFor(post.publishedAt ? new Date(post.publishedAt) : null);
      } else if (!isLongform && "caption" in post) {
        setCaption(post.caption || "");
        setSelectedQueueType(post.queueType?.id ?? "");
        setScheduledFor(
          post.scheduledFor
            ? new Date(parseInt(post.scheduledFor) * 1000)
            : null,
        );

        // Parse existing images
        if ("fileUrl" in post && post.fileUrl && Array.isArray(post.fileUrl)) {
          const urls = post.fileUrl
            .map((url: string) => {
              if (typeof url === "string" && url.startsWith("[")) {
                try {
                  const parsed = JSON.parse(url);
                  return Array.isArray(parsed) ? parsed : [url];
                } catch {
                  return [url];
                }
              }
              return Array.isArray(url) ? url : [url];
            })
            .flat();
          setExistingImages(
            urls.filter((url) => typeof url === "string" && url.length > 0),
          );
        }

        // Parse existing hashtags
        const existingHashtags = post.hashtags || "";
        if (existingHashtags) {
          setManualHashtags(existingHashtags);
        }

        // Check if post uses hashtag preset
        if (post.hashTagPresetId && hashTagPresets.length > 0) {
          const preset = hashTagPresets.find(
            (p) => p.id === post.hashTagPresetId,
          );
          if (preset) {
            setUseHashtagPresets(true);
            setSelectedHashtagPresetId(preset.id);
            setSelectedHashtagPresetTags(preset.tags || "");
          }
        }
      }
    }
  }, [post, isLongform, hashTagPresets]);

  // Initialize EditorJS for longform posts
  useEffect(() => {
    if (!isLongform) return;

    const loadEditor = async () => {
      if (
        typeof window !== "undefined" &&
        !editorRef.current &&
        !editorInitialized.current
      ) {
        editorInitialized.current = true;

        try {
          const EditorJS = (await import("@editorjs/editorjs")).default;

          const editorInstance = new EditorJS({
            holder: "longform-editorjs",
            minHeight: 300,
            tools: {
              header: {
                class: (await import("@editorjs/header")).default as unknown as new (config?: { placeholder?: string; levels?: number[]; defaultLevel?: number }) => unknown,
                config: {
                  placeholder: "Enter a header",
                  levels: [2, 3, 4],
                  defaultLevel: 3,
                },
              },
              list: {
                class: (await import("@editorjs/list")).default,
                inlineToolbar: true,
              },
              quote: {
                class: (await import("@editorjs/quote")).default,
                inlineToolbar: true,
                config: {
                  quotePlaceholder: "Enter a quote",
                  captionPlaceholder: "Quote's author",
                },
              },
              code: {
                class: (await import("@editorjs/code")).default,
                config: {
                  placeholder: "Enter code here...",
                },
              },
              inlineCode: {
                class: (await import("@editorjs/inline-code")).default,
              },
              linkTool: {
                class: (await import("@editorjs/link")).default as unknown as new (config?: { endpoint?: string }) => unknown,
                config: {
                  endpoint: "/api/link-preview",
                },
              },
              embed: {
                class: (await import("@editorjs/embed")).default as unknown as new (config?: { services?: Record<string, boolean> }) => unknown,
                config: {
                  services: {
                    youtube: true,
                    twitter: true,
                  },
                },
              },
              image: {
                class: (await import("@editorjs/image")).default,
                config: {
                  buttonContent: "Select Image",
                  captionPlaceholder: "",
                  withBorder: false,
                  withBackground: false,
                  stretched: false,
                  uploader: {
                    uploadByFile: async (file: File) => {
                      try {
                        const formData = new FormData();
                        formData.append("image", file);

                        const response = await fetch(
                          "/api/upload-editorjs-image",
                          {
                            method: "POST",
                            body: formData,
                          },
                        );

                        if (!response.ok) {
                          throw new Error(`Server error: ${response.status}`);
                        }

                        const result = (await response.json()) as {
                          success?: number;
                          file?: { url?: string };
                          error?: string;
                        };

                        if (result.success === 1 && result.file?.url) {
                          return {
                            success: 1,
                            file: {
                              url: result.file.url,
                            },
                          };
                        } else {
                          throw new Error(result.error || "Upload failed");
                        }
                      } catch (error) {
                        const { handleAsyncError } = await import("~/lib/error-handler.client");
                        handleAsyncError(error, {
                          component: "EditPostModal",
                          action: "uploadImage",
                        }, false);
                        throw error;
                      }
                    },
                  },
                },
              },
            },
            onChange: (async (api: EditorJSAPI) => {
              try {
                const outputData = await api.saver.save();
                const markdownContent = convertEditorJSToMarkdown(outputData);
                setContent(markdownContent);
              } catch (error) {
                console.error("Editor save error:", error);
              }
            }),
          });

          editorRef.current = editorInstance;
          await editorRef.current.isReady;
          setEditorReady(true);
        } catch (error) {
          console.error("Error loading EditorJS:", error);
          editorInitialized.current = false;
        }
      }
    };

    void loadEditor();

    return () => {
      if (editorRef.current) {
        try {
          if (editorRef.current.destroy) {
            editorRef.current.destroy();
          }
        } catch (error) {
          logClientError(
            error instanceof Error ? error : new Error(String(error)),
            {
              component: "useEditPostModal",
              action: "cleanup",
              message: "Error during editor cleanup",
            },
            "warning",
          );
        } finally {
          editorRef.current = null;
          editorInitialized.current = false;
          setEditorReady(false);
        }
      }
    };
  }, [isLongform]);

  // Load initial content into EditorJS for longform posts
  useEffect(() => {
    if (!isLongform || !editorReady || !editorRef.current || !content) return;

    const loadInitialContent = async () => {
      if (!editorRef.current) return;
      try {
        await editorRef.current.isReady;
        const editorJSData = convertMarkdownToEditorJS(content);
        await editorRef.current.render(editorJSData);
      } catch (error) {
        console.error("Error loading initial content into EditorJS:", error);
      }
    };

    const timeoutId = setTimeout(() => {
      void loadInitialContent();
    }, 100);
    return () => clearTimeout(timeoutId);
  }, [isLongform, editorReady, content]);

  const formatDateTimeForInput = (date: Date) => {
    const userTimezone = user?.timezone ?? "UTC";
    const dateInUserTz = new Date(
      date.toLocaleString("en-US", { timeZone: userTimezone }),
    );
    const year = dateInUserTz.getFullYear();
    const month = String(dateInUserTz.getMonth() + 1).padStart(2, "0");
    const day = String(dateInUserTz.getDate()).padStart(2, "0");
    const hours = String(dateInUserTz.getHours()).padStart(2, "0");
    const minutes = String(dateInUserTz.getMinutes()).padStart(2, "0");
    return `${year}-${month}-${day}T${hours}:${minutes}`;
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFiles = Array.from(e.target.files || []);
    if (selectedFiles.length === 0) return;

    try {
      const processedFiles = await Promise.all(
        selectedFiles.map(async (file) => {
          if (file.type.startsWith("image/")) {
            return await resizeImage(file);
          }
          return file;
        }),
      );
      setNewFiles((prev) => [...prev, ...processedFiles]);
    } catch (error) {
      console.error("Error processing files:", error);
      toast.error("Error processing files");
    }
  };

  const removeExistingImage = (index: number) => {
    setExistingImages((prev) => prev.filter((_, i) => i !== index));
  };

  const removeNewFile = (index: number) => {
    setNewFiles((prev) => prev.filter((_, i) => i !== index));
  };

  const handleHashtagPresetSelect = (
    presetId: string | null,
    hashtags: string,
  ) => {
    setSelectedHashtagPresetId(presetId);
    setSelectedHashtagPresetTags(hashtags);
  };

  return {
    // State
    caption,
    setCaption,
    selectedQueueType,
    setSelectedQueueType,
    title,
    setTitle,
    summary,
    setSummary,
    content,
    setContent,
    image,
    setImage,
    scheduledFor,
    setScheduledFor,
    existingImages,
    newFiles,
    isUploadingImages,
    setIsUploadingImages,
    useHashtagPresets,
    setUseHashtagPresets,
    selectedHashtagPresetId,
    selectedHashtagPresetTags,
    manualHashtags,
    setManualHashtags,
    editorRef,
    editorReady,
    // Handlers
    handleFileChange,
    removeExistingImage,
    removeNewFile,
    handleHashtagPresetSelect,
    formatDateTimeForInput,
  };
}

import { useNavigation } from "@remix-run/react";
import { useState } from "react";
interface UseLongFormEditStateProps {
  userTags: string;
  hashtagPresets: { id: string; tags: string }[];
}

/**
 * Custom hook for managing longform edit state
 */
export function useLongFormEditState({
  userTags,
  hashtagPresets,
}: UseLongFormEditStateProps) {
  const navigation = useNavigation();
  const [displayedHashtags, setDisplayedHashtags] = useState(userTags || "");
  const [showPreviewModal, setShowPreviewModal] = useState(false);
  const [previewData, setPreviewData] = useState({
    title: "",
    summary: "",
    content: "",
    image: "",
  });

  // Hashtag preset state
  const [useHashtagPresets, setUseHashtagPresets] = useState(false);
  const [selectedHashtagPresetId, setSelectedHashtagPresetId] = useState("");
  const [selectedHashtags, setSelectedHashtags] = useState("");

  const isSubmitting = navigation.state === "submitting";

  // Hashtag preset handlers
  const handleHashtagPresetToggle = (enabled: boolean) => {
    setUseHashtagPresets(enabled);
    if (!enabled) {
      // If disabled, clear manual selection and revert to queue/user default
      setSelectedHashtagPresetId("");
      setSelectedHashtags("");
      // Note: displayedHashtags will be updated by queue type change logic
    } else if (selectedHashtags) {
      // If enabled and we have selected hashtags, show them
      setDisplayedHashtags(selectedHashtags);
    }
  };

  const handleHashtagPresetChange = (presetId: string) => {
    setSelectedHashtagPresetId(presetId);
    const preset = hashtagPresets.find((p) => p.id === presetId);
    const tags = preset?.tags ?? "";
    setSelectedHashtags(tags);
    if (useHashtagPresets) {
      setDisplayedHashtags(tags);
    }
  };

  // Function to update displayed hashtags when queue type changes
  const updateDisplayedHashtags = async (queueTypeName: string) => {
    // Don't update if using manual hashtag presets
    if (useHashtagPresets) {
      return;
    }

    if (queueTypeName === "unassigned") {
      setDisplayedHashtags(userTags || "");
      return;
    }

    try {
      const response = await fetch("/api/effective-hashtags", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          queueTypeName: queueTypeName,
        }),
      });

      if (response.ok) {
        const data = (await response.json()) as { hashtags?: string };
        setDisplayedHashtags(data.hashtags || userTags || "");
      } else {
        setDisplayedHashtags(userTags || "");
      }
    } catch (error) {
      console.error("Error fetching effective hashtags:", error);
      setDisplayedHashtags(userTags || "");
    }
  };

  const handlePreview = (data: {
    title: string;
    summary: string;
    content: string;
    image: string;
  }) => {
    setPreviewData(data);
    setShowPreviewModal(true);
  };

  return {
    displayedHashtags,
    showPreviewModal,
    setShowPreviewModal,
    previewData,
    useHashtagPresets,
    selectedHashtagPresetId,
    selectedHashtags,
    isSubmitting,
    handleHashtagPresetToggle,
    handleHashtagPresetChange,
    updateDisplayedHashtags,
    handlePreview,
  };
}

import { useNavigation } from "@remix-run/react";
import { useState } from "react";
interface UseNewLongFormStateProps {
  userTags: string;
}

/**
 * Custom hook for managing new longform post state
 */
export function useNewLongFormState({ userTags }: UseNewLongFormStateProps) {
  const navigation = useNavigation();
  const [displayedHashtags, setDisplayedHashtags] = useState(userTags || "");
  const [showPreviewModal, setShowPreviewModal] = useState(false);
  const [previewData, setPreviewData] = useState({
    title: "",
    summary: "",
    content: "",
    image: "",
  });
  const [useHashtagPresets, setUseHashtagPresets] = useState(false);
  const [selectedHashtagPresetId, setSelectedHashtagPresetId] = useState<
    string | null
  >(null);
  const [selectedHashtags, setSelectedHashtags] = useState("");

  const isSubmitting = navigation.state === "submitting";

  const handleHashtagPresetSelect = (
    presetId: string | null,
    hashtags: string,
  ) => {
    setSelectedHashtagPresetId(presetId);
    setSelectedHashtags(hashtags);
    if (useHashtagPresets) {
      setDisplayedHashtags(hashtags);
    }
  };

  // Function to update displayed hashtags when queue type changes
  const updateDisplayedHashtags = async (queueTypeName: string) => {
    if (useHashtagPresets && selectedHashtags) {
      // If manual hashtag presets are enabled, use the selected hashtags
      setDisplayedHashtags(selectedHashtags);
      return;
    }

    if (queueTypeName === "Unassigned") {
      setDisplayedHashtags(userTags || "");
      return;
    }

    try {
      const response = await fetch("/api/effective-hashtags", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          queueTypeName: queueTypeName,
        }),
      });

      if (response.ok) {
        const data = (await response.json()) as { hashtags?: string };
        setDisplayedHashtags(data.hashtags || userTags || "");
      } else {
        setDisplayedHashtags(userTags || "");
      }
    } catch (error) {
      console.error("Error fetching effective hashtags:", error);
      setDisplayedHashtags(userTags || "");
    }
  };

  // Update displayed hashtags when hashtag preset usage changes
  const handleUseHashtagPresetsChange = (enabled: boolean) => {
    setUseHashtagPresets(enabled);
    if (!enabled) {
      // When disabling manual presets, revert to queue type hashtags
      // This will trigger through the queue type change logic in the component
    } else if (selectedHashtags) {
      setDisplayedHashtags(selectedHashtags);
    }
  };

  const handlePreview = (data: {
    title: string;
    summary: string;
    content: string;
    image: string;
  }) => {
    setPreviewData(data);
    setShowPreviewModal(true);
  };

  return {
    displayedHashtags,
    showPreviewModal,
    setShowPreviewModal,
    previewData,
    useHashtagPresets,
    selectedHashtagPresetId,
    selectedHashtags,
    isSubmitting,
    handleHashtagPresetSelect,
    updateDisplayedHashtags,
    handleUseHashtagPresetsChange,
    handlePreview,
  };
}

import { useState, useEffect, useCallback } from "react";

import type { QueueType } from "~/features/posts/types";
import { useOptionalUser } from "~/lib/remix-utils";

interface UsePostSchedulingProps {
  queueTypes: (string | QueueType)[];
  scheduleIntervals?: number[];
  userTimezone?: string;
  initialQueue?: string;
  onQueueTypeChange?: (queueType: string) => void;
  onTimeError?: (error: string) => void;
}

export function usePostScheduling({
  queueTypes,
  scheduleIntervals = [],
  userTimezone = "UTC",
  initialQueue = "unassigned",
  onQueueTypeChange,
  onTimeError,
}: UsePostSchedulingProps) {
  const user = useOptionalUser();
  const [selectedQueue, setSelectedQueue] = useState(initialQueue);
  const [scheduledFor, setScheduledFor] = useState("");
  const [timeError, setTimeError] = useState("");

  const calculateQueueScheduleTime = useCallback(async (queueTypeName: string) => {
    if (queueTypeName === "unassigned") {
      setScheduledFor("");
      return;
    }

    // Find the queue type object to get its ID
    const selectedQueueType = queueTypes.find((qt) =>
      typeof qt === "string" ? qt === queueTypeName : qt.name === queueTypeName
    );
    const queueTypeId =
      typeof selectedQueueType === "object" ? selectedQueueType.id : null;

    try {
      const response = await fetch("/api/queue-schedule", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          queueTypeId,
          queueTypeName, // Keep for backward compatibility
          userId: user?.id,
        }),
      });

      if (response.ok) {
        const data = (await response.json()) as { scheduledTime?: string };
        const scheduledTime = data.scheduledTime;
        if (scheduledTime) {
          setScheduledFor(scheduledTime);
        }
        setTimeError("");
        if (onTimeError) {
          onTimeError("");
        }
      }
    } catch (error) {
      console.error("Error calculating schedule time:", error);
    }
  }, [queueTypes, user?.id, onTimeError]);

  const handleScheduleIntervalClick = (intervalHours: string | number) => {
    // Find the currently selected queue type
    const selectedQueueType = queueTypes.find((qt) =>
      typeof qt === "string"
        ? qt === selectedQueue
        : qt.name === selectedQueue
    );

    // If this is a fixed slot queue, use the API to get the next scheduled time instead
    if (
      selectedQueueType &&
      typeof selectedQueueType === "object" &&
      selectedQueueType.scheduleType === "FIXED_SLOTS"
    ) {
      // For fixed slot queues, recalculate the schedule time instead of adding hours
      calculateQueueScheduleTime(selectedQueue);
      return;
    }

    const now = new Date();
    const hoursLater = new Date(
      now.getTime() + parseInt(String(intervalHours)) * 60 * 60 * 1000
    );

    // Format the date in the user's timezone
    const effectiveTimezone = userTimezone || user?.timezone ?? "UTC";
    const formattedDate = hoursLater.toLocaleString("en-US", {
      timeZone: effectiveTimezone,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      hour12: false,
    });

    // Parse the formatted date back into components
    const [datePart, timePart] = formattedDate.split(", ");
    const [month, day, year] = datePart.split("/");
    const [hours, minutes] = timePart.split(":");

    // Create the datetime-local format (YYYY-MM-DDTHH:mm)
    const formattedForInput = `${year}-${month}-${day}T${hours}:${minutes}`;

    setScheduledFor(formattedForInput);
    setTimeError("");
    if (onTimeError) {
      onTimeError("");
    }
  };

  // Calculate schedule time when queue changes
  useEffect(() => {
    if (selectedQueue !== "unassigned") {
      void calculateQueueScheduleTime(selectedQueue);
    }
    // Notify parent component of queue type change
    if (onQueueTypeChange) {
      onQueueTypeChange(selectedQueue);
    }
  }, [selectedQueue, onQueueTypeChange, calculateQueueScheduleTime]);

  const handleScheduledForChange = (value: string) => {
    setScheduledFor(value);
    setTimeError("");
    if (onTimeError) {
      onTimeError("");
    }
  };

  const handleTimeError = (error: string) => {
    setTimeError(error);
    if (onTimeError) {
      onTimeError(error);
    }
  };

  return {
    selectedQueue,
    setSelectedQueue,
    scheduledFor,
    setScheduledFor: handleScheduledForChange,
    timeError,
    setTimeError: handleTimeError,
    calculateQueueScheduleTime,
    handleScheduleIntervalClick,
    scheduleIntervals: scheduleIntervals || user?.scheduleInterval || [],
  };
}

import type { useFetcher } from "@remix-run/react";
import { useState, useEffect } from "react";

import type { PostData } from "~/features/posts/types";
import { signEventFn } from "~/lib/nostr";

interface Post {
  id: string;
  caption?: string | null;
  postedAt: Date | null;
  fileUrl: string[];
  signedEvent: { id: string };
  queueType?: { name: string; color?: string | null } | null;
  status?: string;
  [key: string]: unknown; // Allow additional properties from Prisma
}

type Stats = Record<string, {
    likes?: number;
    replies?: number;
    mentions?: number;
    reposts?: number;
    zaps?: number;
    satszapped?: number;
  }>;

interface User {
  timezone?: string | null;
  relays?: string[];
}

interface RepostFetcherData {
  repostData?: PostData[];
  scheduledRepostData?: PostData[];
  quotePostData?: {
    caption?: string;
    fileUrl?: string | string[];
    queueType?: string;
    scheduledFor?: string;
    originalPostId?: string;
    originalEventId?: string;
    originalEventPubkey?: string;
    [key: string]: unknown;
  };
}

interface IndividualRepostFetcherData {
  repostEventData?: {
    kind: number;
    content: string;
    tags: string[][];
    created_at: number;
    pubkey: string;
    [key: string]: unknown;
  };
  quotePostData?: {
    caption?: string;
    fileUrl?: string | string[];
    queueType?: string;
    scheduledFor?: string;
    originalPostId?: string;
    originalEventId?: string;
    originalEventPubkey?: string;
    [key: string]: unknown;
  };
  error?: boolean;
  message?: string;
}

interface UseRecyclablesStateProps {
  posts: Post[] | PostData[]; // Accept any post type from loader
  stats: Stats;
  user?: User | null;
  repostFetcher: ReturnType<typeof useFetcher<RepostFetcherData>>;
  bulkDeleteFetcher: ReturnType<typeof useFetcher>;
  bulkRepostFetcher: ReturnType<typeof useFetcher>;
  individualRepostFetcher: ReturnType<typeof useFetcher<IndividualRepostFetcherData>>;
}

interface SortConfig {
  key: string;
  direction: "asc" | "desc";
}

/**
 * Custom hook for managing recyclables posts state and operations
 */
export function useRecyclablesState({
  posts,
  stats,
  user,
  repostFetcher,
  bulkDeleteFetcher,
  bulkRepostFetcher,
  individualRepostFetcher,
}: UseRecyclablesStateProps) {
  const [sortConfig, setSortConfig] = useState<SortConfig>({
    key: "postedAt",
    direction: "desc",
  });
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedPost, setSelectedPost] = useState<Post | null>(null);
  const [selectedPosts, setSelectedPosts] = useState<Set<string>>(new Set());
  const [toast, setToast] = useState<{
    type: "success" | "error";
    message: string;
    link?: string;
    linkText?: string;
  } | null>(null);

  // Sort and filter posts
  const sortedPosts = [...posts].sort((a, b) => {
    if (sortConfig.key === "postedAt") {
      const dateA = new Date(a[sortConfig.key] || 0).getTime();
      const dateB = new Date(b[sortConfig.key] || 0).getTime();
      return sortConfig.direction === "asc" ? dateA - dateB : dateB - dateA;
    }

    // Handle engagement metrics sorting
    if (
      [
        "likes",
        "replies",
        "mentions",
        "reposts",
        "zaps",
        "satszapped",
      ].includes(sortConfig.key)
    ) {
      const aStats = (a.signedEvent?.id ? stats[a.signedEvent.id] : {}) || {};
      const bStats = (b.signedEvent?.id ? stats[b.signedEvent.id] : {}) || {};
      const aValue = Number(aStats[sortConfig.key as keyof typeof aStats] ?? 0);
      const bValue = Number(bStats[sortConfig.key as keyof typeof bStats] ?? 0);
      return sortConfig.direction === "asc" ? aValue - bValue : bValue - aValue;
    }

    const aValue = (a as Record<string, unknown>)[sortConfig.key] as string | number | undefined;
    const bValue = (b as Record<string, unknown>)[sortConfig.key] as string | number | undefined;

    // Handle null/undefined values
    if (aValue == null && bValue == null) return 0;
    if (aValue == null) return sortConfig.direction === "asc" ? -1 : 1;
    if (bValue == null) return sortConfig.direction === "asc" ? 1 : -1;

    if (aValue < bValue)
      return sortConfig.direction === "asc" ? -1 : 1;
    if (aValue > bValue)
      return sortConfig.direction === "asc" ? 1 : -1;
    return 0;
  });

  const filteredPosts = sortedPosts.filter((post) =>
    post.caption?.toLowerCase().includes(searchTerm.toLowerCase()),
  );

  const requestSort = (key: string) => {
    setSortConfig((current) => ({
      key,
      direction:
        current.key === key && current.direction === "asc" ? "desc" : "asc",
    }));
  };

  const togglePostSelection = (postId: string) => {
    setSelectedPosts((prev) => {
      const newSet = new Set(prev);
      if (newSet.has(postId)) {
        newSet.delete(postId);
      } else {
        newSet.add(postId);
      }
      return newSet;
    });
  };

  const toggleSelectAll = () => {
    if (selectedPosts.size === filteredPosts.length) {
      setSelectedPosts(new Set());
    } else {
      setSelectedPosts(new Set(filteredPosts.map((post) => post.id)));
    }
  };

  const handleBulkDelete = () => {
    if (selectedPosts.size === 0) return;

    const formData = new FormData();
    formData.append("_action", "bulkDelete");
    formData.append("postIds", JSON.stringify(Array.from(selectedPosts)));

    bulkDeleteFetcher.submit(formData, { method: "post" });
  };

  const handleBulkRepost = () => {
    if (selectedPosts.size === 0) return;

    const formData = new FormData();
    formData.append("_action", "bulkRepost");
    formData.append("postIds", JSON.stringify(Array.from(selectedPosts)));

    bulkRepostFetcher.submit(formData, { method: "post" });
  };

  const handleBulkScheduledRepost = () => {
    if (selectedPosts.size === 0) return;

    const formData = new FormData();
    formData.append("_action", "bulkScheduledRepost");
    formData.append("postIds", JSON.stringify(Array.from(selectedPosts)));

    bulkRepostFetcher.submit(formData, { method: "post" });
  };

  const handleBulkQuote = () => {
    if (selectedPosts.size === 0) return;

    const formData = new FormData();
    formData.append("_action", "bulkQuote");
    formData.append("postIds", JSON.stringify(Array.from(selectedPosts)));

    bulkRepostFetcher.submit(formData, { method: "post" });
  };

  // Handle bulk delete success
  useEffect(() => {
    const data = bulkDeleteFetcher.data as { success?: boolean } | undefined;
    if (data?.success) {
      setSelectedPosts(new Set());
    }
  }, [bulkDeleteFetcher.data]);

  // Handle repost data and navigation
  useEffect(() => {
    const fetcherData = repostFetcher.data as RepostFetcherData | undefined;
    if (fetcherData?.repostData) {
      const postsData = fetcherData.repostData;

      // Prepare repost data with 1 hour default scheduling
      const now = new Date();
      const userTimezone = user?.timezone ?? "UTC";
      const localDate = new Date(
        now.toLocaleString("en-US", { timeZone: userTimezone }),
      );
      localDate.setHours(localDate.getHours() + 1);

      const repostData = postsData.map((post: PostData, index: number) => {
        const scheduleDate = new Date(localDate);
        scheduleDate.setHours(scheduleDate.getHours() + index);

        return {
          caption: post.caption || "",
          fileUrl:
            post.fileUrl &&
              Array.isArray(post.fileUrl) &&
              post.fileUrl.length > 0
              ? post.fileUrl[0]
              : "",
          queueType: post.queueType || "unassigned",
          scheduledFor: scheduleDate
            .toLocaleString("en-US", {
              year: "numeric",
              month: "2-digit",
              day: "2-digit",
              hour: "2-digit",
              minute: "2-digit",
              hour12: false,
            })
            .replace(/(\d+)\/(\d+)\/(\d+),\s(\d+):(\d+)/, "$3-$1-$2T$4:$5"),
          originalPostId: post.id,
        };
      });

      sessionStorage.setItem("repostData", JSON.stringify(repostData));
      window.location.href = "/dashboard/bulkposts?mode=recycle";
      setSelectedPosts(new Set());
    }

    if (fetcherData?.scheduledRepostData) {
      const postsData = fetcherData.scheduledRepostData;

      const now = new Date();
      const userTimezone = user?.timezone ?? "UTC";
      const localDate = new Date(
        now.toLocaleString("en-US", { timeZone: userTimezone }),
      );
      localDate.setHours(localDate.getHours() + 1);

      const scheduledRepostData = postsData.map((post: PostData, index: number) => {
        const scheduleDate = new Date(localDate);
        scheduleDate.setHours(scheduleDate.getHours() + index);

        return {
          caption: "",
          fileUrl: "",
          queueType: post.queueType || "unassigned",
          scheduledFor: scheduleDate
            .toLocaleString("en-US", {
              year: "numeric",
              month: "2-digit",
              day: "2-digit",
              hour: "2-digit",
              minute: "2-digit",
              hour12: false,
            })
            .replace(/(\d+)\/(\d+)\/(\d+),\s(\d+):(\d+)/, "$3-$1-$2T$4:$5"),
          originalPostId: post.id,
          originalEventId: post.signedEvent?.id,
          originalEventPubkey: post.signedEvent?.pubkey,
          isKind6Repost: true,
        };
      });

      sessionStorage.setItem(
        "scheduledRepostData",
        JSON.stringify(scheduledRepostData),
      );
      window.location.href = "/dashboard/bulkposts?mode=repost";
      setSelectedPosts(new Set());
    }

    if (fetcherData?.quotePostData) {
      const quoteData = fetcherData.quotePostData;
      sessionStorage.setItem("quotePostData", JSON.stringify(quoteData));
      window.location.href = "/dashboard/bulkposts?mode=quote";
      setSelectedPosts(new Set());
    }
  }, [repostFetcher.data, user?.timezone, repostFetcher]);

  // Handle individual repost actions
  useEffect(() => {
    const handleRepost = async () => {
      const data = individualRepostFetcher.data as IndividualRepostFetcherData | undefined;

      if (data?.repostEventData) {
        try {
          const eventData = data.repostEventData;

          // Sign the event using client-side signing
          const { signedEvent } = await signEventFn(eventData);

          // Get user relays from user data
          const sanitizedRelays = user?.relays || ["wss://relay.primal.net"];

          // Publish the signed event
          const response = await fetch("/api/publish", {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
            },
            body: JSON.stringify({
              relays: sanitizedRelays,
              event: signedEvent,
            }),
          });

          if (!response.ok) {
            throw new Error("Failed to publish repost");
          }

          // Add delay before showing success toast
          setTimeout(() => {
            setToast({
              type: "success",
              message: "Post reposted successfully!",
              link: `https://primal.net/e/${eventData.tags.find((tag: string[]) => tag[0] === "e")?.[1]}`,
              linkText: "View Original Post",
            });

            // Hide toast after 8 seconds for success with link
            setTimeout(() => setToast(null), 8000);
          }, 1000); // 1 second delay
        } catch (error: unknown) {
          console.error("Repost signing/publishing error:", error);
          const errorMessage = error instanceof Error 
            ? error.message 
            : "Failed to sign or publish repost";
          setToast({
            type: "error",
            message: errorMessage,
          });

          // Hide toast after 5 seconds for errors
          setTimeout(() => setToast(null), 5000);
        }
      } else if (data?.quotePostData) {
        // Handle individual quote post - redirect to bulk posts with single item
        const quoteData = data.quotePostData;

        // Store quote post data in sessionStorage
        sessionStorage.setItem("quotePostData", JSON.stringify(quoteData));

        // Navigate to bulk posts page with quote mode
        window.location.href = "/dashboard/bulkposts?mode=quote";
      } else if (data?.error) {
        setToast({
          type: "error",
          message: data.message || "Failed to create repost",
        });

        // Hide toast after 5 seconds for errors
        setTimeout(() => setToast(null), 5000);
      }
    };

    if (individualRepostFetcher.data) {
      handleRepost();
    }
  }, [individualRepostFetcher.data, user?.relays, individualRepostFetcher]);

  return {
    sortConfig,
    searchTerm,
    selectedPost,
    selectedPosts,
    toast,
    filteredPosts,
    requestSort,
    setSearchTerm,
    setSelectedPost,
    togglePostSelection,
    toggleSelectAll,
    handleBulkDelete,
    handleBulkRepost,
    handleBulkScheduledRepost,
    handleBulkQuote,
    setToast,
  };
}

import { useFetcher } from "@remix-run/react";
import { useState, useEffect } from "react";

import type { CombinedContent, LongFormPostData, PostData } from "~/features/posts/types";
// Union type for posts that can be edited/rescheduled
type EditablePost = PostData | LongFormPostData;

interface UseScheduledStateProps {
  scheduledPosts: PostData[];
  userTimezone?: string | null;
  allContent?: CombinedContent[];
  currentTab: string;
}

/**
 * Custom hook for managing scheduled posts state and operations
 * Extends useDashboardState with mixed bulk delete support
 */
export function useScheduledState({
  scheduledPosts,
  userTimezone,
  allContent,
  currentTab,
}: UseScheduledStateProps) {
  const [sortConfig, setSortConfig] = useState({
    key: "scheduledFor",
    direction: "asc" as "asc" | "desc",
  });
  const [searchTerm, setSearchTerm] = useState("");
  const [countdowns, setCountdowns] = useState<Record<string, string>>({});
  const [selectedPost, setSelectedPost] = useState<PostData | null>(null);
  const [selectedPosts, setSelectedPosts] = useState<Set<string>>(new Set());
  const [selectedMedia, setSelectedMedia] = useState<string | null>(null);
  const [isMediaModalOpen, setIsMediaModalOpen] = useState(false);

  const [selectedLongFormPost, setSelectedLongFormPost] = useState<LongFormPostData | null>(null);
  const [showEditModal, setShowEditModal] = useState(false);
  const [showRescheduleModal, setShowRescheduleModal] = useState(false);
  const [postToEdit, setPostToEdit] = useState<EditablePost | null>(null);
  const [postToReschedule, setPostToReschedule] = useState<EditablePost | null>(null);
  interface FetcherData {
    success?: boolean;
  }
  const bulkDeleteFetcher = useFetcher<FetcherData>();
  const deleteFetcher = useFetcher<FetcherData>();

  // Update countdowns
  useEffect(() => {
    const updateCountdowns = () => {
      const tz = userTimezone || "UTC";
      const now = new Date(
        new Date().toLocaleString("en-US", { timeZone: tz }),
      ).getTime();
      const newCountdowns: Record<string, string> = {};

      scheduledPosts.forEach((post) => {
        const scheduledFor = typeof post.scheduledFor === "string" ? post.scheduledFor : String(post.scheduledFor || "0");
        const utcTime = parseInt(scheduledFor) * 1000;
        const userTime = new Date(utcTime).toLocaleString("en-US", {
          timeZone: tz,
        });
        const scheduledTime = new Date(userTime).getTime();
        const distance = scheduledTime - now;

        if (distance > 0) {
          const days = Math.floor(distance / (1000 * 60 * 60 * 24));
          const hours = Math.floor(
            (distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60),
          );
          const minutes = Math.floor(
            (distance % (1000 * 60 * 60)) / (1000 * 60),
          );
          newCountdowns[post.id] = `${days}d ${hours}h ${minutes}m`;
        } else {
          newCountdowns[post.id] = "Due now";
        }
      });

      setCountdowns(newCountdowns);
    };

    updateCountdowns();
    const timer = setInterval(updateCountdowns, 60000);
    return () => clearInterval(timer);
  }, [scheduledPosts, userTimezone]);

  // Clear selected posts after bulk delete
  useEffect(() => {
    if (bulkDeleteFetcher.data?.success) {
      setSelectedPosts(new Set());
    }
  }, [bulkDeleteFetcher.data]);

  // Sort posts
  const sortedPosts = [...scheduledPosts].sort((a, b) => {
    if (sortConfig.key === "scheduledFor") {
      const aScheduledFor = typeof a.scheduledFor === "string" ? a.scheduledFor : String(a.scheduledFor || "0");
      const bScheduledFor = typeof b.scheduledFor === "string" ? b.scheduledFor : String(b.scheduledFor || "0");
      const dateA = parseInt(aScheduledFor) * 1000;
      const dateB = parseInt(bScheduledFor) * 1000;
      return sortConfig.direction === "asc" ? dateA - dateB : dateB - dateA;
    }
    const aValue = (a as unknown as Record<string, unknown>)[sortConfig.key] as string | number | undefined;
    const bValue = (b as unknown as Record<string, unknown>)[sortConfig.key] as string | number | undefined;
    if (aValue === undefined || bValue === undefined) return 0;
    if (aValue < bValue)
      return sortConfig.direction === "asc" ? -1 : 1;
    if (aValue > bValue)
      return sortConfig.direction === "asc" ? 1 : -1;
    return 0;
  });

  // Filter posts
  const filteredPosts = sortedPosts.filter((post) =>
    post.caption?.toLowerCase().includes(searchTerm.toLowerCase()),
  );

  const requestSort = (key: string) => {
    setSortConfig((current) => ({
      key,
      direction:
        current.key === key && current.direction === "asc" ? "desc" : "asc",
    }));
  };

  const togglePostSelection = (postId: string) => {
    setSelectedPosts((prev) => {
      const newSet = new Set(prev);
      if (newSet.has(postId)) {
        newSet.delete(postId);
      } else {
        newSet.add(postId);
      }
      return newSet;
    });
  };

  const toggleSelectAll = () => {
    if (selectedPosts.size === filteredPosts.length) {
      setSelectedPosts(new Set());
    } else {
      setSelectedPosts(new Set(filteredPosts.map((post) => post.id)));
    }
  };

  const handleBulkDelete = () => {
    if (selectedPosts.size === 0) return;

    // For All tab, we need to handle mixed content types
    if (currentTab === "all" && allContent) {
      const selectedItems = allContent
        .filter((item) => selectedPosts.has(item.id))
        .map((item) => ({ id: item.id, type: item.type }));

      const formData = new FormData();
      formData.append("_action", "bulkDeleteMixed");
      formData.append("itemData", JSON.stringify(selectedItems));

      bulkDeleteFetcher.submit(formData, { method: "post" });
    } else {
      // For individual tabs, use the original handlers
      const formData = new FormData();
      formData.append(
        "_action",
        currentTab === "longform" ? "bulkDeleteLongForm" : "bulkDelete",
      );
      formData.append("postIds", JSON.stringify(Array.from(selectedPosts)));

      bulkDeleteFetcher.submit(formData, { method: "post" });
    }
  };

  const handleMediaClick = (mediaSrc: string) => {
    setSelectedMedia(mediaSrc);
    setIsMediaModalOpen(true);
  };

  const handleCloseMediaModal = () => {
    setIsMediaModalOpen(false);
    setSelectedMedia(null);
  };

  const handleEditPost = (post: PostData) => {
    setPostToEdit(post);
    setShowEditModal(true);
  };

  const handleReschedulePost = (post: PostData) => {
    setPostToReschedule(post);
    setShowRescheduleModal(true);
  };

  const handleCloseEditModal = () => {
    setShowEditModal(false);
    setPostToEdit(null);
  };

  const handleCloseRescheduleModal = () => {
    setShowRescheduleModal(false);
    setPostToReschedule(null);
  };

  const handleModalSuccess = () => {
    window.location.reload();
  };

  return {
    sortConfig,
    searchTerm,
    countdowns,
    selectedPost,
    selectedPosts,
    selectedMedia,
    isMediaModalOpen,
    selectedLongFormPost,
    showEditModal,
    showRescheduleModal,
    postToEdit,
    postToReschedule,
    filteredPosts,
    bulkDeleteFetcher,
    deleteFetcher,
    requestSort,
    setSearchTerm,
    setSelectedPost,
    setSelectedLongFormPost,
    togglePostSelection,
    toggleSelectAll,
    handleBulkDelete,
    handleMediaClick,
    handleCloseMediaModal,
    handleEditPost,
    handleReschedulePost,
    handleCloseEditModal,
    handleCloseRescheduleModal,
    handleModalSuccess,
  };
}

