  await scheduledPostsWorker.close();
  await scheduledLongFormPostsWorker.close();
  await postCheckerWorker.close();
  await closeAllQueues();
});

process.on("SIGINT", async () => {
  await scheduledPostsWorker.close();
  await scheduledLongFormPostsWorker.close();
  await postCheckerWorker.close();
  await closeAllQueues();
});

