/**
 * Dashboard loader data preparation
 * Centralized data fetching for dashboard index page
 */

import { combineContent } from "~/features/posts/combined.server";
import type { PostData, LongFormPostData } from "~/features/posts/types";
import {
  getScheduledLongFormPosts,
} from "~/models/longformpost.server";
import {
  getScheduledPosts,
  getPostStatistics,
} from "~/models/post.queries.server";
import {
  getUserById,
  getQueueTypes,
  getUserHashTagPresets,
} from "~/models/user.server";

import { filterPostsByQueueType } from "./post-filtering.server";

/**
 * Load dashboard data
 */
export async function loadDashboardData(
  userId: string,
  queueType: string,
) {
  const [
    scheduledPosts,
    allLongformPosts,
    postStatistics,
    user,
    queueTypes,
    hashTagPresets,
  ] = await Promise.all([
    getScheduledPosts({ userId, queueType }),
    getScheduledLongFormPosts({ userId }),
    getPostStatistics({ userId }),
    getUserById(userId),
    getQueueTypes(userId),
    getUserHashTagPresets(userId),
  ]);

  // Filter longform posts by queue type if specific queue is selected
  const longformPosts = filterPostsByQueueType(allLongformPosts, queueType);

  // Convert PostWithQueueType[] to PostData[] for combineContent
  const scheduledPostsData: PostData[] = scheduledPosts.map((post) => {
    const { queueType, ...rest } = post;
    return {
      ...rest,
      queueType: queueType || undefined,
      signedEvent: post.signedEvent as PostData["signedEvent"],
      nostrEvent: post.nostrEvent as PostData["nostrEvent"],
    } as PostData;
  });

  // Convert LongFormPost[] to LongFormPostData[] for combineContent
  const longformPostsData: LongFormPostData[] = longformPosts.map((post) => {
    const { queueType, ...rest } = post;
    return {
      ...rest,
      queueType: queueType || undefined,
      signedEvent: post.signedEvent as LongFormPostData["signedEvent"],
      nostrEvent: post.nostrEvent as LongFormPostData["nostrEvent"],
    } as LongFormPostData;
  });

  // Combine posts and longform posts for the "All" tab
  const allContent = combineContent(
    scheduledPostsData,
    longformPostsData,
    "scheduledFor",
    "asc",
  );

  return {
    scheduledPosts,
    longformPosts,
    allContent,
    postStatistics,
    user,
    queueTypes: queueTypes.filter((qt) => qt.isEnabled !== false),
    selectedQueueType: queueType,
    hashTagPresets,
  };
}

/**
 * Draft edit action handlers
 * Centralized action processing for draft edit page
 */

import { resolveQueueTypeId } from "~/features/posts/services/queue-type-resolver.server";
import { updatePost } from "~/models/post.commands.server";
export async function handleDraftEditAction(
  formData: FormData,
  userId: string,
  postId: string,
) {
  const _action = formData.get("_action");

  if (_action === "update") {
    const content = formData.get("content");
    const caption = formData.get("caption");
    const queueType = formData.get("queueType");
    const queueTypeId = formData.get("queueTypeId");
    const useHashtagPresets = formData.get("useHashtagPresets") === "on";
    const hashTagPresetId = useHashtagPresets
      ? formData.get("hashTagPresetId") || null
      : null;

    // Resolve queue type ID in feature layer (business logic)
    const resolvedQueueTypeId = await resolveQueueTypeId(
      userId,
      queueTypeId as string | null,
      queueType as string | null,
    );

    await updatePost({
      id: postId,
      userId,
      data: {
        content: content as string,
        caption: caption as string,
        queueTypeId: resolvedQueueTypeId,
        hashTagPresetId: hashTagPresetId as string | null,
      },
    });

    return { redirect: "/dashboard/drafts" };
  }

  if (_action === "resume") {
    const content = formData.get("content");
    const caption = formData.get("caption");
    const queueType = formData.get("queueType");
    const queueTypeId = formData.get("queueTypeId");
    const scheduledFor = formData.get("scheduledFor");
    const signedEvent = formData.get("signedEvent");
    const nostrEvent = formData.get("nostrEvent");
    const useHashtagPresets = formData.get("useHashtagPresets") === "on";
    const hashTagPresetId = useHashtagPresets
      ? formData.get("hashTagPresetId") || null
      : null;

    // Ensure the post is signed before resuming
    if (!signedEvent || !nostrEvent) {
      const { ValidationError } = await import("~/lib/errors");
      throw new ValidationError("Post must be signed before resuming", {
        postId,
        hasSignedEvent: !!signedEvent,
        hasNostrEvent: !!nostrEvent,
      });
    }

    // Resolve queue type ID in feature layer (business logic)
    const resolvedQueueTypeId = await resolveQueueTypeId(
      userId,
      queueTypeId as string | null,
      queueType as string | null,
    );

    await updatePost({
      id: postId,
      userId,
      data: {
        content: content as string,
        caption: caption as string,
        queueTypeId: resolvedQueueTypeId,
        scheduledFor: scheduledFor as string,
        signedEvent: JSON.parse(signedEvent as string) as { id: string; pubkey: string; created_at: number; kind: number; content: string; tags: string[][]; sig: string },
        nostrEvent: JSON.parse(nostrEvent as string) as { id: string; pubkey: string; created_at: number; kind: number; content: string; tags: string[][] },
        draft: false,
        isScheduled: true,
        isPosted: false,
        hashTagPresetId: hashTagPresetId as string | null,
      },
    });

    return { redirect: "/dashboard/scheduled" };
  }

  return { error: "Invalid action" };
}

/**
 * Draft signing service
 * Handles signing and scheduling logic for draft posts
 */

import type { NostrEvent as NostrEventType, SignedEvent, NostrEvent } from "~/features/nostr/types";
import type { UserData, PostData } from "~/features/posts/types";
import { logError } from "~/lib/error-logger.server";
import { signEventFn } from "~/lib/nostr";

interface SignDraftParams {
  content: string;
  caption: string;
  scheduledFor: string;
  selectedQueue: string;
  useHashtagPresets: boolean;
  selectedHashtags: string;
  user: UserData;
  currentUser: UserData | null;
  post: PostData;
}

/**
 * Get effective hashtags for a draft post
 */
async function getEffectiveHashtags(
  useHashtagPresets: boolean,
  selectedHashtags: string,
  selectedQueue: string,
  userId: string,
  user: UserData,
): Promise<string> {
  if (useHashtagPresets) {
    // Manual hashtag presets are enabled
    if (selectedHashtags) {
      // Use manually selected hashtag preset
      return selectedHashtags;
    }
    // If useHashtagPresets is true but no manual preset selected, use no hashtags
    return "";
  } else {
    // Manual hashtag presets are disabled, use queue type's default hashtags
    try {
      const response = await fetch("/api/effective-hashtags", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          userId,
          queueTypeName: selectedQueue,
        }),
      });

      if (response.ok) {
        const data = await response.json() as { hashtags?: string };
        return data.hashtags || "";
      } else {
        // Fallback to user's default hashtags
        // Note: hashTags property doesn't exist on UserData, using empty string as fallback
        return "";
      }
    } catch (error) {
      logError(error instanceof Error ? error : new Error(String(error)), {
        userId: user?.id,
        selectedQueue,
        message: "Error fetching effective hashtags",
      });
      // Fallback to user's default hashtags
      // Note: hashTags property doesn't exist on UserData, using empty string as fallback
      return "";
    }
  }
}

/**
 * Get image URLs from post fileUrl
 */
function getImageUrls(fileUrl: string[] | null | undefined): string[] {
  if (!fileUrl || fileUrl.length === 0) return [];

  // Handle case where fileUrl is an array of JSON strings
  if (typeof fileUrl[0] === "string" && fileUrl[0].startsWith("[")) {
    try {
      return JSON.parse(fileUrl[0]) as string[];
    } catch (e) {
      logError(e instanceof Error ? e : new Error(String(e)), {
        fileUrl: fileUrl[0],
        message: "Error parsing fileUrl",
      });
      return [];
    }
  }

  // Handle direct URLs
  return fileUrl;
}

/**
 * Calculate scheduled time in Unix timestamp
 */
function calculateScheduledTime(
  scheduledFor: string,
  userTimezone: string,
): number {
  let scheduledTime: number;

  if (userTimezone !== "UTC" && userTimezone !== "Etc/GMT") {
    const utcDate = new Date(scheduledFor);
    const userDate = new Date(scheduledFor).toLocaleString("en-US", {
      timeZone: userTimezone,
    });
    const userOffset =
      (new Date(userDate).getTime() - new Date(scheduledFor).getTime()) / 60000;
    utcDate.setMinutes(utcDate.getMinutes() - userOffset);
    scheduledTime = utcDate.getTime();
  } else {
    const dateObj = new Date(scheduledFor + "Z");
    scheduledTime = dateObj.getTime();
  }

  return Math.floor(scheduledTime / 1000);
}

/**
 * Sign and prepare draft for scheduling
 */
export function signDraftForScheduling(
  params: SignDraftParams,
): Promise<{ signedEvent: SignedEvent; nostrEvent: NostrEventType; scheduledForUnix: number }> {
  const {
    content,
    caption,
    scheduledFor,
    selectedQueue,
    useHashtagPresets,
    selectedHashtags,
    user,
    currentUser,
    post,
  } = params;

  const userTimezone = currentUser?.timezone ?? "UTC";
  const scheduledForUnix = calculateScheduledTime(scheduledFor, userTimezone);

  // Get effective hashtags
  const effectiveHashtags = await getEffectiveHashtags(
    useHashtagPresets,
    selectedHashtags,
    selectedQueue,
    currentUser?.id ?? "",
    user,
  );

  const tagArray = effectiveHashtags
    .split(" ")
    .filter((tag) => tag.length > 0)
    .map((tag) => ["t", tag.replace("#", "")]);

  // Include image URLs in the content to sign (caption first, then image URLs)
  const imageUrls = getImageUrls(post.fileUrl);
  const imageUrlsText = imageUrls.length > 0 ? imageUrls.join(" ") : "";

  let baseContent = content || caption;
  if (imageUrlsText) {
    baseContent = baseContent
      ? `${baseContent} ${imageUrlsText}`
      : imageUrlsText;
  }

  const contentToSign = currentUser?.showHashTagsinPosts
    ? `${baseContent}\n${effectiveHashtags}`
    : baseContent;

  const { nostrEvent, signedEvent } = await signEventFn({
    content: contentToSign,
    created_at: scheduledForUnix,
    kind: 1,
    tags: tagArray,
  });

  return { signedEvent, nostrEvent, scheduledForUnix };
}

/**
 * Drafts action handlers
 * Centralized action processing for drafts page
 */

import { resolveQueueTypeId } from "~/features/posts/services/queue-type-resolver.server";
import {
  deleteLongFormPost,
} from "~/models/longformpost.server";
import { deletePost, updatePost } from "~/models/post.commands.server";

export async function handleDraftsAction(
  formData: FormData,
  userId: string,
) {
  const postId = formData.get("postId");
  const _action = formData.get("_action");

  if (_action === "delete") {
    await deletePost({ id: postId as string, userId });
    return { success: true };
  }

  if (_action === "deleteLongForm") {
    await deleteLongFormPost({ id: postId as string, userId });
    return { success: true };
  }

  if (_action === "bulkDelete") {
    const postIds = JSON.parse(formData.get("postIds") as string) as string[];
    await Promise.all(postIds.map((id: string) => deletePost({ id, userId })));
    return { success: true };
  }

  if (_action === "bulkDeleteLongForm") {
    const postIds = JSON.parse(formData.get("postIds") as string) as string[];
    await Promise.all(postIds.map((id: string) => deleteLongFormPost({ id, userId })));
    return { success: true };
  }

  if (_action === "bulkSignAndResume") {
    const postIds = formData.getAll("postIds");
    const contents = formData.getAll("contents");
    const captions = formData.getAll("captions");
    const queueTypes = formData.getAll("queueTypes");
    const queueTypeIds = formData.getAll("queueTypeIds");
    const scheduledFors = formData.getAll("scheduledFors");
    const signedEvents = formData.getAll("signedEvents");
    const nostrEvents = formData.getAll("nostrEvents");

    await Promise.all(
      postIds.map(async (id, index) => {
        // Resolve queue type ID in feature layer (business logic)
        const resolvedQueueTypeId = await resolveQueueTypeId(
          userId,
          (queueTypeIds[index] as string) || null,
          (queueTypes[index] as string) || null,
        );

        return updatePost({
          id: id as string,
          userId,
          data: {
            content: contents[index] as string,
            caption: captions[index] as string,
            queueTypeId: resolvedQueueTypeId,
            scheduledFor: scheduledFors[index] as string,
            signedEvent: JSON.parse(signedEvents[index] as string) as { id: string; pubkey: string; created_at: number; kind: number; content: string; tags: string[][]; sig: string },
            nostrEvent: JSON.parse(nostrEvents[index] as string) as { id: string; pubkey: string; created_at: number; kind: number; content: string; tags: string[][] },
            draft: false,
            isScheduled: true,
            isPosted: false,
          },
        });
      }),
    );
    return { success: true };
  }

  return { error: "Invalid action" };
}

