/**
 * Posted Posts Service
 * 
 * Handles posted posts data loading
 */

import { combineContent } from "~/features/posts/combined.server";
import { getPostStats } from "~/features/posts/stats.server";
import type { PostData, LongFormPostData } from "~/features/posts/types";
import { getPublishedLongFormPosts } from "~/models/longformpost.server";
import { getPostedPosts } from "~/models/post.queries.server";
import { getUserById, getQueueTypes } from "~/models/user.server";
/**
 * Get posted posts dashboard data
 */
export async function getPostedDashboardData({
  userId,
  params,
  url,
}: {
  userId: string;
  params: { queueType?: string };
  url: URL;
}) {
  const page = parseInt(url.searchParams.get("page") || "1");
  const limit = 50;
  const queueType = params.queueType || "all";

  const [{ posts, pagination }, allLongformResult, user, queueTypes] =
    await Promise.all([
      getPostedPosts({
        userId,
        page,
        limit,
        queueType,
      }),
      getPublishedLongFormPosts({ userId, page, limit }),
      getUserById(userId),
      getQueueTypes(userId),
    ]);

  const longformResult = {
    ...allLongformResult,
    posts:
      queueType === "all"
        ? allLongformResult.posts
        : allLongformResult.posts.filter(
            (post) => {
              if ("queueType" in post && post.queueType && typeof post.queueType === "object" && "name" in post.queueType) {
                return post.queueType.name === queueType;
              }
              return false;
            },
          ),
  };

  // Convert PostWithQueueType[] to PostData[] for combineContent
  const postsData: PostData[] = posts.map((post) => {
    const { queueType, ...rest } = post;
    return {
      ...rest,
      queueType: ("queueType" in post && post.queueType) || undefined,
      signedEvent: post.signedEvent as PostData["signedEvent"],
      nostrEvent: post.nostrEvent as PostData["nostrEvent"],
    } as PostData;
  });

  // Convert LongFormPost[] to LongFormPostData[] for combineContent
  const longformPostsData: LongFormPostData[] = longformResult.posts.map((post) => {
    return {
      ...post,
      queueType: ("queueType" in post && post.queueType) || undefined,
      signedEvent: post.signedEvent as LongFormPostData["signedEvent"],
      nostrEvent: post.nostrEvent as LongFormPostData["nostrEvent"],
    } as LongFormPostData;
  });

  const allContent = combineContent(
    postsData,
    longformPostsData,
    "postedAt",
    "desc",
  );

  const eventIds = posts.map((post) => {
    const signedEvent = post.signedEvent;
    if (signedEvent && typeof signedEvent === "object" && "id" in signedEvent && typeof signedEvent.id === "string") {
      return signedEvent.id;
    }
    return "";
  }).filter((id) => id !== "");
  const stats = await getPostStats(eventIds);

  return {
    posts,
    longformPosts: longformResult.posts,
    allContent,
    longformPagination: longformResult.pagination,
    pagination,
    stats,
    user,
    queueTypes: queueTypes.filter((qt) => qt.isEnabled !== false),
    selectedQueueType: queueType,
  };
}

/**
 * Queue schedule service
 * Handles queue schedule time calculation for API endpoints
 */

import { json } from "@remix-run/node";

import {
  calculateNextScheduleTime,
  formatScheduleTimeForInput,
} from "~/features/posts/schedulers";
import { createSuccessResponse } from "~/lib/error-handler.server";
import { NotFoundError, ValidationError } from "~/lib/errors";
import {
  getQueueTypes,
  getUserTimezone,
  getQueueTypeByIdForUser,
} from "~/models/user.server";

/**
 * Calculate next schedule time for a queue type
 * Supports both queueTypeName (legacy) and queueTypeId (preferred)
 */
export async function calculateQueueScheduleTime(
  userId: string,
  queueTypeName?: string,
  queueTypeId?: string,
) {
  if ((!queueTypeName && !queueTypeId) || queueTypeName === "unassigned") {
    return json({ scheduledTime: "" });
  }

  // Get user timezone
  const userTimezone = await getUserTimezone(userId);

  let selectedQueue;

  if (queueTypeId) {
    // Use queue type ID for direct lookup (preferred method)
    selectedQueue = await getQueueTypeByIdForUser(userId, queueTypeId);
  } else if (queueTypeName) {
    // Fallback to name-based lookup for backward compatibility
    const queueTypes = await getQueueTypes(userId);
    selectedQueue = queueTypes.find((qt) => qt.name === queueTypeName);
  }

  if (!selectedQueue) {
    throw new NotFoundError("Queue type not found", {
      queueTypeName,
      queueTypeId,
      userId,
    });
  }

  // Calculate next schedule time with user timezone
  const nextScheduleTime = await calculateNextScheduleTime({
    queueType: selectedQueue,
    userId,
    userTimezone: userTimezone || "UTC",
  });

  // Format for datetime-local input in user's timezone
  const formattedTime = formatScheduleTimeForInput(
    nextScheduleTime,
    userTimezone || "UTC",
  );

  return createSuccessResponse({ scheduledTime: formattedTime });
}

/**
 * Parse and validate queue schedule request body
 */
export function parseQueueScheduleRequest(body: unknown): {
  queueTypeName?: string;
  queueTypeId?: string;
} {
  if (typeof body !== "object" || body === null) {
    throw new ValidationError("Request body must be an object", {
      bodyType: typeof body,
    });
  }

  const requestBody = body as { queueTypeName?: string; queueTypeId?: string };

  return {
    queueTypeName: requestBody.queueTypeName,
    queueTypeId: requestBody.queueTypeId,
  };
}

/**
 * Queue Type Resolver
 * 
 * Business logic for resolving queue type IDs from names.
 * This handles the lookup logic that was previously in the model layer.
 */

import { prisma } from "~/lib/prisma.server";
/**
 * Resolve queue type ID from name or ID
 * 
 * If queueTypeId is provided, returns it directly.
 * If queueType (name) is provided, looks up the ID.
 * Returns null if queueType is "unassigned" or not found.
 */
export function resolveQueueTypeId(
  userId: string,
  queueTypeId?: string | null,
  queueType?: string | null,
): Promise<string | null> {
  // Use provided queue type ID directly
  if (queueTypeId) {
    return queueTypeId;
  }

  // If no queueType name provided or it's "unassigned", return null
  if (!queueType || queueType === "unassigned") {
    return null;
  }

  // Lookup queue type by name
  const queueTypeRecord = await prisma.queueType.findFirst({
    where: {
      userId,
      name: queueType,
    },
    select: {
      id: true,
    },
  });

  return queueTypeRecord?.id ?? null;
}

/**
 * Recyclable Posts Service
 * 
 * Handles recyclable posts data loading and actions (repost, quote, delete)
 */

import { json } from "@remix-run/node";

import { getPostStats } from "~/features/posts/stats.server";
import type { UserWithHashTagPresets } from "~/features/user";
import { deletePost } from "~/models/post.commands.server";
import { getRecyclablePosts, getPostsByIds } from "~/models/post.queries.server";
import { getUserById, getQueueTypes } from "~/models/user.server";
/**
 * Get recyclable posts dashboard data
 */
export async function getRecyclableDashboardData({
  userId,
  params,
  url,
}: {
  userId: string;
  params: { queueType?: string };
  url: URL;
}) {
  const page = parseInt(url.searchParams.get("page") || "1");
  const limit = 50;
  const queueType = params.queueType || "all";

  const [{ posts, pagination }, userResult, queueTypesResult] = await Promise.all([
    getRecyclablePosts({
      userId,
      page,
      limit,
      queueType,
    }),
    getUserById(userId),
    getQueueTypes(userId),
  ]);

  if (!userResult) {
    throw new Error("User not found");
  }

  const user: UserWithHashTagPresets = userResult;
  const queueTypes = queueTypesResult;

  // Get event IDs from signedEvent.id
  const eventIds = posts
    .map((post) => {
      const signedEvent = post.signedEvent;
      if (signedEvent && typeof signedEvent === "object" && "id" in signedEvent && typeof signedEvent.id === "string") {
        return signedEvent.id;
      }
      return "";
    })
    .filter((id) => id !== "");

  // Use the extracted stats fetching logic
  const stats = await getPostStats(eventIds);

  return {
    posts,
    pagination,
    stats,
    user,
    queueTypes: queueTypes.filter((qt) => qt.isEnabled !== false),
    selectedQueueType: queueType,
  };
}

/**
 * Handle recyclable post actions (delete, repost, quote)
 */
export async function handleRecyclablePostAction(
  formData: FormData,
  userId: string,
) {
  const postId = formData.get("postId") as string;
  const _action = formData.get("_action");

  if (_action === "delete") {
    await deletePost({ id: postId, userId });
    return json({ success: true });
  }

  if (_action === "bulkDelete") {
    const postIds = JSON.parse(formData.get("postIds") as string) as string[];
    await Promise.all(postIds.map((id: string) => deletePost({ id, userId })));
    return json({ success: true });
  }

  if (_action === "bulkRepost") {
    const postIds = JSON.parse(formData.get("postIds") as string) as string[];
    const postsData = await getPostsByIds({ ids: postIds, userId });
    return json({ repostData: postsData });
  }

  if (_action === "bulkScheduledRepost") {
    const postIds = JSON.parse(formData.get("postIds") as string) as string[];
    const postsData = await getPostsByIds({ ids: postIds, userId });
    return json({ scheduledRepostData: postsData });
  }

  if (_action === "bulkQuote") {
    const postIds = JSON.parse(formData.get("postIds") as string) as string[];
    const postsData = await getPostsByIds({ ids: postIds, userId });

    // Transform posts data into quote post format
    const quotePostsData = postsData.map((post) => {
      const signedEvent = post.signedEvent;
      let eventId = "";
      let eventPubkey = "";

      if (signedEvent && typeof signedEvent === "object" && !Array.isArray(signedEvent)) {
        if ("id" in signedEvent && typeof signedEvent.id === "string") {
          eventId = signedEvent.id;
        }
        if ("pubkey" in signedEvent && typeof signedEvent.pubkey === "string") {
          eventPubkey = signedEvent.pubkey;
        }
      }

      const fileUrl = Array.isArray(post.fileUrl) ? post.fileUrl : typeof post.fileUrl === "string" ? [post.fileUrl] : [];
      const caption = typeof post.caption === "string" ? post.caption : "";
      const queueTypeName = post.queueType && typeof post.queueType === "object" && "name" in post.queueType && typeof post.queueType.name === "string" ? post.queueType.name : "unassigned";

      return {
        caption: "", // Empty caption - user can add content
        fileUrl: fileUrl.length > 0 ? fileUrl[0] ?? "" : "",
        queueType: queueTypeName,
        scheduledFor: "",
        originalPostId: post.id,
        originalEventId: eventId,
        originalEventPubkey: eventPubkey,
        isQuotePost: true,
        originalCaption: caption,
      };
    });

    return json({ quotePostData: quotePostsData });
  }

  if (_action === "repost") {
    try {
      // Get the original post data
      const postsData = await getPostsByIds({ ids: [postId], userId });
      if (!postsData || postsData.length === 0) {
        const { NotFoundError } = await import("~/lib/errors");
        throw new NotFoundError("Post not found", { postId, userId });
      }

      const originalPost = postsData[0];
      const originalEvent = originalPost.signedEvent;

      if (!originalEvent || typeof originalEvent !== "object" || !("id" in originalEvent) || !("pubkey" in originalEvent)) {
        return json({ error: "Invalid event data" }, { status: 400 });
      }

      const eventId = typeof originalEvent.id === "string" ? originalEvent.id : String(originalEvent.id);
      const eventPubkey = typeof originalEvent.pubkey === "string" ? originalEvent.pubkey : String(originalEvent.pubkey);

      // Create kind 6 repost event structure according to NIP-18
      const kind6EventData = {
        kind: 6,
        content: "", // Empty content as recommended by NIP-18
        tags: [
          // e tag with the id of the note being reposted and relay URL
          ["e", eventId, "wss://relay.primal.net"],
          // p tag with the pubkey of the event being reposted
          ["p", eventPubkey],
        ],
        created_at: Math.floor(Date.now() / 1000),
      };

      // Return the unsigned event data for client-side signing
      return json({
        repostEventData: kind6EventData,
        originalPost: originalPost,
      });
    } catch (error) {
      const { handleActionError } = await import("~/lib/error-handler.server");
      return handleActionError(error);
    }
  }

  if (_action === "quote") {
    try {
      // Get the original post data
      const postsData = await getPostsByIds({ ids: [postId], userId });
      if (!postsData || postsData.length === 0) {
        const { NotFoundError } = await import("~/lib/errors");
        throw new NotFoundError("Post not found", { postId, userId });
      }

      const originalPost = postsData[0];
      const originalEvent = originalPost.signedEvent;

      if (!originalEvent || typeof originalEvent !== "object" || !("id" in originalEvent) || !("pubkey" in originalEvent)) {
        return json({ error: "Invalid event data" }, { status: 400 });
      }

      const eventId = typeof originalEvent.id === "string" ? originalEvent.id : String(originalEvent.id);
      const eventPubkey = typeof originalEvent.pubkey === "string" ? originalEvent.pubkey : String(originalEvent.pubkey);

      // Create quote post data for bulk posts page
      const quotePostData = {
        caption: "", // Empty caption - user can add content
        fileUrl: originalPost.fileUrl || "",
        queueType: originalPost.queueType?.name ?? "unassigned",
        scheduledFor: "",
        originalPostId: originalPost.id,
        originalEventId: eventId,
        originalEventPubkey: eventPubkey,
        isQuotePost: true,
        originalCaption: originalPost.caption || "",
      };

      return json({ quotePostData: [quotePostData] });
    } catch (error) {
      const { handleActionError } = await import("~/lib/error-handler.server");
      return handleActionError(error);
    }
  }

  return json({ error: "Invalid action" }, { status: 400 });
}

