/**
 * Scheduled Posts Service
 * 
 * Handles scheduled posts data loading and actions
 */

import { json } from "@remix-run/node";

import { combineContent } from "~/features/posts/combined.server";
import type { PostData, LongFormPostData } from "~/features/posts/types";
import {
  enqueuePostJob as schedulePost,
  cancelPostJob as cancelScheduledPost,
} from "~/infra/queue";
import { logError } from "~/lib/error-logger.server";
import {
  getScheduledLongFormPosts,
  deleteLongFormPost,
  updateLongFormPost,
  getLongFormPost as getLongFormPostModel,
} from "~/models/longformpost.server";
import {
  deletePost,
  reschedulePost,
  updatePost,
} from "~/models/post.commands.server";
import {
  getScheduledPosts,
  getPostById,
} from "~/models/post.queries.server";
import {
  getUserById,
  getQueueTypes,
  getUserHashTagPresets,
} from "~/models/user.server";

/**
 * Get scheduled posts dashboard data
 */
export async function getScheduledDashboardData({
  userId,
  queueType,
}: {
  userId: string;
  queueType: string;
}) {
  const [posts, allLongformPosts, user, queueTypes, hashTagPresets] =
    await Promise.all([
      getScheduledPosts({ userId, queueType }),
      getScheduledLongFormPosts({ userId }),
      getUserById(userId),
      getQueueTypes(userId),
      getUserHashTagPresets(userId),
    ]);

  // Filter longform posts by queue type if specific queue is selected
  const longformPosts =
    queueType === "all"
      ? allLongformPosts
      : allLongformPosts.filter((post) => post.queueType?.name === queueType);

  // Convert PostWithQueueType[] to PostData[] for combineContent
  const postsData: PostData[] = posts.map((post) => {
    const { queueType, ...rest } = post;
    return {
      ...rest,
      queueType: queueType || undefined,
      signedEvent: post.signedEvent as PostData["signedEvent"],
      nostrEvent: post.nostrEvent as PostData["nostrEvent"],
    } as PostData;
  });

  // Convert LongFormPost[] to LongFormPostData[] for combineContent
  const longformPostsData: LongFormPostData[] = longformPosts.map((post) => {
    return {
      ...post,
      queueType: ("queueType" in post && post.queueType) || undefined,
      signedEvent: post.signedEvent as LongFormPostData["signedEvent"],
      nostrEvent: post.nostrEvent as LongFormPostData["nostrEvent"],
    } as LongFormPostData;
  });

  // Combine posts and longform posts for the "All" tab
  const allContent = combineContent(
    postsData,
    longformPostsData,
    "scheduledFor",
    "asc",
  );

  return {
    posts,
    longformPosts,
    allContent,
    user,
    queueTypes: queueTypes.filter((qt) => qt.isEnabled !== false),
    selectedQueueType: queueType,
    hashTagPresets,
  };
}

/**
 * Handle scheduled post actions (delete, reschedule, edit)
 */
export async function handleScheduledPostAction(
  formData: FormData,
  userId: string,
) {
  const postId = formData.get("postId") as string;
  const _action = formData.get("_action");

  if (_action === "delete") {
    await deletePost({ id: postId, userId });
    return json({ success: true });
  }

  if (_action === "deleteLongForm") {
    await deleteLongFormPost({ id: postId, userId });
    return json({ success: true });
  }

  if (_action === "bulkDelete") {
    const postIds = JSON.parse(formData.get("postIds") as string) as string[];
    await Promise.all(postIds.map((id: string) => deletePost({ id, userId })));
    return json({ success: true });
  }

  if (_action === "bulkDeleteLongForm") {
    const postIds = JSON.parse(formData.get("postIds") as string) as string[];
    await Promise.all(
      postIds.map((id: string) => deleteLongFormPost({ id, userId })),
    );
    return json({ success: true });
  }

  if (_action === "bulkDeleteMixed") {
    const itemData = JSON.parse(formData.get("itemData") as string) as { id: string; type: string }[];
    const promises = itemData.map((item: { id: string; type: string }) => {
      if (item.type === "post") {
        return deletePost({ id: item.id, userId });
      } else {
        return deleteLongFormPost({ id: item.id, userId });
      }
    });
    await Promise.all(promises);
    return json({ success: true });
  }

  // Reschedule a regular post (with optional re-signed event)
  if (_action === "reschedule") {
    const newTime = formData.get("newTime") as string;
    const overrideQueue = formData.get("overrideQueue") === "true";
    const signedEventStr = formData.get("signedEvent") as string;
    const nostrEventStr = formData.get("nostrEvent") as string;
    const queueTypeId = formData.get("queueTypeId") as string;

    if (!postId || !newTime) {
      return json({ error: "Missing required fields" }, { status: 400 });
    }

    const originalPost = await getPostById({ id: postId, userId });
    if (!originalPost) {
      return json({ error: "Post not found" }, { status: 404 });
    }

    await cancelScheduledPost(postId);

    let parsedSignedEvent = null;
    let parsedNostrEvent = null;
    if (signedEventStr && nostrEventStr) {
      try {
        parsedSignedEvent = JSON.parse(signedEventStr) as { id: string; pubkey: string; created_at: number; kind: number; content: string; tags: string[][]; sig: string };
        parsedNostrEvent = JSON.parse(nostrEventStr) as { id: string; pubkey: string; created_at: number; kind: number; content: string; tags: string[][] };
      } catch (e) {
        logError(e instanceof Error ? e : new Error(String(e)), {
          userId,
          postId,
          message: "Error parsing signed events",
        });
      }
    }

    const updatedPost = await reschedulePost({
      id: postId,
      userId,
      newScheduledFor: newTime,
      overrideQueue,
      queueTypeId,
      signedEvent: parsedSignedEvent || undefined,
      nostrEvent: parsedNostrEvent || undefined,
    });

    if (parsedSignedEvent && parsedNostrEvent) {
      await schedulePost(postId, userId, parsedSignedEvent, parseInt(newTime));
      return json({ success: true, post: updatedPost, signed: true });
    }

    return json({ success: true, post: updatedPost, needsSigning: true });
  }

  // Reschedule a longform post (with optional re-signed event)
  if (_action === "rescheduleLongform") {
    const newTime = formData.get("newTime") as string;
    const signedEventStr = formData.get("signedEvent") as string;
    const nostrEventStr = formData.get("nostrEvent") as string;

    if (!postId || !newTime) {
      return json({ error: "Missing required fields" }, { status: 400 });
    }

    const originalPost = await getLongFormPostModel({ id: postId, userId });
    if (!originalPost) {
      return json({ error: "Longform post not found" }, { status: 404 });
    }

    let parsedSignedEvent = null;
    let parsedNostrEvent = null;
    if (signedEventStr && nostrEventStr) {
      try {
        parsedSignedEvent = JSON.parse(signedEventStr) as { id: string; pubkey: string; created_at: number; kind: number; content: string; tags: string[][]; sig: string };
        parsedNostrEvent = JSON.parse(nostrEventStr) as { id: string; pubkey: string; created_at: number; kind: number; content: string; tags: string[][] };
      } catch (e) {
        logError(e instanceof Error ? e : new Error(String(e)), {
          userId,
          postId,
          message: "Error parsing signed events",
        });
      }
    }

    const updatedPost = await updateLongFormPost({
      id: postId,
      userId,
      publishedAt: new Date(parseInt(newTime) * 1000),
      status: "SCHEDULED",
      signedEvent: parsedSignedEvent || undefined,
      nostrEvent: parsedNostrEvent || undefined,
    });

    return json({
      success: true,
      post: updatedPost,
      signed: !!parsedSignedEvent,
    });
  }

  // Edit a regular post's content/media/hashtags and re-sign
  if (_action === "editPost") {
    const caption = (formData.get("caption") ?? "") as string;
    const fileUrl = (formData.get("fileUrl") ?? "") as string;
    const hashtags = (formData.get("hashtags") ?? "") as string;
    const signedEventStr = formData.get("signedEvent") as string;
    const nostrEventStr = formData.get("nostrEvent") as string;
    const queueTypeId = (formData.get("queueTypeId") as string) || null;
    const scheduledFor = (formData.get("scheduledFor") as string) || null;
    const hashTagPresetId =
      (formData.get("hashTagPresetId") as string) || null;

    if (!postId) {
      return json({ error: "Missing postId" }, { status: 400 });
    }

    let parsedSignedEvent = null;
    let parsedNostrEvent = null;
    if (signedEventStr && nostrEventStr) {
      try {
        parsedSignedEvent = JSON.parse(signedEventStr) as { id: string; pubkey: string; created_at: number; kind: number; content: string; tags: string[][]; sig: string };
        parsedNostrEvent = JSON.parse(nostrEventStr) as { id: string; pubkey: string; created_at: number; kind: number; content: string; tags: string[][] };
      } catch (e) {
        logError(e instanceof Error ? e : new Error(String(e)), {
          userId,
          postId,
          message: "Error parsing signed events",
        });
      }
    }

    let parsedFileUrl: string[] = [];
    if (fileUrl) {
      try {
        parsedFileUrl = JSON.parse(fileUrl) as string[];
      } catch (e) {
        logError(e instanceof Error ? e : new Error(String(e)), {
          userId,
          postId,
          fileUrl,
          message: "Error parsing fileUrl",
        });
        parsedFileUrl = [];
      }
    }

    const updated = await updatePost({
      id: postId,
      userId,
      data: {
        caption,
        fileUrl: parsedFileUrl,
        tags: hashtags
          ? hashtags.toString().split(" ").filter((tag) => tag.trim())
          : [],
        queueTypeId,
        scheduledFor: scheduledFor ? String(Number(scheduledFor)) : undefined,
        signedEvent: parsedSignedEvent || undefined,
        nostrEvent: parsedNostrEvent || undefined,
        hashTagPresetId,
      },
    });

    if (scheduledFor && parsedSignedEvent) {
      await cancelScheduledPost(postId);
      await schedulePost(
        postId,
        userId,
        parsedSignedEvent,
        Number(scheduledFor),
      );
    }

    return json({
      success: true,
      post: updated,
      signed: !!parsedSignedEvent,
    });
  }

  // Edit a longform post's content and re-sign
  if (_action === "editLongform") {
    const title = (formData.get("title") ?? "") as string;
    const summary = (formData.get("summary") ?? "") as string;
    const content = (formData.get("content") ?? "") as string;
    const image = (formData.get("image") ?? "") as string;
    const signedEventStr = formData.get("signedEvent") as string;
    const nostrEventStr = formData.get("nostrEvent") as string;
    const scheduledFor = (formData.get("scheduledFor") as string) || null;

    if (!postId) {
      return json({ error: "Missing postId" }, { status: 400 });
    }

    let parsedSignedEvent = null;
    let parsedNostrEvent = null;
    if (signedEventStr && nostrEventStr) {
      try {
        parsedSignedEvent = JSON.parse(signedEventStr) as { id: string; pubkey: string; created_at: number; kind: number; content: string; tags: string[][]; sig: string };
        parsedNostrEvent = JSON.parse(nostrEventStr) as { id: string; pubkey: string; created_at: number; kind: number; content: string; tags: string[][] };
      } catch (e) {
        logError(e instanceof Error ? e : new Error(String(e)), {
          userId,
          postId,
          message: "Error parsing signed events",
        });
      }
    }

    const updated = await updateLongFormPost({
      id: postId,
      userId,
      title,
      summary,
      content,
      image,
      publishedAt: scheduledFor
        ? new Date(Number(scheduledFor) * 1000)
        : undefined,
      status: "SCHEDULED",
      signedEvent: parsedSignedEvent || undefined,
      nostrEvent: parsedNostrEvent || undefined,
    });

    return json({
      success: true,
      post: updated,
      signed: !!parsedSignedEvent,
    });
  }

  return json({ error: "Invalid action" }, { status: 400 });
}

export interface PostStats {
    likes: number;
    replies: number;
    mentions: number;
    reposts: number;
    zaps: number;
    satszapped: number;
}

export async function getPostStats(eventIds: string[]): Promise<Record<string, PostStats>> {
    let stats: Record<string, PostStats> = {};

    if (eventIds.length === 0) {
        return stats;
    }

    try {
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 5000);

        // Fetch stats for each event ID
        const statsPromises = eventIds.map(async (eventId) => {
            const response = await fetch(process.env.PRIMAL_CACHING_URL!, {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                },
                body: JSON.stringify({
                    requestType: "thread_view",
                    params: {
                        event_id: eventId,
                    },
                }),
                signal: controller.signal,
            });

            if (!response.ok) {
                throw new Error("Failed to fetch stats");
            }

            const data = await response.json() as [string, unknown, { kind?: number; content?: string }][];
            // Find the stats event in the response array
            // The stats event has kind 10000100 and contains engagement metrics
            const statsEvent = data.find(
                (event: [string, unknown, { kind?: number; content?: string }]) => {
                    if (event[0] !== "EVENT" || !event[2]) return false;
                    const eventData = event[2];
                    if (!eventData || typeof eventData !== "object" || Array.isArray(eventData)) return false;
                    const eventTyped = eventData as { kind?: number; content?: string };
                    return eventTyped.kind === 10000100 &&
                        eventTyped.content &&
                        typeof eventTyped.content === "string" &&
                        eventTyped.content.includes(eventId);
                },
            );

            if (statsEvent?.[2] && typeof statsEvent[2] === "object" && !Array.isArray(statsEvent[2])) {
                const eventData = statsEvent[2] as { kind?: number; content?: string };
                if (eventData.content && typeof eventData.content === "string") {
                    const content = JSON.parse(eventData.content) as {
                        likes?: number;
                        replies?: number;
                        mentions?: number;
                        reposts?: number;
                        zaps?: number;
                        satszapped?: number;
                    };
                    return {
                        [eventId]: {
                            likes: content.likes || 0,
                            replies: content.replies || 0,
                            mentions: content.mentions || 0,
                            reposts: content.reposts || 0,
                            zaps: content.zaps || 0,
                            satszapped: content.satszapped || 0,
                        },
                    };
                }
            }

            return {
                [eventId]: {
                    likes: 0,
                    replies: 0,
                    mentions: 0,
                    reposts: 0,
                    zaps: 0,
                    satszapped: 0,
                },
            };
        });

        const statsResults = await Promise.all(statsPromises);
        stats = statsResults.reduce((acc, curr) => ({ ...acc, ...curr }), {});
        clearTimeout(timeoutId);
    } catch (error) {
        console.error("Error fetching stats:", error);
        // Initialize empty stats object with 0 values for each post
        stats = eventIds.reduce((acc, eventId) => {
            acc[eventId] = {
                likes: 0,
                replies: 0,
                mentions: 0,
                reposts: 0,
                zaps: 0,
                satszapped: 0,
            };
            return acc;
        }, {} as Record<string, PostStats>);
    }

    return stats;
}

/**
 * Post Types
 * Shared TypeScript interfaces for post and queue features
 */

import type { Post, LongFormPost, QueueType as PrismaQueueType, HashTagPreset as PrismaHashTagPreset } from "@prisma/client";
import type { FetcherWithComponents } from "@remix-run/react";

import type { SignedEvent, NostrEvent } from "~/features/nostr/types";
/**
 * Schedule configuration for INTERVAL schedule type
 */
export interface IntervalScheduleConfig {
    useGlobalInterval?: boolean;
    intervalHours?: number;
}

/**
 * Schedule configuration for FIXED_SLOTS schedule type
 */
export interface FixedSlotsScheduleConfig {
    slots: string[];
}

/**
 * Union type for schedule configurations
 */
export type ScheduleConfig = IntervalScheduleConfig | FixedSlotsScheduleConfig;

/**
 * Type guard to check if config is IntervalScheduleConfig
 */
export function isIntervalScheduleConfig(
    config: ScheduleConfig | unknown
): config is IntervalScheduleConfig {
    if (typeof config !== "object" || config === null) {
        return false;
    }

    const cfg = config as Record<string, unknown>;

    // Check if it's NOT a FixedSlotsScheduleConfig (doesn't have slots array)
    const hasSlotsArray = Array.isArray(cfg.slots);

    // Must have either useGlobalInterval or intervalHours, but not slots array
    return !hasSlotsArray && ("useGlobalInterval" in cfg || "intervalHours" in cfg);
}

/**
 * Type guard to check if config is FixedSlotsScheduleConfig
 */
export function isFixedSlotsScheduleConfig(
    config: ScheduleConfig | unknown
): config is FixedSlotsScheduleConfig {
    if (typeof config !== "object" || config === null) {
        return false;
    }

    const cfg = config as Record<string, unknown>;

    // Must have slots array
    return Array.isArray(cfg.slots);
}

/**
 * Queue type with scheduling configuration
 */
export interface QueueType {
    id: string;
    name: string;
    color?: string | null;
    description?: string | null;
    scheduleType?: "INTERVAL" | "FIXED_SLOTS";
    scheduleConfig?: ScheduleConfig;
    isEnabled?: boolean;
    userId?: string;
}

/**
 * Extended queue type with relations
 */
export type QueueTypeWithRelations = PrismaQueueType & {
    hashTagPreset?: HashTagPreset | null;
};

/**
 * Bulk post data for scheduling
 */
export interface BulkPost {
    file: File | null;
    caption: string;
    queueType: string;
    scheduledFor: string;
    isRecyclable: boolean;
    fileUrl?: string;
    isRepost?: boolean;
    isKind6Repost?: boolean;
    isQuotePost?: boolean;
    isLongformQuote?: boolean;
    originalPostId?: string;
    originalEventId?: string;
    originalEventPubkey?: string;
    originalCaption?: string;
    originalTitle?: string;
    originalFileUrl?: string | string[];
    naddr?: string;
}

/**
 * Dependencies for bulk posts handlers
 */
export interface BulkPostsHandlerDeps {
    posts: BulkPost[];
    setPosts: React.Dispatch<React.SetStateAction<BulkPost[]>>;
    queueTypes: QueueType[];
    tags: string[];
    user: { id?: string; timezone?: string; scheduleInterval?: number[] } | null;
    setDisplayedHashtags: (hashtags: string | string[]) => void;
    setSelectedQueueType: (type: string) => void;
    setIsProcessing: (processing: boolean) => void;
    setProcessingProgress: (progress: { current: number; total: number }) => void;
    scheduleIntervals: number[] | undefined;
    firstItemTimeManuallyChanged: boolean;
    setFirstItemTimeManuallyChanged: (changed: boolean) => void;
}

/**
 * Post data structure for editing/displaying
 */
export interface PostData extends Omit<Post, "signedEvent" | "nostrEvent"> {
    signedEvent?: SignedEvent | null;
    nostrEvent?: NostrEvent | null;
    queueType?: QueueType | null;
    hashTagPreset?: HashTagPreset | null;
    hashtags?: string; // Space-separated hashtags string
}

/**
 * Longform post data structure for editing/displaying
 */
export interface LongFormPostData extends Omit<LongFormPost, "signedEvent" | "nostrEvent"> {
    signedEvent?: SignedEvent | null;
    nostrEvent?: NostrEvent | null;
    queueType?: QueueType | null;
}

/**
 * Combined content for displaying posts and longform posts together
 */
export interface CombinedContent {
    id: string;
    type: "post" | "longform";
    title?: string;
    caption?: string;
    content?: string;
    summary?: string;
    image?: string;
    fileUrl?: string[];
    scheduledFor?: string;
    publishedAt?: Date;
    postedAt?: Date;
    createdAt: Date;
    updatedAt: Date;
    isScheduled?: boolean;
    isPosted?: boolean;
    isPublished?: boolean;
    draft?: boolean;
    status: string;
    queueType?: {
        id: string;
        name: string;
        color?: string;
    };
    queueTypeId?: string;
    userId: string;
    tags?: string[];
    signedEvent?: SignedEvent;
    nostrEvent?: NostrEvent;
    nostrEventId?: string;
    manual_override?: boolean;
    postType?: string;
    repost?: boolean;
    isQuotedPost?: boolean;
    isRecyclable?: boolean;
    templateId?: string;
    originalData: PostData | LongFormPostData;
}

/**
 * Post job data for BullMQ workers
 */
export interface PostJobData {
    postId: string;
    userId: string;
    signedEvent: SignedEvent;
}

/**
 * Longform post job data for BullMQ workers
 */
export interface LongFormPostJobData {
    postId: string;
    userId: string;
    signedEvent: SignedEvent;
}

/**
 * Prepared event for bulk posting operations
 */
export interface PreparedEvent {
    fileUrl: string;
    scheduledFor: number;
    caption: string;
    queueType: string;
    isRecyclable: boolean;
    originalPostId?: string;
    originalEventId?: string;
    originalEventPubkey?: string;
    events: {
        content: string;
        created_at: number;
        kind: number;
        tags: string[][];
        isQuotePost?: boolean;
    };
}

/**
 * Hashtag preset configuration
 */
export interface HashTagPreset {
    id: string;
    name: string;
    tags: string; // Stored as space-separated string
    description?: string | null;
    createdAt?: Date;
    updatedAt?: Date;
    userId?: string;
}

/**
 * Extended hashtag preset with relations
 */
export type HashTagPresetWithRelations = PrismaHashTagPreset;

/**
 * Props for HashtagPresetToggle component
 */
export interface HashtagPresetToggleProps {
    presets: HashTagPreset[];
    queueTypes: QueueType[];
    selectedQueueType: QueueType | null;
    onPresetChange: (presetId: string | null) => void;
}

/**
 * Props for HashtagPresetSelector component
 */
export interface HashtagPresetSelectorProps {
    presets: HashTagPreset[];
    selectedPresetId: string | null;
    onPresetChange: (presetId: string | null) => void;
}

/**
 * Props for BulkPostCard component
 */
export interface BulkPostCardProps {
    post: BulkPost;
    index: number;
    queueTypes: (QueueType | string)[];
    previewData: Map<number, { url: string; isVideo: boolean; file: File }>;
    onCaptionChange: (index: number, value: string) => void;
    onDateChange: (index: number, value: string) => void;
    onQueueTypeChange: (index: number, value: string) => void;
    onIsRecyclableChange: (index: number, checked: boolean) => void;
    onRemove: (index: number) => void;
    onMediaClick: (src: string) => void;
}

/**
 * User data structure for components
 */
export interface UserData {
    id: string;
    npub?: string;
    pubKey?: string;
    name?: string | null;
    picture?: string | null;
    timezone?: string | null;
    scheduleInterval?: number[];
    userRelays?: string[];
    showHashTagsinPosts?: boolean;
    isEnabled?: boolean;
}

/**
 * Remix Fetcher type for form submissions
 */
export type PostFetcher = FetcherWithComponents<{
    success?: boolean;
    error?: string;
    needsSigning?: boolean;
    post?: PostData | LongFormPostData;
}>;

/**
 * EditorJS block data structure
 */
export interface EditorJSBlock {
    id?: string;
    type: string;
    data: Record<string, unknown>;
}

/**
 * EditorJS output data structure
 */
export interface EditorJSOutput {
    blocks: EditorJSBlock[];
    time?: number;
    version?: string;
}

/**
 * EditorJS API interface
 */
export interface EditorJSAPI {
    saver: {
        save: () => Promise<EditorJSOutput>;
    };
    blocks: {
        getCurrentBlockIndex: () => number;
        insert: (type: string, data: Record<string, unknown>) => void;
    };
    focus: () => void;
    isReady: Promise<void>;
    render: (data: EditorJSOutput) => Promise<void>;
    destroy: () => void;
