import { type FetcherWithComponents } from "@remix-run/react";
import { nip19 } from "nostr-tools";
import { useEffect, useState, useRef, useCallback } from "react";

import { type ToastMessage } from "~/components/types";
import { type BulkPost , type PreparedEvent } from "~/features/posts/types";
import { uploadMultipleFiles } from "~/features/upload/upload.client";
import { logClientError } from "~/lib/error-handler.client";
import { type User } from "~/models/user.server";
interface FetcherData {
    fileUrls?: { fileUrl: string; scheduledFor: string }[];
}

interface UseBulkPostEventsProps {
    posts: BulkPost[];
    fetcher: FetcherWithComponents<FetcherData>;
    user: User | null;
    tags: string[];
    useHashtagPresets: boolean;
    selectedHashtags: string;
    setToast: (toast: ToastMessage | null) => void;
    setPreparedEvents: (events: PreparedEvent[]) => void;
    setShowConfirmation: (show: boolean) => void;
    setIsPreviewSubmitting: (isSubmitting: boolean) => void;
    setIsProcessing: (isProcessing: boolean) => void;
}

export function useBulkPostEvents({
    posts,
    fetcher,
    user,
    tags,
    useHashtagPresets,
    selectedHashtags,
    setToast,
    setPreparedEvents,
    setShowConfirmation,
    setIsPreviewSubmitting,
    setIsProcessing,
}: UseBulkPostEventsProps) {
    const isWaitingForUpload = useRef(false);

    // Validation function to check if all posts are ready for preview
    const validatePostsForPreview = () => {
        const errors: string[] = [];

        posts.forEach((post, index) => {
            // Check if schedule time is set
            if (!post.scheduledFor || post.scheduledFor.trim() === "") {
                errors.push(`Post ${index + 1}: Schedule time is required`);
            }

            // Check if schedule time is in the future
            if (post.scheduledFor) {
                const userTimezone = user?.timezone ?? "UTC";

                // The scheduledFor value is in user's timezone (from datetime-local input)
                // We need to compare it with current time in the same user timezone
                // Get current time in user's timezone as a comparable string
                const nowInUserTz = new Date().toLocaleString("en-US", {
                    timeZone: userTimezone,
                    year: "numeric",
                    month: "2-digit",
                    day: "2-digit",
                    hour: "2-digit",
                    minute: "2-digit",
                    hour12: false,
                }).replace(/(\d+)\/(\d+)\/(\d+),\s(\d+):(\d+)/, "$3-$1-$2T$4:$5");

                // Compare as strings since both are in the same format (YYYY-MM-DDTHH:mm)
                // This avoids timezone conversion issues
                if (post.scheduledFor <= nowInUserTz) {
                    errors.push(`Post ${index + 1}: Schedule time must be in the future`);
                }
            }

            // Check if queue type is assigned (for new uploads)
            if (
                !post.isRepost &&
                !post.isKind6Repost &&
                !post.isQuotePost &&
                post.queueType === "unassigned"
            ) {
                errors.push(`Post ${index + 1}: Please assign a queue type`);
            }
        });

        return { isValid: errors.length === 0, errors };
    };

    const processEvents = useCallback(async () => {
        // Create events with image URLs and hashtags
        const events = await Promise.all(
            posts.map(async (post, index) => {
                // Get effective hashtags - use manual selection if enabled, otherwise queue default
                let effectiveHashtags = "";

                if (useHashtagPresets && selectedHashtags) {
                    // Use manually selected hashtag preset
                    effectiveHashtags = selectedHashtags;
                } else {
                    // Use queue type's default hashtags
                    try {
                        const res = await fetch("/api/effective-hashtags", {
                            method: "POST",
                            headers: {
                                "Content-Type": "application/json",
                            },
                            body: JSON.stringify({
                                userId: user?.id,
                                queueTypeName: post.queueType,
                            }),
                        });
                        const data = (await res.json()) as { hashtags?: string };
                        effectiveHashtags = data.hashtags || tags;
                    } catch {
                        effectiveHashtags = tags;
                    }
                }

                const tagsString = effectiveHashtags || "";
                const addTags = user?.showHashTagsinPosts ? `${tagsString}` : "";

                // Build content array, filtering out null/undefined/empty values
                const fileUrls = fetcher.data?.fileUrls;
                const fileUrlItem = fileUrls && Array.isArray(fileUrls) && fileUrls[index] ? fileUrls[index] : null;
                const fileUrl = fileUrlItem && typeof fileUrlItem === "object" && "fileUrl" in fileUrlItem && typeof fileUrlItem.fileUrl === "string" ? fileUrlItem.fileUrl : "";

                const contentParts = [
                    fileUrl,
                    post.caption,
                    addTags,
                ].filter((part) => part != null && part !== ""); // Filter out null, undefined, and empty strings

                const content = contentParts.join("\n");

                // Convert space-separated tags string into array of ["t", tag] pairs
                const tagArray: string[][] = tagsString
                    .split(" ")
                    .filter((tag: string) => tag.length > 0)
                    .map((tag: string) => ["t", tag.replace("#", "")]);

                const userTimezone = user?.timezone ?? "UTC";
                const scheduledForValue = fileUrlItem && typeof fileUrlItem === "object" && "scheduledFor" in fileUrlItem && typeof fileUrlItem.scheduledFor === "string" ? fileUrlItem.scheduledFor : "";
                const userTimezoneDateStr = scheduledForValue;
                let scheduledTime;

                // Only convert timezone if not UTC/Etc/GMT
                if (userTimezone !== "UTC" && userTimezone !== "Etc/GMT") {
                    const utcDate = new Date(userTimezoneDateStr);

                    // Get timezone offset in minutes between user timezone and UTC
                    const userDate = new Date(userTimezoneDateStr).toLocaleString(
                        "en-US",
                        {
                            timeZone: userTimezone,
                        },
                    );
                    const userOffset =
                        (new Date(userDate).getTime() - new Date(userTimezoneDateStr).getTime()) / 60000;

                    // Adjust the date by the offset
                    utcDate.setMinutes(utcDate.getMinutes() - userOffset);
                    scheduledTime = utcDate.getTime();
                } else {
                    // Parse date string and ensure it's in UTC
                    const dateObj = new Date(userTimezoneDateStr + "Z");
                    scheduledTime = dateObj.getTime();
                }

                // Handle kind 6 reposts differently
                if (post.isKind6Repost) {
                    // For kind 6 reposts, use the original file URL for display purposes
                    let displayFileUrl = "";
                    if (post.originalFileUrl && post.originalFileUrl.length > 0) {
                        // Handle case where fileUrl might be a JSON string array
                        if (
                            typeof post.originalFileUrl === "string" &&
                            post.originalFileUrl.startsWith("[")
                        ) {
                            try {
                                const parsed = JSON.parse(post.originalFileUrl) as string[];
                                if (Array.isArray(parsed) && parsed.length > 0) {
                                    displayFileUrl = parsed[0];
                                }
                            } catch (e) {
                                // If parsing fails, use as is
                                displayFileUrl = post.originalFileUrl;
                            }
                        } else if (
                            Array.isArray(post.originalFileUrl) &&
                            post.originalFileUrl.length > 0
                        ) {
                            displayFileUrl = post.originalFileUrl[0];
                        } else {
                            displayFileUrl = post.originalFileUrl as string;
                        }
                    }

                    return {
                        fileUrl: displayFileUrl, // Use original file URL for display
                        scheduledFor: Math.floor(scheduledTime / 1000),
                        caption: "", // No caption for kind 6 reposts
                        queueType: post?.queueType ?? "unassigned",
                        isRecyclable: post?.isRecyclable ?? false,
                        originalPostId: post.originalPostId,
                        originalEventId: post.originalEventId,
                        originalEventPubkey: post.originalEventPubkey,
                        events: {
                            content: "", // Empty content for kind 6 reposts
                            created_at: Math.floor(scheduledTime / 1000),
                            kind: 6, // Kind 6 for reposts
                            tags: [
                                ["e", post.originalEventId || "", "wss://relay.primal.net"],
                                ["p", post.originalEventPubkey || ""],
                            ],
                        },
                    };
                } else if (post.isQuotePost) {
                    // Handle quote posts (kind 1 with e and p tags)
                    let quoteContent;
                    let quoteTags;

                    if (post.isLongformQuote) {
                        // For longform quote posts, the caption already contains the naddr reference
                        // Don't add an additional nevent reference
                        quoteContent = [
                            post.caption, // This already contains nostr:naddr1... for longform
                            addTags.length > 10 ? "" : addTags, // Hide tags if longer than 10 characters
                        ]
                            .filter(Boolean)
                            .join("\n");

                        // For longform quotes, use 'a' tag instead of 'e' tag
                        // Extract dTag from naddr if available
                        let aTag = null;
                        if (post.naddr) {
                            try {
                                const decoded = nip19.decode(post.naddr.replace("nostr:", ""));
                                if (decoded.type === "naddr" && decoded.data) {
                                    const { identifier, pubkey, kind } = decoded.data;
                                    aTag = [
                                        "a",
                                        `${kind}:${pubkey}:${identifier}`,
                                        "wss://relay.primal.net",
                                        "mention",
                                    ];
                                }
                            } catch (e) {
                                logClientError(
                                    e instanceof Error ? e : new Error(String(e)),
                                    {
                                        component: "useBulkPostEvents",
                                        action: "decodeNaddr",
                                        message: "Failed to decode naddr for longform quote",
                                    },
                                    "warning",
                                );
                            }
                        }

                        quoteTags = [
                            ...tagArray, // Hashtag tags
                            ...(aTag ? [aTag] : []), // 'a' tag for longform reference if available
                            ["p", post.originalEventPubkey || "", "", "mention"], // Reference to quoted author
                        ];
                    } else {
                        // Create nevent1 format for regular quoted events
                        const neventEncoded = nip19.neventEncode({
                            id: post.originalEventId || "",
                            relays: ["wss://relay.primal.net"],
                            author: post.originalEventPubkey,
                        });

                        // For regular quote posts, content should include caption + nevent + hashtags
                        quoteContent = [
                            post.caption,
                            `nostr:${neventEncoded}`,
                            addTags.length > 10 ? "" : addTags, // Hide tags if longer than 10 characters
                        ]
                            .filter(Boolean)
                            .join("\n");

                        // Include hashtag t tags plus e and p tags for quote posts
                        quoteTags = [
                            ...tagArray, // Hashtag tags
                            ["e", post.originalEventId || "", "wss://relay.primal.net", "mention"], // Reference to quoted event
                            ["p", post.originalEventPubkey || "", "", "mention"], // Reference to quoted author
                        ];
                    }

                    return {
                        fileUrl,
                        scheduledFor: Math.floor(scheduledTime / 1000),
                        caption: post?.caption ?? "",
                        queueType: post?.queueType ?? "unassigned",
                        isRecyclable: post?.isRecyclable ?? false,
                        originalPostId: post.originalPostId,
                        originalEventId: post.originalEventId,
                        originalEventPubkey: post.originalEventPubkey,
                        events: {
                            content: quoteContent,
                            created_at: Math.floor(scheduledTime / 1000),
                            kind: 1, // Kind 1 for quote posts
                            tags: quoteTags,
                            isQuotePost: true, // Flag to identify quote posts
                        },
                    };
                } else {
                    return {
                        fileUrl,
                        scheduledFor: Math.floor(scheduledTime / 1000),
                        caption: post?.caption ?? "",
                        queueType: post?.queueType ?? "unassigned",
                        isRecyclable: post?.isRecyclable ?? false,
                        originalPostId: post?.originalPostId,
                        events: {
                            content,
                            created_at: Math.floor(scheduledTime / 1000),
                            kind: 1,
                            tags: tagArray,
                        },
                    };
                }
            }),
        );

        setPreparedEvents(events);
        setShowConfirmation(true);

        // Reset loading state when events are processed successfully
        setIsPreviewSubmitting(false);
    }, [posts, useHashtagPresets, selectedHashtags, user, tags, fetcher.data, setPreparedEvents, setShowConfirmation, setIsPreviewSubmitting]);

    const prepareEvents = async (e: React.FormEvent) => {
        e.preventDefault();

        // Validate posts before proceeding
        const { isValid, errors } = validatePostsForPreview();
        if (!isValid) {
            // Show toast notification with validation errors
            const errorMessage =
                errors.length === 1
                    ? errors[0]
                    : `${errors.length} issues found:\n• ${errors.slice(0, 3).join("\n• ")}${errors.length > 3 ? "\n• And more..." : ""}`;

            setToast({
                type: "error",
                message: errorMessage,
            });

            // Hide toast after 5 seconds
            setTimeout(() => setToast(null), 5000);
            return;
        }

        // Set loading state for preview submission
        setIsPreviewSubmitting(true);

        try {
            // Check if this is a repost with existing URLs, kind 6 repost, or quote post
            const hasRepostData = posts.some((post) => post.isRepost && post.fileUrl);
            const hasKind6RepostData = posts.some((post) => post.isKind6Repost);
            const hasQuotePostData = posts.some((post) => post.isQuotePost);

            if (hasRepostData || hasKind6RepostData || hasQuotePostData) {
                // For reposts and quote posts, create fake upload response with existing URLs
                const fakeFileUrls = posts.map((post) => {
                    let fileUrl = "";

                    if (post.isKind6Repost) {
                        // For kind 6 reposts, use the original file URL for display
                        if (post.originalFileUrl && post.originalFileUrl.length > 0) {
                            if (Array.isArray(post.originalFileUrl)) {
                                fileUrl = post.originalFileUrl[0];
                            } else if (
                                typeof post.originalFileUrl === "string" &&
                                post.originalFileUrl.startsWith("[")
                            ) {
                                try {
                                    const parsed = JSON.parse(post.originalFileUrl);
                                    if (Array.isArray(parsed) && parsed.length > 0) {
                                        fileUrl = parsed[0];
                                    }
                                } catch (_e) {
                                    // If parsing fails, use as is
                                    fileUrl = post.originalFileUrl;
                                }
                            } else {
                                fileUrl = post.originalFileUrl;
                            }
                        }
                    } else {
                        // For regular reposts and quote posts, use the fileUrl
                        fileUrl = Array.isArray(post.fileUrl)
                            ? post.fileUrl[0]
                            : post.fileUrl as string;
                    }

                    return {
                        fileUrl,
                        scheduledFor: post.scheduledFor,
                        queueType: post.queueType,
                        isRecyclable: post.isRecyclable || false,
                    };
                });

                // Simulate the fetcher response
                fetcher.data = { fileUrls: fakeFileUrls };

                // Trigger the event creation manually
                const customEvent = new CustomEvent("repostEventsPrepared");
                document.dispatchEvent(customEvent);
            } else {
                // Use client-side upload system
                const filesToUpload = posts
                    .map((post) => post.file)
                    .filter((file) => file !== null);

                if (filesToUpload.length > 0) {
                    try {
                        // Upload all files using the new upload system
                        const uploadResults = await uploadMultipleFiles(filesToUpload);

                        // Check for failed uploads
                        const failedUploads = uploadResults.filter(
                            (result) => !result.success,
                        );
                        if (failedUploads.length > 0) {
                            const errorMessages = failedUploads
                                .map((result) => result.error)
                                .join(", ");
                            throw new Error(`Upload failed: ${errorMessages}`);
                        }

                        // Map upload results back to posts (maintaining order)
                        let uploadIndex = 0;
                        const mappedResults = posts.map((post) => {
                            if (post.file) {
                                return uploadResults[uploadIndex++];
                            }
                            return { success: true, file: { url: "" } }; // Placeholder for posts without files
                        });

                        // Send results to server
                        const formData = new FormData();
                        formData.append("uploadResults", JSON.stringify(mappedResults));
                        posts.forEach((post) => {
                            formData.append("scheduledDates", post.scheduledFor);
                            formData.append("queueTypes", post.queueType);
                            formData.append("isRecyclable", (post.isRecyclable || false).toString());
                        });
                        formData.append("_action", "_upload_images_preview");

                        // Submit to server for processing
                        isWaitingForUpload.current = true;
                        fetcher.submit(formData, {
                            method: "post",
                        });
                    } catch (error: unknown) {
                        const { handleAsyncErrorWithMessage, getErrorMessage } = await import("~/lib/error-handler.client");
                        const errorMessage = `Upload failed: ${getErrorMessage(error)}`;
                        handleAsyncErrorWithMessage(
                            error,
                            errorMessage,
                            {
                                component: "useBulkPostEvents",
                                action: "prepareEvents",
                            },
                            false, // Don't show toast, we set toast state instead
                        );
                        setToast({
                            type: "error",
                            message: errorMessage,
                        });
                        setTimeout(() => setToast(null), 5000);
                        setIsPreviewSubmitting(false);
                        return;
                    }
                } else {
                    // No files to upload, just proceed with existing URLs (for reposts/quotes)
                    const formData = new FormData();
                    formData.append("uploadResults", JSON.stringify([])); // Empty results for no uploads
                    posts.forEach((post) => {
                        formData.append("scheduledDates", post.scheduledFor);
                        formData.append("queueTypes", post.queueType);
                        formData.append("isRecyclable", (post.isRecyclable || false).toString());
                    });
                    formData.append("_action", "_upload_images_preview");

                    // Submit to server for processing
                    isWaitingForUpload.current = true;
                    fetcher.submit(formData, {
                        method: "post",
                    });
                }
            }
        } catch (error: unknown) {
            const { handleAsyncErrorWithMessage } = await import("~/lib/error-handler.client");
            handleAsyncErrorWithMessage(
                error,
                "An error occurred while preparing posts. Please try again.",
                {
                    component: "useBulkPostEvents",
                    action: "prepareEvents",
                },
                false, // Don't show toast, we set toast state instead
            );
            setToast({
                type: "error",
                message: "An error occurred while preparing posts. Please try again.",
            });

            // Hide toast after 5 seconds
            setTimeout(() => setToast(null), 5000);
            setIsPreviewSubmitting(false);
        }
    };

    // Add event listener for repost events
    useEffect(() => {
        const handleRepostEventsPrepared = () => {
            // Manually trigger the event creation logic
            if (fetcher.data?.fileUrls) {
                void processEvents();
            }
        };

        document.addEventListener(
            "repostEventsPrepared",
            handleRepostEventsPrepared,
        );

        return () => {
            document.removeEventListener(
                "repostEventsPrepared",
                handleRepostEventsPrepared,
            );
        };
    }, [fetcher.data, processEvents]);

    // Watch for upload completion
    useEffect(() => {
        if (
            isWaitingForUpload.current &&
            fetcher.state === "idle" &&
            fetcher.data?.fileUrls
        ) {
            isWaitingForUpload.current = false;
            processEvents();
        }
    }, [fetcher.state, fetcher.data, processEvents]);

    return { prepareEvents };
}

import { useEffect } from "react";

import { type BulkPost } from "~/features/posts/components/BulkPostCard";
import { handleErrorSafely } from "~/lib/error-handler.client";
interface RepostDataItem {
    fileUrl?: string | string[];
    caption?: string;
    queueType?: string;
    scheduledFor?: string;
    isRecyclable?: boolean;
    originalPostId?: string;
}

interface UseBulkPostsStateProps {
    mode: string | null;
    posts: BulkPost[];
    setPosts: (posts: BulkPost[]) => void;
}

export function useBulkPostsState({ mode, posts, setPosts }: UseBulkPostsStateProps) {
    // Load repost data from sessionStorage if in recycle mode
    useEffect(() => {
        if (mode === "recycle") {
            const repostData = sessionStorage.getItem("repostData");
            if (repostData) {
                try {
                    const parsedData = JSON.parse(repostData) as RepostDataItem[];

                    // Convert repost data to posts format with file objects from URLs
                    const repostPosts = parsedData.map((item: RepostDataItem, _index: number) => {
                        let fileUrl = item.fileUrl;

                        // Handle case where fileUrl might be a JSON string array
                        if (typeof fileUrl === "string") {
                            try {
                                const parsed = JSON.parse(fileUrl) as string[];
                                if (Array.isArray(parsed) && parsed.length > 0) {
                                    fileUrl = parsed[0]; // Take first URL from array
                                }
                            } catch (e) {
                                // If it's not JSON, keep as is
                            }
                        } else if (Array.isArray(fileUrl) && fileUrl.length > 0) {
                            fileUrl = fileUrl[0]; // Take first URL from array
                        }

                        return {
                            file: null, // We'll handle URL-based files differently
                            caption: item.caption,
                            queueType: item.queueType,
                            scheduledFor: item.scheduledFor,
                            fileUrl: fileUrl, // Ensured to be a single URL string
                            isRepost: true, // Flag to indicate this is a repost
                            isRecyclable: item.isRecyclable || false,
                            originalPostId: item.originalPostId, // Include original post ID for tracking
                        };
                    });

                    setPosts(repostPosts);

                    // Clear sessionStorage after loading
                    sessionStorage.removeItem("repostData");
                } catch (error) {
                    handleErrorSafely(error, {
                        component: "useBulkPostsState",
                        action: "loadRepostData",
                    });
                }
            }
        } else if (mode === "repost") {
            // Load scheduled repost data for kind 6 reposts
            const scheduledRepostData = sessionStorage.getItem("scheduledRepostData");
            if (scheduledRepostData) {
                try {
                    const parsedData = JSON.parse(scheduledRepostData) as RepostDataItem[];

                    // We need to fetch the original posts to get their images
                    const fetchOriginalPosts = async () => {
                        try {
                            const response = await fetch("/api/posts/batch", {
                                method: "POST",
                                headers: {
                                    "Content-Type": "application/json",
                                },
                                body: JSON.stringify({
                                    postIds: parsedData.map((item: RepostDataItem) => item.originalPostId).filter((id: string | undefined): id is string => id !== undefined),
                                }),
                            });

                            if (response.ok) {
                                const originalPosts = (await response.json()) as OriginalPost[];
                                return originalPosts;
                            }
                        } catch (error) {
                            handleErrorSafely(error, {
                                component: "useBulkPostsState",
                                action: "fetchOriginalPosts",
                            });
                        }
                        return [];
                    };

                    interface ScheduledRepostDataItem {
                        caption?: string;
                        queueType?: string;
                        scheduledFor?: string;
                        originalPostId?: string;
                        originalEventId?: string;
                        originalEventPubkey?: string;
                        isRecyclable?: boolean;
                    }
                    interface OriginalPost {
                        id: string;
                        fileUrl?: string | string[];
                        caption?: string;
                    }
                    // Fetch original posts and merge with repost data
                    void (async () => {
                        try {
                            const originalPosts = await fetchOriginalPosts();
                            const repostPosts = parsedData.map((item: ScheduledRepostDataItem) => {
                                const originalPost = originalPosts.find(
                                    (p: OriginalPost) => p.id === item.originalPostId,
                                );

                                return {
                                    file: null, // No file for kind 6 reposts
                                    caption: item.caption, // Empty for kind 6
                                    queueType: item.queueType,
                                    scheduledFor: item.scheduledFor,
                                    fileUrl: originalPost?.fileUrl || [], // Use original post's images for display
                                    originalFileUrl: originalPost?.fileUrl || [], // Keep original file URLs for display
                                    isKind6Repost: true, // Flag to indicate this is a kind 6 repost
                                    originalPostId: item.originalPostId,
                                    originalEventId: item.originalEventId,
                                    originalEventPubkey: item.originalEventPubkey,
                                    originalCaption: originalPost?.caption || "", // Store original caption for context
                                    isRecyclable: item.isRecyclable || false,
                                };
                            });

                            setPosts(repostPosts);
                        } catch (error) {
                            handleErrorSafely(error, {
                                component: "useBulkPostsState",
                                action: "fetchOriginalPosts",
                            });
                        }
                    })();

                    // Clear sessionStorage after loading
                    sessionStorage.removeItem("scheduledRepostData");
                } catch (error) {
                    handleErrorSafely(error, {
                        component: "useBulkPostsState",
                        action: "loadScheduledRepostData",
                    });
                }
            }
        } else if (mode === "quote") {
            // Load quote post data
            const quotePostData = sessionStorage.getItem("quotePostData");
            if (quotePostData) {
                try {
                    const parsedData = JSON.parse(quotePostData) as QuotePostDataItem[];

                    interface QuotePostDataItem {
                        fileUrl?: string | string[];
                        caption?: string;
                        queueType?: string;
                        scheduledFor?: string;
                        isQuotePost?: boolean;
                        isLongformQuote?: boolean;
                        naddr?: string;
                        originalPostId?: string;
                        originalEventId?: string;
                        originalEventPubkey?: string;
                        originalCaption?: string;
                        originalTitle?: string;
                        isRecyclable?: boolean;
                    }
                    // Convert quote post data to posts format
                    const quotePosts = parsedData.map((item: QuotePostDataItem) => {
                        let fileUrl = item.fileUrl;

                        // Handle case where fileUrl might be a JSON string array
                        if (typeof fileUrl === "string") {
                            try {
                                const parsed = JSON.parse(fileUrl) as string[];
                                if (Array.isArray(parsed) && parsed.length > 0) {
                                    fileUrl = parsed[0]; // Take first URL from array
                                }
                            } catch (e) {
                                // If it's not JSON, keep as is
                            }
                        } else if (Array.isArray(fileUrl) && fileUrl.length > 0) {
                            fileUrl = fileUrl[0]; // Take first URL from array
                        }

                        return {
                            file: null, // We'll handle URL-based files differently
                            caption: item.caption || "", // Start with empty caption for user to add content
                            queueType: item.queueType,
                            scheduledFor: item.scheduledFor,
                            fileUrl: fileUrl, // Ensured to be a single URL string
                            isQuotePost: true, // Flag to indicate this is a quote post
                            isLongformQuote: item.isLongformQuote || false, // Preserve longform quote flag
                            naddr: item.naddr || "", // Preserve naddr for longform quotes
                            originalPostId: item.originalPostId,
                            originalEventId: item.originalEventId,
                            originalEventPubkey: item.originalEventPubkey,
                            originalCaption: item.originalCaption || "",
                            originalTitle: item.originalTitle || "", // Preserve original title for longform
                            isRecyclable: item.isRecyclable || false,
                        };
                    });

                    setPosts(quotePosts);

                    // Clear sessionStorage after loading
                    sessionStorage.removeItem("quotePostData");
                } catch (error) {
                    handleErrorSafely(error, {
                        component: "useBulkPostsState",
                        action: "loadQuotePostData",
                    });
                }
            }
        }
    }, [mode, setPosts]);
}

import { useFetcher } from "@remix-run/react";
import { useState, useCallback } from "react";

import { resizeImage } from "~/features/upload/image-resize";
interface UseCoverImageUploadOptions {
    uploadProvider: string | null;
    initialImage?: string;
}

interface SelectedAsset {
    assetType: string;
    fileUrl?: string;
}

export function useCoverImageUpload({
    uploadProvider,
    initialImage = "",
}: UseCoverImageUploadOptions) {
    const uploadFetcher = useFetcher<{ success?: boolean; imageUrl?: string; error?: string }>();
    const [image, setImage] = useState(initialImage);
    const [uploadError, setUploadError] = useState("");

    const handleImageUpload = useCallback(async (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (!file) return;

        if (!file.type.startsWith("image/")) {
            setUploadError("Please select an image file");
            return;
        }

        if (file.size > 5 * 1024 * 1024) {
            setUploadError("Image size must be less than 5MB");
            return;
        }

        setUploadError("");

        try {
            // Process the image to remove all metadata for privacy
            const processedFile = await resizeImage(file);

            // Check if user has Blossom provider selected
            if (uploadProvider && uploadProvider.includes("BLOSSOM")) {
                // Use client-side upload for Blossom
                const { uploadFile } = await import("~/features/upload/upload.client");
                const uploadResult = await uploadFile(processedFile);

                if (uploadResult.success && uploadResult.file) {
                    setImage(uploadResult.file.url);
                    setUploadError("");
                } else {
                    setUploadError(uploadResult.error || "Upload failed");
                }
            } else {
                // Use server-side upload for S3
                const formData = new FormData();
                formData.append("imageFile", processedFile);
                formData.append("_action", "upload-image");

                uploadFetcher.submit(formData, {
                    method: "post",
                    encType: "multipart/form-data",
                });
            }
        } catch (error) {
            const { handleAsyncErrorWithMessage } = await import("~/lib/error-handler.client");
            handleAsyncErrorWithMessage(
                error,
                "Error uploading image. Please try again.",
                {
                    component: "useCoverImageUpload",
                    action: "handleImageUpload",
                },
                false, // Don't show toast, we set uploadError instead
            );
            setUploadError("Error uploading image. Please try again.");
        }
    }, [uploadProvider, uploadFetcher]);

    const handleCoverImageAssets = useCallback((selectedAssets: SelectedAsset[]) => {
        // For cover image, only use the first selected image asset
        const imageAssets = selectedAssets.filter(
            (asset) => asset.assetType === "IMAGE",
        );
        if (imageAssets.length > 0 && imageAssets[0].fileUrl) {
            setImage(imageAssets[0].fileUrl);
            setUploadError("");
        }
    }, []);

    // Handle upload fetcher responses
    const handleFetcherData = useCallback(() => {
        if (uploadFetcher.data) {
            if (uploadFetcher.data.success && uploadFetcher.data.imageUrl) {
                setImage(uploadFetcher.data.imageUrl);
                setUploadError("");
            } else if (uploadFetcher.data.error) {
                setUploadError(uploadFetcher.data.error);
            }
        }
    }, [uploadFetcher.data]);

    // Clear upload errors when fetcher state changes
    const handleFetcherStateChange = useCallback(() => {
        if (uploadFetcher.state === "submitting") {
            setUploadError("");
        }
    }, [uploadFetcher.state]);

    return {
        image,
        setImage,
        uploadError,
        uploadFetcherState: uploadFetcher.state,
        handleImageUpload,
        handleCoverImageAssets,
        handleFetcherData,
        handleFetcherStateChange,
    };
}

import { useState, useEffect, useRef, useCallback } from "react";

import type { EditorJSInstance, EditorJSAPI } from "~/features/posts/types/editorjs.types";
import {
  disableCaptions,
  setupCaptionObserver,
} from "~/features/posts/utils/editorjs-captions";
import { createEditorJSToolsConfig } from "~/features/posts/utils/editorjs-config";
import {
  loadEditorJSContent,
  insertAssetsIntoEditor,
  generateSummaryFromContent as generateSummary,
} from "~/features/posts/utils/editorjs-content";
import { setupCustomDragDrop } from "~/features/posts/utils/editorjs-dragdrop";
import { logClientError } from "~/lib/error-handler.client";

interface UseLongFormEditorOptions {
    uploadProvider: string | null;
    initialContent?: string;
    onContentChange: (content: string) => void;
}

export function useLongFormEditor({
    uploadProvider,
    initialContent,
    onContentChange,
}: UseLongFormEditorOptions) {
    const editorRef = useRef<EditorJSInstance | null>(null);
    const editorInitialized = useRef(false);
    const [editorReady, setEditorReady] = useState(false);

    // Disable captions function
    const disableCaptionsFn = useCallback(() => {
        disableCaptions();
    }, []);

    // Main editor initialization effect
    useEffect(() => {
        const loadEditor = async () => {
            // Prevent multiple initializations more aggressively
            if (
                typeof window !== "undefined" &&
                !editorRef.current &&
                !editorInitialized.current
            ) {
                editorInitialized.current = true;

                // Check if editor is already initialized in DOM
                const existingEditor = document.getElementById("editorjs");
                if (existingEditor) {
                    // If there's already EditorJS content, don't reinitialize
                    const hasEditorContent =
                        existingEditor.querySelector(".codex-editor") ||
                        existingEditor.querySelector(".ce-block") ||
                        existingEditor.innerHTML.trim().length > 0;

                    if (hasEditorContent) {
                        logClientError(
                            "EditorJS already initialized, skipping...",
                            {
                                component: "useLongFormEditor",
                                action: "loadEditor",
                            },
                            "info",
                        );
                        editorInitialized.current = false; // Reset flag so it can try again if needed
                        return;
                    }

                    existingEditor.innerHTML = "";

                    // Remove any existing EditorJS classes that might interfere
                    existingEditor.className = existingEditor.className
                        .split(" ")
                        .filter((cls) => !cls.startsWith("codex-editor"))
                        .join(" ");
                }

                // Also check for any existing editor instances globally
                if (window.EditorJSInstances) {
                    window.EditorJSInstances.forEach((instance) => {
                        try {
                            if (instance.destroy) instance.destroy();
                        } catch (e) {
                            /* ignore cleanup errors */
                        }
                    });
                    window.EditorJSInstances = [];
                } else {
                    window.EditorJSInstances = [];
                }

                const EditorJS = (await import("@editorjs/editorjs")).default;

                // Add a small delay to ensure DOM is fully ready
                await new Promise((resolve) => setTimeout(resolve, 100));

                // Create tools configuration
                const tools = await createEditorJSToolsConfig(uploadProvider);

                const editorInstance = new EditorJS({
                    holder: "editorjs",
                    minHeight: 300,
                    tools: tools as unknown as Record<string, { class: unknown; config?: Record<string, unknown>; inlineToolbar?: boolean }>,
                    data: undefined, // Initial data will be loaded separately
                    onChange: (async (api: EditorJSAPI) => {
                        try {
                            const outputData = await api.saver.save();
                            onContentChange(JSON.stringify(outputData));
                        } catch (error) {
                            const { handleErrorSafely } = await import("~/lib/error-handler.client");
                            handleErrorSafely(error, {
                                component: "useLongFormEditor",
                                action: "onChange",
                            });
                        }
                    }) as unknown as (api: EditorJSAPI) => void,
                }) as EditorJSInstance;

                // Store the editor reference and add to global tracking
                editorRef.current = editorInstance;
                window.EditorJSInstances.push(editorInstance);

                // Initialize custom drag and drop functionality after editor is ready
                void (async () => {
                    try {
                        await editorRef.current.isReady;
                        if (!editorRef.current) return;
                        const editorElement = document.getElementById("editorjs");
                        if (editorElement) {
                            const dragObserver = setupCustomDragDrop(
                                editorRef as unknown as React.RefObject<EditorJSInstance>,
                                editorElement,
                                onContentChange,
                                disableCaptionsFn,
                            );
                            editorRef.current._dragObserver = dragObserver;
                        }
                        setEditorReady(true);
                    } catch (error) {
                        logClientError(
                            error instanceof Error ? error : new Error(String(error)),
                            {
                                component: "useLongFormEditor",
                                action: "initializeDragDrop",
                            },
                            "warning",
                        );
                    }
                })();

                // Run caption disabling immediately and on editor changes
                setTimeout(disableCaptionsFn, 100);

                // Set up a mutation observer to remove captions whenever they appear
                const editorElement = document.getElementById("editorjs");
                if (editorElement) {
                    const captionObserver = setupCaptionObserver(editorElement, disableCaptionsFn);
                    editorRef.current._captionObserver = captionObserver;
                }
            }
        };

        void loadEditor();

        return () => {
            if (editorRef.current) {
                try {
                    // Clean up mutation observers
                    if (editorRef.current._captionObserver) {
                        editorRef.current._captionObserver.disconnect();
                    }
                    if (editorRef.current._dragObserver) {
                        editorRef.current._dragObserver.disconnect();
                    }

                    // Destroy the editor instance
                    if (editorRef.current.destroy) {
                        editorRef.current.destroy();
                    }
                } catch (error) {
                    logClientError(
                        error instanceof Error ? error : new Error(String(error)),
                        {
                            component: "useLongFormEditor",
                            action: "cleanup",
                            message: "Error during editor cleanup",
                        },
                        "warning",
                    );
                } finally {
                    editorRef.current = null;
                    editorInitialized.current = false;
                    setEditorReady(false);

                    // Remove from global tracking
                    if (window.EditorJSInstances) {
                        window.EditorJSInstances = window.EditorJSInstances.filter(
                            (instance) => instance !== editorRef.current,
                        );
                    }

                    // Also clear the DOM container to prevent issues
                    const editorContainer = document.getElementById("editorjs");
                    if (editorContainer) {
                        editorContainer.innerHTML = "";

                        // Remove any EditorJS classes
                        editorContainer.className = editorContainer.className
                            .split(" ")
                            .filter((cls) => !cls.startsWith("codex-editor"))
                            .join(" ");
                    }
                }
            }
        };
    }, [uploadProvider, onContentChange, disableCaptionsFn]);

    // Load initial content when editor is ready
    const loadInitialData = useCallback(async (content: string) => {
        if (editorReady && editorRef.current && content) {
            await loadEditorJSContent(editorRef, content, onContentChange);
        }
    }, [editorReady, onContentChange]);

    // Insert assets into the editor
    const insertAssetIntoEditor = useCallback(async (selectedAssets: {
        assetType: string;
        fileUrl?: string;
        content?: string;
        title?: string;
    }[]) => {
        await insertAssetsIntoEditor(editorRef, selectedAssets, onContentChange);
    }, [onContentChange]);

    // Generate summary from editor content
    const generateSummaryFromContent = useCallback((content: string) => {
        return generateSummary(content);
    }, []);

    return {
        editorRef,
        editorReady,
        loadInitialData,
        insertAssetIntoEditor,
        generateSummaryFromContent,
    };
}

import { useState, useCallback } from "react";
interface QueueType {
    id?: string;
    name: string;
    color?: string | null;
    hashtags?: string | null;
    scheduleType?: string;
    isEnabled?: boolean;
}

interface UseLongFormSchedulingOptions {
    queueTypes: (string | QueueType)[];
    scheduleIntervals: number[];
    userTags: string;
    userTimezone: string;
    initialQueueType?: string;
    onQueueTypeChange?: (name: string) => void;
}

export function useLongFormScheduling({
    queueTypes,
    scheduleIntervals,
    userTags,
    userTimezone,
    initialQueueType = "Unassigned",
    onQueueTypeChange,
}: UseLongFormSchedulingOptions) {
    const [selectedQueueType, setSelectedQueueType] = useState(initialQueueType);
    const [scheduledFor, setScheduledFor] = useState("");
    const [displayedHashtags, setDisplayedHashtags] = useState(userTags);

    const calculateQueueScheduleTime = useCallback(async (queueTypeName: string) => {
        if (queueTypeName === "Unassigned") {
            setScheduledFor("");
            return;
        }

        // Find the queue type object to get its ID
        const selectedQueue = queueTypes.find(qt =>
            (typeof qt === "string" ? qt : qt.name) === queueTypeName
        );
        const queueTypeId = typeof selectedQueue === "object" ? selectedQueue.id : null;

        try {
            const response = await fetch("/api/queue-schedule", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                },
                body: JSON.stringify({
                    queueTypeId,
                    queueTypeName, // Keep for backward compatibility
                }),
            });

            if (response.ok) {
                const { scheduledTime } = await response.json();
                setScheduledFor(scheduledTime);
            }
        } catch (error) {
            const { handleErrorSafely } = await import("~/lib/error-handler.client");
            handleErrorSafely(error, {
                component: "useLongFormScheduling",
                action: "calculateQueueScheduleTime",
            });
        }
    }, [queueTypes]);

    const updateDisplayedHashtags = useCallback(async (queueTypeName: string) => {
        setSelectedQueueType(queueTypeName);

        // Calculate the next scheduled time when queue type changes
        if (queueTypeName !== "Unassigned") {
            await calculateQueueScheduleTime(queueTypeName);
        } else {
            setScheduledFor("");
        }

        if (queueTypeName === "Unassigned") {
            setDisplayedHashtags(userTags);
            if (onQueueTypeChange) onQueueTypeChange(queueTypeName);
            return;
        }

        try {
            const response = await fetch("/api/effective-hashtags", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                },
                body: JSON.stringify({
                    queueTypeName: queueTypeName,
                }),
            });

            if (response.ok) {
                const data = await response.json();
                setDisplayedHashtags(data.hashtags || userTags);
                if (onQueueTypeChange) onQueueTypeChange(queueTypeName);
            } else {
                setDisplayedHashtags(userTags);
            }
        } catch (error) {
            const { handleErrorSafely } = await import("~/lib/error-handler.client");
            handleErrorSafely(error, {
                component: "useLongFormScheduling",
                action: "updateDisplayedHashtags",
            });
            setDisplayedHashtags(userTags);
        }
    }, [userTags, onQueueTypeChange, calculateQueueScheduleTime]);

    const handleScheduleIntervalClick = useCallback((intervalHours: number) => {
        // Find the currently selected queue type
        const currentQueueType = queueTypes.find(qt =>
            (typeof qt === "string" ? qt : qt.name) === selectedQueueType
        );

        // If this is a fixed slot queue, use the API to get the next scheduled time instead
        if (currentQueueType && typeof currentQueueType === "object" && currentQueueType.scheduleType === "FIXED_SLOTS") {
            // For fixed slot queues, recalculate the schedule time instead of adding hours
            calculateQueueScheduleTime((currentQueueType).name);
            return;
        }

        const now = new Date();
        const hoursLater = new Date(
            now.getTime() + intervalHours * 60 * 60 * 1000,
        );

        // Format the date in the user's timezone
        const formattedDate = hoursLater.toLocaleString("en-US", {
            timeZone: userTimezone,
            year: "numeric",
            month: "2-digit",
            day: "2-digit",
            hour: "2-digit",
            minute: "2-digit",
            hour12: false,
        });

        // Parse the formatted date back into components
        const [datePart, timePart] = formattedDate.split(", ");
        const [month, day, year] = datePart.split("/");
        const [hours, minutes] = timePart.split(":");

        // Create the datetime-local format (YYYY-MM-DDTHH:mm)
        const formattedForInput = `${year}-${month}-${day}T${hours}:${minutes}`;

        setScheduledFor(formattedForInput);
    }, [queueTypes, selectedQueueType, userTimezone, calculateQueueScheduleTime]);

    return {
        selectedQueueType,
        scheduledFor,
        setScheduledFor,
        displayedHashtags,
        updateDisplayedHashtags,
        handleScheduleIntervalClick,
        calculateQueueScheduleTime,
    };
}

import { useFetcher, useRevalidator, useSearchParams } from "@remix-run/react";
import { useState, useEffect } from "react";

import type { ToastMessage } from "~/components/types";
import type { CombinedContent, PostData, LongFormPostData } from "~/features/posts/types";
import { signEventFn } from "~/lib/nostr";
import { type User } from "~/models/user.server";

interface UsePostedPostsProps {
    user: User;
    allContent: CombinedContent[];
    posts: PostData[];
}

export function usePostedPosts({ user, allContent, posts }: UsePostedPostsProps) {
    const revalidator = useRevalidator();
    const [searchParams] = useSearchParams();

    // Get current tab from URL params - default to "all"
    const currentTab = searchParams.get("tab") || "all";

    const [sortConfig, setSortConfig] = useState({
        key: "postedAt",
        direction: "desc",
    });
    const [searchTerm, setSearchTerm] = useState("");
    const [selectedPost, setSelectedPost] = useState<PostData | null>(null);
    const [selectedPosts, setSelectedPosts] = useState<Set<string>>(new Set());
    const [selectedLongFormPost, setSelectedLongFormPost] = useState<LongFormPostData | null>(null);
    const [toast, setToast] = useState<ToastMessage | null>(null);

    const deleteFetcher = useFetcher<{ success?: boolean; error?: string }>();
    const bulkDeleteFetcher = useFetcher<{ success?: boolean; error?: string }>();
    const repostFetcher = useFetcher<{
        repostData?: PostData[];
        scheduledRepostData?: PostData[];
        quotePostData?: {
            caption: string;
            fileUrl: string;
            queueType: string;
            scheduledFor: string;
            originalPostId: string;
            originalEventId?: string;
            originalEventPubkey?: string;
            isQuotePost?: boolean;
            originalCaption?: string;
        }[];
        longformQuotePostData?: {
            caption: string;
            fileUrl: string;
            queueType: string;
            scheduledFor: string;
            originalPostId: string;
            originalEventId?: string;
            originalEventPubkey?: string;
            isQuotePost?: boolean;
            originalCaption?: string;
        }[];
    }>();
    const individualRepostFetcher = useFetcher<{
        repostEventData?: {
            kind: number;
            content: string;
            tags: string[][];
            created_at: number;
        };
        quotePostData?: {
            caption: string;
            fileUrl: string;
            queueType: string;
            scheduledFor: string;
            originalPostId: string;
            originalEventId?: string;
            originalEventPubkey?: string;
            isQuotePost?: boolean;
            originalCaption?: string;
        }[];
        originalPost?: PostData;
        error?: string;
        message?: string;
    }>();
    const longformRepostFetcher = useFetcher<{
        longformRepostEventData?: {
            kind: number;
            content: string;
            tags: string[][];
            created_at: number;
        };
        originalPost?: LongFormPostData;
        error?: string;
        message?: string;
    }>();
    const longformQuoteFetcher = useFetcher<{
        longformQuotePostData?: {
            caption: string;
            fileUrl: string;
            queueType: string;
            scheduledFor: string;
            originalPostId: string;
            originalEventId?: string;
            originalEventPubkey?: string;
            isQuotePost?: boolean;
            originalCaption?: string;
        }[];
        error?: string;
        message?: string;
    }>();

    const requestSort = (key: string) => {
        setSortConfig((current) => ({
            key,
            direction:
                current.key === key && current.direction === "asc" ? "desc" : "asc",
        }));
    };

    const togglePostSelection = (postId: string) => {
        setSelectedPosts((prev) => {
            const newSet = new Set(prev);
            if (newSet.has(postId)) {
                newSet.delete(postId);
            } else {
                newSet.add(postId);
            }
            return newSet;
        });
    };

    const toggleSelectAll = (filteredPosts: PostData[] | CombinedContent[]) => {
        if (selectedPosts.size === filteredPosts.length) {
            setSelectedPosts(new Set());
        } else {
            setSelectedPosts(new Set(filteredPosts.map((post) => post.id)));
        }
    };

    const handleBulkDelete = () => {
        if (selectedPosts.size === 0) return;

        // For All tab, we need to handle mixed content types
        if (currentTab === "all") {
            const selectedItems = allContent
                .filter((item) => selectedPosts.has(item.id))
                .map((item) => ({ id: item.id, type: item.type }));

            const formData = new FormData();
            formData.append("_action", "bulkDeleteMixed");
            formData.append("itemData", JSON.stringify(selectedItems));

            bulkDeleteFetcher.submit(formData, { method: "post" });
        } else {
            // For individual tabs, use the original handlers
            const formData = new FormData();
            formData.append(
                "_action",
                currentTab === "longform" ? "bulkDeleteLongForm" : "bulkDelete",
            );
            formData.append("postIds", JSON.stringify(Array.from(selectedPosts)));

            bulkDeleteFetcher.submit(formData, { method: "post" });
        }
    };

    const handleBulkRepost = () => {
        if (selectedPosts.size === 0) return;

        if (currentTab === "all") {
            // For All tab, only process regular posts (longform doesn't support bulk repost)
            const selectedItems = allContent.filter(
                (item) => selectedPosts.has(item.id) && item.type === "post",
            );

            if (selectedItems.length === 0) {
                alert("No regular posts selected for recycling.");
                return;
            }

            const formData = new FormData();
            formData.append("_action", "bulkRepost");
            formData.append(
                "postIds",
                JSON.stringify(selectedItems.map((item) => item.id)),
            );

            repostFetcher.submit(formData, { method: "post" });
        } else {
            const formData = new FormData();
            formData.append("_action", "bulkRepost");
            formData.append("postIds", JSON.stringify(Array.from(selectedPosts)));

            repostFetcher.submit(formData, { method: "post" });
        }
    };

    const handleBulkScheduledRepost = () => {
        if (selectedPosts.size === 0) return;

        if (currentTab === "all") {
            // For All tab, only process regular posts
            const selectedItems = allContent.filter(
                (item) => selectedPosts.has(item.id) && item.type === "post",
            );

            if (selectedItems.length === 0) {
                alert("No regular posts selected for reposting.");
                return;
            }

            const formData = new FormData();
            formData.append("_action", "bulkScheduledRepost");
            formData.append(
                "postIds",
                JSON.stringify(selectedItems.map((item) => item.id)),
            );

            repostFetcher.submit(formData, { method: "post" });
        } else {
            const formData = new FormData();
            formData.append("_action", "bulkScheduledRepost");
            formData.append("postIds", JSON.stringify(Array.from(selectedPosts)));

            repostFetcher.submit(formData, { method: "post" });
        }
    };

    const handleBulkQuote = () => {
        if (selectedPosts.size === 0) return;

        if (currentTab === "all") {
            // For All tab, only process regular posts
            const selectedItems = allContent.filter(
                (item) => selectedPosts.has(item.id) && item.type === "post",
            );

            if (selectedItems.length === 0) {
                alert("No regular posts selected for quote posting.");
                return;
            }

            const formData = new FormData();
            formData.append("_action", "bulkQuote");
            formData.append(
                "postIds",
                JSON.stringify(selectedItems.map((item) => item.id)),
            );

            repostFetcher.submit(formData, { method: "post" });
        } else {
            const formData = new FormData();
            formData.append("_action", "bulkQuote");
            formData.append("postIds", JSON.stringify(Array.from(selectedPosts)));

            repostFetcher.submit(formData, { method: "post" });
        }
    };

    useEffect(() => {
        if (bulkDeleteFetcher.data?.success) {
            setSelectedPosts(new Set());
        }
    }, [bulkDeleteFetcher.data]);

    useEffect(() => {
        if (repostFetcher.data?.repostData) {
            const postsData = repostFetcher.data.repostData;

            // Prepare repost data with 1 hour default scheduling
            const now = new Date();
            const userTimezone = user?.timezone ?? "UTC";
            const localDate = new Date(
                now.toLocaleString("en-US", { timeZone: userTimezone }),
            );
            localDate.setHours(localDate.getHours() + 1);

            const repostData = postsData.map((post, index: number) => {
                const scheduleDate = new Date(localDate);
                scheduleDate.setHours(scheduleDate.getHours() + index);

                return {
                    caption: post.caption || "",
                    fileUrl:
                        post.fileUrl &&
                            Array.isArray(post.fileUrl) &&
                            post.fileUrl.length > 0
                            ? post.fileUrl[0]
                            : "",
                    queueType: post.queueType || "unassigned",
                    scheduledFor: scheduleDate
                        .toLocaleString("en-US", {
                            year: "numeric",
                            month: "2-digit",
                            day: "2-digit",
                            hour: "2-digit",
                            minute: "2-digit",
                            hour12: false,
                        })
                        .replace(/(\d+)\/(\d+)\/(\d+),\s(\d+):(\d+)/, "$3-$1-$2T$4:$5"),
                };
            });

            // Store repost data in sessionStorage
            sessionStorage.setItem("repostData", JSON.stringify(repostData));

            // Navigate to bulk posts page
            window.location.href = "/dashboard/bulkposts?mode=recycle";

            // Clear selection
            setSelectedPosts(new Set());
        }

        if (repostFetcher.data?.scheduledRepostData) {
            const postsData = repostFetcher.data.scheduledRepostData;

            // Prepare scheduled repost data with 1 hour default scheduling
            const now = new Date();
            const userTimezone = user?.timezone ?? "UTC";
            const localDate = new Date(
                now.toLocaleString("en-US", { timeZone: userTimezone }),
            );
            localDate.setHours(localDate.getHours() + 1);

            const scheduledRepostData = postsData.map((post, index: number) => {
                const scheduleDate = new Date(localDate);
                scheduleDate.setHours(scheduleDate.getHours() + index);

                return {
                    caption: "", // Empty content for kind 6 reposts
                    fileUrl: "", // No file URL for kind 6 reposts
                    queueType: post.queueType || "unassigned",
                    scheduledFor: scheduleDate
                        .toLocaleString("en-US", {
                            year: "numeric",
                            month: "2-digit",
                            day: "2-digit",
                            hour: "2-digit",
                            minute: "2-digit",
                            hour12: false,
                        })
                        .replace(/(\d+)\/(\d+)\/(\d+),\s(\d+):(\d+)/, "$3-$1-$2T$4:$5"),
                    originalPostId: post.id,
                    originalEventId: post.signedEvent?.id,
                    originalEventPubkey: post.signedEvent?.pubkey,
                    isKind6Repost: true,
                };
            });

            // Store scheduled repost data in sessionStorage
            sessionStorage.setItem(
                "scheduledRepostData",
                JSON.stringify(scheduledRepostData),
            );

            // Navigate to bulk posts page with repost mode
            window.location.href = "/dashboard/bulkposts?mode=repost";

            // Clear selection
            setSelectedPosts(new Set());
        }

        if (repostFetcher.data?.quotePostData) {
            const quoteData = repostFetcher.data.quotePostData;

            // Store quote post data in sessionStorage
            sessionStorage.setItem("quotePostData", JSON.stringify(quoteData));

            // Navigate to bulk posts page with quote mode
            window.location.href = "/dashboard/bulkposts?mode=quote";

            // Clear selection
            setSelectedPosts(new Set());
        }

        if (repostFetcher.data?.longformQuotePostData) {
            const quoteData = repostFetcher.data.longformQuotePostData;

            // Store longform quote post data in sessionStorage
            sessionStorage.setItem("quotePostData", JSON.stringify(quoteData));

            // Navigate to bulk posts page with quote mode
            window.location.href = "/dashboard/bulkposts?mode=quote";

            // Clear selection
            setSelectedPosts(new Set());
        }
    }, [repostFetcher.data, user?.timezone]);

    // Handle longform repost responses
    useEffect(() => {
        const handleLongformRepost = async () => {
            if (longformRepostFetcher.data?.longformRepostEventData) {
                try {
                    const eventData = longformRepostFetcher.data.longformRepostEventData;
                    const originalPost = longformRepostFetcher.data.originalPost;

                    // Sign the event using client-side signing
                    const { signedEvent } = await signEventFn(eventData);

                    // Get user relays from user data
                    const sanitizedRelays = user.userRelays || ["wss://relay.primal.net"];

                    // Publish the signed event
                    const response = await fetch("/api/publish", {
                        method: "POST",
                        headers: {
                            "Content-Type": "application/json",
                        },
                        body: JSON.stringify({
                            relays: sanitizedRelays,
                            event: signedEvent,
                        }),
                    });

                    if (!response.ok) {
                        throw new Error("Failed to publish longform repost");
                    }

                    // Show success toast
                    setTimeout(() => {
                        setToast({
                            type: "success",
                            message: "Article reposted successfully!",
                            link: `https://primal.net/a/${originalPost?.nostrEventId || originalPost?.signedEvent?.id || ""}`,
                            linkText: "View Original Article",
                        });

                        // Hide toast after 8 seconds
                        setTimeout(() => setToast(null), 8000);
                    }, 1000);
                } catch (error: unknown) {
                    const { handleAsyncError, getErrorMessage } = await import("~/lib/error-handler.client");
                    handleAsyncError(error, {
                        component: "usePostedPosts",
                        action: "handleLongformRepost",
                    }, false); // Don't show toast, we set toast state instead
                    setToast({
                        type: "error",
                        message: getErrorMessage(error) || "Failed to sign or publish longform repost",
                    });

                    // Hide toast after 5 seconds for errors
                    setTimeout(() => setToast(null), 5000);
                }
            } else if (longformRepostFetcher.data?.error) {
                setToast({
                    type: "error",
                    message:
                        longformRepostFetcher.data.message ||
                        "Failed to create longform repost",
                });

                // Hide toast after 5 seconds for errors
                setTimeout(() => setToast(null), 5000);
            }
        };

        if (longformRepostFetcher.data) {
            handleLongformRepost();
        }
    }, [longformRepostFetcher.data, user]);

    // Handle longform quote responses
    useEffect(() => {
        if (longformQuoteFetcher.data?.longformQuotePostData) {
            const quoteData = longformQuoteFetcher.data.longformQuotePostData;

            // Store longform quote post data in sessionStorage
            sessionStorage.setItem("quotePostData", JSON.stringify(quoteData));

            // Navigate to bulk posts page with quote mode
            window.location.href = "/dashboard/bulkposts?mode=quote";
        } else if (longformQuoteFetcher.data?.error) {
            setToast({
                type: "error",
                message:
                    longformQuoteFetcher.data.message ||
                    "Failed to create longform quote post",
            });

            // Hide toast after 5 seconds for errors
            setTimeout(() => setToast(null), 5000);
        }
    }, [longformQuoteFetcher.data]);

    useEffect(() => {
        const handleRepost = async () => {
            if (individualRepostFetcher.data?.repostEventData) {
                try {
                    const eventData = individualRepostFetcher.data.repostEventData;

                    // Sign the event using client-side signing
                    const { signedEvent } = await signEventFn(eventData);

                    // Get user relays from user data
                    const sanitizedRelays = user.userRelays || ["wss://relay.primal.net"];

                    // Publish the signed event
                    const response = await fetch("/api/publish", {
                        method: "POST",
                        headers: {
                            "Content-Type": "application/json",
                        },
                        body: JSON.stringify({
                            relays: sanitizedRelays,
                            event: signedEvent,
                        }),
                    });

                    if (!response.ok) {
                        throw new Error("Failed to publish repost");
                    }

                    // Add delay before showing success toast
                    setTimeout(() => {
                        setToast({
                            type: "success",
                            message: "Post reposted successfully!",
                            link: `https://primal.net/e/${eventData.tags.find((tag: string[]) => tag[0] === "e")?.[1]}`,
                            linkText: "View Original Post",
                        });

                        // Hide toast after 8 seconds for success with link
                        setTimeout(() => setToast(null), 8000);
                    }, 1000); // 1 second delay
                } catch (error: unknown) {
                    const { handleAsyncError, getErrorMessage } = await import("~/lib/error-handler.client");
                    handleAsyncError(error, {
                        component: "usePostedPosts",
                        action: "handleRepost",
                    }, false); // Don't show toast, we set toast state instead
                    setToast({
                        type: "error",
                        message: getErrorMessage(error) || "Failed to sign or publish repost",
                    });

                    // Hide toast after 5 seconds for errors
                    setTimeout(() => setToast(null), 5000);
                }
            } else if (individualRepostFetcher.data?.quotePostData) {
                // Handle individual quote post - redirect to bulk posts with single item
                const quoteData = individualRepostFetcher.data.quotePostData;

                // Store quote post data in sessionStorage
                sessionStorage.setItem("quotePostData", JSON.stringify(quoteData));

                // Navigate to bulk posts page with quote mode
                window.location.href = "/dashboard/bulkposts?mode=quote";
            } else if (individualRepostFetcher.data?.error) {
                setToast({
                    type: "error",
                    message:
                        individualRepostFetcher.data.message || "Failed to create repost",
                });

                // Hide toast after 5 seconds for errors
                setTimeout(() => setToast(null), 5000);
            }
        };

        if (individualRepostFetcher.data) {
            handleRepost();
        }
    }, [individualRepostFetcher.data, user.userRelays]);

    return {
        currentTab,
        sortConfig,
        setSortConfig,
        searchTerm,
        setSearchTerm,
        selectedPost,
        setSelectedPost,
        selectedPosts,
        setSelectedPosts,
        selectedLongFormPost,
        setSelectedLongFormPost,
        toast,
        setToast,
        deleteFetcher,
        bulkDeleteFetcher,
        repostFetcher,
        individualRepostFetcher,
        longformRepostFetcher,
        longformQuoteFetcher,
        requestSort,
        togglePostSelection,
        toggleSelectAll,
        handleBulkDelete,
        handleBulkRepost,
        handleBulkScheduledRepost,
        handleBulkQuote,
    };
}

/**
 * Calendar Post Converter
 * 
 * Utility functions to convert PostData and LongFormPostData to CalendarPost format
 */

import type { CalendarPost } from "~/features/posts/components/Calendar/PostBlock.types";
import type { PostData, LongFormPostData } from "~/features/posts/types";
/**
 * Convert PostData to CalendarPost
 */
export function postDataToCalendarPost(post: PostData): CalendarPost {
  return {
    ...post,
    scheduledFor: post.scheduledFor || null,
    postedAt: post.postedAt || null,
    publishedAt: ("publishedAt" in post ? post.publishedAt : null) || null,
    queueType: post.queueType || null,
    manual_override: post.manual_override ?? false,
  } as CalendarPost;
}

/**
 * Convert LongFormPostData to CalendarPost
 */
export function longFormPostDataToCalendarPost(post: LongFormPostData): CalendarPost {
  return {
    id: post.id,
    userId: post.userId,
    caption: post.content || null,
    fileUrl: null,
    hashtags: post.tags?.join(" ") || null,
    isScheduled: post.isScheduled ?? false,
    isPosted: post.isPublished ?? false,
    draft: post.draft ?? false,
    status: post.status || "DRAFT",
    queueTypeId: post.queueTypeId || null,
    templateId: ("templateId" in post ? post.templateId : null) || null,
    createdAt: post.createdAt,
    updatedAt: post.updatedAt,
    // CalendarPost specific fields
    title: post.title || undefined,
    summary: post.summary || undefined,
    image: post.image || undefined,
    publishedAt: ("publishedAt" in post ? post.publishedAt : null) || null,
    postedAt: ("publishedAt" in post ? post.publishedAt : null) || null,
    scheduledFor: post.scheduledFor || null,
    queueType: post.queueType || null,
    manual_override: false,
    isPast: false,
  } as unknown as CalendarPost;
}

/**
 * Convert array of PostData to CalendarPost[]
 */
export function postsToCalendarPosts(posts: PostData[]): CalendarPost[] {
  return posts.map(postDataToCalendarPost);
}

/**
 * Convert array of LongFormPostData to CalendarPost[]
 */
export function longFormPostsToCalendarPosts(posts: LongFormPostData[]): CalendarPost[] {
  return posts.map(longFormPostDataToCalendarPost);
}

/**
 * Convert mixed array of PostData and LongFormPostData to CalendarPost[]
 */
export function mixedPostsToCalendarPosts(
  posts: PostData[],
  longFormPosts: LongFormPostData[],
): CalendarPost[] {
  return [
    ...posts.map(postDataToCalendarPost),
    ...longFormPosts.map(longFormPostDataToCalendarPost),
  ];
}

/**
 * Helper functions for content listing components
 */

import type { CombinedContent } from "~/features/posts/combined.server";
import { getQueueColor } from "~/features/posts/queueColors";
import { handleErrorSafely } from "~/lib/error-handler.client";

export function getImageUrls(fileUrl: string[] | undefined): string[] {
  if (!fileUrl || fileUrl.length === 0) return [];

  if (typeof fileUrl[0] === "string" && fileUrl[0].startsWith("[")) {
    try {
      return JSON.parse(fileUrl[0]) as string[];
    } catch (e) {
      handleErrorSafely(e, {
        component: "AllContentListing",
        action: "parseFileUrl",
      });
      return [];
    }
  }

  return fileUrl;
}

export function getContentTitle(item: CombinedContent): string {
  if (item.type === "longform") {
    return item.title || "Untitled Article";
  }
  return item.caption?.length && item.caption.length > 50
    ? item.caption.substring(0, 50) + "..."
    : item.caption || "No caption";
}

export function getContentPreview(item: CombinedContent): string | null {
  if (item.type === "longform") {
    return (
      item.summary ||
      (item.content?.length && item.content.length > 100
        ? item.content.substring(0, 100) + "..."
        : item.content) ||
      "No content"
    );
  }
  return null; // Posts show caption in title column
}

export function getStatusColor(item: CombinedContent): string {
  if (item.draft) {
    return "bg-orange-100 text-orange-900 dark:border-orange-900/75 dark:bg-orange-700/10 dark:text-orange-200";
  }
  if (item.isPosted || item.isPublished) {
    return "bg-green-100 text-green-900 dark:border-green-900/75 dark:bg-green-700/10 dark:text-green-200";
  }
  if (item.isScheduled) {
    return "bg-blue-100 text-blue-900 dark:border-blue-900/75 dark:bg-blue-700/10 dark:text-blue-200";
  }
  return "bg-gray-100 text-gray-900 dark:border-gray-900/75 dark:bg-gray-700/10 dark:text-gray-200";
}

export function getStatusText(item: CombinedContent): string {
  if (item.draft) return "Draft";
  if (item.isPosted || item.isPublished) return "Posted";
  if (item.isScheduled) return "Scheduled";
  return "Unknown";
}

export function formatDate(
  date: Date | string | undefined,
  isUnixTimestamp = false,
  userTimezone?: string,
): string {
  if (!date) return "-";

  let dateObj: Date;
  if (isUnixTimestamp && typeof date === "string") {
    dateObj = new Date(parseInt(date) * 1000);
  } else {
    dateObj = new Date(date);
  }

  return dateObj.toLocaleString("en-US", {
    timeZone: userTimezone || "UTC",
    month: "2-digit",
    day: "2-digit",
    year: "numeric",
    hour: "numeric",
    minute: "2-digit",
    hour12: true,
  });
}

export function getQueueTypeDisplay(
  queueType: CombinedContent["queueType"],
): { className: string; style?: React.CSSProperties; name: string } {
  const name = queueType?.name ?? "unassigned";

  if (queueType?.color) {
    return {
      className: "inline-flex rounded-full border-2 px-3 py-1 text-xs font-semibold leading-4 shadow-sm",
      style: {
        backgroundColor: `${queueType.color}20`,
        color: queueType.color,
        borderColor: queueType.color,
      },
      name,
    };
  }

  const colors = getQueueColor(name);
  return {
    className: `inline-flex rounded-full border-2 px-3 py-1 text-xs font-semibold leading-4 ${colors.bg} ${colors.text} ${colors.border} shadow-sm`,
    name,
  };
}

export function getContentTypeBadge(item: CombinedContent): {
  className: string;
  text: string;
} {
  // Check for kind property in signedEvent or originalData.signedEvent
  const kind =
    item.signedEvent?.kind ||
    item.originalData?.signedEvent?.kind;

  if (kind === 6) {
    return {
      className: "inline-flex rounded-full bg-orange-100 px-2 py-1 text-xs font-medium text-orange-800 dark:bg-orange-900 dark:text-orange-200",
      text: "REPOST",
    };
  } else if (kind === 30023) {
    return {
      className: "inline-flex rounded-full bg-purple-100 px-2 py-1 text-xs font-medium text-purple-800 dark:bg-purple-900 dark:text-purple-200",
      text: "LONG-FORM",
    };
  } else {
    // Default behavior for other types
    return {
      className: `inline-flex rounded-full px-2 py-1 text-xs font-medium ${
        item.type === "post"
          ? "bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200"
          : "bg-purple-100 text-purple-800 dark:bg-purple-900 dark:text-purple-200"
      }`,
      text: item.type === "post" ? "Post" : "Article",
    };
  }
}

/**
 * Client-side submit handler logic for editing posts
 * Extracted from EditPostModal for better separation of concerns
 */

import type { PostData, LongFormPostData, UserData, QueueType, HashTagPreset } from "~/features/posts/types";
import { uploadMultipleFiles } from "~/features/upload/upload.client";
import { signEventFn } from "~/lib/nostr";

interface EditPostSubmitParams {
  post: PostData | LongFormPostData;
  isLongform: boolean;
  caption?: string;
  title?: string;
  summary?: string;
  content?: string;
  image?: string;
  existingImages: string[];
  newFiles: File[];
  selectedHashtagPresetTags: string;
  manualHashtags: string;
  useHashtagPresets: boolean;
  selectedQueueType: string;
  selectedHashtagPresetId: string | null;
  scheduledFor: Date | null;
  user?: UserData;
}

export async function prepareEditPostSubmission({
  post,
  isLongform,
  caption,
  title,
  summary,
  content,
  image,
  existingImages,
  newFiles,
  selectedHashtagPresetTags,
  manualHashtags,
  useHashtagPresets,
  selectedQueueType,
  selectedHashtagPresetId,
  scheduledFor,
  user,
}: EditPostSubmitParams) {
  // Handle image uploads first if there are new files
  const allImageUrls = [...existingImages];
  if (newFiles.length > 0) {
    const uploadResults = await uploadMultipleFiles(newFiles);
    const failedUploads = uploadResults.filter(
      (result) => !result.success,
    );
    if (failedUploads.length > 0) {
      throw new Error(
        `Upload failed: ${failedUploads.map((r) => r.error).join(", ")}`,
      );
    }
    const newUrls = uploadResults
      .filter((result) => result.success && result.file)
      .map((result) => result.file!.url);
    allImageUrls.push(...newUrls);
  }

  let eventContent = "";
  let eventTags: string[][] = [];
  let finalHashtags = "";

  if (isLongform) {
    // Create longform event content (NIP-23)
    eventContent = content || "";
    eventTags = [
      ["d", post.id], // identifier tag
      ["title", title || ""],
      ["summary", summary || ""],
    ];
    if (image) {
      eventTags.push(["image", image]);
    }
  } else {
    // Determine final hashtags to use
    if (useHashtagPresets && selectedHashtagPresetTags) {
      finalHashtags = selectedHashtagPresetTags;
    } else {
      finalHashtags = manualHashtags;
    }

    // Create post content with images below text
    eventContent = caption || "";

    // Add image URLs to content (below the text)
    if (allImageUrls.length > 0) {
      const imageContent = allImageUrls.join("\n");
      eventContent = eventContent
        ? `${eventContent}\n\n${imageContent}`
        : imageContent;
    }

    // Add hashtags if applicable and user setting is enabled
    if (user?.showHashTagsinPosts && finalHashtags) {
      eventContent = `${eventContent}\n${finalHashtags}`;
    }

    // Parse hashtags and add as 't' tags
    if (finalHashtags) {
      const hashtagList = finalHashtags
        .split(/\s+/)
        .filter((tag) => tag.startsWith("#") && tag.length > 1);
      hashtagList.forEach((tag) => {
        eventTags.push(["t", tag.replace("#", "")]);
      });
    }
  }

  const eventKind = isLongform ? 30023 : 1;
  const eventTime = scheduledFor
    ? Math.floor(scheduledFor.getTime() / 1000)
    : Math.floor(Date.now() / 1000);

  // Re-sign the event with new content
  const { nostrEvent, signedEvent } = await signEventFn({
    content: eventContent,
    created_at: eventTime,
    kind: eventKind,
    tags: eventTags,
  });

  // Build form data
  const formData = new FormData();
  formData.append("_action", isLongform ? "editLongform" : "editPost");
  formData.append("postId", post.id);
  formData.append("signedEvent", JSON.stringify(signedEvent));
  formData.append("nostrEvent", JSON.stringify(nostrEvent));

  if (scheduledFor) {
    formData.append(
      "scheduledFor",
      Math.floor(scheduledFor.getTime() / 1000).toString(),
    );
  }

  if (isLongform) {
    formData.append("title", title || "");
    formData.append("summary", summary || "");
    formData.append("content", content || "");
    formData.append("image", image || "");
  } else {
    formData.append("caption", caption || "");
    formData.append("fileUrl", JSON.stringify(allImageUrls));
    formData.append("hashtags", finalHashtags);
    if (selectedQueueType) {
      formData.append("queueTypeId", selectedQueueType);
    }
    if (useHashtagPresets && selectedHashtagPresetId) {
      formData.append("hashTagPresetId", selectedHashtagPresetId);
    }
  }

  return formData;
}

