    },
  };
}

async function createImageUploadHandler(uploadProvider: string | null) {
  return async (file: File) => {
    try {
      logClientError(
        "Starting EditorJS image upload",
        {
          component: "createImageUploadHandler",
          action: "uploadImage",
          fileName: file.name,
          fileSize: file.size,
          uploadProvider,
        },
        "info",
      );

      // Check upload provider and use appropriate method
      if (uploadProvider && uploadProvider.includes("BLOSSOM")) {
        // Use client-side upload for Blossom
        const { uploadFile } = await import("~/features/upload/upload.client");
        const uploadResult = await uploadFile(file);

        if (uploadResult.success && uploadResult.file) {
          logClientError(
            "Blossom upload successful",
            {
              component: "createImageUploadHandler",
              action: "uploadImage",
              provider: "Blossom",
              fileUrl: uploadResult.file.url,
            },
            "info",
          );
          return {
            success: 1,
            file: {
              url: uploadResult.file.url,
              size: uploadResult.file.size || file.size,
              name: uploadResult.file.name || file.name,
              extension: uploadResult.file.extension || file.name.split(".").pop(),
            },
          };
        } else {
          const { logClientError } = await import("~/lib/error-handler.client");
          logClientError(
            new Error(uploadResult.error || "Blossom upload failed"),
            {
              component: "useLongFormEditor",
              action: "uploadImage",
              provider: "Blossom",
            },
            "warning",
          );
          throw new Error(uploadResult.error || "Blossom upload failed");
        }
      } else {
        // Use server-side upload for S3
        const formData = new FormData();
        formData.append("image", file);

        const response = await fetch(
          "/api/upload-editorjs-image",
          {
            method: "POST",
            body: formData,
          },
        );

        if (!response.ok) {
          const errorText = await response.text();
          const { logClientError } = await import("~/lib/error-handler.client");
          logClientError(
            new Error(`Server error: ${response.status}`),
            {
              component: "useLongFormEditor",
              action: "uploadImage",
              provider: "S3",
              serverResponse: errorText,
            },
            "error",
          );
          throw new Error(`Server error: ${response.status}`);
        }

        const result = (await response.json()) as {
          success?: number;
          file?: { url?: string; size?: number; name?: string; extension?: string };
          error?: string;
        };
        logClientError(
          "S3 EditorJS upload response",
          {
            component: "createImageUploadHandler",
            action: "uploadImage",
            provider: "S3",
            response: result,
          },
          "info",
        );

        if (result.success === 1 && result.file?.url) {
          logClientError(
            "S3 upload successful",
            {
              component: "createImageUploadHandler",
              action: "uploadImage",
              provider: "S3",
              fileUrl: result.file.url,
            },
            "info",
          );
          return {
            success: 1,
            file: {
              url: result.file.url,
              size: result.file.size || file.size,
              name: result.file.name || file.name,
              extension:
                result.file.extension ||
                file.name.split(".").pop(),
            },
          };
        } else {
          const { logClientError } = await import("~/lib/error-handler.client");
          logClientError(
            new Error(result.error || "Upload failed"),
            {
              component: "useLongFormEditor",
              action: "uploadImage",
              provider: "S3",
            },
            "warning",
          );
          throw new Error(result.error || "Upload failed");
        }
      }
    } catch (error) {
      const { handleAsyncError } = await import("~/lib/error-handler.client");
      handleAsyncError(error, {
        component: "useLongFormEditor",
        action: "uploadImage",
      }, false); // Don't show toast, let EditorJS handle it
      throw error;
    }
  };
}

/**
 * EditorJS content loading and manipulation utilities
 */


import type React from "react";

import type { EditorJSInstance, EditorJSBlock } from "~/features/posts/types/editorjs.types";
import { handleErrorSafely, logClientError } from "~/lib/error-handler.client";
import { convertMarkdownToEditorJS } from "~/lib/nostr";
/**
 * Load initial content into EditorJS
 */
export async function loadEditorJSContent(
  editorRef: React.RefObject<EditorJSInstance>,
  content: string,
  onContentChange: (content: string) => void,
) {
  if (!editorRef.current || !content) return;

  try {
    await editorRef.current.isReady;

    let parsedContent;

    // Try to parse as JSON first (for legacy EditorJS format)
    if (content.trim().startsWith("{")) {
      try {
        parsedContent = JSON.parse(content) as { blocks?: unknown[]; time?: number; version?: string };
        // Validate it has EditorJS structure
        if (
          !parsedContent.blocks ||
          !Array.isArray(parsedContent.blocks)
        ) {
          throw new Error("Not valid EditorJS format");
        }
      } catch (jsonError) {
        logClientError(
          jsonError instanceof Error ? jsonError : new Error(String(jsonError)),
          {
            component: "loadEditorJSContent",
            action: "parseContent",
            message: "Content is not valid EditorJS JSON, treating as markdown",
          },
          "warning",
        );
        // If JSON parsing fails, treat as markdown and convert to EditorJS
        parsedContent = convertMarkdownToEditorJS(content);
      }
    } else {
      // Content is in markdown format, convert to EditorJS
      logClientError(
        "Converting markdown content to EditorJS format",
        {
          component: "loadEditorJSContent",
          action: "convertMarkdown",
        },
        "info",
      );
      parsedContent = convertMarkdownToEditorJS(content);
    }

    await editorRef.current.render(parsedContent);
    onContentChange(JSON.stringify(parsedContent));
  } catch (error) {
    const { handleAsyncError } = await import("~/lib/error-handler.client");
    handleAsyncError(error, {
      component: "useLongFormEditor",
      action: "loadInitialData",
    }, false);
    // Fallback to empty editor if all else fails
    try {
      const emptyContent = { blocks: [] };
      await editorRef.current.render(emptyContent);
      onContentChange(JSON.stringify(emptyContent));
    } catch (fallbackError) {
      const { handleAsyncError: handleFallbackError } = await import("~/lib/error-handler.client");
      handleFallbackError(fallbackError, {
        component: "useLongFormEditor",
        action: "loadInitialDataFallback",
      }, false);
    }
  }
}

/**
 * Insert assets into the editor
 */
export async function insertAssetsIntoEditor(
  editorRef: React.RefObject<EditorJSInstance>,
  selectedAssets: {
    assetType: string;
    fileUrl?: string;
    content?: string;
    title?: string;
  }[],
  onContentChange: (content: string) => void,
) {
  if (!editorRef.current) return;

  try {
    // Wait for editor to be ready
    await editorRef.current.isReady;

    // Get current editor data and insert at current block position
    const currentData = await editorRef.current.saver.save();
    const blocks = [...currentData.blocks];

    // Try to get current block index
    let insertIndex = blocks.length; // Default to end
    try {
      const currentBlockIndex =
        editorRef.current.blocks.getCurrentBlockIndex();
      if (currentBlockIndex >= 0) {
        insertIndex = currentBlockIndex + 1; // Insert after current block
      }
    } catch (error) {
      logClientError(
        "Using default insertion position at end",
        {
          component: "insertAssetsIntoEditor",
          action: "getCurrentBlockIndex",
          error: error instanceof Error ? error.message : String(error),
        },
        "info",
      );
    }

    // Create new blocks for assets
    const newBlocks: EditorJSBlock[] = [];
    for (const asset of selectedAssets) {
      if (asset.assetType === "TEXT") {
        const textContent = asset.content || asset.title || "";
        if (textContent) {
          newBlocks.push({
            id: Math.random().toString(36).substr(2, 9),
            type: "paragraph",
            data: {
              text: textContent,
            },
          });
        }
      } else if (asset.assetType === "IMAGE") {
        newBlocks.push({
          id: Math.random().toString(36).substr(2, 9),
          type: "image",
          data: {
            file: {
              url: asset.fileUrl,
            },
            caption: "",
            withBorder: false,
            withBackground: false,
            stretched: false,
          },
        });
      }
    }

    // Insert new blocks at the determined position
    blocks.splice(insertIndex, 0, ...newBlocks);

    // Render the updated data
    const updatedData = {
      ...currentData,
      blocks: blocks,
    };

    await editorRef.current.render(updatedData);
    onContentChange(JSON.stringify(updatedData));

    // Focus editor
    setTimeout(() => {
      editorRef.current?.focus();
    }, 100);
  } catch (error) {
    const { handleAsyncError } = await import("~/lib/error-handler.client");
    handleAsyncError(error, {
      component: "useLongFormEditor",
      action: "insertAssetIntoEditor",
    }, false);
    // Fallback to simple insertion
    try {
      for (const asset of selectedAssets) {
        if (asset.assetType === "TEXT") {
          const textContent = asset.content || asset.title || "";
          if (textContent) {
            const insertResult = editorRef.current.blocks.insert("paragraph", {
              text: textContent,
            });
            if (insertResult && typeof insertResult === "object" && "then" in insertResult) {
              await insertResult;
            }
          }
        } else if (asset.assetType === "IMAGE") {
          const insertResult = editorRef.current.blocks.insert("image", {
            file: {
              url: asset.fileUrl,
            },
            caption: "",
            withBorder: false,
            withBackground: false,
            stretched: false,
          });
          if (insertResult && typeof insertResult === "object" && "then" in insertResult) {
            await insertResult;
          }
        }
      }
      const saveResult = editorRef.current.saver.save();
      const updatedData = saveResult && typeof saveResult === "object" && "then" in saveResult ? await saveResult : saveResult;
      onContentChange(JSON.stringify(updatedData));
    } catch (fallbackError) {
      const { handleAsyncError: handleFallbackError } = await import("~/lib/error-handler.client");
      handleFallbackError(fallbackError, {
        component: "useLongFormEditor",
        action: "insertAssetIntoEditorFallback",
      }, false);
    }
  }
}

/**
 * Generate summary from editor content
 */
export function generateSummaryFromContent(content: string): string {
  if (!content) return "";

  try {
    const editorData = JSON.parse(content);
    let textContent = "";

    editorData.blocks?.forEach((block: EditorJSBlock) => {
      if (block.type === "paragraph" || block.type === "header") {
        textContent += block.data.text + " ";
      } else if (block.type === "list") {
        if (Array.isArray(block.data.items)) {
          block.data.items.forEach((item: string) => {
            textContent += item + " ";
          });
        }
      }
    });

    const plainText = textContent.replace(/<[^>]*>/g, "").trim();
    const generatedSummary =
      plainText.length > 280
        ? plainText.substring(0, 280) + "..."
        : plainText;

    return generatedSummary;
  } catch (error) {
    handleErrorSafely(error, {
      component: "useLongFormEditor",
      action: "generateSummaryFromContent",
    });
    return "";
  }
}

/**
 * EditorJS drag and drop functionality
 */

import type { EditorJSBlock, EditorJSInstance } from "~/features/posts/types/editorjs.types";
export function setupCustomDragDrop(
  editorRef: React.RefObject<EditorJSInstance>,
  editorElement: HTMLElement,
  onContentChange: (content: string) => void,
  disableCaptions: () => void,
) {
  let draggedBlockIndex: number | null = null;
  let draggedBlockData: EditorJSBlock | null = null;

  const addDragHandlers = () => {
    const blocks = editorElement.querySelectorAll(".ce-block");

    blocks.forEach((block, index) => {
      const blockElement = block as HTMLElement;
      // Remove existing handlers to avoid duplicates
      blockElement.removeEventListener("dragstart", handleDragStart);
      blockElement.removeEventListener("dragend", handleDragEnd);
      blockElement.removeEventListener("dragover", handleDragOver);
      blockElement.removeEventListener("drop", handleDrop);

      // Make blocks draggable
      blockElement.draggable = true;
      blockElement.dataset.blockIndex = String(index);

      // Add drag handlers
      blockElement.addEventListener("dragstart", handleDragStart);
      blockElement.addEventListener("dragend", handleDragEnd);
      blockElement.addEventListener("dragover", handleDragOver);
      blockElement.addEventListener("drop", handleDrop);
    });
  };

  const handleDragStart = async (e: Event) => {
    const dragEvent = e as DragEvent;
    const blockElement = (dragEvent.target as HTMLElement).closest(".ce-block") as HTMLElement;
    draggedBlockIndex = parseInt(blockElement.dataset.blockIndex || "0");

    // Get block data using EditorJS API
    try {
      const currentData = await editorRef.current!.saver.save();
      draggedBlockData = currentData.blocks[draggedBlockIndex];

      dragEvent.dataTransfer!.effectAllowed = "move";
      dragEvent.dataTransfer!.setData("text/html", blockElement.outerHTML);

      blockElement.style.opacity = "0.5";
      blockElement.classList.add("dragging");
    } catch (error) {
      const { handleErrorSafely } = await import("~/lib/error-handler.client");
      handleErrorSafely(error, {
        component: "useLongFormEditor",
        action: "handleDragStart",
      });
    }
  };

  const handleDragEnd = (e: Event) => {
    const blockElement = (e.target as HTMLElement).closest(".ce-block") as HTMLElement;
    if (blockElement) {
      blockElement.style.opacity = "1";
      blockElement.classList.remove("dragging");
    }

    // Clean up
    draggedBlockIndex = null;
    draggedBlockData = null;
  };

  const handleDragOver = (e: Event) => {
    e.preventDefault();
    const dragEvent = e as DragEvent;
    dragEvent.dataTransfer!.dropEffect = "move";

    const blockElement = (dragEvent.target as HTMLElement).closest(".ce-block") as HTMLElement;
    if (blockElement && draggedBlockIndex !== null) {
      blockElement.classList.add("drag-over");
    }
  };

  const handleDrop = async (e: Event) => {
    e.preventDefault();
    e.stopPropagation();

    const dropBlockElement = (e.target as HTMLElement).closest(".ce-block") as HTMLElement;
    if (
      !dropBlockElement ||
      draggedBlockIndex === null ||
      !draggedBlockData
    )
      return;

    const dropIndex = parseInt(dropBlockElement.dataset.blockIndex || "0");

    // Don't do anything if dropping on the same position
    if (draggedBlockIndex === dropIndex) return;

    try {
      // Get current editor data
      const currentData = await editorRef.current!.saver.save();
      const blocks = [...currentData.blocks];

      // Remove the dragged block from its original position
      blocks.splice(draggedBlockIndex, 1);

      // Calculate the new insertion index
      let newIndex = dropIndex;
      if (draggedBlockIndex < dropIndex) {
        newIndex = dropIndex - 1;
      }

      // Insert the block at the new position
      blocks.splice(newIndex, 0, draggedBlockData);

      // Update the editor with the new order
      const newData = {
        ...currentData,
        blocks: blocks,
      };

      await editorRef.current!.render(newData);
      onContentChange(JSON.stringify(newData));

      const { logClientError } = await import("~/lib/error-handler.client");
      logClientError(
        `Moved block from index ${draggedBlockIndex} to ${newIndex}`,
        {
          component: "editorjs-dragdrop",
          action: "handleDrop",
          draggedBlockIndex,
          newIndex,
        },
        "info",
      );
    } catch (error) {
      const { handleErrorSafely } = await import("~/lib/error-handler.client");
      handleErrorSafely(error, {
        component: "useLongFormEditor",
        action: "handleDrop",
      });
    } finally {
      // Clean up drag state
      dropBlockElement.classList.remove("drag-over");
      document.querySelectorAll(".ce-block").forEach((block) => {
        block.classList.remove("drag-over", "dragging");
      });
    }
  };

  // Initial setup
  addDragHandlers();

  // Re-add handlers when content changes
  const dragObserver = new MutationObserver(() => {
    setTimeout(() => {
      addDragHandlers();
      // Remove captions that might have been added
      setTimeout(disableCaptions, 50);
    }, 100);
  });

  dragObserver.observe(editorElement, {
    childList: true,
    subtree: true,
  });

  return dragObserver;
}

import { useFetcher } from "@remix-run/react";
import { useEffect, useState } from "react";
interface User {
  timezone?: string | null;
}

interface SearchResultData {
  event?: {
    id: string;
    pubkey: string;
    created_at: number;
    kind: number;
    content: string;
    tags: string[][];
    mediaUrls?: string[];
  };
  stats?: {
    likes: number;
    replies: number;
    mentions: number;
    reposts: number;
    zaps: number;
    satszapped: number;
  };
  error?: string;
}

interface UseSearchStateProps {
  user: User | null;
  fetcherData: SearchResultData | null;
}

/**
 * Custom hook for managing search state and operations
 */
export function useSearchState({ user, fetcherData }: UseSearchStateProps) {
  const fetcher = useFetcher();
  const [eventInput, setEventInput] = useState("");
  const [toast, setToast] = useState<{ type: "success" | "error"; message: string } | null>(null);

  const isSearching = fetcher.state !== "idle";
  const searchResult = fetcherData?.event;
  const searchStats = fetcherData?.stats;
  const searchError = fetcherData?.error;

  useEffect(() => {
    if (searchError) {
      setToast({
        type: "error",
        message: searchError,
      });
      setTimeout(() => setToast(null), 5000);
    }
  }, [searchError]);

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    const formData = new FormData();
    formData.append("_action", "searchEvent");
    formData.append("eventInput", eventInput);
    fetcher.submit(formData, { method: "post" });
  };

  const handleScheduleQuote = () => {
    if (!searchResult) return;

    // Prepare quote post data
    const quotePostData = [
      {
        caption: "", // Empty caption - user can add content
        fileUrl: searchResult.mediaUrls?.[0] || "",
        queueType: "unassigned",
        scheduledFor: "",
        originalPostId: null, // No local post ID for external events
        originalEventId: searchResult.id,
        originalEventPubkey: searchResult.pubkey,
        isQuotePost: true,
        originalCaption: searchResult.content || "",
        isRecyclable: false,
      },
    ];

    // Store in sessionStorage
    sessionStorage.setItem("quotePostData", JSON.stringify(quotePostData));

    // Navigate to bulk posts page with quote mode
    window.location.href = "/dashboard/bulkposts?mode=quote";
  };

  const handleScheduleRepost = () => {
    if (!searchResult) return;

    // Prepare scheduled repost data (kind 6)
    const now = new Date();
    const userTimezone = user?.timezone ?? "UTC";
    const localDate = new Date(
      now.toLocaleString("en-US", { timeZone: userTimezone })
    );
    localDate.setHours(localDate.getHours() + 1);

    const scheduledRepostData = [
      {
        caption: "", // Empty content for kind 6 reposts
        fileUrl: "", // No file URL for kind 6 reposts
        queueType: "unassigned",
        scheduledFor: localDate
          .toLocaleString("en-US", {
            year: "numeric",
            month: "2-digit",
            day: "2-digit",
            hour: "2-digit",
            minute: "2-digit",
            hour12: false,
          })
          .replace(/(\d+)\/(\d+)\/(\d+),\s(\d+):(\d+)/, "$3-$1-$2T$4:$5"),
        originalPostId: null, // No local post ID for external events
        originalEventId: searchResult.id,
        originalEventPubkey: searchResult.pubkey,
        isKind6Repost: true,
        originalFileUrl: searchResult.mediaUrls || [],
        originalCaption: searchResult.content || "",
        isRecyclable: false,
      },
    ];

    // Store in sessionStorage
    sessionStorage.setItem(
      "scheduledRepostData",
      JSON.stringify(scheduledRepostData)
    );

    // Navigate to bulk posts page with repost mode
    window.location.href = "/dashboard/bulkposts?mode=repost";
  };

  const clearSearch = () => {
    setEventInput("");
    // Clear fetcher data by resetting the form
    fetcher.load("/dashboard/search/posts");
  };

  return {
    eventInput,
    toast,
    isSearching,
    searchResult,
    searchStats,
    fetcher,
    setEventInput,
    setToast,
    handleSearch,
    handleScheduleQuote,
    handleScheduleRepost,
    clearSearch,
  };
}

/**
 * Search Feature Public API
 * 
 * This module exports the public API for search-related operations.
 * Internal implementation details are kept in services/, hooks/, and components/ directories.
 * 
 * Usage:
 *   import { handleSearchAction } from "~/features/search";
 * 
 * Do NOT import from internal paths like:
 *   import { ... } from "~/features/search/services/..."  // ❌ Bad
 *   import { ... } from "~/features/search/hooks/..."      // ❌ Bad
 */

// ============================================================================
// Search Actions
// ============================================================================

export {
  handleSearchEvent as handleSearchAction,
} from "./services/search-action.server";

/**
 * Search action handlers
 * Centralized action processing for search page
 */

import { nip19 } from "nostr-tools";

import { connectToPrimalCache } from "~/features/cache/primalCache.server";
import type { NostrEvent, SignedEvent } from "~/features/nostr/types";
/**
 * Extended NostrEvent with pubkey and id (from Primal cache)
 */
type NostrEventWithMetadata = NostrEvent & {
  pubkey?: string;
  id?: string;
};

/**
 * Decode event ID from various formats (nevent1, note1, hex)
 */
function decodeEventId(eventInput: string): string {
  const eventId = eventInput.trim();

  // Check if input is in nevent1 format
  if (eventId.startsWith("nevent1")) {
    try {
      const decoded = nip19.decode(eventId);
      if (decoded.type === "nevent" && decoded.data) {
        return decoded.data.id;
      }
    } catch (e) {
      throw new Error("Invalid nevent1 format");
    }
  } else if (eventId.startsWith("nostr:nevent1")) {
    try {
      const decoded = nip19.decode(eventId.replace("nostr:", ""));
      if (decoded.type === "nevent" && decoded.data) {
        return decoded.data.id;
      }
    } catch (e) {
      throw new Error("Invalid nevent1 format");
    }
  } else if (eventId.startsWith("note1")) {
    try {
      const decoded = nip19.decode(eventId);
      if (decoded.type === "note") {
        return decoded.data;
      }
    } catch (e) {
      throw new Error("Invalid note1 format");
    }
  }

  // Validate hex format (64 character hex string)
  if (!/^[a-f0-9]{64}$/i.test(eventId)) {
    throw new Error(
      "Invalid event ID format. Must be a 64-character hex string, note1, or nevent1",
    );
  }

  return eventId;
}

/**
 * Fetch author profile information
 */
async function fetchAuthorInfo(pubkey: string): Promise<{
  name: string;
  image: string | null;
}> {
  let authorName = pubkey.substring(0, 8) + "...";
  let authorImage = null;

  try {
    const userInfoResponses = await connectToPrimalCache("user_infos", {
      pubkeys: [pubkey],
    });

    const userMetadataEvent = userInfoResponses?.find(
      (res): res is [string, string, NostrEventWithMetadata] =>
        Array.isArray(res) &&
        res[0] === "EVENT" &&
        res[2] !== undefined &&
        (res[2] as NostrEventWithMetadata).kind === 0 &&
        (res[2] as NostrEventWithMetadata).pubkey === pubkey,
    );

    if (userMetadataEvent && userMetadataEvent[2]) {
      const event = userMetadataEvent[2];
      const metadata = JSON.parse(event.content) as { name?: string; display_name?: string; picture?: string };
      authorName = metadata.name || metadata.display_name || authorName;
      authorImage = metadata.picture || null;
    }
  } catch (error) {
    console.error("[Search] Error fetching author info:", error);
  }

  return { name: authorName, image: authorImage };
}

/**
 * Fetch engagement stats for an event
 */
async function fetchEventStats(eventId: string): Promise<{
  likes: number;
  replies: number;
  mentions: number;
  reposts: number;
  zaps: number;
  satszapped: number;
}> {
  let stats = {
    likes: 0,
    replies: 0,
    mentions: 0,
    reposts: 0,
    zaps: 0,
    satszapped: 0,
  };

  try {
    const threadResponses = await connectToPrimalCache("thread_view", {
      event_id: eventId,
    });

    const statsEvent = threadResponses?.find(
      (res): res is [string, string, NostrEventWithMetadata] =>
        Array.isArray(res) &&
        res[0] === "EVENT" &&
        res[2] !== undefined &&
        (res[2] as NostrEventWithMetadata).kind === 10000100 &&
        typeof (res[2] as NostrEventWithMetadata).content === "string" &&
        (res[2] as NostrEventWithMetadata).content.includes(eventId),
    );

    if (statsEvent && statsEvent[2]) {
      const event = statsEvent[2];
      const content = JSON.parse(event.content) as {
        likes?: number;
        replies?: number;
        mentions?: number;
        reposts?: number;
        zaps?: number;
        satszapped?: number;
      };
      stats = {
        likes: content.likes || 0,
        replies: content.replies || 0,
        mentions: content.mentions || 0,
        reposts: content.reposts || 0,
        zaps: content.zaps || 0,
        satszapped: content.satszapped || 0,
      };
    }
  } catch (error) {
    // Log but continue - stats are optional
    const { logWarning } = await import("~/lib/error-logger.server");
    logWarning("Failed to fetch stats for searched event", {
      eventId,
      error: error instanceof Error ? error.message : String(error),
    });
  }

  return stats;
}

/**
 * Extract media URLs from event content
 */
function extractMediaUrls(content: string): string[] {
  const urlRegex = /(https?:\/\/[^\s]+\.(jpg|jpeg|png|gif|webp|mp4|webm|mov))/gi;
  return content.match(urlRegex) || [];
}

/**
 * Handle search event action
 */
export async function handleSearchEvent(eventInput: string) {
  if (!eventInput || eventInput.trim() === "") {
    const { ValidationError } = await import("~/lib/errors");
    throw new ValidationError("Please enter an event ID or nevent1");
  }

  // Decode event ID from various formats
  let eventId: string;
  try {
    eventId = decodeEventId(eventInput);
  } catch (error) {
    const { ValidationError } = await import("~/lib/errors");
    throw new ValidationError(
      error instanceof Error ? error.message : "Invalid event ID format",
      { input: eventInput },
    );
  }

  // Fetch event from Primal cache
  let responses: unknown;
  try {
    responses = await connectToPrimalCache("events", {
      event_ids: [eventId],
    });
  } catch (error) {
    const { ExternalServiceError } = await import("~/lib/errors");
    throw new ExternalServiceError("Failed to fetch event from cache", 502, {
      service: "PrimalCache",
      eventId,
      originalError: error instanceof Error ? error.message : String(error),
    });
  }

  // Find the EVENT response
  const eventResponse = Array.isArray(responses)
    ? responses.find(
        (res): res is [string, string, NostrEventWithMetadata] => Array.isArray(res) && res[0] === "EVENT" && res[2] !== undefined,
      )
    : null;

  if (!eventResponse || !eventResponse[2]) {
    const { NotFoundError } = await import("~/lib/errors");
    throw new NotFoundError(
      "Event not found. Please check the event ID and try again.",
      { eventId },
    );
  }

  const event = eventResponse[2];
  if (!event) {
    const { NotFoundError } = await import("~/lib/errors");
    throw new NotFoundError(
      "Event not found. Please check the event ID and try again.",
      { eventId },
    );
  }

  // Fetch author profile info and stats in parallel
  const eventPubkey = typeof event.pubkey === "string" ? event.pubkey : "";
  const eventContent = typeof event.content === "string" ? event.content : "";
  const [authorInfo, stats] = await Promise.all([
    fetchAuthorInfo(eventPubkey),
    fetchEventStats(eventId),
  ]);

  // Extract media URLs from content
  const mediaUrls = extractMediaUrls(eventContent);

  return {
    success: true,
    event: {
      id: (typeof event.id === "string" ? event.id : eventId),
      pubkey: eventPubkey,
      created_at: typeof event.created_at === "number" ? event.created_at : 0,
      kind: typeof event.kind === "number" ? event.kind : 1,
      content: eventContent,
      tags: Array.isArray(event.tags) ? event.tags : [],
      authorName: authorInfo.name,
      authorImage: authorInfo.image,
      mediaUrls,
    },
    stats,
  };
}

/**
 * Toast notification component
 */

interface ToastNotificationProps {
  message: string;
  onClose: () => void;
}

export function ToastNotification({ message, onClose }: ToastNotificationProps) {
  return (
    <div className="fixed bottom-4 right-4 rounded-lg bg-green-500 px-4 py-3 text-white shadow-lg">
      {message}
    </div>
