}

import { useFetcher, useLocation } from "@remix-run/react";
import { useState, useEffect, useRef } from "react";

import type { Asset, AssetFetcher } from "~/features/assets/types";
import type { Template, ScheduleData, TemplateFetcher } from "~/features/templates/types";
import { resizeImage } from "~/features/upload/image-resize";
import { uploadFile, uploadMultipleFiles } from "~/features/upload/upload.client";

interface UseTemplatesStateProps {
  searchTerm: string;
}

/**
 * Custom hook for managing templates/assets state and operations
 */
export function useTemplatesState({ searchTerm }: UseTemplatesStateProps) {
  const [selectedTemplate, setSelectedTemplate] = useState<Template | null>(null);
  const [activeTab, setActiveTab] = useState<"assets" | "upload">("assets");
  const [selectedAssets, setSelectedAssets] = useState<string[]>([]);
  const [searchInput, setSearchInput] = useState(searchTerm || "");
  const [bulkUploadFiles, setBulkUploadFiles] = useState<File[]>([]);
  const [showToast, setShowToast] = useState(false);
  const [toastMessage, setToastMessage] = useState("");
  const [uploadProvider, setUploadProvider] = useState<string | null>(null);
  const [singleFileUploading, setSingleFileUploading] = useState(false);
  const [bulkFileUploading, setBulkFileUploading] = useState(false);

  const textAssetFormRef = useRef<HTMLFormElement>(null);
  const imageAssetFormRef = useRef<HTMLFormElement>(null);
  const location = useLocation();

  const deleteFetcher = useFetcher();
  const scheduleFetcher: TemplateFetcher = useFetcher<{ scheduleData?: ScheduleData[] }>();
  const assetFetcher = useFetcher<{ success?: boolean; asset?: Asset; assets?: Asset[] }>() as AssetFetcher;

  // Fetch upload provider on component mount
  useEffect(() => {
    void (async () => {
      try {
        const res = await fetch("/api/user-upload-provider");
        const data = (await res.json()) as { provider?: string };
        setUploadProvider(data.provider);
      } catch (err) {
        console.error("Failed to get upload provider:", err);
      }
    })();
  }, []);

  // Check if we're on a child route (edit page)
  const isOnChildRoute = location.pathname.includes("/edit/");

  // Handle schedule data response
  useEffect(() => {
    if (scheduleFetcher.data?.scheduleData) {
      sessionStorage.setItem(
        "repostData",
        JSON.stringify(scheduleFetcher.data.scheduleData),
      );
      window.location.href = "/dashboard/bulkposts?mode=recycle";
    }
  }, [scheduleFetcher.data]);

  // Handle successful asset creation
  useEffect(() => {
    if (assetFetcher.data?.success) {
      if (assetFetcher.data.asset) {
        setToastMessage(
          `${assetFetcher.data.asset.assetType.toLowerCase()} asset created successfully!`,
        );
      } else if (assetFetcher.data.assets) {
        setToastMessage(
          `${assetFetcher.data.assets.length} image assets uploaded successfully!`,
        );
      } else {
        setToastMessage("Asset created successfully!");
      }
      setShowToast(true);

      if (textAssetFormRef.current) {
        textAssetFormRef.current.reset();
      }
      if (imageAssetFormRef.current) {
        imageAssetFormRef.current.reset();
      }

      setBulkUploadFiles([]);
      setTimeout(() => setShowToast(false), 3000);
      window.location.reload();
    }
  }, [assetFetcher.data]);

  // Asset management handlers
  const handleAssetSelect = (assetId: string) => {
    setSelectedAssets((prev) =>
      prev.includes(assetId)
        ? prev.filter((id) => id !== assetId)
        : [...prev, assetId],
    );
  };

  const handleSelectAllAssets = (assets: Asset[]) => {
    if (selectedAssets.length === assets.length) {
      setSelectedAssets([]);
    } else {
      setSelectedAssets(assets.map((asset) => asset.id));
    }
  };

  const handleBulkPostAssets = (assets: Asset[]) => {
    if (selectedAssets.length === 0) return;

    const selectedAssetData = assets.filter((asset) =>
      selectedAssets.includes(asset.id),
    );

    const assetData = selectedAssetData.map((asset) => ({
      caption: asset.assetType === "TEXT" ? asset.content : asset.title || "",
      fileUrl:
        asset.assetType === "IMAGE" || asset.assetType === "VIDEO"
          ? asset.fileUrl
          : null,
      queueType: "unassigned",
      scheduledFor: new Date(Date.now() + 60 * 60 * 1000)
        .toISOString()
        .slice(0, 16),
    }));

    sessionStorage.setItem("repostData", JSON.stringify(assetData));
    window.location.href = "/dashboard/bulkposts?mode=recycle";
  };

  const handleBulkDeleteAssets = () => {
    if (selectedAssets.length === 0) return;

    if (
      !confirm(
        `Are you sure you want to delete ${selectedAssets.length} selected asset${selectedAssets.length > 1 ? "s" : ""}?`,
      )
    ) {
      return;
    }

    const formData = new FormData();
    formData.append("_action", "bulk_delete_assets");
    selectedAssets.forEach((assetId) => {
      formData.append("assetIds", assetId);
    });

    deleteFetcher.submit(formData, { method: "post" });
    setSelectedAssets([]);
  };

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    const url = new URL(window.location.href);
    if (searchInput.trim()) {
      url.searchParams.set("search", searchInput.trim());
    } else {
      url.searchParams.delete("search");
    }
    url.searchParams.delete("page");
    window.location.href = url.toString();
  };

  const handlePageChange = (newPage: number) => {
    setSelectedAssets([]);
    const url = new URL(window.location.href);
    if (newPage === 1) {
      url.searchParams.delete("page");
    } else {
      url.searchParams.set("page", newPage.toString());
    }
    window.location.href = url.toString();
  };

  const handleDeleteAsset = (e: React.MouseEvent<HTMLButtonElement>, assetId: string) => {
    if (!confirm("Are you sure you want to delete this asset?")) {
      e.preventDefault();
    }
  };

  // Upload handlers
  const handleSingleFileUpload = async (
    e: React.FormEvent,
    form: HTMLFormElement,
  ) => {
    e.preventDefault();
    setSingleFileUploading(true);

    try {
      const formData = new FormData(form);
      const fileInput = form.querySelector(
        'input[type="file"]',
      ) as HTMLInputElement;
      const file = fileInput?.files?.[0];

      if (!file) {
        throw new Error("No file selected");
      }

      const processedFile = file.type.startsWith("image/")
        ? await resizeImage(file)
        : file;

      const uploadResult = await uploadFile(processedFile);

      if (!uploadResult.success) {
        throw new Error(uploadResult.error || "Upload failed");
      }

      const serverFormData = new FormData();
      serverFormData.append("_action", formData.get("_action") as string);
      serverFormData.append("title", formData.get("title") as string);
      serverFormData.append("tags", formData.get("tags") as string);
      serverFormData.append("uploadResult", JSON.stringify(uploadResult));

      assetFetcher.submit(serverFormData, { method: "post" });
    } catch (error: unknown) {
      console.error("Upload error:", error);
      const errorMessage = error instanceof Error ? error.message : "Unknown error";
      setToastMessage(`Upload failed: ${errorMessage}`);
      setShowToast(true);
      setTimeout(() => setShowToast(false), 3000);
    } finally {
      setSingleFileUploading(false);
    }
  };

  const handleBulkFileUpload = async () => {
    if (bulkUploadFiles.length === 0) return;

    setBulkFileUploading(true);

    try {
      const uploadResults = await uploadMultipleFiles(bulkUploadFiles);

      const failedUploads = uploadResults.filter((result) => !result.success);
      if (failedUploads.length > 0) {
        const errorMessages = failedUploads
          .map((result) => result.error)
          .join(", ");
        throw new Error(`Upload failed: ${errorMessages}`);
      }

      const bulkForm = document.querySelector(
        "form[data-bulk-form]",
      ) as HTMLFormElement;
      if (!bulkForm) throw new Error("Bulk form not found");

      const formData = new FormData(bulkForm);
      const serverFormData = new FormData();
      serverFormData.append("_action", "bulk_create_media_assets");
      serverFormData.append("uploadResults", JSON.stringify(uploadResults));

      const titles = formData.getAll("titles");
      const tags = formData.getAll("tags");
      titles.forEach((title) =>
        serverFormData.append("titles", title as string),
      );
      tags.forEach((tag) => serverFormData.append("tags", tag as string));

      assetFetcher.submit(serverFormData, { method: "post" });
    } catch (error: unknown) {
      console.error("Bulk upload error:", error);
      const errorMessage = error instanceof Error ? error.message : "Unknown error";
      setToastMessage(`Bulk upload failed: ${errorMessage}`);
      setShowToast(true);
      setTimeout(() => setShowToast(false), 3000);
    } finally {
      setBulkFileUploading(false);
    }
  };

  const handleBulkFileChange = async (
    e: React.ChangeEvent<HTMLInputElement>,
  ) => {
    if (e.target.files) {
      const selectedFiles = Array.from(e.target.files);

      try {
        const processedFiles = await Promise.all(
          selectedFiles.map(async (file) => {
            if (file.type.startsWith("image/")) {
              return await resizeImage(file);
            }
            return file;
          }),
        );
        setBulkUploadFiles(processedFiles);
      } catch (error) {
        console.error("Error processing media files:", error);
        setBulkUploadFiles(selectedFiles);
      }
    }
  };

  return {
    selectedTemplate,
    activeTab,
    selectedAssets,
    searchInput,
    bulkUploadFiles,
    showToast,
    toastMessage,
    uploadProvider,
    singleFileUploading,
    bulkFileUploading,
    textAssetFormRef,
    imageAssetFormRef,
    isOnChildRoute,
    deleteFetcher,
    scheduleFetcher,
    assetFetcher,
    setSelectedTemplate,
    setActiveTab,
    setSearchInput,
    handleAssetSelect,
    handleSelectAllAssets,
    handleBulkPostAssets,
    handleBulkDeleteAssets,
    handleSearch,
    handlePageChange,
    handleDeleteAsset,
    handleSingleFileUpload,
    handleBulkFileUpload,
    handleBulkFileChange,
  };
}

/**
 * Templates Feature Public API
 * 
 * This module exports the public API for template-related operations.
 * Internal implementation details are kept in services/, hooks/, and components/ directories.
 * 
 * Usage:
 *   import { loadTemplatesData, handleTemplateAction } from "~/features/templates";
 * 
 * Do NOT import from internal paths like:
 *   import { ... } from "~/features/templates/services/..."  // ❌ Bad
 *   import { ... } from "~/features/templates/hooks/..."    // ❌ Bad
 */

// ============================================================================
// Types
// ============================================================================

export type {
  Template,
} from "./types";

// ============================================================================
// Template Services
// ============================================================================

export {
  loadTemplatesData,
} from "./services/templates-loader.server";

export {
  handleTemplatesAction,
} from "./services/templates-action.server";

/**
 * Template edit service layer
 * Handles template editing operations
 */

import { json, redirect } from "@remix-run/node";

import { ValidationError } from "~/lib/errors";
import {
  getTemplateById,
  updateTemplate,
  deleteTemplate,
  removePostFromTemplate,
} from "~/models/template.server";

/**
 * Load template data for editing
 */
export async function loadTemplateEditData(templateId: string, userId: string) {
  if (!templateId) {
    throw new ValidationError("Template ID is required");
  }

  const template = await getTemplateById({ id: templateId, userId });

  if (!template) {
    throw new ValidationError("Template not found", { templateId, userId });
  }

  return { template };
}

/**
 * Handle template edit actions
 */
export async function handleTemplateEditAction(
  formData: FormData,
  templateId: string,
  userId: string,
) {
  if (!templateId) {
    throw new ValidationError("Template ID is required");
  }

  const _action = formData.get("_action");

  if (_action === "updateName") {
    const name = formData.get("name");
    if (!name || typeof name !== "string") {
      return json({ error: "Template name is required" }, { status: 400 });
    }

    await updateTemplate({
      id: templateId,
      userId,
      name,
    });

    return json({ success: true });
  }

  if (_action === "removePost") {
    const postId = formData.get("postId");
    if (!postId || typeof postId !== "string") {
      return json({ error: "Post ID is required" }, { status: 400 });
    }

    await removePostFromTemplate({
      templateId,
      postId,
      userId,
    });

    return json({ success: true });
  }

  if (_action === "delete") {
    await deleteTemplate({
      id: templateId,
      userId,
    });

    return json({ success: true });
  }

  if (_action === "deleteTemplate") {
    await deleteTemplate({ id: templateId, userId });
    return redirect("/dashboard/templates");
  }

  if (_action === "schedule") {
    const template = await getTemplateById({ id: templateId, userId });

    if (!template) {
      return json({ error: "Template not found" }, { status: 404 });
    }

    // Prepare template data for scheduling (similar to repost mode)
    const localDate = new Date();
    localDate.setHours(localDate.getHours() + 1);

    const templateData = template.posts.map((post, index) => {
      const scheduleDate = new Date(localDate);
      scheduleDate.setHours(scheduleDate.getHours() + index);

      return {
        caption: post.caption || "",
        fileUrl: post.fileUrl,
        queueType: post.queueTypeId || "unassigned",
        scheduledFor: scheduleDate
          .toLocaleString("en-US", {
            year: "numeric",
            month: "2-digit",
            day: "2-digit",
            hour: "2-digit",
            minute: "2-digit",
            hour12: false,
          })
          .replace(/(\d+)\/(\d+)\/(\d+),\s(\d+):(\d+)/, "$3-$1-$2T$4:$5"),
      };
    });

    return json({ scheduleData: templateData });
  }

  return json({ error: "Invalid action" }, { status: 400 });
}

/**
 * Templates action handlers
 * Centralized action processing for templates page
 */

import { AssetType } from "@prisma/client";

import {
  createAsset,
  deleteAsset,
} from "~/models/asset.server";
import { deleteTemplate, getTemplates } from "~/models/template.server";

export async function handleTemplatesAction(
  formData: FormData,
  userId: string,
) {
  const _action = formData.get("_action");

  if (_action === "delete") {
    const templateId = formData.get("templateId");
    await deleteTemplate({ id: templateId as string, userId });
    return { success: true };
  }

  if (_action === "delete_asset") {
    const assetId = formData.get("assetId");
    await deleteAsset({ id: assetId as string, userId });
    return { success: true };
  }

  if (_action === "create_text_asset") {
    const title = formData.get("title") as string;
    const content = formData.get("content") as string;
    const tagsString = formData.get("tags") as string;
    const tags = tagsString
      ? tagsString
          .split(",")
          .map((tag) => tag.trim())
          .filter(Boolean)
      : [];

    const asset = await createAsset({
      userId,
      title,
      content,
      tags,
      assetType: AssetType.TEXT,
    });

    return { success: true, asset };
  }

  if (
    _action === "create_image_asset" ||
    _action === "create_video_asset" ||
    _action === "create_media_asset"
  ) {
    const title = formData.get("title") as string;
    const uploadResultRaw = formData.get("uploadResult");
    const uploadResultParsed = typeof uploadResultRaw === "string" ? JSON.parse(uploadResultRaw) : null;

    if (!uploadResultParsed || typeof uploadResultParsed !== "object" || Array.isArray(uploadResultParsed)) {
      return { error: "Invalid upload result format" };
    }

    const uploadResult = uploadResultParsed as { success?: unknown; file?: { url?: string; mimeType?: string } };

    const tagsString = formData.get("tags") as string;
    const tags = tagsString
      ? tagsString
          .split(",")
          .map((tag) => tag.trim())
          .filter(Boolean)
      : [];

    if (!uploadResult.success || !uploadResult.file?.url) {
      return { error: "No file uploaded or upload failed" };
    }

    const fileUrl = uploadResult.file.url;
    if (typeof fileUrl !== "string") {
      return { error: "Invalid file URL" };
    }

    // Determine asset type based on file URL extension or mime type
    let assetType: typeof AssetType.IMAGE | typeof AssetType.VIDEO = AssetType.IMAGE;
    const mimeType = typeof uploadResult.file.mimeType === "string" ? uploadResult.file.mimeType : "";
    const lower = fileUrl.toLowerCase();
    const videoExtensions = [
      ".mp4",
      ".webm",
      ".ogg",
      ".mov",
      ".avi",
      ".mkv",
      ".m4v",
    ];

    if (
      mimeType.startsWith("video/") ||
      videoExtensions.some((ext) => lower.includes(ext))
    ) {
      assetType = AssetType.VIDEO;
    }

    const asset = await createAsset({
      userId,
      title,
      fileUrl,
      tags,
      assetType,
    });

    return { success: true, asset };
  }

  if (
    _action === "bulk_create_image_assets" ||
    _action === "bulk_create_media_assets"
  ) {
    const uploadResultsRaw = formData.get("uploadResults");
    const uploadResultsParsed = typeof uploadResultsRaw === "string" ? JSON.parse(uploadResultsRaw) : null;

    if (!Array.isArray(uploadResultsParsed)) {
      return { error: "Invalid upload results format" };
    }

    const uploadResults = uploadResultsParsed as { success?: unknown; file?: { url?: string; mimeType?: string } | undefined; error?: string }[];
    const titles = formData.getAll("titles") as string[];
    const tagsInputs = formData.getAll("tags") as string[];

    if (uploadResults.length === 0) {
      return { error: "No files uploaded" };
    }

    // Check for failed uploads
    const failedUploads = uploadResults.filter(
      (result) => !result.success,
    );
    if (failedUploads.length > 0) {
      return { error: "Some uploads failed" };
    }

    const assets = await Promise.all(
      uploadResults.map(async (uploadResult, index: number) => {
        if (!uploadResult.file?.url) {
          throw new Error("File upload failed");
        }
        const fileUrl = uploadResult.file.url;
        if (typeof fileUrl !== "string") {
          throw new Error("Invalid file URL");
        }
        const mimeType = typeof uploadResult.file.mimeType === "string" ? uploadResult.file.mimeType : "";

        // Determine asset type based on file URL extension or mime type
        let assetType: typeof AssetType.IMAGE | typeof AssetType.VIDEO = AssetType.IMAGE;
        const lower = fileUrl.toLowerCase();
        const videoExtensions = [
          ".mp4",
          ".webm",
          ".ogg",
          ".mov",
          ".avi",
          ".mkv",
          ".m4v",
        ];

        if (
          mimeType.startsWith("video/") ||
          videoExtensions.some((ext) => lower.includes(ext))
        ) {
          assetType = AssetType.VIDEO;
        }

        const title =
          titles[index] ||
          `${assetType === AssetType.VIDEO ? "Video" : "Image"} ${index + 1}`;
        const tagsString = tagsInputs[index] || "";
        const tags = tagsString
          ? tagsString
              .split(",")
              .map((tag) => tag.trim())
              .filter(Boolean)
          : [];

        return createAsset({
          userId,
          title,
          fileUrl,
          tags,
          assetType,
        });
      }),
    );

    return { success: true, assets };
  }

  if (_action === "bulk_delete_assets") {
    const assetIds = formData.getAll("assetIds") as string[];

    if (assetIds.length === 0) {
      return { error: "No assets selected for deletion" };
    }

    await Promise.all(
      assetIds.map((assetId) => deleteAsset({ id: assetId, userId })),
    );

    return { success: true, deletedCount: assetIds.length };
  }

  if (_action === "schedule") {
    const templateId = formData.get("templateId");
    const templates = await getTemplates({ userId });
    const template = templates.find((t) => t.id === templateId);

    if (!template) {
      return { error: "Template not found" };
    }

    // Prepare template data for scheduling
    const localDate = new Date();
    localDate.setHours(localDate.getHours() + 1);

    const templateData = template.posts.map((post, index) => {
      const scheduleDate = new Date(localDate);
      scheduleDate.setHours(scheduleDate.getHours() + index);

      return {
        caption: post.caption || "",
        fileUrl: post.fileUrl,
        queueType: post.queueTypeId || "unassigned",
        scheduledFor: scheduleDate
          .toLocaleString("en-US", {
            year: "numeric",
            month: "2-digit",
            day: "2-digit",
            hour: "2-digit",
            minute: "2-digit",
            hour12: false,
          })
          .replace(/(\d+)\/(\d+)\/(\d+),\s(\d+):(\d+)/, "$3-$1-$2T$4:$5"),
      };
    });

    return { scheduleData: templateData };
  }

  return { error: "Invalid action" };
}

import { useState, useCallback, useRef } from "react";

import { Button } from "~/components/ui/button";
interface SmartUploadButtonProps {
  onUploadStart?: () => void;
  onUploadProgress?: (progress: number) => void;
  onUploadComplete?: (fileUrl: string, provider: string) => void;
  onUploadError?: (error: string) => void;
  accept?: string;
  multiple?: boolean;
  children?: React.ReactNode;
  className?: string;
  disabled?: boolean;
}

interface UploadProvider {
  provider: "S3" | "BLOSSOM_PRIMAL" | "BLOSSOM_BLOSSTR";
  isUsingBlossom: boolean;
}

export function SmartUploadButton({
  onUploadStart,
  onUploadProgress,
  onUploadComplete,
  onUploadError,
  accept = "image/*",
  multiple = false,
  children = "Upload File",
  className,
  disabled = false,
}: SmartUploadButtonProps) {
  const [uploading, setUploading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const checkUploadProvider = async (): Promise<UploadProvider> => {
    try {
      const response = await fetch("/api/user-upload-provider");
      if (!response.ok) throw new Error("Failed to check provider");
      const data = await response.json() as { provider?: string };

      // Handle legacy BLOSSOM value as BLOSSOM_PRIMAL
      if (data.provider === "BLOSSOM" || data.provider === "BLOSSOM_PRIMAL") {
        return { provider: "BLOSSOM_PRIMAL", isUsingBlossom: true };
      }
      if (data.provider === "BLOSSOM_BLOSSTR") {
        return { provider: "BLOSSOM_BLOSSTR", isUsingBlossom: true };
      }
      return { provider: "S3", isUsingBlossom: false };
    } catch (error) {
      const { handleErrorSafely } = await import("~/lib/error-handler.client");
      handleErrorSafely(error, {
        component: "SmartUploadButton",
        action: "checkUploadProvider",
      });
      return { provider: "S3", isUsingBlossom: false };
    }
  };

  const uploadToS3 = async (file: File): Promise<string> => {
    const formData = new FormData();
    formData.append("file", file);

    const response = await fetch("/api/upload", {
      method: "POST",
      body: formData,
    });

    if (!response.ok) {
      const error = (await response.json()) as { error?: string };
      throw new Error(error.error || "Upload failed");
    }

    const result = (await response.json()) as { fileUrl?: string };
    if (!result.fileUrl) {
      throw new Error("Upload failed: No file URL returned");
    }
    return result.fileUrl;
  };

  const uploadToBlossom = useCallback(async (
    file: File,
    provider: "BLOSSOM_PRIMAL" | "BLOSSOM_BLOSSTR",
  ): Promise<string> => {
    try {
      // Check if NOSTR extension is available
      if (!window.nostr) {
        throw new Error(
          "NOSTR extension not found. Please install Alby, Amber, or another NOSTR extension to upload to Blossom.",
        );
      }

      onUploadProgress?.(10); // Starting auth

      // Note: Blossom uploads now handled by upload.client.ts utility
      throw new Error(
        "Direct blossom uploads not supported in SmartUploadButton. Use upload.client.ts instead.",
      );
    } catch (error) {
      const { handleAsyncError } = await import("~/lib/error-handler.client");
      handleAsyncError(error, {
        component: "SmartUploadButton",
        action: "uploadToBlossom",
      }, false); // Don't show toast, throw to caller
      throw error;
    }
  }, [onUploadProgress]);

  const handleFileUpload = useCallback(
    async (file: File) => {
      setUploading(true);
      onUploadStart?.();

      try {
        onUploadProgress?.(5); // Starting

        // Check which provider the user has selected
        const providerInfo = await checkUploadProvider();

        onUploadProgress?.(10); // Provider checked

        let fileUrl: string;

        if (providerInfo.isUsingBlossom) {
          if (
            providerInfo.provider === "BLOSSOM_PRIMAL" ||
            providerInfo.provider === "BLOSSOM_BLOSSTR"
          ) {
            fileUrl = await uploadToBlossom(file, providerInfo.provider);
          } else {
            throw new Error("Unknown Blossom provider");
          }
        } else {
          fileUrl = await uploadToS3(file);
        }

        onUploadProgress?.(100); // Complete
        onUploadComplete?.(fileUrl, providerInfo.provider);
      } catch (error) {
        console.error("Upload error:", error);
        const errorMessage =
          error instanceof Error ? error.message : "Upload failed";
        onUploadError?.(errorMessage);
      } finally {
        setUploading(false);
        onUploadProgress?.(0);

        // Reset file input
        if (fileInputRef.current) {
          fileInputRef.current.value = "";
        }
      }
    },
    [onUploadStart, onUploadProgress, onUploadComplete, onUploadError, uploadToBlossom],
  );

  const handleFileSelect = useCallback(
    (event: React.ChangeEvent<HTMLInputElement>) => {
      const files = event.target.files;
      if (!files || files.length === 0) return;

      if (multiple) {
        // Handle multiple files
        Array.from(files).forEach((file) => handleFileUpload(file));
      } else {
        // Handle single file
        handleFileUpload(files[0]);
      }
    },
    [handleFileUpload, multiple],
  );

  const handleButtonClick = useCallback(() => {
    fileInputRef.current?.click();
  }, []);

  return (
    <>
      <input
        ref={fileInputRef}
        type="file"
        accept={accept}
        multiple={multiple}
        onChange={handleFileSelect}
        style={{ display: "none" }}
      />
      <Button
        onClick={handleButtonClick}
        disabled={disabled || uploading}
        className={className}
      >
        {uploading ? (
          <>
            <svg
              className="-ml-1 mr-3 h-4 w-4 animate-spin"
              xmlns="http://www.w3.org/2000/svg"
              fill="none"
              viewBox="0 0 24 24"
            >
              <circle
                className="opacity-25"
                cx="12"
                cy="12"
                r="10"
                stroke="currentColor"
                strokeWidth="4"
              ></circle>
              <path
                className="opacity-75"
                fill="currentColor"
                d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
              ></path>
            </svg>
            Uploading...
          </>
        ) : (
          children
        )}
      </Button>
    </>
  );
}

export default SmartUploadButton;

import { S3Client, PutObjectCommand } from "@aws-sdk/client-s3";
import {
  unstable_composeUploadHandlers as composeUploadHandlers,
  unstable_createMemoryUploadHandler as createMemoryUploadHandler,
} from "@remix-run/node";
import { v4 as uuidv4 } from "uuid";

import { logError } from "~/lib/error-logger.server";

type UploadStream = AsyncIterable<Uint8Array>;

const uploadStreamToS3 = async (
  stream: UploadStream,
  key: string,
  s3Client: S3Client,
): Promise<string> => {
  // Convert stream to buffer
  const chunks = [];
  for await (const chunk of stream) {
    chunks.push(typeof chunk === "string" ? Buffer.from(chunk) : chunk);
  }
  const buffer = Buffer.concat(chunks);

  const params = {
    Bucket: process.env.STORAGE_BUCKET,
    Key: key,
    Body: buffer,
  };

  try {
    const command = new PutObjectCommand(params);
    await s3Client.send(command);
    // Construct the URL manually since v3 doesn't return Location
    return `https://${process.env.STORAGE_BUCKET}.s3.${process.env.STORAGE_REGION}.amazonaws.com/${key}`;
  } catch (error) {
    logError(error instanceof Error ? error : new Error(String(error)), {
      key,
      bucket: process.env.STORAGE_BUCKET,
      message: "S3 upload error",
    });
    throw error;
  }
};

export function createUploadHandler(userId: string) {
  return composeUploadHandlers(
    async ({ name, filename, contentType, data }) => {
      // if (name !== "STLFileURL" && name !== "additionalFilesURLs") {
      //   return undefined;
      // }

      // Skip if no filename is provided
      if (!filename) {
        return undefined;
      }

      try {
        const ext = filename.split(".").pop()?.toLowerCase() ?? "";
        const uniqueFilename = `${uuidv4()}.${ext}`;
        const key = `clients/${userId}/${uniqueFilename}`;

        const s3Client = new S3Client({
          credentials: {
            accessKeyId: process.env.STORAGE_ACCESS_KEY!,
            secretAccessKey: process.env.STORAGE_SECRET!,
          },
          region: process.env.STORAGE_REGION!,
        });

        const uploadedFileLocation = await uploadStreamToS3(
          data,
          key,
          s3Client,
        );

        return uploadedFileLocation;
      } catch (error) {
        logError(error instanceof Error ? error : new Error(String(error)), {
          userId,
          filename,
          message: "Upload handler error",
        });
        throw error;
      }
    },
    createMemoryUploadHandler({
      maxPartSize: 100 * 1024 * 1024,
    }),
  );
}

// Upload a buffer directly to S3 (useful for processed files)
export function uploadBufferToS3(
  buffer: Buffer,
  userId: string,
  filename?: string,
  customKey?: string,
): Promise<string> {
  // Generate filename if not provided
  let finalFilename: string;
  if (filename) {
    const ext = filename.split(".").pop()?.toLowerCase() || "jpg";
    finalFilename = `${Date.now()}-${Math.random().toString(36).substring(2)}.${ext}`;
  } else {
    finalFilename = `${Date.now()}-${Math.random().toString(36).substring(2)}.jpg`;
  }

  // Use custom key or generate default one
  const key = customKey || `clients/${userId}/${finalFilename}`;

  try {
    const s3Client = createS3Client();

    const command = new PutObjectCommand({
      Bucket: process.env.STORAGE_BUCKET,
      Key: key,
      Body: buffer,
    });

    await s3Client.send(command);

    // Return the full URL
    const bucket = process.env.STORAGE_BUCKET ?? "";
    const region = process.env.STORAGE_REGION ?? "";
    return `https://${bucket}.s3.${region}.amazonaws.com/${key}`;
  } catch (error) {
    logError(error instanceof Error ? error : new Error(String(error)), {
      userId,
      filename: finalFilename,
      key,
      message: "S3 buffer upload error",
    });
    throw error;
  }
}

// Create S3 client with credentials
export function createS3Client() {
  return new S3Client({
    region: process.env.STORAGE_REGION!,
    credentials: {
      accessKeyId: process.env.STORAGE_ACCESS_KEY!,
      secretAccessKey: process.env.STORAGE_SECRET!,
    },
  });
}

// Specialized function for EditorJS image uploads
export function uploadEditorJSImage(
  buffer: Buffer,
  userId: string,
  filename: string,
): Promise<string> {
  try {
    // Generate a unique filename with timestamp and random string
    const ext = filename.split(".").pop()?.toLowerCase() || "jpg";
    const uniqueFilename = `editorjs-${Date.now()}-${Math.random().toString(36).substring(2, 8)}.${ext}`;
    const key = `clients/${userId}/editorjs/${uniqueFilename}`;

    const s3Client = createS3Client();

    const command = new PutObjectCommand({
      Bucket: process.env.STORAGE_BUCKET,
      Key: key,
      Body: buffer,
      ContentType: `image/${ext === "jpg" ? "jpeg" : ext}`,
      // Add cache control for better performance
      CacheControl: "public, max-age=31536000",
    });

    await s3Client.send(command);

    // Return the full URL
    const bucket = process.env.STORAGE_BUCKET ?? "";
    const region = process.env.STORAGE_REGION ?? "";
    const imageUrl = `https://${bucket}.s3.${region}.amazonaws.com/${key}`;

    return imageUrl;
  } catch (error) {
    logError(error instanceof Error ? error : new Error(String(error)), {
      userId,
      filename,
      message: "EditorJS S3 upload error",
    });
    throw new Error(`Failed to upload image: ${error instanceof Error ? error.message : String(error)}`);
  }
}

// Type declaration for window.nostr
import type { NostrEventData, SignedEvent } from "~/features/nostr/types";
declare global {
  interface Window {
    nostr?: {
      getPublicKey(): Promise<string>;
