interface UploadResult {
  success: boolean;
  file?: {
    url: string;
    size: number;
    name: string;
    extension: string;
    sha256?: string;
    mimeType?: string;
    provider: "S3" | "BLOSSOM_PRIMAL" | "BLOSSOM_BLOSSTR";
  };
  error?: string;
}

/**
 * Upload a file using the user's preferred upload provider (S3 or Blossom)
 * This function handles client-side uploads and server-side processing
 */
export async function uploadFile(file: File): Promise<UploadResult> {
  try {
    // First, check what upload provider the user prefers
    const response = await fetch("/api/user-upload-provider");
    if (!response.ok) {
      throw new Error("Failed to get upload provider");
    }

    const data = (await response.json()) as {
      provider?: string;
      enableMirrorBlossom?: boolean;
      mirrorUploadUrls?: string[];
    };
    const uploadProvider = data.provider;
    const enableMirrorBlossom = data.enableMirrorBlossom;
    const mirrorUploadUrls = data.mirrorUploadUrls;

    if (
      uploadProvider === "BLOSSOM_PRIMAL" ||
      uploadProvider === "BLOSSOM_BLOSSTR" ||
      uploadProvider === "BLOSSOM"
    ) {
      return await uploadFileToBlossom(
        file,
        uploadProvider,
        enableMirrorBlossom,
        mirrorUploadUrls,
      );
    } else {
      return await uploadFileToS3(file);
    }
  } catch (error) {
    const { handleAsyncError, getErrorMessage } = await import("~/lib/error-handler.client");
    handleAsyncError(error, {
      component: "upload.client",
      action: "uploadFile",
    }, false); // Don't show toast, return error instead
    return {
      success: false,
      error: getErrorMessage(error) || "Upload failed",
    };
  }
}

/**
 * Upload file to S3 via server-side processing
 */
async function uploadFileToS3(file: File): Promise<UploadResult> {
  const formData = new FormData();
  formData.append("file", file);

  const response = await fetch("/api/upload", {
    method: "POST",
    body: formData,
  });

  const result = (await response.json()) as {
    success?: boolean;
    fileUrl?: string;
    error?: string;
  };

  if (result.success && result.fileUrl) {
    return {
      success: true,
      file: {
        url: result.fileUrl,
        size: file.size,
        name: file.name,
        extension: file.name.split(".").pop() || "",
        provider: "S3" as const,
      },
    };
  } else {
    return {
      success: false,
      error: result.error || "S3 upload failed",
    };
  }
}

/**
 * Upload file to Blossom via client-side processing
 */
async function uploadFileToBlossom(
  file: File,
  provider = "BLOSSOM_PRIMAL",
  enableMirrorBlossom = false,
  mirrorUploadUrls: string[] = [],
): Promise<UploadResult> {
  try {
    // Check if NOSTR is available
    if (!window.nostr) {
      throw new Error(
        "NOSTR extension not available. Please install a NOSTR browser extension like Alby, Amber, or nos2x.",
      );
    }

    // Dynamic import to avoid SSR issues
    const { BlossomUploader } = await import("@nostrify/nostrify/uploaders");

    // Determine primary server based on provider
    let primaryServerUrl;
    if (provider === "BLOSSOM_BLOSSTR") {
      primaryServerUrl = "https://blosstr.com";
    } else {
      // Default to Primal for BLOSSOM_PRIMAL or legacy BLOSSOM
      primaryServerUrl = "https://blossom.primal.net";
    }

    // Build servers array starting with primary server
    const servers = [primaryServerUrl];

    // Add mirror URLs if enabled and available
    if (
      enableMirrorBlossom &&
      Array.isArray(mirrorUploadUrls) &&
      mirrorUploadUrls.length > 0
    ) {
      servers.push(...mirrorUploadUrls);
    }

    // Create uploader with NOSTR signer and all servers
    const uploader = new BlossomUploader({
      servers: servers,
      signer: window.nostr,
    });

    // Upload the file
    const tags = await uploader.upload(file);

    // Validate that we got the expected tag format
    if (!Array.isArray(tags)) {
      throw new Error(
        "BlossomUploader returned invalid format - expected array of tags",
      );
    }

    // Send the result to server for processing
    const response = await fetch("/api/upload-blossom", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        tags,
        fileName: file.name,
      }),
    });

    const result = (await response.json()) as {
      success?: boolean;
      file?: { url: string };
      error?: string;
    };

    if (result.success && result.file) {
      return {
        success: true,
        file: result.file,
      };
    } else {
      return {
        success: false,
        error: result.error || "Blossom upload failed",
      };
    }
  } catch (error) {
    const { handleAsyncError, getErrorMessage } = await import("~/lib/error-handler.client");
    handleAsyncError(error, {
      component: "upload.client",
      action: "uploadFileToBlossom",
      provider,
    }, false); // Don't show toast, return error instead
    return {
      success: false,
      error: getErrorMessage(error) || "Blossom upload failed",
    };
  }
}

/**
 * Upload multiple files
 */
export async function uploadMultipleFiles(
  files: File[],
): Promise<UploadResult[]> {
  const uploadPromises = files.map((file) => uploadFile(file));
  return Promise.all(uploadPromises);
}

/**
 * Upload file for EditorJS image tool compatibility
 * This specifically uses the EditorJS endpoint which handles image processing
 */
export async function uploadEditorJSImage(
  file: File,
): Promise<{ success: number; file?: { url: string } }> {
  try {
    const formData = new FormData();
    formData.append("image", file);

    const response = await fetch("/api/upload-editorjs-image", {
      method: "POST",
      body: formData,
    });

    const result = (await response.json()) as {
      success?: number;
      file?: { url: string };
      error?: { message?: string };
    };

    if (result.success === 1 && result.file) {
      return {
        success: 1,
        file: {
          url: result.file.url,
        },
      };
    } else {
      const { logClientError } = await import("~/lib/error-handler.client");
      logClientError(
        new Error(result.error?.message ?? "EditorJS upload failed"),
        {
          component: "upload.client",
          action: "uploadEditorJSImage",
        },
        "warning",
      );
      return {
        success: 0,
        // EditorJS expects no error property in success response
      };
    }
  } catch (error) {
    const { handleAsyncError } = await import("~/lib/error-handler.client");
    handleAsyncError(error, {
      component: "upload.client",
      action: "uploadEditorJSImage",
    }, false); // Don't show toast, return error code instead
    return {
      success: 0,
    };
  }
}

import { useNavigate } from "@remix-run/react";
import { useState, useCallback } from "react";
import { toast } from "react-hot-toast";
interface UploadProvider {
  provider: "S3" | "BLOSSOM_PRIMAL" | "BLOSSOM_BLOSSTR";
  isUsingBlossom: boolean;
  enableMirrorBlossom?: boolean;
  mirrorUploadUrls?: string[];
}

interface SubmitOptions {
  method: string;
  encType?: string;
  action?: string;
}

export function useBlossomAwareUpload() {
  const [isUploading, setIsUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [response, setResponse] = useState(null);
  const [error, setError] = useState<string | null>(null);
  const navigate = useNavigate();

  const checkUploadProvider = async (): Promise<UploadProvider> => {
    try {
      const response = await fetch("/api/user-upload-provider");
      if (!response.ok) throw new Error("Failed to check provider");
      const data = (await response.json()) as {
        provider?: string;
        enableMirrorBlossom?: boolean;
        mirrorUploadUrls?: string[];
      };

      const {
        provider,
        enableMirrorBlossom = false,
        mirrorUploadUrls = [],
      } = data;

      // Handle legacy BLOSSOM value as BLOSSOM_PRIMAL
      if (provider === "BLOSSOM" || provider === "BLOSSOM_PRIMAL") {
        return {
          provider: "BLOSSOM_PRIMAL",
          isUsingBlossom: true,
          enableMirrorBlossom,
          mirrorUploadUrls,
        };
      }
      if (provider === "BLOSSOM_BLOSSTR") {
        return {
          provider: "BLOSSOM_BLOSSTR",
          isUsingBlossom: true,
          enableMirrorBlossom,
          mirrorUploadUrls,
        };
      }
      return {
        provider: "S3",
        isUsingBlossom: false,
        enableMirrorBlossom: false,
        mirrorUploadUrls: [],
      };
    } catch (error) {
      console.error("Failed to check upload provider:", error);
      return {
        provider: "S3",
        isUsingBlossom: false,
        enableMirrorBlossom: false,
        mirrorUploadUrls: [],
      };
    }
  };

  const createBlossomAuthHeaders = async (
    provider: "BLOSSOM_PRIMAL" | "BLOSSOM_BLOSSTR",
  ) => {
    if (!window.nostr) {
      throw new Error(
        "NOSTR extension not found. Please install Alby, Amber, or another NOSTR extension to upload to Blossom.",
      );
    }

    let uploadUrl: string;
    if (provider === "BLOSSOM_PRIMAL") {
      uploadUrl = "https://blossom.primal.net/upload";
    } else if (provider === "BLOSSOM_BLOSSTR") {
      uploadUrl = "https://blosstr.com/upload";
    } else {
      throw new Error("Invalid blossom provider");
    }

    // Note: Authentication should be handled by the upload service directly
    throw new Error(
      "Blossom auth not implemented in useBlossomAwareUpload. Use upload.client.ts instead.",
    );
  };

  const submitForm = useCallback(
    async (formData: FormData, options: SubmitOptions) => {
      setIsUploading(true);
      setUploadProgress(10);
      setError(null);

      try {
        // Check upload provider
        const providerInfo = await checkUploadProvider();
        setUploadProgress(20);

        let headers: Record<string, string> = {};

        // If using any Blossom provider, create auth headers and show progress
        if (providerInfo.isUsingBlossom) {
          setUploadProgress(30);
          const providerName =
            providerInfo.provider === "BLOSSOM_PRIMAL" ? "Primal" : "Blosstr";

          // Log mirror configuration if enabled
          if (
            providerInfo.enableMirrorBlossom &&
            providerInfo.mirrorUploadUrls?.length
          ) {
            // Mirror configuration is active
          }

          toast.loading(
            `Signing upload request with NOSTR extension for ${providerName}...`,
            {
              id: "blossom-auth",
            },
          );
          try {
            headers = await createBlossomAuthHeaders(
              providerInfo.provider as "BLOSSOM_PRIMAL" | "BLOSSOM_BLOSSTR",
            );
            toast.success("Upload authorized!", { id: "blossom-auth" });
            setUploadProgress(60);
          } catch (authError: unknown) {
            const errorMessage = authError instanceof Error ? authError.message : String(authError);
            toast.error("Failed to authorize upload: " + errorMessage, {
              id: "blossom-auth",
            });
            throw authError;
          }
        }

        setUploadProgress(70);

        // Get the action URL (default to current page)
        const actionUrl = options.action || window.location.pathname;

        // Make the request with custom headers for Blossom Primal
        const fetchResponse = await fetch(actionUrl, {
          method: options.method,
          body: formData,
          headers: {
            ...headers,
            // Don't set Content-Type for FormData, let the browser set it
          },
        });

        setUploadProgress(90);

        if (!fetchResponse.ok) {
          let errorData: { error?: string };
          try {
            errorData = (await fetchResponse.json()) as { error?: string };
          } catch {
            // If response is not JSON, try to get text
            const errorText = await fetchResponse
              .text()
              .catch(() => `HTTP ${fetchResponse.status}`);
            errorData = {
              error: errorText.includes("<!DOCTYPE")
                ? `HTTP ${fetchResponse.status}`
                : errorText,
            };
          }
          throw new Error(errorData.error || "Upload failed");
        }

        let result;
        const responseText = await fetchResponse.text();

        try {
          // Try to parse as JSON first
          result = JSON.parse(responseText) as Record<string, unknown>;
        } catch (_parseError: unknown) {
          // If response is HTML (redirect or error page), handle gracefully
          if (
            responseText.includes("<!DOCTYPE") ||
            responseText.includes("<html")
          ) {
            if (
              responseText.includes("success") ||
              responseText.includes("uploaded") ||
              fetchResponse.status === 200
            ) {
              result = {
                success: true,
                redirect: true,
                message:
                  "Upload completed, but received HTML response instead of JSON",
              };
            } else {
              result = {
                success: false,
                error: "Server returned HTML instead of expected JSON response",
              };
            }
          } else {
            const parseError = _parseError as Error;
            throw new Error(
              "Invalid response format: " +
              (parseError?.message ?? "Unknown error") +
              ". Response: " +
              responseText.substring(0, 100),
            );
          }
        }

        setResponse(result);
        setUploadProgress(100);

        // Handle successful response
        if (result.success !== false) {
          // Check if this was a redirect response
          if (fetchResponse.redirected || result.redirect) {
            const redirectUrl = result.redirect || fetchResponse.url;
            navigate(redirectUrl);
          }
        }

        return result;
      } catch (error: unknown) {
        const { handleAsyncError } = await import("~/lib/error-handler.client");
        const errorMessage =
          error instanceof Error ? error.message : "Upload failed";
        handleAsyncError(error, {
          component: "useBlossomAwareUpload",
          action: "submitForm",
        });
        setError(errorMessage);
        throw error;
      } finally {
        setTimeout(() => {
          setIsUploading(false);
          setUploadProgress(0);
        }, 1000);
      }
    },
    [navigate],
  );

  return {
    submitForm,
    isUploading,
    uploadProgress,
    response,
    error,
  };
}

import { Link, useFetcher } from "@remix-run/react";
import { RefreshCw } from "lucide-react";
import * as React from "react";

import { Avatar, AvatarImage, AvatarFallback } from "~/components/ui/avatar";
import { Button } from "~/components/ui/button";
import {
  Dialog,
  DialogTrigger,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "~/components/ui/dialog";
import type { NostrEvent, ProfileData } from "~/features/nostr/types";
import { useSubscription } from "~/features/payments/types";
import { hexToNpub } from "~/lib/nostr";
import { useOptionalUser } from "~/lib/remix-utils";

interface UserWithProfile {
  npub: string;
  nostrProfile?: ProfileData | null;
  [key: string]: unknown;
}

interface ChildAccount {
  npub: string;
  name?: string;
  displayName?: string;
  picture?: string;
}

function displayLabel(user: UserWithProfile | null | undefined): string {
  try {
    let p: ProfileData | null | undefined;
    if (typeof user?.nostrProfile === "string") {
      const parsed: unknown = JSON.parse(user.nostrProfile);
      p = parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed as ProfileData : null;
    } else {
      p = user?.nostrProfile;
    }
    const name = p && typeof p === "object" && "name" in p && typeof p.name === "string" ? p.name : undefined;
    const displayName = p && typeof p === "object" && "display_name" in p && typeof p.display_name === "string" ? p.display_name : undefined;
    return name ?? displayName ?? formatNpubShort(user?.npub);
  } catch {
    return formatNpubShort(user?.npub);
  }
}

function displayPicture(user: UserWithProfile | null | undefined): string | undefined {
  try {
    let p: ProfileData | null | undefined;
    if (typeof user?.nostrProfile === "string") {
      const parsed: unknown = JSON.parse(user.nostrProfile);
      p = parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed as ProfileData : null;
    } else {
      p = user?.nostrProfile;
    }
    const picture = p && typeof p === "object" && "picture" in p && typeof p.picture === "string" ? p.picture : undefined;
    return picture ?? undefined;
  } catch {
    return undefined;
  }
}

function formatNpubShort(hexOrNpub?: string): string {
  if (!hexOrNpub) return "";
  const np = hexOrNpub.startsWith("npub")
    ? hexOrNpub
    : hexToNpub(hexOrNpub) || hexOrNpub;
  if (!np) return "";
  if (np.length <= 20) return np; // already short
  return `${np.slice(0, 8)}...${np.slice(-8)}`;
}

export default function AccountSwitchMenu() {
  const user = useOptionalUser() as UserWithProfile | null | undefined;
  const subscription = useSubscription();
  const fetcher = useFetcher<{ children: ChildAccount[] }>();
  const [open, setOpen] = React.useState(false);
  const [children, setChildren] = React.useState<ChildAccount[]>([]);

  // Safely handle potentially undefined subscription values
  const planId = (
    subscription?.currentSubscription?.planId ?? ""
  )?.toString?.().toLowerCase?.() ?? "";
  const planName = (
    subscription?.currentSubscription?.Plan?.name ?? ""
  )?.toString?.().toLowerCase?.() ?? "";
  const isChild = !!user?.isChild;
  const parentNpub = user?.parentNpub as string | undefined;
  const hasAccountsAccess =
    !isChild &&
    (planId === "premium" || planName === "premium" || planName === "founder");

  React.useEffect(() => {
    if (
      open &&
      hasAccountsAccess &&
      fetcher.state === "idle" &&
      !fetcher.data
    ) {
      fetcher.load("/api/children");
    }
  }, [open, hasAccountsAccess, fetcher.state, fetcher]);

  React.useEffect(() => {
    if (fetcher.data?.children) setChildren(fetcher.data.children);
  }, [fetcher.data]);

  // Hide trigger if not parent with access and not a child with parent link
  if (!hasAccountsAccess && !(isChild && parentNpub)) return null;

  const onSwitch = async (childNpub: string) => {
    try {
      const { init } = await import("nostr-login");
      await init({
        methods: ["connect", "extension"],
        noBanner: true,
        onAuth: async () => {
          if (window.nostr) {
            const contentSign = `Switch account ${Math.random().toString(36).slice(2, 12)}`;
            const event: NostrEvent = {
              kind: 27235,
              created_at: Math.floor(Date.now() / 1000),
              tags: [],
              content: contentSign,
            };
            const signedEvent = await window.nostr.signEvent(event);
            if (signedEvent.pubkey !== childNpub) {
              // Silent no-op on mismatch
              return;
            }
            const formData = new FormData();
            formData.append("pubkey", signedEvent.pubkey);
            formData.append("signature", signedEvent.sig);
            formData.append("event", JSON.stringify(signedEvent));
            formData.append("contentSign", contentSign);
            formData.append("redirectTo", "/dashboard");
            fetcher.submit(formData, { method: "post", action: "/nostr-auth" });
          }
        },
      });
      document.dispatchEvent(new CustomEvent("nlLaunch", { detail: "switch" }));
    } catch (e) {
      // eslint-disable-next-line @typescript-eslint/no-var-requires
      const { handleErrorSafely } = require("~/lib/error-handler.client") as { handleErrorSafely: (error: unknown, context: { component: string; action: string }) => void };
      handleErrorSafely(e, {
        component: "AccountSwitchMenu",
        action: "onSwitchAccount",
      });
    }
  };

  const onSwitchParent = async () => {
    if (!parentNpub) return;
    try {
      const { init } = await import("nostr-login");
      await init({
        methods: ["connect", "extension"],
        noBanner: true,
        onAuth: async () => {
          if (window.nostr) {
            const contentSign = `Switch parent ${Math.random().toString(36).slice(2, 12)}`;
            const event: NostrEvent = {
              kind: 27235,
              created_at: Math.floor(Date.now() / 1000),
              tags: [],
              content: contentSign,
            };
            const signedEvent = await window.nostr.signEvent(event);
            if (signedEvent.pubkey !== parentNpub) {
              // Silent no-op on mismatch
              return;
            }
            const formData = new FormData();
            formData.append("pubkey", signedEvent.pubkey);
            formData.append("signature", signedEvent.sig);
            formData.append("event", JSON.stringify(signedEvent));
            formData.append("contentSign", contentSign);
            formData.append("redirectTo", "/dashboard");
            fetcher.submit(formData, { method: "post", action: "/nostr-auth" });
          }
        },
      });
      document.dispatchEvent(new CustomEvent("nlLaunch", { detail: "switch" }));
    } catch (e) {
      // eslint-disable-next-line @typescript-eslint/no-var-requires
      const { handleErrorSafely } = require("~/lib/error-handler.client") as { handleErrorSafely: (error: unknown, context: { component: string; action: string }) => void };
      handleErrorSafely(e, {
        component: "AccountSwitchMenu",
        action: "onSwitchParent",
      });
    }
  };

  const currentAvatar = displayPicture(user);
  const currentLabel = displayLabel(user);

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button variant="outline" size="sm" className="gap-2">
          <RefreshCw className="h-4 w-4" />
          <span className="hidden sm:inline">Accounts</span>
        </Button>
      </DialogTrigger>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Switch account</DialogTitle>
          <DialogDescription>
            Choose an account to switch to or manage your linked accounts.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-6">
          <div className="flex items-center gap-3 rounded-md border p-3">
            <Avatar className="h-8 w-8">
              {currentAvatar ? (
                <AvatarImage src={currentAvatar} alt={currentLabel} />
              ) : (
                <AvatarFallback>{currentLabel?.[0] || "U"}</AvatarFallback>
              )}
            </Avatar>
            <div className="min-w-0">
              <div className="truncate font-medium">{currentLabel}</div>
              <div className="truncate text-xs text-muted-foreground">
                {formatNpubShort(user?.npub)}
              </div>
              <div className="text-xs text-muted-foreground">
                Currently signed in
              </div>
            </div>
          </div>

          {hasAccountsAccess ? (
            <div>
              <div className="mb-2 text-sm font-medium">Child accounts</div>
              <div className="divide-y rounded-md border">
                {children.length === 0 ? (
                  <div className="p-3 text-sm text-muted-foreground">
                    No child accounts linked
                  </div>
                ) : (
                  children.map((c) => {
                    const label =
                      c.name ||
                      c.displayName ||
                      `${c.npub.slice(0, 8)}...${c.npub.slice(-8)}`;
                    return (
                      <div
                        key={c.npub}
                        className="flex items-center justify-between p-3"
                      >
                        <div className="flex min-w-0 items-center gap-3">
                          <Avatar className="h-7 w-7">
                            {c.picture ? (
                              <AvatarImage src={c.picture} alt={label} />
                            ) : (
                              <AvatarFallback>C</AvatarFallback>
                            )}
                          </Avatar>
                          <div className="min-w-0">
                            <div className="truncate font-medium">{label}</div>
                            <div className="truncate text-xs text-muted-foreground">
                              {formatNpubShort(c.npub)}
                            </div>
                          </div>
                        </div>
                        <Button
                          size="sm"
                          onClick={() => { void onSwitch(c.npub); }}
                          disabled={fetcher.state !== "idle"}
                        >
                          {fetcher.state !== "idle" ? "Switching..." : "Switch"}
                        </Button>
                      </div>
                    );
                  })
                )}
              </div>
            </div>
          ) : null}

          {isChild && parentNpub ? (
            <div className="rounded-md border p-3">
              <div className="mb-2 text-sm font-medium">Managed by account</div>
              <div className="flex items-center justify-between">
                <div className="min-w-0">
                  <div className="truncate text-sm">
                    {formatNpubShort(parentNpub)}
                  </div>
                </div>
                <Button
                  size="sm"
                  onClick={() => { void onSwitchParent(); }}
                  disabled={fetcher.state !== "idle"}
                >
                  {fetcher.state !== "idle"
                    ? "Switching..."
                    : "Switch to parent"}
                </Button>
              </div>
            </div>
          ) : null}

          <div className="flex justify-between">
            <Link
              to="/dashboard/settings?tab=accounts"
              className="text-sm underline underline-offset-2"
            >
              Manage accounts
            </Link>
            <Button variant="outline" size="sm" onClick={() => setOpen(false)}>
              Close
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import { useFetcher } from "@remix-run/react";
import * as React from "react";

import { Avatar, AvatarImage, AvatarFallback } from "~/components/ui/avatar";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "~/components/ui/select";
import type { NostrEventData } from "~/features/nostr/types";
import { useSubscription } from "~/features/payments/types";
import { useOptionalUser } from "~/lib/remix-utils";

interface ChildAccount {
  npub: string;
  name?: string;
  displayName?: string;
  picture?: string;
}

export default function AccountSwitcher() {
  const user = useOptionalUser();
  const subscription = useSubscription();
  const fetcher = useFetcher<{ children: ChildAccount[] }>();
  const [children, setChildren] = React.useState<ChildAccount[]>([]);

  const planId = (subscription?.currentSubscription?.planId ?? "").toLowerCase();
  const planName = (subscription?.currentSubscription?.Plan?.name ?? "").toLowerCase();
  const hasAccountsAccess = planId === "premium" || planName === "premium" || planName === "founder";
  const isChild = !!user?.isChild;

  React.useEffect(() => {
    if (!isChild && hasAccountsAccess && fetcher.state === "idle" && !fetcher.data) {
      fetcher.load("/api/children");
    }
  }, [isChild, hasAccountsAccess, fetcher.state, fetcher]);

  React.useEffect(() => {
    if (fetcher.data?.children) {
      setChildren(fetcher.data.children);
    }
  }, [fetcher.data]);

  // Hide if not allowed or no children
  if (isChild || !hasAccountsAccess || children.length === 0) return null;

  const handleSwitch = async (childNpub: string) => {
    try {
      const { init } = await import("nostr-login");
      await init({
        methods: ["connect", "extension"],
        noBanner: true,
        onAuth: async () => {
          if (window.nostr) {
            const randomKeys = () => Math.random().toString(36).slice(2, 12);
            const contentSign = `Switch account ${randomKeys()}`;
            const event: NostrEventData = {
              kind: 27235,
              created_at: Math.floor(Date.now() / 1000),
              tags: [],
              content: contentSign,
            };

            const signedEvent = await window.nostr.signEvent(event);
            if (signedEvent.pubkey !== childNpub) {
              alert("Please sign with the selected child's keys in your Nostr extension.");
              return;
            }

            const formData = new FormData();
            formData.append("pubkey", signedEvent.pubkey);
            formData.append("signature", signedEvent.sig);
            formData.append("event", JSON.stringify(signedEvent));
            formData.append("contentSign", contentSign);
            formData.append("redirectTo", "/dashboard");

            fetcher.submit(formData, { method: "post", action: "/nostr-auth" });
          }
        },
      });

      document.dispatchEvent(new CustomEvent("nlLaunch", { detail: "switch" }));
    } catch (e) {
      // eslint-disable-next-line @typescript-eslint/no-var-requires
      const { handleErrorSafely } = require("~/lib/error-handler.client");
      handleErrorSafely(e, {
        component: "AccountSwitcher",
        action: "handleAccountSwitch",
      });
    }
  };

  return (
    <div className="flex items-center">
      <Select onValueChange={(value) => handleSwitch(value)}>
        <SelectTrigger className="h-9 w-[220px] bg-white dark:bg-gray-900 text-sm">
          <SelectValue placeholder="Switch account" />
        </SelectTrigger>
        <SelectContent>
          {children.map((c) => {
            const label = c.name || c.displayName || `${c.npub.slice(0, 8)}...${c.npub.slice(-8)}`;
            return (
              <SelectItem key={c.npub} value={c.npub}>
                <div className="flex items-center gap-2">
                  <Avatar className="h-5 w-5">
                    {c.picture ? <AvatarImage src={c.picture} alt={label} /> : <AvatarFallback>C</AvatarFallback>}
                  </Avatar>
                  <span>{label}</span>
                </div>
              </SelectItem>
            );
          })}
        </SelectContent>
      </Select>
    </div>
  );
}

import { useFetcher, useRevalidator } from "@remix-run/react";
import * as React from "react";

import { Avatar, AvatarImage } from "~/components/ui/avatar";
import { Button } from "~/components/ui/button";
import { Card } from "~/components/ui/card";
import { Input } from "~/components/ui/input";
import type { ProfileData } from "~/features/nostr/types";
interface AccountInfo {
  npub: string;
  nostrProfile?: ProfileData | null;
}

interface SearchResult {
  id: string;
  npub: string;
  profileName?: string;
  profileDisplayName?: string;
  profilePicture?: string;
  isChild?: boolean;
  parentNpub?: string | null;
  pendingParentRequests?: string[];
}

function extractProfileBits(nostrProfile: ProfileData | null | undefined) {
  if (!nostrProfile)
    return {
      name: undefined,
      display_name: undefined,
      picture: undefined,
    } as const;
  try {
    if (typeof nostrProfile === "string") {
      const p = JSON.parse(nostrProfile) as { name?: string; display_name?: string; picture?: string };
      return {
        name: p?.name,
        display_name: p?.display_name,
        picture: p?.picture,
      } as const;
    }
    if (typeof nostrProfile === "object") {
      const p = nostrProfile;
      return {
        name: p?.name,
        display_name: p?.display_name,
        picture: p?.picture,
      } as const;
    }
  } catch {
    // Ignore parsing errors, return defaults
  }
  return {
    name: undefined,
    display_name: undefined,
    picture: undefined,
  } as const;
}

export function AccountsSettings({
  parentNpub,
  confirmedChildren,
  pendingChildren,
  isChild = false,
  parentUser,
}: {
  parentNpub?: string;
  confirmedChildren?: AccountInfo[];
  pendingChildren?: AccountInfo[];
  isChild?: boolean;
  parentUser?: AccountInfo | null;
}) {
  const fetcher = useFetcher<{ results?: SearchResult[]; error?: string }>();
  const [q, setQ] = React.useState("");
  const revalidator = useRevalidator();

  // Prevent duplicate submissions due to re-renders by remembering last query
  const lastSubmittedRef = React.useRef("");

  React.useEffect(() => {
    const value = q.trim();
    if (!value) {
      lastSubmittedRef.current = "";
      return;
    }
    if (lastSubmittedRef.current === value) return;

    const i = setTimeout(() => {
      lastSubmittedRef.current = value;
      fetcher.submit(
        { _action: "search_accounts", q: value },
        { method: "post" },
      );
    }, 300);

    return () => clearTimeout(i);
  }, [q, fetcher]);

  const onRequestChild = (childNpub: string) => {
    const np = (childNpub || "").trim();
    fetcher.submit(
      { _action: "request_child", childNpub: np },
      { method: "post", action: "/dashboard/settings" },
    );
  };

  // Submission state feedback
  const submittingAction = (fetcher.formData?.get("_action") as string) || undefined;
  const submittingChildNpub = (fetcher.formData?.get("childNpub") as string) || undefined;
  const isUnlinking = submittingAction === "unlink_parent" && fetcher.state !== "idle";

  React.useEffect(() => {
    if (
      (submittingAction === "unlink_parent" || submittingAction === "unlink_child" || submittingAction === "cancel_child_request") &&
      fetcher.state === "idle" &&
      (fetcher.data as { success?: boolean } | undefined)?.success
    ) {
      revalidator.revalidate();
    }
  }, [fetcher.state, fetcher.data, submittingAction, revalidator]);

  const renderAccountRow = (npub: string, nostrProfile?: ProfileData | null) => {
    const bits = extractProfileBits(nostrProfile);
    return (
      <div
        key={npub}
        className="flex items-center justify-between border-b py-2 last:border-0"
      >
        <div className="flex min-w-0 items-center gap-3">
          <Avatar className="h-8 w-8">
            {bits.picture ? (
              <AvatarImage
                src={bits.picture}
                alt={bits.name || bits.display_name || npub}
              />
            ) : null}
          </Avatar>
          <div className="min-w-0">
            <div className="truncate font-medium">
              {bits.name || bits.display_name || npub}
            </div>
            <div className="truncate text-xs text-muted-foreground">{npub}</div>
          </div>
        </div>
      </div>
    );
  };

  const results = fetcher.data?.results || [];

  if (isChild) {
    const bits = extractProfileBits(parentUser?.nostrProfile);
    const parentName =
      bits.name || bits.display_name || parentUser?.npub ?? "Parent";
    return (
      <Card className="p-4">
        <div className="mb-4">
          <h2 className="text-xl font-semibold">Accounts</h2>
          <p className="text-sm text-muted-foreground">
            This account is managed by a parent account.
          </p>
        </div>

        <div className="mb-6 flex items-center justify-between rounded-md border bg-muted/30 p-4">
          <div className="flex min-w-0 items-center gap-3">
            <Avatar className="h-10 w-10">
              {bits.picture ? (
                <AvatarImage src={bits.picture} alt={parentName} />
              ) : null}
            </Avatar>
            <div className="min-w-0">
              <div className="truncate font-medium">
                Managed by {parentName}
              </div>
              {parentUser?.npub ? (
                <div className="truncate text-xs text-muted-foreground">
                  {parentUser.npub}
                </div>
              ) : null}
            </div>
          </div>
          <Button
            size="sm"
            variant="destructive"
            disabled={isUnlinking}
            onClick={() => fetcher.submit({ _action: "unlink_parent" }, { method: "post", action: "/dashboard/settings" })}
          >
            {isUnlinking ? "Unlinking..." : "Unlink from Parent"}
          </Button>
        </div>

        <p className="text-sm text-muted-foreground">
          As a child account, you cannot search for or link child accounts.
        </p>
      </Card>
    );
  }

  return (
    <Card className="p-4">
      <div className="mb-4">
        <h2 className="text-xl font-semibold">Accounts</h2>
        <p className="text-sm text-muted-foreground">Search Nostr users by profile name and request to add them as child accounts.</p>
      </div>

      <div className="mb-6">
        <label htmlFor="accounts-search" className="mb-2 block text-sm font-medium">Search users</label>
        <Input
          id="accounts-search"
          placeholder="Search by name or npub..."
          value={q}
          onChange={(e) => setQ(e.target.value)}
        />
      </div>

      {q.trim() ? (
        <div className="mb-8">
          <h3 className="mb-2 text-sm font-medium">Search results</h3>
          <div className="divide-y rounded-md border">
            {results.length === 0 ? (
              <div className="p-3 text-sm text-muted-foreground">No results</div>
            ) : (
              results.map((r) => {
                const isSubmittingThis =
                  submittingAction === "request_child" && submittingChildNpub === r.npub && fetcher.state !== "idle";
                const disabled =
                  isSubmittingThis ||
                  r.npub === parentNpub ||
                  (r.pendingParentRequests || []).includes(parentNpub || "") ||
                  r.parentNpub === parentNpub ||
                  r.isChild === true;
                const label = isSubmittingThis
                  ? "Requesting..."
                  : r.npub === parentNpub
                    ? "This is you"
                    : (r.pendingParentRequests || []).includes(parentNpub || "")
                    ? "Requested"
                    : r.parentNpub
                    ? "Has a parent"
                    : r.isChild
                    ? "Is a child"
                    : "Request";

                return (
                  <div key={r.id} className="flex items-center justify-between p-3">
                    <div className="flex items-center gap-3 min-w-0">
                      <Avatar className="h-8 w-8">
                        {r.profilePicture ? (
                          <AvatarImage src={r.profilePicture} alt={r.profileName || r.profileDisplayName || r.npub} />
                        ) : null}
                      </Avatar>
                      <div className="min-w-0">
                        <div className="font-medium truncate">{r.profileName || r.profileDisplayName || r.npub}</div>
                        <div className="text-xs text-muted-foreground truncate">{r.npub}</div>
                      </div>
                    </div>
                    <Button size="sm" variant={disabled ? "secondary" : "default"} disabled={disabled} onClick={() => onRequestChild(r.npub)}>
                      {label}
                    </Button>
                  </div>
                );
              })
            )}
          </div>
          {fetcher.data?.error ? (
            <p className="mt-2 text-sm text-red-600">{fetcher.data.error}</p>
          ) : null}
        </div>
      ) : null}

      <div className="grid md:grid-cols-2 gap-6">
        <div>
          <h3 className="mb-2 text-sm font-medium">Confirmed children</h3>
          <div className="divide-y rounded-md border">
            {confirmedChildren && confirmedChildren.length === 0 ? (
              <div className="p-3 text-sm text-muted-foreground">No confirmed children</div>
            ) : (
              (confirmedChildren || []).map((u) => {
                const bits = extractProfileBits(u.nostrProfile);
                const removingThis =
                  submittingAction === "unlink_child" &&
                  (fetcher.formData?.get("childNpub") as string) === u.npub &&
                  fetcher.state !== "idle";
                return (
                  <div key={u.npub} className="flex items-center justify-between p-3">
                    <div className="flex items-center gap-3 min-w-0">
                      <Avatar className="h-8 w-8">
                        {bits.picture ? (
                          <AvatarImage src={bits.picture} alt={bits.name || bits.display_name || u.npub} />
                        ) : null}
                      </Avatar>
                      <div className="min-w-0">
                        <div className="font-medium truncate">{bits.name || bits.display_name || u.npub}</div>
                        <div className="text-xs text-muted-foreground truncate">{u.npub}</div>
                      </div>
                    </div>
                    <Button
                      size="sm"
                      variant="destructive"
                      disabled={removingThis}
                      onClick={() =>
                        fetcher.submit(
                          { _action: "unlink_child", childNpub: u.npub },
                          { method: "post", action: "/dashboard/settings" },
                        )
                      }
                    >
                      {removingThis ? "Removing..." : "Remove"}
                    </Button>
                  </div>
                );
              })
            )}
          </div>
        </div>
        <div>
          <h3 className="mb-2 text-sm font-medium">Pending requests</h3>
          <div className="divide-y rounded-md border">
            {pendingChildren && pendingChildren.length === 0 ? (
              <div className="p-3 text-sm text-muted-foreground">No pending requests</div>
            ) : (
              (pendingChildren || []).map((u) => {
                const bits = extractProfileBits(u.nostrProfile);
                const cancelingThis =
                  submittingAction === "cancel_child_request" &&
                  (fetcher.formData?.get("childNpub") as string) === u.npub &&
                  fetcher.state !== "idle";
                return (
                  <div key={u.npub} className="flex items-center justify-between p-3">
                    <div className="flex items-center gap-3 min-w-0">
                      <Avatar className="h-8 w-8">
                        {bits.picture ? (
                          <AvatarImage src={bits.picture} alt={bits.name || bits.display_name || u.npub} />
                        ) : null}
                      </Avatar>
                      <div className="min-w-0">
                        <div className="font-medium truncate">{bits.name || bits.display_name || u.npub}</div>
                        <div className="text-xs text-muted-foreground truncate">{u.npub}</div>
                      </div>
                    </div>
                    <Button
                      size="sm"
                      variant="secondary"
                      disabled={cancelingThis}
                      onClick={() =>
                        fetcher.submit(
                          { _action: "cancel_child_request", childNpub: u.npub },
                          { method: "post", action: "/dashboard/settings" },
                        )
                      }
                    >
                      {cancelingThis ? "Canceling..." : "Cancel"}
                    </Button>
                  </div>
                );
              })
            )}
          </div>
        </div>
      </div>
    </Card>
  );
}

