import type { User } from "@prisma/client";

import {
  encrypt,
  decrypt,
  validateNWCString,
  maskNWCString,
} from "~/lib/encryption.server";
import { prisma } from "~/lib/prisma.server";

/**
 * Updates user's NWC (Nostr Wallet Connect) connection string
 * Validates and encrypts the NWC string before storing
 */
export function updateUserNWC(
  userId: string,
  nwcString: string,
  enabled = true,
): Promise<User> {
  // Validate NWC string format
  if (!validateNWCString(nwcString)) {
    throw new Error("Invalid NWC connection string format");
  }

  // Encrypt the NWC string before storing
  const encryptedNwc = encrypt(nwcString);

  const result = await prisma.user.update({
    where: {
      id: userId,
    },
    data: {
      encryptedNwc,
      nwcEnabled: enabled,
      nwcLastUsed: new Date(),
    },
  });

  return result;
}

/**
 * Updates whether NWC is enabled for a user
 */
export async function updateUserNWCEnabled(
  userId: string,
  enabled: boolean,
): Promise<User> {
  const result = await prisma.user.update({
    where: {
      id: userId,
    },
    data: {
      nwcEnabled: enabled,
      ...(enabled && { nwcLastUsed: new Date() }),
    },
  });

  return result;
}

/**
 * Clears user's NWC connection string
 */
export function clearUserNWC(userId: string): Promise<User> {
  return prisma.user.update({
    where: {
      id: userId,
    },
    data: {
      encryptedNwc: null,
      nwcEnabled: false,
      nwcLastUsed: null,
    },
  });
}

/**
 * Gets user's NWC information (masked string, enabled status, last used)
 * Returns masked string for display purposes
 */
export async function getUserNWC(userId: string): Promise<{
  enabled: boolean;
  maskedString?: string;
  lastUsed?: Date | null;
}> {
  const user = await prisma.user.findUnique({
    where: {
      id: userId,
    },
    select: {
      nwcEnabled: true,
      encryptedNwc: true,
      nwcLastUsed: true,
    },
  });

  if (!user) {
    return { enabled: false };
  }

  let maskedString: string | undefined;
  if (user.encryptedNwc) {
    try {
      const decryptedNwc = decrypt(user.encryptedNwc);
      maskedString = maskNWCString(decryptedNwc);
    } catch (_error) {
      // If decryption fails, we can't show the masked string
    }
  }

  const result = {
    enabled: user.nwcEnabled,
    maskedString,
    lastUsed: user.nwcLastUsed,
  };

  return result;
}

/**
 * Gets decrypted NWC string for a user
 * Only returns if NWC is enabled and decryption succeeds
 * Used for payment processing
 */
export async function getDecryptedUserNWC(
  userId: string,
): Promise<string | null> {
  const user = await prisma.user.findUnique({
    where: {
      id: userId,
    },
    select: {
      encryptedNwc: true,
      nwcEnabled: true,
    },
  });

  if (!user?.encryptedNwc || !user.nwcEnabled) {
    return null;
  }

  try {
    return decrypt(user.encryptedNwc);
  } catch (error) {
    // Use safe logging to prevent NWC strings from appearing in logs
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const { safeConsoleError } = require("~/lib/secrets-sanitizer.server");
    safeConsoleError("Failed to decrypt NWC string for user", userId);
    return null;
  }
}

/**
 * Parent API service layer
 * Handles parent account information for child accounts
 */

import { json } from "@remix-run/node";

import type { ProfileData } from "~/features/nostr/types";
import { logError } from "~/lib/error-logger.server";
import { normalizeError } from "~/lib/errors";
import { getUserBasicInfo, getUserByNpubWithProfile } from "~/models/user.server";
function extractProfileBits(nostrProfile: ProfileData | null | undefined) {
  if (!nostrProfile) {
    return { name: undefined, display_name: undefined, picture: undefined } as const;
  }
  try {
    if (typeof nostrProfile === "string") {
      const pParsed = JSON.parse(nostrProfile);
      if (pParsed && typeof pParsed === "object" && !Array.isArray(pParsed)) {
        const p = pParsed as { name?: string; display_name?: string; picture?: string };
        return { 
          name: typeof p.name === "string" ? p.name : undefined, 
          display_name: typeof p.display_name === "string" ? p.display_name : undefined, 
          picture: typeof p.picture === "string" ? p.picture : undefined 
        } as const;
      }
    }
    if (typeof nostrProfile === "object" && !Array.isArray(nostrProfile)) {
      const p = nostrProfile as { name?: string; display_name?: string; picture?: string };
      return { 
        name: typeof p.name === "string" ? p.name : undefined, 
        display_name: typeof p.display_name === "string" ? p.display_name : undefined, 
        picture: typeof p.picture === "string" ? p.picture : undefined 
      } as const;
    }
  } catch {
    // Silently ignore parse errors - return defaults
  }
  return { name: undefined, display_name: undefined, picture: undefined } as const;
}

/**
 * Load parent information for a child account
 */
export async function loadParentData(userId: string) {
  const me = await getUserBasicInfo(userId);

  if (!me?.isChild || !me.parentNpub) {
    return json({ parent: null });
  }

  const parent = await getUserByNpubWithProfile(me.parentNpub);

  if (!parent) {
    return json({ parent: null });
  }

  const bits = extractProfileBits(parent.nostrProfile);

  return json({
    parent: {
      npub: parent.npub,
      name: bits.name,
      displayName: bits.display_name,
      picture: bits.picture,
    },
  });
}

/**
 * Handle errors for parent API
 */
export function handleParentApiError(error: unknown, requestUrl: string) {
  // If error is a Response (e.g., redirect from requireUserId), rethrow it
  if (error instanceof Response) {
    throw error;
  }

  // Gracefully handle other errors by returning null parent
  // Log error but don't expose it to client
  logError(normalizeError(error), { path: requestUrl });
  return json({ parent: null });
}

import type { User } from "@prisma/client";

import type { ProfileData } from "~/features/nostr/types";
import { logWarning, logError } from "~/lib/error-logger.server";
import { prisma } from "~/lib/prisma.server";

type MinimalUser = Pick<User, "id" | "npub"> & {
  nostrProfile?: ProfileData | null;
  isChild?: boolean;
  parentNpub?: string | null;
  pendingParentRequests?: string[];
};

function extractProfileBits(nostrProfile: ProfileData | null | undefined): {
  name?: string;
  display_name?: string;
  picture?: string;
} {
  if (!nostrProfile) return {};
  try {
    if (typeof nostrProfile === "string") {
      const parsed = JSON.parse(nostrProfile) as { name?: string; display_name?: string; picture?: string };
      return {
        name: parsed?.name,
        display_name: parsed?.display_name,
        picture: parsed?.picture,
      };
    }
    if (typeof nostrProfile === "object") {
      return {
        name: nostrProfile?.name,
        display_name: nostrProfile?.display_name,
        picture: nostrProfile?.picture,
      };
    }
  } catch {
    // Ignore parsing errors, return empty object
  }
  return {};
}

/**
 * Searches users by profile name or npub
 * Used for parent/child account linking
 */
export async function searchUsersByProfileName(
  query: string,
  excludeNpub?: string,
  limit = 20,
): Promise<
  (MinimalUser & {
    profileName?: string;
    profileDisplayName?: string;
    profilePicture?: string;
  })[]
> {
  const trimmed = query.trim();
  if (!trimmed) return [];

  // Broad prefilter to avoid full table scan; then filter in app
  const fetched = await prisma.user.findMany({
    where: {
      AND: [
        excludeNpub ? { npub: { not: excludeNpub } } : {},
        {
          OR: [
            { npub: { contains: trimmed, mode: "insensitive" } },
            { nostrProfile: { not: { equals: null } } },
          ],
        },
      ],
    },
    take: 200,
    select: {
      id: true,
      npub: true,
      nostrProfile: true,
      isChild: true,
      parentNpub: true,
      pendingParentRequests: true,
    },
  });

  const lowered = trimmed.toLowerCase();
  const filtered = fetched
    .map((u) => {
      const profile = u.nostrProfile && typeof u.nostrProfile === "object" && !Array.isArray(u.nostrProfile)
        ? (u.nostrProfile as ProfileData)
        : null;
      const bits = extractProfileBits(profile);
      const name = bits.name || bits.display_name || "";
      return {
        id: u.id,
        npub: u.npub,
        nostrProfile: profile,
        isChild: u.isChild ?? false,
        parentNpub: u.parentNpub,
        pendingParentRequests: u.pendingParentRequests ?? [],
        profileName: bits.name,
        profileDisplayName: bits.display_name,
        profilePicture: bits.picture,
        _match:
          u.npub.toLowerCase().includes(lowered) ||
          (name && name.toLowerCase().includes(lowered)),
      };
    })
    .filter((u) => u._match)
    .slice(0, limit)
    .map(({ _match, ...rest }) => rest);

  return filtered as (MinimalUser & {
    profileName?: string;
    profileDisplayName?: string;
    profilePicture?: string;
  })[];
}

/**
 * Requests to link a child account to a parent account
 */
export function requestChildLink(
  parentHex: string,
  childHex: string,
): Promise<{ ok: true } | { ok: false; reason: string }> {
  // Directly use 64-char hex keys, no normalization or conversion.
  const parent = (parentHex || "").trim();
  const child = (childHex || "").trim();

  if (!/^[0-9a-fA-F]{64}$/.test(parent) || !/^[0-9a-fA-F]{64}$/.test(child)) {
    logWarning("[requestChildLink] Invalid hex key(s)", { parent, child });
    return { ok: false, reason: "Invalid hex public key provided." };
  }

  if (parent === child) {
    logWarning("[requestChildLink] Attempt to add self as child", { parent });
    return { ok: false, reason: "You cannot add yourself as a child." };
  }

  const childUser = await prisma.user.findUnique({ where: { npub: child } });
  if (!childUser) {
    logError(new Error("[requestChildLink] Child account not found in DB"), {
      child,
    });
    return { ok: false, reason: "Child account not found." };
  }

  if (childUser.parentNpub) {
    logWarning("[requestChildLink] Child already linked to a parent", {
      parentNpub: childUser.parentNpub,
      child: childUser.npub,
    });
    return { ok: false, reason: "This account is already linked to a parent." };
  }

  const alreadyRequested = (childUser.pendingParentRequests || []).includes(
    parent,
  );
  if (alreadyRequested) {
    return { ok: true };
  }

  await prisma.user.update({
    where: { npub: childUser.npub },
    data: {
      pendingParentRequests: { push: parent },
    },
  });

  return { ok: true };
}

/**
 * Cancels a pending child link request
 */
export function cancelChildLinkRequest(
  parentHex: string,
  childHex: string,
): Promise<{ ok: true } | { ok: false; reason: string }> {
  const parent = (parentHex || "").trim();
  const child = (childHex || "").trim();

  if (!/^[0-9a-fA-F]{64}$/.test(parent) || !/^[0-9a-fA-F]{64}$/.test(child)) {
    return { ok: false, reason: "Invalid hex public key provided." };
  }

  const childUser = await prisma.user.findUnique({ where: { npub: child } });
  if (!childUser) return { ok: false, reason: "Child account not found." };

  const pending = childUser.pendingParentRequests || [];
  if (!pending.includes(parent)) {
    return { ok: false, reason: "No pending request to cancel." };
  }

  await prisma.user.update({
    where: { npub: child },
    data: {
      pendingParentRequests: pending.filter((p) => p !== parent),
    },
  });

  return { ok: true };
}

/**
 * Gets all confirmed children for a parent account
 */
export async function getConfirmedChildrenForParent(parentNpub: string) {
  return prisma.user.findMany({
