/**
 * Schedule a regular post to be published
 * @param postId - The post ID
 * @param userId - The user ID
 * @param signedEvent - The signed Nostr event
 * @param scheduledFor - Unix timestamp (in seconds) when the post should be published, or 0 for immediate
 */
export function enqueuePostJob(
  postId: string,
  userId: string,
  signedEvent: SignedEvent,
  scheduledFor: number,
): Promise<void> {
  // Handle immediate scheduling (delay: 0)
  const options = scheduledFor === 0 
    ? { delay: 0 }
    : { scheduledFor };

  const result = await queueClient.enqueue<PostJobData>(
    "scheduled-posts",
    "publish-post",
    { postId, userId, signedEvent },
    options,
  );

  if (!result.success) {
    throw new Error(result.error || "Failed to schedule post");
  }
}

/**
 * Cancel a scheduled post
 * @param postId - The post ID to cancel
 * @returns true if the job was found and cancelled, false otherwise
 */
export function cancelPostJob(postId: string): Promise<boolean> {
  return queueClient.cancelByData("scheduled-posts", "postId", postId);
}

/**
 * Schedule a longform post to be published
 * @param postId - The longform post ID
 * @param userId - The user ID
 * @param signedEvent - The signed Nostr event
 * @param scheduledFor - Unix timestamp (in seconds) when the post should be published, or 0 for immediate
 */
export function enqueueLongFormPostJob(
  postId: string,
  userId: string,
  signedEvent: SignedEvent,
  scheduledFor: number,
): Promise<void> {
  // Handle immediate scheduling (delay: 0)
  const options = scheduledFor === 0 
    ? { delay: 0 }
    : { scheduledFor };

  const result = await queueClient.enqueue<LongFormPostJobData>(
    "scheduled-longform-posts",
    "publish-longform-post",
    { postId, userId, signedEvent },
    options,
  );

  if (!result.success) {
    throw new Error(result.error || "Failed to schedule longform post");
  }
}

/**
 * Cancel a scheduled longform post
 * @param postId - The longform post ID to cancel
 * @returns true if the job was found and cancelled, false otherwise
 */
export function cancelLongFormPostJob(postId: string): Promise<boolean> {
  return queueClient.cancelByData("scheduled-longform-posts", "postId", postId);
}

/**
 * Enqueue a post checker job (for cron-like recurring jobs)
 * @param delay - Delay in milliseconds before processing
 */
export async function enqueuePostCheckerJob(delay = 0): Promise<void> {
  const result = await queueClient.enqueue<PostJobData>(
    "post-checker",
    "check-due-posts",
    { postId: "", userId: "", signedEvent: { id: "", pubkey: "", created_at: 0, kind: 0, tags: [], content: "", sig: "" } },
    { delay },
  );

  if (!result.success) {
    throw new Error(result.error || "Failed to enqueue post checker job");
  }
}

import crypto from 'crypto';
// Encryption version constants
const VERSION_LEGACY_CBC = 0x01; // Legacy AES-256-CBC (no version byte in old format)
const VERSION_GCM = 0x02; // New AES-256-GCM

// Algorithm constants
const ALGORITHM_LEGACY = 'aes-256-cbc';
const ALGORITHM_GCM = 'aes-256-gcm';

// Length constants
const IV_LENGTH_CBC = 16;
const IV_LENGTH_GCM = 12; // GCM uses 12-byte IV (96 bits)
const AUTH_TAG_LENGTH = 16; // GCM authentication tag
const SALT_LENGTH = 32;
const KEY_LENGTH = 32;
const VERSION_LENGTH = 1;

/**
 * Derive encryption key from SESSION_SECRET
 */
function deriveKey(salt: Buffer): Buffer {
  const sessionSecret = process.env.SESSION_SECRET;
  if (!sessionSecret) {
    throw new Error('SESSION_SECRET environment variable is required for encryption');
  }

  return crypto.pbkdf2Sync(sessionSecret, salt, 100000, KEY_LENGTH, 'sha512');
}

/**
 * Encrypt sensitive data using AES-256-GCM (authenticated encryption)
 * Format: [VERSION(1)] [SALT(32)] [IV(12)] [ENCRYPTED_DATA] [AUTH_TAG(16)]
 */
export function encrypt(text: string): string {
  try {
    const salt = crypto.randomBytes(SALT_LENGTH);
    const iv = crypto.randomBytes(IV_LENGTH_GCM);
    const key = deriveKey(salt);

    const cipher = crypto.createCipheriv(ALGORITHM_GCM, key, iv);

    let encrypted = cipher.update(text, 'utf8');
    encrypted = Buffer.concat([encrypted, cipher.final()]);

    // Get authentication tag (required for GCM)
    const authTag = cipher.getAuthTag();

    // Combine: version + salt + iv + encrypted + authTag
    const combined = Buffer.concat([
      Buffer.from([VERSION_GCM]), // Version byte
      salt,
      iv,
      encrypted,
      authTag,
    ]);

    return combined.toString('base64');
  } catch (error) {
    // Use safe logging to prevent sensitive data in logs
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const { safeConsoleError } = require("./secrets-sanitizer.server");
    safeConsoleError("Encryption failed");
    throw new Error('Failed to encrypt data');
  }
}

/**
 * Decrypt sensitive data with backward compatibility
 * Supports both legacy CBC and new GCM formats
 */
export function decrypt(encryptedData: string): string {
  try {
    const combined = Buffer.from(encryptedData, 'base64');

    // Check if this is the new format (has version byte)
    // Legacy format: [SALT(32)] [IV(16)] [ENCRYPTED_DATA]
    // New format: [VERSION(1)] [SALT(32)] [IV(12)] [ENCRYPTED_DATA] [AUTH_TAG(16)]

    let version: number;
    let salt: Buffer;
    let iv: Buffer;
    let encrypted: Buffer;
    let authTag: Buffer | undefined;

    // Detect format: if first byte is a valid version, use new format
    // Otherwise, assume legacy CBC format
    if (combined.length >= VERSION_LENGTH + SALT_LENGTH + IV_LENGTH_CBC) {
      const firstByte = combined[0];
      if (firstByte === VERSION_GCM) {
        // New GCM format
        version = VERSION_GCM;
        let offset = VERSION_LENGTH;
        salt = combined.subarray(offset, offset + SALT_LENGTH);
        offset += SALT_LENGTH;
        iv = combined.subarray(offset, offset + IV_LENGTH_GCM);
        offset += IV_LENGTH_GCM;
        authTag = combined.subarray(combined.length - AUTH_TAG_LENGTH);
        encrypted = combined.subarray(offset, combined.length - AUTH_TAG_LENGTH);
      } else {
        // Legacy CBC format (no version byte)
        version = VERSION_LEGACY_CBC;
        salt = combined.subarray(0, SALT_LENGTH);
        iv = combined.subarray(SALT_LENGTH, SALT_LENGTH + IV_LENGTH_CBC);
        encrypted = combined.subarray(SALT_LENGTH + IV_LENGTH_CBC);
      }
    } else {
      // Too short, assume legacy format
      version = VERSION_LEGACY_CBC;
      salt = combined.subarray(0, SALT_LENGTH);
      iv = combined.subarray(SALT_LENGTH, SALT_LENGTH + IV_LENGTH_CBC);
      encrypted = combined.subarray(SALT_LENGTH + IV_LENGTH_CBC);
    }

    const key = deriveKey(salt);

    if (version === VERSION_GCM && authTag) {
      // New GCM decryption
      const decipher = crypto.createDecipheriv(ALGORITHM_GCM, key, iv);
      decipher.setAuthTag(authTag);

      let decrypted = decipher.update(encrypted);
      decrypted = Buffer.concat([decrypted, decipher.final()]);

      return decrypted.toString('utf8');
    } else {
      // Legacy CBC decryption (for backward compatibility)
      const decipher = crypto.createDecipheriv(ALGORITHM_LEGACY, key, iv);

      let decrypted = decipher.update(encrypted, undefined, 'utf8');
      decrypted += decipher.final('utf8');

      return decrypted;
    }
  } catch (error) {
    // Use safe logging to prevent sensitive data in logs
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const { safeConsoleError } = require("./secrets-sanitizer.server");
    safeConsoleError("Decryption failed");
    throw new Error('Failed to decrypt data');
  }
}

/**
 * Validate NWC connection string format
 */
export function validateNWCString(nwcString: string): boolean {
  try {
    // Basic validation for NWC format
    return nwcString.startsWith('nostr+walletconnect://') && nwcString.length > 30;
  } catch {
    return false;
  }
}

/**
 * Mask NWC string for display (show only first and last few characters)
 */
export function maskNWCString(nwcString: string): string {
  if (!nwcString || nwcString.length < 10) {
    return '***';
  }

  const prefix = nwcString.substring(0, 25); // nostr+walletconnect://
  const visible = nwcString.substring(25, 29); // First few chars after protocol
  const masked = '...';
  const suffix = nwcString.substring(nwcString.length - 4); // Last 4 chars

  return `${prefix}${visible}${masked}${suffix}`;
}

/**
 * Client-side Error Handling Utilities
 * 
 * Provides standardized error handling for client-side code
 */

import { toast } from "react-hot-toast";

import type { ErrorResponse } from "./error-handler.server";
import { captureException } from "./sentry.client";
export type ClientErrorLevel = "error" | "warning" | "info";

export interface ClientErrorContext {
  component?: string;
  action?: string;
  userId?: string;
  [key: string]: unknown;
}

/**
 * Client-side error logger
 * Logs errors to console with structured format
 */
export function logClientError(
  error: Error | string,
  context?: ClientErrorContext,
  level: ClientErrorLevel = "error",
): void {
  const errorMessage = error instanceof Error ? error.message : error;
  const errorStack = error instanceof Error ? error.stack : undefined;

  const logEntry = {
    timestamp: new Date().toISOString(),
    level,
    message: errorMessage,
    ...(errorStack && { stack: errorStack }),
    ...(context && { context }),
    environment: typeof window !== "undefined" ? window.location.href : "unknown",
  };

  if (process.env.NODE_ENV === "production") {
    // In production, log as JSON for log aggregation
    console.error(JSON.stringify(logEntry));
  } else {
    // In development, use readable format
    const emoji = level === "error" ? "❌" : level === "warning" ? "⚠️" : "ℹ️";
    console[level === "error" ? "error" : level === "warning" ? "warn" : "info"](
      `${emoji} [CLIENT ${level.toUpperCase()}]`,
      errorMessage,
      context || "",
    );
    if (errorStack && level === "error") {
      console.error("Stack:", errorStack);
    }
  }

  // Send to Sentry if configured
  if (error instanceof Error) {
    const tags: Record<string, string> = { level };
    if (context?.component) {
      tags.component = context.component;
    }
    if (context?.action) {
      tags.action = context.action;
    }
    captureException(error, {
      tags,
      extra: context,
      user: context?.userId ? { id: context.userId } : undefined,
      level: level === "error" ? "error" : level === "warning" ? "warning" : "info",
    });
  }
}

/**
 * Handle API error responses
 * Extracts error message from standardized error response format
 */
export function handleApiError(
  response: Response | { error?: ErrorResponse["error"]; success?: boolean },
): string {
  // Handle Response object
  if (response instanceof Response) {
    // Try to parse JSON error response
    return response.statusText || `HTTP ${response.status} Error`;
  }

  // Handle error response object
  if (response.error) {
    return response.error.message || "An error occurred";
  }

  return "An unexpected error occurred";
}

/**
 * Display error to user via toast notification
 */
export function showErrorToast(
  error: ErrorResponse["error"] | Error | string,
  options?: {
    duration?: number;
    position?: "top-left" | "top-center" | "top-right" | "bottom-left" | "bottom-center" | "bottom-right";
  },
): void {
  let message: string;

  if (typeof error === "string") {
    message = error;
  } else if (error instanceof Error) {
    message = error.message;
  } else {
    message = error.message || "An error occurred";
  }

  toast.error(message, {
    duration: options?.duration ?? 5000,
    position: options?.position ?? "top-right",
  });
}

/**
 * Handle error in async operations with logging and user notification
 */
export function handleAsyncError(
  error: unknown,
  context?: ClientErrorContext,
  showToast = true,
): void {
  const errorObj = error instanceof Error ? error : new Error(String(error));

  // Log the error
  logClientError(errorObj, context, "error");

  // Show toast to user
  if (showToast) {
    showErrorToast(errorObj.message);
  }
}

/**
 * Handle error in async operations with custom message
 */
export function handleAsyncErrorWithMessage(
  error: unknown,
  userMessage: string,
  context?: ClientErrorContext,
  showToast = true,
): void {
  const errorObj = error instanceof Error ? error : new Error(String(error));

  // Log the error with original message
  logClientError(errorObj, context, "error");

  // Show custom message to user
  if (showToast) {
    showErrorToast(userMessage);
  }
}

/**
 * Safe error handler that doesn't throw
 * Useful for non-critical operations
 */
export function handleErrorSafely(
  error: unknown,
  context?: ClientErrorContext,
  fallback?: () => void,
): void {
  try {
    handleAsyncError(error, context, false);
    if (fallback) {
      fallback();
    }
  } catch (handlingError) {
    // Even error handling can fail, so we catch it
    console.error("Error in error handler:", handlingError);
  }
}

/**
 * Extract error message from various error types
 */
export function getErrorMessage(error: unknown): string {
  if (typeof error === "string") {
    return error;
  }

  if (error instanceof Error) {
    return error.message;
  }

  if (error && typeof error === "object" && "message" in error) {
    return String(error.message);
  }

  return "An unexpected error occurred";
}

/**
 * Check if error is a network error
 */
export function isNetworkError(error: unknown): boolean {
  if (error instanceof Error) {
    return (
      error.message.includes("fetch") ||
      error.message.includes("network") ||
      error.message.includes("Failed to fetch") ||
      error.name === "NetworkError" ||
      error.name === "TypeError"
    );
  }
  return false;
}

/**
 * Check if error is a timeout error
 */
export function isTimeoutError(error: unknown): boolean {
  if (error instanceof Error) {
    return (
      error.message.includes("timeout") ||
      error.message.includes("Timeout") ||
      error.name === "TimeoutError"
    );
  }
  return false;
}

/**
 * Error Logging Service
 * 
 * Centralized error logging with different log levels and structured output
 */

import { recordErrorMetric } from "./error-metrics.server";
import type { AppError } from "./errors";
import { sanitizeError, sanitizeObject } from "./secrets-sanitizer.server";
import { captureException } from "./sentry.server";
export type LogLevel = "error" | "warn" | "info" | "debug";

export interface LogContext {
  userId?: string;
  requestId?: string;
  path?: string;
  method?: string;
  userAgent?: string;
  ip?: string;
  includeStack?: boolean;
  [key: string]: unknown;
}

/**
 * Structured error log entry
 */
interface ErrorLogEntry {
  timestamp: string;
  level: LogLevel;
  error: {
    name: string;
    message: string;
    code: string;
    statusCode: number;
    isOperational: boolean;
    stack?: string;
    context?: Record<string, unknown>;
  };
  request?: {
    method?: string;
    path?: string;
    userAgent?: string;
    ip?: string;
  };
  user?: {
    id?: string;
  };
  environment: string;
}

/**
 * Log an error with structured output
 * Automatically sanitizes sensitive data (NWC strings, secrets, etc.)
 */
export function logError(
  error: AppError | Error,
  context: LogContext = {},
): void {
  const logEntry: ErrorLogEntry = {
    timestamp: new Date().toISOString(),
    level: "error",
    error: {
      name: error.name,
      message: error.message,
      code: isAppError(error) ? error.code : "UNKNOWN_ERROR",
      statusCode: isAppError(error) ? error.statusCode : 500,
      isOperational: isAppError(error) ? error.isOperational : false,
      ...(context.includeStack && error.stack && { stack: error.stack }),
      ...(isAppError(error) && error.context && { context: error.context }),
    },
    ...(context.method && {
      request: {
        method: context.method,
        path: context.path,
        userAgent: context.userAgent,
        ip: context.ip,
      },
    }),
    ...(context.userId && {
      user: {
        id: context.userId,
      },
    }),
    environment: process.env.NODE_ENV || "development",
  };

  // Sanitize log entry to prevent secrets from appearing in logs
  const sanitizedError = sanitizeError(error);
  const sanitizedLogEntry = sanitizeObject({
    ...logEntry,
    error: {
      ...logEntry.error,
      message: sanitizedError.message,
      stack: sanitizedError.stack,
    },
  });

  // In production, you might want to send to an external service
  // For now, we'll use structured console logging
  if (process.env.NODE_ENV === "production") {
    // In production, log as JSON for log aggregation services
    console.error(JSON.stringify(sanitizedLogEntry));
  } else {
    // In development, use more readable format
    console.error("\n❌ Error:", {
      message: sanitizedError.message,
      code: logEntry.error.code,
      statusCode: logEntry.error.statusCode,
      path: logEntry.request?.path,
      method: logEntry.request?.method,
      userId: logEntry.user?.id,
      ...(context.includeStack && sanitizedError.stack && { stack: sanitizedError.stack }),
    });
  }

  // Record error in metrics
  if (isAppError(error)) {
    recordErrorMetric(error);
  }

  // Send to Sentry if configured
  captureException(sanitizedError, {
    tags: {
      code: isAppError(error) ? error.code : "UNKNOWN_ERROR",
      statusCode: String(logEntry.error.statusCode),
      isOperational: String(logEntry.error.isOperational),
    },
    extra: {
      ...sanitizedLogEntry,
      // Include sanitized context
      context: sanitizedLogEntry.request || sanitizedLogEntry.user || {},
    },
    user: context.userId ? { id: context.userId } : undefined,
    level: logEntry.error.isOperational ? "warning" : "error",
  });
}

/**
 * Log a warning
 */
export function logWarning(
  message: string,
  context: LogContext = {},
): void {
  const logEntry = {
    timestamp: new Date().toISOString(),
    level: "warn" as LogLevel,
    message,
    ...context,
    environment: process.env.NODE_ENV || "development",
  };

  if (process.env.NODE_ENV === "production") {
    console.warn(JSON.stringify(logEntry));
  } else {
    console.warn("⚠️  Warning:", message, context);
  }
}

/**
 * Log info
 */
export function logInfo(
  message: string,
  context: LogContext = {},
): void {
  const logEntry = {
    timestamp: new Date().toISOString(),
    level: "info" as LogLevel,
    message,
    ...context,
    environment: process.env.NODE_ENV || "development",
  };

  if (process.env.NODE_ENV === "production") {
    console.info(JSON.stringify(logEntry));
  } else {
    console.info("ℹ️  Info:", message, context);
  }
}

/**
 * Type guard for AppError
 */
function isAppError(error: AppError | Error): error is AppError {
  return "code" in error && "statusCode" in error;
}

import { marked } from "marked";
const ALLOWED_TAGS = [
  "p",
  "br",
  "strong",
  "em",
  "h1",
  "h2",
  "h3",
  "h4",
  "h5",
  "h6",
  "ul",
  "ol",
  "li",
  "blockquote",
  "pre",
  "code",
  "a",
  "img",
];

const ALLOWED_ATTRIBUTES: Record<string, string[]> = {
  a: ["href", "title"],
  img: ["src", "alt", "title"],
};

const DANGEROUS_PROTOCOLS = [
  "javascript:",
  "data:",
  "vbscript:",
  "file:",
  "about:",
];

function isValidUrl(url: string): boolean {
  try {
    const parsed = new URL(url);
    return ["http:", "https:"].includes(parsed.protocol);
  } catch {
    return false;
  }
}

function sanitizeAttribute(
  tagName: string,
  attrName: string,
  attrValue: string,
): string | null {
  const allowedAttrs = ALLOWED_ATTRIBUTES[tagName];
  if (!allowedAttrs?.includes(attrName)) {
    return null;
  }

  if (attrName === "href" || attrName === "src") {
    if (!isValidUrl(attrValue)) {
      return null;
    }

    const lowerValue = attrValue.toLowerCase();
    for (const protocol of DANGEROUS_PROTOCOLS) {
      if (lowerValue.startsWith(protocol)) {
        return null;
      }
    }
  }

  return attrValue.trim();
}

function sanitizeHtml(html: string): string {
  return html
    // Remove script tags and all content between them (case-insensitive)
    .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, "")
    .replace(/<SCRIPT\b[^>]*>[\s\S]*?<\/SCRIPT>/gi, "")
    // Remove inline event handlers
    .replace(/on\w+\s*=\s*["'][^"']*["']/gi, "")
    .replace(/on\w+\s*=\s*[^>\s]*/gi, "")
    // Remove dangerous protocols
    .replace(/javascript:/gi, "")
    .replace(/data:/gi, "")
    .replace(/vbscript:/gi, "")
    // Remove dangerous tags
    .replace(/<iframe\b[^>]*>[\s\S]*?<\/iframe>/gi, "")
    .replace(/<embed\b[^>]*>/gi, "")
    .replace(/<object\b[^>]*>[\s\S]*?<\/object>/gi, "")
    .replace(/<form\b[^>]*>[\s\S]*?<\/form>/gi, "")
    .replace(/<input\b[^>]*>/gi, "")
    .replace(/<textarea\b[^>]*>[\s\S]*?<\/textarea>/gi, "")
    .replace(/<select\b[^>]*>[\s\S]*?<\/select>/gi, "")
    .replace(/<button\b[^>]*>[\s\S]*?<\/button>/gi, "")
    .replace(/<link\b[^>]*>/gi, "")
    .replace(/<meta\b[^>]*>/gi, "")
    .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, "");
}

export function sanitizeMarkdown(markdown: string): string {
  if (!markdown || typeof markdown !== "string") {
    return "";
  }

  // Type guard for marked return values
  const ensureString = (value: unknown): string => {
    if (typeof value === "string") {
      return value;
    }
    return String(value ?? "");
  };

  try {
    // Parse markdown to HTML
    const htmlResult = marked(markdown, {
      gfm: true,
      breaks: false,
      pedantic: false,
      smartLists: true,
      smartypants: false,
    });
    let html = typeof htmlResult === "string" ? htmlResult : String(htmlResult ?? "");

    // Sanitize links and images by processing the HTML
    html = html.replace(
      /<a\s+([^>]*?)href=["']([^"']*?)["']([^>]*?)>(.*?)<\/a>/gi,
      (match, before, href, after, text) => {
        const hrefStr = typeof href === "string" ? href : String(href ?? "");
        const textStr = typeof text === "string" ? text : String(text ?? "");
        const sanitizedHref = sanitizeAttribute("a", "href", hrefStr);
        if (!sanitizedHref) {
          return textStr; // Return just the text if href is invalid
        }
        return `<a href="${sanitizedHref}" target="_blank" rel="noopener noreferrer">${textStr}</a>`;
      }
    );

    html = html.replace(
      /<img\s+([^>]*?)src=["']([^"']*?)["']([^>]*?)>/gi,
      (match, before, src, after) => {
        const srcStr = typeof src === "string" ? src : String(src ?? "");
        const sanitizedSrc = sanitizeAttribute("img", "src", srcStr);
        if (!sanitizedSrc) {
          return ""; // Remove image if src is invalid
        }
        return `<img src="${sanitizedSrc}" loading="lazy">`;
      }
    );

    // FIRST: Remove dangerous tags and content (script tags, event handlers, etc.)
    html = sanitizeHtml(html);

    // SECOND: Escape code blocks properly - decode HTML entities first, then escape
    html = html.replace(
      /<pre><code(?: class="language-([^"]*)")?>([\s\S]*?)<\/code><\/pre>/gi,
      (match, lang, code) => {
        const codeStr = typeof code === "string" ? code : String(code ?? "");
        const langStr = typeof lang === "string" ? lang : String(lang ?? "");
        // Decode HTML entities that marked might have added, then escape properly
        const decodedCode = codeStr
          .replace(/&amp;/g, "&")
          .replace(/&lt;/g, "<")
          .replace(/&gt;/g, ">")
          .replace(/&quot;/g, '"')
          .replace(/&#39;/g, "'")
          .replace(/&#x27;/g, "'");

        // Now escape properly
        const escapedCode = decodedCode
          .replace(/&/g, "&amp;")
          .replace(/</g, "&lt;")
          .replace(/>/g, "&gt;")
          .replace(/"/g, "&quot;")
          .replace(/'/g, "&#39;");

        if (lang) {
          const sanitizedLang = lang.replace(/[^a-zA-Z0-9-_]/g, "");
          return `<pre><code class="language-${sanitizedLang}">${escapedCode}</code></pre>`;
        }

        return `<pre><code>${escapedCode}</code></pre>`;
      }
    );

    // THIRD: Escape HTML tags that aren't in our allowed list
    // This handles cases like <b>, <i>, etc. that aren't dangerous but should be escaped
    // Store code blocks temporarily to avoid escaping their content
    const codeBlockPlaceholders: { placeholder: string; content: string }[] = [];
    let placeholderIndex = 0;

    html = html.replace(/<pre><code[^>]*>[\s\S]*?<\/code><\/pre>/gi, (match) => {
      const placeholder = `__CODE_BLOCK_${placeholderIndex}__`;
      codeBlockPlaceholders.push({ placeholder, content: match });
      placeholderIndex++;
      return placeholder;
    });

    // Escape HTML tags that aren't in our allowed list
    html = html.replace(/<(\/?)(?!\/?(?:p|br|strong|em|h[1-6]|ul|ol|li|blockquote|pre|code|a|img)\b)[a-z][^>]*>/gi, (match) => {
      return match
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;");
    });

    // Restore code blocks
    codeBlockPlaceholders.forEach(({ placeholder, content }) => {
      html = html.replace(placeholder, content);
    });

    return html;
  } catch (error) {
    console.error("Error sanitizing markdown:", error);
    return "";
  }
}

export function extractPlainText(markdown: string): string {
  if (!markdown || typeof markdown !== "string") {
    return "";
  }

  return markdown
    .replace(/#+\s*/g, "")
    .replace(/\*\*(.*?)\*\*/g, "$1")
    .replace(/\*(.*?)\*/g, "$1")
    .replace(/~~(.*?)~~/g, "$1")
    .replace(/`(.*?)`/g, "$1")
    .replace(/\[(.*?)\]\(.*?\)/g, "$1")
    .replace(/!\[(.*?)\]\(.*?\)/g, "$1")
    .replace(/>\s*/g, "")
    .replace(/^\s*[-*+]\s+/gm, "")
    .replace(/^\s*\d+\.\s+/gm, "")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

export function generateSummary(content: string, maxLength = 280): string {
  const plainText = extractPlainText(content);
  if (plainText.length <= maxLength) {
    return plainText;
  }

  const truncated = plainText.substring(0, maxLength);
  const lastSpace = truncated.lastIndexOf(" ");

  if (lastSpace > maxLength * 0.8) {
    return truncated.substring(0, lastSpace) + "...";
  }

  return truncated + "...";
}

