}

export function convertEditorJSToMarkdown(editorData: EditorJSOutput | string | null | undefined): string {
  // Handle string input (JSON string)
  let parsedData: EditorJSOutput | null = null;
  if (typeof editorData === "string") {
    try {
      parsedData = JSON.parse(editorData) as EditorJSOutput;
    } catch {
      return "";
    }
  } else if (editorData && typeof editorData === "object") {
    parsedData = editorData;
  }

  if (!parsedData?.blocks || !Array.isArray(parsedData.blocks)) {
    return "";
  }

  let markdown = "";

  parsedData.blocks.forEach((block: EditorJSBlock) => {
    const data = block.data;

    switch (block.type) {
      case "header": {
        const level = "#".repeat((typeof data.level === "number" ? data.level : 1));
        const text = typeof data.text === "string" ? data.text : "";
        markdown += `${level} ${text}\n\n`;
        break;
      }

      case "paragraph": {
        const text = typeof data.text === "string" ? data.text : "";
        markdown += `${text}\n\n`;
        break;
      }

      case "list": {
        const style = data.style;
        const items = Array.isArray(data.items) ? data.items : [];
        if (style === "ordered") {
          items.forEach((item: unknown, index: number) => {
            const itemText = typeof item === "string" ? item : String(item);
            markdown += `${index + 1}. ${itemText}\n`;
          });
        } else {
          items.forEach((item: unknown) => {
            const itemText = typeof item === "string" ? item : String(item);
            markdown += `- ${itemText}\n`;
          });
        }
        markdown += "\n";
        break;
      }

      case "quote": {
        const text = typeof data.text === "string" ? data.text : "";
        markdown += `> ${text}\n`;
        if (data.caption && typeof data.caption === "string") {
          markdown += `> \n> — ${data.caption}\n`;
        }
        markdown += "\n";
        break;
      }

      case "code": {
        const code = typeof data.code === "string" ? data.code : "";
        markdown += "```\n";
        markdown += code;
        markdown += "\n```\n\n";
        break;
      }

      case "linkTool": {
        const link = typeof data.link === "string" ? data.link : "";
        const meta = data.meta && typeof data.meta === "object" ? data.meta as Record<string, unknown> : {};
        const title = typeof meta.title === "string" ? meta.title : null;
        if (title) {
          markdown += `[${title}](${link})\n\n`;
        } else {
          markdown += `${link}\n\n`;
        }
        break;
      }

      case "embed": {
        const service = typeof data.service === "string" ? data.service : "";
        const source = typeof data.source === "string" ? data.source : "";
        if (service === "youtube") {
          markdown += `[![YouTube Video](https://img.youtube.com/vi/${source}/0.jpg)](${source})\n\n`;
        } else {
          markdown += `${source}\n\n`;
        }
        break;
      }

      case "image": {
        const file = data.file && typeof data.file === "object" ? data.file as Record<string, unknown> : null;
        const fileUrl = file && typeof file.url === "string" ? file.url : null;
        const url = typeof data.url === "string" ? data.url : null;
        const imageUrl = fileUrl || url;
        const caption = typeof data.caption === "string" ? data.caption : "";
        if (imageUrl) {
          if (caption && caption.trim()) {
            markdown += `![${caption}](${imageUrl})\n\n`;
          } else {
            markdown += `![](${imageUrl})\n\n`;
          }
        }
        break;
      }

      default: {
        const text = typeof data.text === "string" ? data.text : null;
        if (text) {
          markdown += `${text}\n\n`;
        }
        break;
      }
    }
  });

  return markdown.trim();
}

export function convertMarkdownToEditorJS(markdown: string): EditorJSOutput {
  if (!markdown || markdown.trim() === "") {
    return { blocks: [] };
  }

  const blocks: EditorJSBlock[] = [];
  const lines = markdown.split("\n");
  let i = 0;

  while (i < lines.length) {
    const line = lines[i].trim();

    if (line === "") {
      i++;
      continue;
    }

    // Headers
    if (line.startsWith("#")) {
      const level = line.match(/^#+/)?.[0].length || 1;
      const text = line.replace(/^#+\s*/, "");
      blocks.push({
        id: generateBlockId(),
        type: "header",
        data: {
          text: text,
          level: Math.min(Math.max(level, 1), 6),
        },
      });
    }
    // Images
    else if (line.match(/^!\[([^\]]*)\]\(([^)]+)\)$/)) {
      const match = line.match(/^!\[([^\]]*)\]\(([^)]+)\)$/);
      if (match) {
        const [, caption, url] = match;
        blocks.push({
          id: generateBlockId(),
          type: "image",
          data: {
            file: {
              url: url,
            },
            caption: caption || "",
            withBorder: false,
            withBackground: false,
            stretched: false,
          },
        });
      }
    }
    // Blockquotes
    else if (line.startsWith("> ")) {
      let quoteText = "";
      let caption = "";

      // Collect all consecutive quote lines
      while (i < lines.length && lines[i].trim().startsWith("> ")) {
        const quoteLine = lines[i].trim().substring(2);
        if (quoteLine.startsWith("— ")) {
          caption = quoteLine.substring(2);
        } else if (quoteLine !== "") {
          if (quoteText) quoteText += " ";
          quoteText += quoteLine;
        }
        i++;
      }
      i--; // Adjust for the loop increment

      blocks.push({
        id: generateBlockId(),
        type: "quote",
        data: {
          text: quoteText,
          caption: caption,
        },
      });
    }
    // Code blocks
    else if (line === "```") {
      let code = "";
      i++; // Skip the opening ```

      while (i < lines.length && lines[i].trim() !== "```") {
        if (code) code += "\n";
        code += lines[i];
        i++;
      }

      blocks.push({
        id: generateBlockId(),
        type: "code",
        data: {
          code: code,
        },
      });
    }
    // Ordered lists
    else if (line.match(/^\d+\.\s/)) {
      const items: string[] = [];

      while (i < lines.length && lines[i].trim().match(/^\d+\.\s/)) {
        const item = lines[i].trim().replace(/^\d+\.\s/, "");
        items.push(item);
        i++;
      }
      i--; // Adjust for the loop increment

      blocks.push({
        id: generateBlockId(),
        type: "list",
        data: {
          style: "ordered",
          items: items,
        },
      });
    }
    // Unordered lists
    else if (line.startsWith("- ")) {
      const items: string[] = [];

      while (i < lines.length && lines[i].trim().startsWith("- ")) {
        const item = lines[i].trim().substring(2);
        items.push(item);
        i++;
      }
      i--; // Adjust for the loop increment

      blocks.push({
        id: generateBlockId(),
        type: "list",
        data: {
          style: "unordered",
          items: items,
        },
      });
    }
    // Links (simple detection)
    else if (line.match(/^\[([^\]]+)\]\(([^)]+)\)$/)) {
      const match = line.match(/^\[([^\]]+)\]\(([^)]+)\)$/);
      if (match) {
        const [, title, url] = match;
        blocks.push({
          id: generateBlockId(),
          type: "linkTool",
          data: {
            link: url,
            meta: {
              title: title,
            },
          },
        });
      }
    }
    // Regular paragraphs
    else if (line) {
      // Collect consecutive non-empty lines for paragraph
      let paragraphText = line;
      let j = i + 1;

      while (
        j < lines.length &&
        lines[j].trim() !== "" &&
        !lines[j].trim().startsWith("#") &&
        !lines[j].trim().startsWith("> ") &&
        !lines[j].trim().startsWith("- ") &&
        !lines[j].trim().match(/^\d+\.\s/) &&
        lines[j].trim() !== "```" &&
        !lines[j].trim().match(/^!\[([^\]]*)\]\(([^)]+)\)$/)
      ) {
        paragraphText += " " + lines[j].trim();
        j++;
      }

      blocks.push({
        id: generateBlockId(),
        type: "paragraph",
        data: {
          text: paragraphText,
        },
      });

      i = j - 1; // Set i to the last line we processed
    }

    i++;
  }

  return {
    blocks: blocks,
  };
}

function generateBlockId(): string {
  return Math.random().toString(36).substr(2, 9);
}

import WebSocket from "ws";

type CacheParams = Record<string, unknown>;
type CacheResponse = unknown[];

/**
 * Gets Primal cache endpoints from environment variable or uses defaults
 * Supports comma-separated list of WebSocket URLs
 */
function getCacheEndpoints(): string[] {
  const envUrl = process.env.PRIMAL_CACHING_URL;

  if (envUrl) {
    // Support comma-separated list of endpoints
    const endpoints = envUrl.split(",").map((url) => url.trim()).filter(Boolean);
    if (endpoints.length > 0) {
      return endpoints;
    }
  }

  // Default fallback endpoints (public Primal cache servers only)
  return [
    "wss://cache1.primal.net/v1",
    "wss://cache2.primal.net/v1",
  ];
}

async function tryConnectToCache(
  endpoint: string,
  requestType: string,
  params: CacheParams,
): Promise<CacheResponse> {
  return new Promise((resolve, reject) => {
    let resolved = false;
    const ws: WebSocket = new WebSocket(endpoint);
    const requestId = Math.random().toString(36).substring(2, 12);
    const responses: unknown[] = [];

    ws.onopen = () => {
      switch (requestType) {
        case "net_stats":
          ws.send(JSON.stringify(["REQ", requestId, { cache: ["net_stats"] }]));
          break;
        case "feed":
          ws.send(
            JSON.stringify([
              "REQ",
              requestId,
              { cache: ["feed", { pubkey: params.pubkey }] },
            ]),
          );
          break;
        case "thread_view": {
          const threadViewMsg = JSON.stringify([
            "REQ",
            requestId,
            { cache: ["thread_view", { event_id: params.event_id }] },
          ]);
          ws.send(threadViewMsg);
          break;
        }
        case "user_infos":
          ws.send(
            JSON.stringify([
              "REQ",
              requestId,
              { cache: ["user_infos", { pubkeys: params.pubkeys }] },
            ]),
          );
          break;
        case "events":
          ws.send(
            JSON.stringify([
              "REQ",
              requestId,
              { cache: ["events", { event_ids: params.event_ids }] },
            ]),
          );
          break;
        case "user_profile":
          ws.send(
            JSON.stringify([
              "REQ",
              requestId,
              { cache: ["user_profile", { pubkey: params.pubkey }] },
            ]),
          );
          break;
        // ---- Added request types below ----

        // Get reposts (kind: 6)
        case "reposts":
          ws.send(
            JSON.stringify([
              "REQ",
              requestId,
              {
                cache: [
                  "event_actions",
                  {
                    event_id: params.event_id,
                    kind: 6,
                    limit: params.limit ?? 100,
                  },
                ],
              },
            ]),
          );
          break;

        // Get likes/reactions (kind: 7)
        case "likes":
          ws.send(
            JSON.stringify([
              "REQ",
              requestId,
              {
                cache: [
                  "event_actions",
                  {
                    event_id: params.event_id,
                    kind: 7,
                    limit: params.limit ?? 100,
                  },
                ],
              },
            ]),
          );
          break;

        // Get replies (kind: 1)
        case "replies":
          ws.send(
            JSON.stringify([
              "REQ",
              requestId,
              {
                cache: [
                  "event_actions",
                  {
                    event_id: params.event_id,
                    kind: 1,
                    limit: params.limit ?? 100,
                  },
                ],
              },
            ]),
          );
          break;

        // Get zaps (kind: 9735)
        case "zaps":
          ws.send(
            JSON.stringify([
              "REQ",
              requestId,
              {
                cache: [
                  "event_actions",
                  {
                    event_id: params.event_id,
                    kind: 9735,
                    limit: params.limit ?? 100,
                  },
                ],
              },
            ]),
          );
          break;

        // ---- End of added request types ----
        default:
          ws.close();
          reject(new Error("Invalid request type"));
          return;
      }
    };

    ws.onmessage = (event: { data: { toString(): string } }) => {
      const data = JSON.parse(event.data.toString()) as unknown;
      const dataArray = Array.isArray(data) ? data : [];
      responses.push(dataArray);

      if (dataArray[0] === "EOSE") {
        ws.send(JSON.stringify(["CLOSE", requestId]));
        ws.close();
        if (!resolved) {
          resolved = true;
          resolve(responses);
        }
      }
    };

    ws.onerror = (error: Error) => {
      console.error(`[WS] WebSocket error on ${endpoint}:`, error);
      ws.close();
      if (!resolved) {
        resolved = true;
        reject(error);
      }
    };

    ws.onclose = () => {
      // If ws closed before resolved, must reject if not already handled
      if (!resolved) {
        resolved = true;
        resolve(responses);
      }
    };

    // timeout in case hangs forever
    setTimeout(() => {
      if (!resolved) {
        resolved = true;
        try {
          ws.close();
        } catch {
          // Ignore errors when closing WebSocket during timeout
        }
        resolve(responses);
      }
    }, 6000);
  });
}

/**
 * Attempts each Primal cache endpoint, returning the first successful non-empty response.
 * Uses PRIMAL_CACHING_URL from environment (comma-separated for multiple endpoints),
 * or falls back to default endpoints if not configured.
 */
export async function connectToPrimalCache(
  requestType: string,
  params: CacheParams,
): Promise<CacheResponse> {
  const endpoints = getCacheEndpoints();

  for (const endpoint of endpoints) {
    try {
      const responses = await tryConnectToCache(endpoint, requestType, params);

      // A "good" response: has at least one element that's not ["EOSE"]
      const nonEose = responses?.filter(
        (res): res is unknown[] => Array.isArray(res) && res[0] !== "EOSE",
      );

      if (nonEose && nonEose.length > 0) {
        return responses;
      }
      // else, try next endpoint
    } catch (err) {
      console.error(`[Cache] ${endpoint} failed with error:`, err);
      // try next endpoint
      continue;
    }
  }
  // All endpoints failed or gave empty responses
  console.error("[Cache] All endpoints failed or gave empty responses");
  throw new Error("All Primal cache endpoints failed or gave empty responses.");
}

import { PrismaClient } from "@prisma/client";
import invariant from "tiny-invariant";

import { recordQueryMetrics } from "./query-metrics.server";
import { singleton } from "./singleton.server";
// Hard-code a unique key, so we can look up the client when this module gets re-imported
const prisma = singleton("prisma", getPrismaClient);

function getPrismaClient() {
  const { DATABASE_URL } = process.env;
  invariant(typeof DATABASE_URL === "string", "DATABASE_URL env var not set");

  const databaseUrl = new URL(DATABASE_URL);

  const isLocalHost = databaseUrl.hostname === "localhost";

  const PRIMARY_REGION = isLocalHost ? null : process.env.PRIMARY_REGION;
  const FLY_REGION = isLocalHost ? null : process.env.FLY_REGION;

  const isReadReplicaRegion = !PRIMARY_REGION || PRIMARY_REGION === FLY_REGION;

  if (!isLocalHost) {
    if (databaseUrl.host.endsWith(".internal")) {
      databaseUrl.host = `${FLY_REGION}.${databaseUrl.host}`;
    }

    if (!isReadReplicaRegion) {
      // 5433 is the read-replica port
      databaseUrl.port = "5433";
    }
  }

  // NOTE: during development if you change anything in this function, remember
  // that this only runs once per server restart and won't automatically be
  // re-run per request like everything else is. So if you need to change
  // something in this file, you'll need to manually restart the server.
  const baseClient = new PrismaClient({
    datasources: {
      db: {
        url: databaseUrl.toString(),
      },
    },
    // Enable query logging in development for performance monitoring
    log: process.env.NODE_ENV === "development" 
      ? ["query", "info", "warn", "error"]
      : ["error"],
  });

  // Add query performance monitoring middleware using $extends (Prisma 5+)
  const client = baseClient.$extends({
    query: {
      $allModels: {
        async $allOperations({ model, operation, args, query }) {
          const before = Date.now();
          let error: Error | undefined;

          try {
            const result = await query(args);
            const after = Date.now();
            const duration = after - before;

            // Record metrics
            recordQueryMetrics(
              model || "unknown",
              operation,
              duration,
              true,
            );

            // Log slow queries (over 100ms)
            if (duration > 100) {
              // eslint-disable-next-line no-console
              console.warn(
                `⚠️ Slow query detected: ${model}.${operation} took ${duration}ms`,
                {
                  model,
                  operation,
                  duration,
                  args,
                },
              );
            }

            return result;
          } catch (err) {
            error = err instanceof Error ? err : new Error(String(err));
            const after = Date.now();
            const duration = after - before;

            // Record error metrics
            recordQueryMetrics(
              model || "unknown",
              operation,
              duration,
              false,
              error,
            );

            // Log query errors
            // eslint-disable-next-line no-console
            console.error(
              `❌ Query error: ${model}.${operation} failed after ${duration}ms`,
              {
                model,
                operation,
                error: error.message,
                duration,
              },
            );

            throw err;
          }
        },
      },
    },
  });

  // connect eagerly
  client.$connect();

  return client;
}

export { prisma };

/**
 * Query Batching Utilities
 * 
 * Provides utilities for batching database queries to prevent N+1 query problems.
 * These functions help optimize database access by loading related data in batches.
 */

import type { User, QueueType, HashTagPreset, Template } from "@prisma/client";

import { prisma } from "~/lib/prisma.server";

/**
 * Batch load users by their IDs
 * Returns a Map for O(1) lookup
 */
export async function batchLoadUsers(
  userIds: string[],
): Promise<Map<string, Pick<User, "id" | "npub" | "timezone" | "isEnabled" | "createdAt" | "updatedAt">>> {
  if (userIds.length === 0) {
    return new Map();
  }

  const uniqueIds = [...new Set(userIds)];
  const users = await prisma.user.findMany({
    where: { id: { in: uniqueIds } },
    select: {
      id: true,
      npub: true,
      timezone: true,
      isEnabled: true,
      createdAt: true,
      updatedAt: true,
      // Add other commonly needed fields
    },
  });

  return new Map(users.map((user) => [user.id, user]));
}

/**
 * Batch load queue types by their IDs
 * Returns a Map for O(1) lookup
 */
export async function batchLoadQueueTypes(
  queueTypeIds: (string | null)[],
): Promise<Map<string, QueueType>> {
  const validIds = queueTypeIds.filter(
    (id): id is string => id !== null && id !== undefined,
  );

  if (validIds.length === 0) {
    return new Map();
  }

  const uniqueIds = [...new Set(validIds)];
  const queueTypes = await prisma.queueType.findMany({
    where: { id: { in: uniqueIds } },
  });

  return new Map(queueTypes.map((qt) => [qt.id, qt]));
}

/**
 * Batch load hashtag presets by their IDs
 * Returns a Map for O(1) lookup
 */
export async function batchLoadHashTagPresets(
  hashTagPresetIds: (string | null)[],
): Promise<Map<string, HashTagPreset>> {
  const validIds = hashTagPresetIds.filter(
    (id): id is string => id !== null && id !== undefined,
  );

  if (validIds.length === 0) {
    return new Map();
  }

  const uniqueIds = [...new Set(validIds)];
  const hashTagPresets = await prisma.hashTagPreset.findMany({
    where: { id: { in: uniqueIds } },
  });

  return new Map(hashTagPresets.map((htp) => [htp.id, htp]));
}

/**
 * Batch load templates by their IDs
 * Returns a Map for O(1) lookup
 */
export async function batchLoadTemplates(
  templateIds: (string | null)[],
): Promise<Map<string, Template>> {
  const validIds = templateIds.filter(
    (id): id is string => id !== null && id !== undefined,
  );

  if (validIds.length === 0) {
    return new Map();
  }

  const uniqueIds = [...new Set(validIds)];
  const templates = await prisma.template.findMany({
    where: { id: { in: uniqueIds } },
  });

  return new Map(templates.map((template) => [template.id, template]));
}

/**
 * Batch load all related data for posts
 * This is useful when you have posts and need to load all their relations
 */
export async function batchLoadPostRelations(ids: {
  queueTypeIds: (string | null)[];
  hashTagPresetIds: (string | null)[];
  templateIds: (string | null)[];
}): Promise<{
  queueTypes: Map<string, QueueType>;
  hashTagPresets: Map<string, HashTagPreset>;
  templates: Map<string, Template>;
}> {
  const [queueTypes, hashTagPresets, templates] = await Promise.all([
    batchLoadQueueTypes(ids.queueTypeIds),
    batchLoadHashTagPresets(ids.hashTagPresetIds),
    batchLoadTemplates(ids.templateIds),
  ]);

  return {
    queueTypes,
    hashTagPresets,
    templates,
  };
}

/**
 * Rate Limiting Middleware
 * 
 * Provides rate limiting functionality to protect against abuse, DDoS attacks, and API exhaustion.
 * Uses both in-memory (express-rate-limit) and Redis-based (rate-limiter-flexible) rate limiting.
 */

import type { Request, Response, NextFunction } from "express";
import rateLimit from "express-rate-limit";
import { RateLimiterRedis } from "rate-limiter-flexible";

import { redis } from "~/infra/queue/queue-client.server";
import { RateLimitError } from "~/lib/errors";

/**
 * General API rate limiter
 * Limits: 100 requests per 15 minutes per IP
 */
export const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per window
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  message: "Too many requests, please try again later.",
  handler: (req: Request, res: Response) => {
    res.status(429).json({
      error: "Rate limit exceeded",
      message: "Too many requests, please try again later.",
      retryAfter: Math.ceil((req.rateLimit?.resetTime ?? Date.now() + 15 * 60 * 1000 - Date.now()) / 1000),
    });
  },
});

/**
 * Strict rate limiter for sensitive endpoints
 * Limits: 10 requests per 15 minutes per IP
 */
export const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 10, // 10 requests per window
  standardHeaders: true,
  legacyHeaders: false,
  message: "Rate limit exceeded for this endpoint.",
  handler: (req: Request, res: Response) => {
    res.status(429).json({
      error: "Rate limit exceeded",
      message: "Rate limit exceeded for this endpoint. Please try again later.",
      retryAfter: Math.ceil((req.rateLimit?.resetTime ?? Date.now() + 15 * 60 * 1000 - Date.now()) / 1000),
    });
  },
});

/**
 * Very strict rate limiter for authentication endpoints
 * Limits: 5 requests per 15 minutes per IP
 */
export const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // 5 requests per window
  standardHeaders: true,
  legacyHeaders: false,
  message: "Too many authentication attempts, please try again later.",
  handler: (req: Request, res: Response) => {
    res.status(429).json({
      error: "Rate limit exceeded",
      message: "Too many authentication attempts, please try again later.",
      retryAfter: Math.ceil((req.rateLimit?.resetTime ?? Date.now() + 15 * 60 * 1000 - Date.now()) / 1000),
    });
  },
});

/**
 * Check if Redis is available for rate limiting
 */
function isRedisAvailable(): boolean {
  return !!process.env.REDIS_URL && redis.status === "ready";
}

/**
 * Per-user rate limiting middleware
 * Uses Redis for distributed rate limiting across multiple server instances
 * 
 * @param points - Number of requests allowed
 * @param duration - Time window in seconds
 */
export function createUserRateLimiter(
  points = 100,
  duration = 60,
) {
  return async (req: Request, res: Response, next: NextFunction) => {
    // Get user ID from request (set by auth middleware)
    const userId = req.user?.id;

    if (!userId) {
      // No user ID, skip rate limiting (will be handled by IP-based limiter)
      return next();
    }

    if (!isRedisAvailable()) {
      // Redis not available, skip Redis-based rate limiting
      return next();
    }

    try {
      // Create a per-user limiter with custom points/duration
      const userLimiter = new RateLimiterRedis({
        storeClient: redis,
        keyPrefix: `rl:user`,
        points,
        duration,
        blockDuration: duration,
      });

      await userLimiter.consume(userId);
      next();
    } catch (error: unknown) {
      // Rate limit exceeded
      // rate-limiter-flexible throws errors with msBeforeNext property
      const rateLimitError = error as { msBeforeNext?: number };
      const retryAfter = rateLimitError.msBeforeNext 
        ? Math.ceil(rateLimitError.msBeforeNext / 1000)
        : duration;

      res.status(429).json({
        error: "Rate limit exceeded",
        message: "Too many requests, please try again later.",
        retryAfter,
      });
    }
  };
}

/**
 * Per-IP rate limiting using Redis (for distributed systems)
 * Falls back to in-memory limiter if Redis is not available
 */
export function createIPRateLimiter(
  points = 100,
  duration = 60,
) {
  return async (req: Request, res: Response, next: NextFunction) => {
    if (!isRedisAvailable()) {
      // Redis not available, skip Redis-based rate limiting
      // Will be handled by express-rate-limit middleware
      return next();
    }

    const ip = req.ip || req.socket.remoteAddress || "unknown";

    try {
      const ipLimiter = new RateLimiterRedis({
        storeClient: redis,
        keyPrefix: `rl:ip`,
        points,
        duration,
        blockDuration: duration,
      });

      await ipLimiter.consume(ip);
      next();
    } catch (error: unknown) {
      // Rate limit exceeded
      // rate-limiter-flexible throws errors with msBeforeNext property
      const rateLimitError = error as { msBeforeNext?: number };
      const retryAfter = rateLimitError.msBeforeNext 
        ? Math.ceil(rateLimitError.msBeforeNext / 1000)
        : duration;

      res.status(429).json({
        error: "Rate limit exceeded",
        message: "Too many requests from this IP, please try again later.",
        retryAfter,
      });
    }
  };
}

/**
 * Helper to get rate limit info for a user
 * Useful for displaying rate limit status to users
 */
export function getRateLimitInfo(userId: string): Promise<{
  remaining: number;
  resetTime: number;
} | null> {
  if (!isRedisAvailable()) {
    return null;
  }

  try {
    const userLimiter = new RateLimiterRedis({
      storeClient: redis,
      keyPrefix: `rl:user`,
      points: 100,
      duration: 60,
    });

    const info = await userLimiter.get(userId);

    if (!info) {
      return {
        remaining: 100, // Default points
        resetTime: Date.now() + 60 * 1000, // Default duration
      };
    }

    return {
      remaining: info.remainingPoints,
      resetTime: Date.now() + info.msBeforeNext,
    };
  } catch (error) {
    console.error("Error getting rate limit info:", error);
    return null;
  }
}

/**
 * Pure utility functions for schedule time formatting
 * This file has no server-side dependencies and can be safely imported in tests
 */

/**
 * Formats a Date object for use in HTML datetime-local input
 * @param date - The date to format
 * @param userTimezone - The user's timezone (defaults to UTC)
 * @returns Formatted date string in YYYY-MM-DDTHH:mm format
 */
export function formatScheduleTimeForInput(
  date: Date,
  userTimezone = "UTC",
): string {
  try {
    // For UTC/GMT timezones, use the date directly
    if (userTimezone === "UTC" || userTimezone === "Etc/GMT") {
      const year = date.getUTCFullYear();
      const month = String(date.getUTCMonth() + 1).padStart(2, "0");
      const day = String(date.getUTCDate()).padStart(2, "0");
      const hours = String(date.getUTCHours()).padStart(2, "0");
      const minutes = String(date.getUTCMinutes()).padStart(2, "0");

      const result = `${year}-${month}-${day}T${hours}:${minutes}`;
      return result;
    }

    // Convert UTC date to user's timezone for display in datetime-local input
    // Use a more reliable approach: get individual date components in user timezone
    const formatter = new Intl.DateTimeFormat('en-CA', {
      timeZone: userTimezone,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      hour12: false,
    });

    const parts = formatter.formatToParts(date);
    const partsObj = parts.reduce((acc, part) => {
      acc[part.type] = part.value;
      return acc;
    }, {} as Record<string, string>);

    // Format for datetime-local input: YYYY-MM-DDTHH:MM
    const result = `${partsObj.year}-${partsObj.month}-${partsObj.day}T${partsObj.hour}:${partsObj.minute}`;

    return result;
  } catch (error) {
    console.error("Error in formatScheduleTimeForInput:", error, {
      date,
      userTimezone,
    });
    // Fallback to UTC formatting
    const year = date.getUTCFullYear();
    const month = String(date.getUTCMonth() + 1).padStart(2, "0");
    const day = String(date.getUTCDate()).padStart(2, "0");
    const hours = String(date.getUTCHours()).padStart(2, "0");
    const minutes = String(date.getUTCMinutes()).padStart(2, "0");

    return `${year}-${month}-${day}T${hours}:${minutes}`;
  }
}

/**
 * Secrets Sanitization Utility
 * 
 * Prevents sensitive data (NWC strings, secrets, etc.) from appearing in logs or error messages
 */

/**
 * Patterns that indicate sensitive data
 */
const SENSITIVE_PATTERNS = [
  /nostr\+walletconnect:\/\/[^\s"']+/gi, // NWC connection strings
  /nsec1[a-z0-9]+/gi, // Nostr secret keys
  /encryptedNwc/gi, // Encrypted NWC field names
  /SESSION_SECRET/gi,
  /DATABASE_URL/gi,
  /REDIS_URL/gi,
  /STORAGE_(ACCESS_KEY|SECRET)/gi,
  /NOSTR_NSEC/gi,
  /OWNER_NWC/gi,
];

/**
 * Replace sensitive data with [REDACTED]
 */
export function sanitizeString(input: string): string {
  let sanitized = input;

  for (const pattern of SENSITIVE_PATTERNS) {
    sanitized = sanitized.replace(pattern, "[REDACTED]");
  }

  return sanitized;
}

/**
 * Sanitize an object recursively, removing or masking sensitive fields
 */
export function sanitizeObject<T>(obj: T): T {
  if (obj === null || obj === undefined) {
    return obj;
  }

  if (typeof obj === "string") {
    return sanitizeString(obj) as T;
  }

  if (Array.isArray(obj)) {
    return obj.map((item) => sanitizeObject(item)) as T;
  }

  if (typeof obj === "object") {
    const sanitized = {} as Record<string, unknown>;
    for (const [key, value] of Object.entries(obj)) {
      const lowerKey = key.toLowerCase();

      // Check if key indicates sensitive data
      if (
        lowerKey.includes("nwc") ||
        lowerKey.includes("secret") ||
        lowerKey.includes("password") ||
        lowerKey.includes("token") ||
        lowerKey.includes("key") ||
        lowerKey.includes("encrypted")
      ) {
        sanitized[key] = "[REDACTED]";
      } else {
        sanitized[key] = sanitizeObject(value);
      }
    }
    return sanitized as T;
  }

  return obj;
}

/**
 * Sanitize error message and stack trace
 */
export function sanitizeError(error: Error | unknown): {
  message: string;
  stack?: string;
  name: string;
} {
  if (error instanceof Error) {
    return {
      name: error.name,
      message: sanitizeString(error.message),
      stack: error.stack ? sanitizeString(error.stack) : undefined,
    };
  }

  return {
    name: "Error",
    message: sanitizeString(String(error)),
  };
}

/**
 * Safe console.error that sanitizes sensitive data
 */
export function safeConsoleError(
  message: string,
  ...args: unknown[]
): void {
  const sanitizedMessage = sanitizeString(message);
  const sanitizedArgs = args.map((arg) => {
    if (typeof arg === "string") {
      return sanitizeString(arg);
    }
    if (typeof arg === "object" && arg !== null) {
      return sanitizeObject(arg);
    }
    return arg;
  });

  console.error(sanitizedMessage, ...sanitizedArgs);
}

/**
 * Safe console.log that sanitizes sensitive data
 */
export function safeConsoleLog(
  message: string,
  ...args: unknown[]
): void {
  const sanitizedMessage = sanitizeString(message);
  const sanitizedArgs = args.map((arg) => {
    if (typeof arg === "string") {
      return sanitizeString(arg);
    }
    if (typeof arg === "object" && arg !== null) {
      return sanitizeObject(arg);
    }
    return arg;
  });

  console.log(sanitizedMessage, ...sanitizedArgs);
}

/**
 * Sentry Client-side Initialization
 * 
 * Initializes Sentry for client-side error tracking
 * Only initializes if SENTRY_DSN is configured
 */

let sentryInitialized = false;

/**
 * Initialize Sentry for client-side error tracking
 * Should be called early in the application lifecycle (e.g., in entry.client.tsx)
 */
export function initSentry(): void {
  if (sentryInitialized || typeof window === "undefined") {
    return;
  }

  // Get DSN from window.ENV (set by root.tsx)
  const dsn = (window as { ENV?: { SENTRY_DSN?: string } }).ENV?.SENTRY_DSN ?? null;

  if (!dsn) {
    // Sentry not configured - that's okay, just return
    return;
  }

  try {
    // Use dynamic import for async initialization
    void (async () => {
      try {
        const Sentry = await import("@sentry/remix");
        const isProduction = (window as { ENV?: { NODE_ENV?: string } }).ENV?.NODE_ENV === "production" || false;

        Sentry.init({
          dsn,
          environment: isProduction ? "production" : "development",
          // Lower sample rate for client-side to reduce noise
          tracesSampleRate: isProduction ? 0.1 : 1.0,
          // Enable session replay in production (optional)
          replaysSessionSampleRate: isProduction ? 0.1 : 1.0,
          replaysOnErrorSampleRate: 1.0, // Always capture replays on errors
          // Filter out noise
          beforeSend(event, hint) {
            // Don't send events for browser extensions, etc.
            if (event.exception?.values?.[0]?.value?.includes("Non-Error promise rejection")) {
              return null;
            }
            return event;
          },
          // Configure integrations
          integrations: [
            Sentry.replayIntegration(),
          ],
        });

        sentryInitialized = true;
      } catch (error) {
        // Fail silently if Sentry can't be initialized
        // This allows the app to continue working even if Sentry is misconfigured
        console.error("Failed to initialize Sentry:", error);
      }
    })();
  } catch (error) {
    // Fail silently if Sentry can't be initialized
    // This allows the app to continue working even if Sentry is misconfigured
    console.error("Failed to initialize Sentry:", error);
  }
}

/**
 * Check if Sentry is initialized
 */
export function isSentryInitialized(): boolean {
  return sentryInitialized;
}

/**
 * Capture an exception in Sentry (client-side)
 * Safe to call even if Sentry is not initialized
 */
export function captureException(
  error: Error,
  context?: {
    tags?: Record<string, string>;
    extra?: Record<string, unknown>;
    user?: { id?: string; email?: string };
    level?: "fatal" | "error" | "warning" | "info" | "debug";
  },
): void {
  if (!sentryInitialized || typeof window === "undefined") {
    return;
  }

  try {
    void (async () => {
      try {
        const Sentry = await import("@sentry/remix");
        Sentry.captureException(error, {
          tags: context?.tags,
          extra: context?.extra,
          user: context?.user,
          level: context?.level ?? "error",
        });
      } catch {
        // Fail silently
      }
    })();
  } catch (err) {
    // Fail silently - don't break the app if Sentry fails
    console.error("Failed to capture exception in Sentry:", err);
  }
}

