export async function updateTemplate({
  id,
  userId,
  name,
  postIds,
}: {
  id: string;
  userId: string;
  name?: string;
  postIds?: string[];
}) {
  const updateData: Prisma.TemplateUpdateInput = {};
  if (name !== undefined) updateData.name = name;
  if (postIds !== undefined) {
    updateData.posts = {
      set: postIds.map((id) => ({ id })),
    };
  }

  return prisma.template.update({
    where: { id, userId },
    data: updateData,
    include: {
      posts: true,
    },
  });
}

