type LoaderData = Awaited<ReturnType<typeof loaderImpl>>;

export default function DraftPosts() {
  const data = useLoaderData<LoaderData>();
  const {
    posts,
    longformPosts,
    allContent,
    user,
    queueTypes,
    selectedQueueType,
  } = data;
  const params = useParams();
  const [searchParams] = useSearchParams();
  const revalidator = useRevalidator();

  // Check if we're on a child route (like edit)
  const isChildRoute = params.id;

  // Get current tab from URL params - default to "all"
  const currentTab = searchParams.get("tab") || "all";

  const {
    sortConfig,
    searchTerm,
    selectedPost,
    selectedPosts,
    showAdvancedBulkResume,
    filteredPosts,
    bulkDeleteFetcher,
    bulkResumeFetcher,
    requestSort,
    setSearchTerm,
    setSelectedPost,
    togglePostSelection,
    toggleSelectAll,
    handleBulkDelete,
    setShowAdvancedBulkResume,
  } = useDraftsState({ posts });

  // If we're on a child route, render the child component
  if (isChildRoute) {
    return <Outlet />;
  }

  return (
    <div>
      <DraftsHeader
        currentTab={currentTab}
        allContentCount={allContent.length}
        postsCount={filteredPosts.length}
        longformCount={longformPosts.length}
      />

      {/* Post Type Tabs */}
      <DraftsPostTypeTabs
        currentTab={currentTab}
        allContentCount={allContent.length}
        postsCount={filteredPosts.length}
        longformCount={longformPosts.length}
        queueType={params.queueType}
      />

      {/* Queue Selection Tabs */}
      {currentTab === "all" ||
      currentTab === "posts" ||
      currentTab === "longform" ? (
        <QueueSelectionTabs
          currentTab={currentTab}
          queueTypes={queueTypes}
          basePath="/dashboard/drafts"
        />
      ) : null}

      {/* Content based on current tab */}
      {currentTab === "all" ? (
        <AllContentListing
          content={allContent}
          type="draft"
          searchTerm={searchTerm}
          onSearchChange={setSearchTerm}
          userTimezone={user?.timezone}
          onPostSelect={(content) => {
            if (content.type === "post") {
              setSelectedPost(content.originalData as unknown as { id: string; content?: string; caption?: string; fileUrl?: string[]; queueType?: { name: string } | null } | null);
            }
          }}
          selectedItems={selectedPosts}
          onToggleSelection={togglePostSelection}
          onToggleSelectAll={toggleSelectAll}
          showBulkActions={true}
          onBulkDelete={handleBulkDelete}
          bulkDeleteState={bulkDeleteFetcher.state}
        />
      ) : currentTab === "posts" ? (
        <div>
          <PostsSearch searchTerm={searchTerm} onSearchChange={setSearchTerm} />

          <DraftsBulkActions
            selectedCount={selectedPosts.size}
            onBulkEdit={() => setShowAdvancedBulkResume(true)}
            onBulkDelete={handleBulkDelete}
            isDeleting={bulkDeleteFetcher.state !== "idle"}
            isResuming={bulkResumeFetcher.state !== "idle"}
          />

          <DraftsTable
            posts={filteredPosts}
            sortConfig={sortConfig}
            onRequestSort={requestSort}
            selectedPosts={selectedPosts}
            onToggleSelection={togglePostSelection}
            onToggleSelectAll={toggleSelectAll}
            onPostClick={(post) => setSelectedPost(post as unknown as { id: string; content?: string; caption?: string; fileUrl?: string[]; queueType?: { name: string } | null } | null)}
            bulkDeleteState={bulkDeleteFetcher.state}
          />

          {selectedPost ? (
            <PostDetailsModal
              post={selectedPost as unknown as { id: string; content?: string; caption?: string; fileUrl?: string[]; queueType?: { name: string } | null }}
              onClose={() => setSelectedPost(null)}
              type="draft"
              userTimezone={user?.timezone ?? undefined}
            />
          ) : null}

          {/* Bulk Edit */}
          {showAdvancedBulkResume ? (
            <div className="fixed inset-0 z-50 bg-white dark:bg-gray-900">
              <DraftBulkResume
                selectedDrafts={filteredPosts.filter((post) =>
                  selectedPosts.has(post.id),
                ) as unknown as { id: string; content?: string; caption?: string; fileUrl?: string[]; queueType?: string; scheduledFor?: string }[]}
                queueTypes={Array.isArray(queueTypes) ? queueTypes as unknown as { id: string; name: string; color?: string | null; scheduleType?: string; scheduleConfig?: unknown; isEnabled?: boolean }[] : []}
                onCancel={() => setShowAdvancedBulkResume(false)}
              />
            </div>
          ) : null}
        </div>
      ) : (
        <LongFormListing
          posts={longformPosts}
          type="draft"
          searchTerm={searchTerm}
          onSearchChange={setSearchTerm}
          userTimezone={user?.timezone}
          onPostSelect={(_post) => {
            // TODO: Add longform post detail modal here if needed
          }}
        />
      )}
    </div>
  );
}

import { json, type LoaderFunctionArgs } from "@remix-run/node";
import { useLoaderData } from "@remix-run/react";

import { requireUserId } from "~/features/auth/session.server";
import { EngagementContent } from "~/features/engagement/components/EngagementContent";
import { EngagementHeader } from "~/features/engagement/components/EngagementHeader";
import { EngagementTabs } from "~/features/engagement/components/EngagementTabs";
import { useEngagementState } from "~/features/engagement/hooks/useEngagementState";
import { loadEngagementFeedData } from "~/features/engagement/services/engagement-loader.server";
import { requireAnySubscription } from "~/features/payments/subscriptions.server";
import PostDetailsModal from "~/features/posts/components/PostDetailsModal";
async function loaderImpl({ request }: LoaderFunctionArgs) {
  const userId = await requireUserId(request);

  // Require that the user has at least a subscription record
  await requireAnySubscription(userId);

  const url = new URL(request.url);
  const page = parseInt(url.searchParams.get("page") || "1");
  const limit = 50; // Get last 50 posts

  const data = await loadEngagementFeedData(userId, page, limit);

  return json(data);
}

export const loader = async ({ request }: LoaderFunctionArgs) => {
  try {
    return await loaderImpl({ request });
  } catch (error) {
    // Return safe default data on error using centralized error handling
    const { handleLoaderError } = await import("~/lib/error-handler.server");
    return handleLoaderError(error, {
      posts: [],
      stats: {},
      user: {},
      notifications: { all: [], replies: [], mentions: [], zaps: [], quotes: [] },
      groupedNotifications: {
        replies: [],
        quotes: [],
      },
      trustScores: {},
    });
  }
};

type LoaderData = Awaited<ReturnType<typeof loaderImpl>>;

interface SafeLoaderData {
  posts: unknown[];
  stats: Record<string, unknown>;
  user: Record<string, unknown> | null;
  groupedNotifications: {
    replies: unknown[];
    quotes: unknown[];
  };
  trustScores: Record<string, unknown>;
}

export default function PostedPosts() {
  const rawData = useLoaderData<LoaderData | SafeLoaderData>();

  // Type guard to safely extract data
  const posts = Array.isArray(rawData?.posts) ? rawData.posts : [];
  const stats = rawData && typeof rawData === "object" && !Array.isArray(rawData) && "stats" in rawData && rawData.stats && typeof rawData.stats === "object" && !Array.isArray(rawData.stats) ? rawData.stats : {};
  const user = rawData && typeof rawData === "object" && !Array.isArray(rawData) && "user" in rawData ? rawData.user : null;
  const groupedNotifications = rawData && typeof rawData === "object" && !Array.isArray(rawData) && "groupedNotifications" in rawData && rawData.groupedNotifications && typeof rawData.groupedNotifications === "object" && !Array.isArray(rawData.groupedNotifications) ? rawData.groupedNotifications : { replies: [], quotes: [] };
  const trustScores = rawData && typeof rawData === "object" && !Array.isArray(rawData) && "trustScores" in rawData && rawData.trustScores && typeof rawData.trustScores === "object" && !Array.isArray(rawData.trustScores) ? rawData.trustScores : {};

  const { selectedPost, activeTab, setSelectedPost, setActiveTab } =
    useEngagementState();

  // Type guard for groupedNotifications
  const safeGroupedNotifications = groupedNotifications;
  const replies = Array.isArray(safeGroupedNotifications.replies) ? safeGroupedNotifications.replies : [];
  const quotes = Array.isArray(safeGroupedNotifications.quotes) ? safeGroupedNotifications.quotes : [];

  // Type guard for user
  const safeUser = user && typeof user === "object" && !Array.isArray(user) ? user : null;
  const userTimezone = safeUser && "timezone" in safeUser && typeof safeUser.timezone === "string" ? safeUser.timezone : undefined;
  const userRelays = safeUser && "userRelays" in safeUser ? safeUser.userRelays : undefined;

  // Type guard for posts
  const safePosts = posts;

  // Type guard for trustScores
  const safeTrustScores = trustScores;

  return (
    <div>
      <EngagementHeader />

      <EngagementTabs
        activeTab={activeTab}
        onTabChange={setActiveTab}
        repliesCount={replies.length}
        quotesCount={quotes.length}
      />

      <EngagementContent
        activeTab={activeTab}
        groupedNotifications={safeGroupedNotifications}
        userTimezone={userTimezone}
        userRelays={userRelays}
        trustScores={safeTrustScores}
        postsCount={safePosts.length}
      />

      {selectedPost ? (
        <PostDetailsModal
          post={selectedPost as unknown as { id: string; caption?: string; fileUrl?: string[]; signedEvent?: unknown; queueType?: { name: string } | null }}
          stats={selectedPost && typeof selectedPost === "object" && "signedEvent" in selectedPost && selectedPost.signedEvent && typeof selectedPost.signedEvent === "object" && "id" in selectedPost.signedEvent && typeof selectedPost.signedEvent.id === "string" && stats && typeof stats === "object" && !Array.isArray(stats) ? stats[selectedPost.signedEvent.id] : undefined}
          onClose={() => setSelectedPost(null)}
          showStats={true}
          showSignedEvent={true}
          type="posted"
          userTimezone={userTimezone}
        />
      ) : null}
    </div>
  );
}

