/**
 * Nostr Event Signing Utilities for Cypress Tests
 *
 * Provides real cryptographic signing using nostr-tools without
 * requiring browser extensions or wallet flows.
 */

import {
    finalizeEvent,
    nip19,
} from "nostr-tools";
import type { EventTemplate } from "nostr-tools";

import { TEST_NSEC, TEST_PUBKEY_HEX } from "./nostr-test-keys";

/**
 * Interface for signed event result
 */
export interface SignedEvent {
    id: string;
    pubkey: string;
    created_at: number;
    kind: number;
    tags: string[][];
    content: string;
    sig: string;
}

/**
 * Decode the nsec to get the secret key bytes
 */
function decodeNsec(nsec: string): Uint8Array {
    const decoded = nip19.decode(nsec);
    if (decoded.type !== "nsec") {
        throw new Error("Invalid nsec format");
    }
    return decoded.data;
}

/**
 * Get test secret key as Uint8Array
 */
export function getTestSecretKey(): Uint8Array {
    return decodeNsec(TEST_NSEC);
}

/**
 * Get test public key as hex string
 */
export function getTestPublicKeyHex(): string {
    return TEST_PUBKEY_HEX;
}

/**
 * Sign a NOSTR event using the test private key
 */
export function signEvent(eventData: {
    content: string;
    created_at?: number;
    kind?: number;
    tags?: string[][];
}): SignedEvent {
    const secretKey = getTestSecretKey();

    const eventTemplate: EventTemplate = {
        kind: eventData.kind || 1,
        created_at: eventData.created_at || Math.floor(Date.now() / 1000),
        tags: eventData.tags || [],
        content: eventData.content,
    };

    // finalizeEvent adds id, pubkey, and sig
    const signedEvent = finalizeEvent(eventTemplate, secretKey);

    return signedEvent as unknown as SignedEvent;
}

/**
 * Create and sign a test kind 1 note (regular post)
 */
export function createTestNote(
    content: string,
    tags: string[][] = [],
): SignedEvent {
    return signEvent({
        content,
        kind: 1,
        tags,
    });
}

/**
 * Create and sign a test kind 0 profile event
 */
export function createTestProfileEvent(profile: {
    name?: string;
    display_name?: string;
    about?: string;
    picture?: string;
}): SignedEvent {
    return signEvent({
        content: JSON.stringify(profile),
        kind: 0,
        tags: [],
    });
}

// Use this to update a Nostr user's subscription status for testing
// Simply call this with:
// npx tsx ./tests/e2e/support/update-subscription-status.ts npub1xxx STATUS
//
// Where STATUS is one of: FREE, ACTIVE, EXPIRED, CANCELED, PAST_DUE

import { PrismaClient, SubscriptionStatus } from "@prisma/client";
import { installGlobals } from "@remix-run/node";
installGlobals();

const prisma = new PrismaClient();

type TestSubscriptionStatus = "FREE" | "ACTIVE" | "EXPIRED" | "CANCELED" | "PAST_DUE";

async function updateSubscriptionStatus(npub: string, targetStatus: TestSubscriptionStatus) {
    if (!npub) {
        throw new Error("npub required");
    }

    if (!targetStatus) {
        throw new Error("status required (FREE, ACTIVE, EXPIRED, CANCELED, PAST_DUE)");
    }

    // Find the user
    const user = await prisma.user.findUnique({
        where: { npub },
        include: { Subscription: true },
    });

    if (!user) {
        throw new Error(`User not found: ${npub}`);
    }

    if (targetStatus === "FREE") {
        // Delete any existing subscription to simulate free user
        if (user.Subscription) {
            await prisma.subscription.delete({
                where: { userId: user.id },
            });
        }
        // eslint-disable-next-line no-console
        console.log(`<status>FREE</status>`);
    } else if (targetStatus === "ACTIVE") {
        const now = new Date();
        const thirtyDaysFromNow = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000);

        if (user.Subscription) {
            // Update existing subscription to active
            await prisma.subscription.update({
                where: { userId: user.id },
                data: {
                    status: SubscriptionStatus.ACTIVE,
                    currentPeriodStart: now,
                    currentPeriodEnd: thirtyDaysFromNow,
                    cancelAtPeriodEnd: false,
                },
            });
        } else {
            // Create a new active subscription
            let plan = await prisma.plan.findFirst({
                where: { id: "premium" },
            });

            if (!plan) {
                plan = await prisma.plan.findFirst({
                    where: { isActive: true },
                });
            }

            if (!plan) {
                throw new Error("No plan found in database");
            }

            const subscriptionId = `test_sub_${Date.now()}_${user.id.slice(-8)}`;
            await prisma.subscription.create({
                data: {
                    id: subscriptionId,
                    userId: user.id,
                    planId: plan.id,
                    status: SubscriptionStatus.ACTIVE,
                    startDate: now,
                    currentPeriodStart: now,
                    currentPeriodEnd: thirtyDaysFromNow,
                },
            });
        }
        // eslint-disable-next-line no-console
        console.log(`<status>ACTIVE</status>`);
    } else if (targetStatus === "EXPIRED") {
        const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);
        const sixtyDaysAgo = new Date(Date.now() - 60 * 24 * 60 * 60 * 1000);

        if (user.Subscription) {
            // Update subscription to expired (INACTIVE status with past end date)
            await prisma.subscription.update({
                where: { userId: user.id },
                data: {
                    status: SubscriptionStatus.INACTIVE,
                    currentPeriodStart: sixtyDaysAgo,
                    currentPeriodEnd: thirtyDaysAgo,
                    endDate: thirtyDaysAgo,
                },
            });
        } else {
            // Create an expired subscription
            let plan = await prisma.plan.findFirst({
                where: { id: "premium" },
            });

            if (!plan) {
                plan = await prisma.plan.findFirst({
                    where: { isActive: true },
                });
            }

            if (!plan) {
                throw new Error("No plan found in database");
            }

            const subscriptionId = `test_sub_${Date.now()}_${user.id.slice(-8)}`;
            await prisma.subscription.create({
                data: {
                    id: subscriptionId,
                    userId: user.id,
                    planId: plan.id,
                    status: SubscriptionStatus.INACTIVE,
                    startDate: sixtyDaysAgo,
                    currentPeriodStart: sixtyDaysAgo,
                    currentPeriodEnd: thirtyDaysAgo,
                    endDate: thirtyDaysAgo,
                },
            });
        }
        // eslint-disable-next-line no-console
        console.log(`<status>EXPIRED</status>`);
    } else if (targetStatus === "CANCELED") {
        const now = new Date();
        const thirtyDaysFromNow = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000);

        if (user.Subscription) {
            // Update subscription to canceled (still active until period end, but won't renew)
            await prisma.subscription.update({
                where: { userId: user.id },
                data: {
                    status: SubscriptionStatus.CANCELED,
                    currentPeriodEnd: thirtyDaysFromNow,
                    cancelAtPeriodEnd: true,
                },
            });
        } else {
            // Create a canceled subscription
            let plan = await prisma.plan.findFirst({
                where: { id: "premium" },
            });

            if (!plan) {
                plan = await prisma.plan.findFirst({
                    where: { isActive: true },
                });
            }

            if (!plan) {
                throw new Error("No plan found in database");
            }

            const subscriptionId = `test_sub_${Date.now()}_${user.id.slice(-8)}`;
            await prisma.subscription.create({
                data: {
                    id: subscriptionId,
                    userId: user.id,
                    planId: plan.id,
                    status: SubscriptionStatus.CANCELED,
                    startDate: now,
                    currentPeriodStart: now,
                    currentPeriodEnd: thirtyDaysFromNow,
                    cancelAtPeriodEnd: true,
                },
            });
        }
        // eslint-disable-next-line no-console
        console.log(`<status>CANCELED</status>`);
    } else if (targetStatus === "PAST_DUE") {
        const now = new Date();
        const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

        if (user.Subscription) {
            // Update subscription to past due
            await prisma.subscription.update({
                where: { userId: user.id },
                data: {
                    status: SubscriptionStatus.PAST_DUE,
                    currentPeriodEnd: sevenDaysAgo,
                },
            });
        } else {
            // Create a past due subscription
            let plan = await prisma.plan.findFirst({
                where: { id: "premium" },
            });

            if (!plan) {
                plan = await prisma.plan.findFirst({
                    where: { isActive: true },
                });
            }

            if (!plan) {
                throw new Error("No plan found in database");
            }

            const subscriptionId = `test_sub_${Date.now()}_${user.id.slice(-8)}`;
            await prisma.subscription.create({
                data: {
                    id: subscriptionId,
                    userId: user.id,
                    planId: plan.id,
                    status: SubscriptionStatus.PAST_DUE,
                    startDate: sevenDaysAgo,
                    currentPeriodStart: sevenDaysAgo,
                    currentPeriodEnd: sevenDaysAgo,
                },
            });
        }
        // eslint-disable-next-line no-console
        console.log(`<status>PAST_DUE</status>`);
    } else {
        throw new Error(`Unknown status: ${targetStatus}`);
    }

    await prisma.$disconnect();
}

updateSubscriptionStatus(process.argv[2], process.argv[3] as TestSubscriptionStatus);

