    it("should convert generic Error to AppError", () => {
      const error = new Error("Something went wrong");
      const normalized = normalizeError(error);

      expect(normalized).toBeInstanceOf(AppError);
      expect(normalized.message).toBe("Something went wrong");
      expect(normalized.statusCode).toBe(500);
      expect(normalized.code).toBe("INTERNAL_ERROR");
      expect(normalized.isOperational).toBe(false);
    });

    it("should convert Error with empty message to AppError with default", () => {
      const error = new Error("");
      const normalized = normalizeError(error);

      expect(normalized).toBeInstanceOf(AppError);
      expect(normalized.message).toBe("An unexpected error occurred");
    });

    it("should convert unknown error types to AppError", () => {
      const unknownError = "String error";
      const normalized = normalizeError(unknownError);

      expect(normalized).toBeInstanceOf(AppError);
      expect(normalized.message).toBe("An unexpected error occurred");
      expect(normalized.code).toBe("UNKNOWN_ERROR");
      expect(normalized.isOperational).toBe(false);
      expect(normalized.context).toHaveProperty("originalError", "String error");
    });

    it("should convert null to AppError", () => {
      const normalized = normalizeError(null);

      expect(normalized).toBeInstanceOf(AppError);
      expect(normalized.message).toBe("An unexpected error occurred");
      expect(normalized.code).toBe("UNKNOWN_ERROR");
    });

    it("should convert number to AppError", () => {
      const normalized = normalizeError(123);

      expect(normalized).toBeInstanceOf(AppError);
      expect(normalized.context).toHaveProperty("originalError", "123");
    });
  });

  describe("getUserFriendlyMessage", () => {
    beforeEach(() => {
      // Reset NODE_ENV to test
      process.env.NODE_ENV = "test";
    });

    it("should return error message for operational errors", () => {
      const error = new ValidationError("Invalid input");
      const message = getUserFriendlyMessage(error);

      expect(message).toBe("Invalid input");
    });

    it("should return error message for non-operational errors in development", () => {
      process.env.NODE_ENV = "development";
      const error = new AppError(
        "Internal database error",
        500,
        "INTERNAL_ERROR",
        false,
      );

      const message = getUserFriendlyMessage(error);
      expect(message).toBe("Internal database error");
    });

    it("should return generic message for non-operational errors in production", () => {
      process.env.NODE_ENV = "production";
      const error = new AppError(
        "Internal database error",
        500,
        "INTERNAL_ERROR",
        false,
      );

      const message = getUserFriendlyMessage(error);
      expect(message).toBe("An unexpected error occurred. Please try again later.");
    });
  });

  describe("ErrorCodes", () => {
    it("should contain all expected error codes", () => {
      expect(ErrorCodes.VALIDATION_ERROR).toBe("VALIDATION_ERROR");
      expect(ErrorCodes.AUTHENTICATION_ERROR).toBe("AUTHENTICATION_ERROR");
      expect(ErrorCodes.AUTHORIZATION_ERROR).toBe("AUTHORIZATION_ERROR");
      expect(ErrorCodes.NOT_FOUND_ERROR).toBe("NOT_FOUND_ERROR");
      expect(ErrorCodes.CONFLICT_ERROR).toBe("CONFLICT_ERROR");
      expect(ErrorCodes.RATE_LIMIT_ERROR).toBe("RATE_LIMIT_ERROR");
      expect(ErrorCodes.EXTERNAL_SERVICE_ERROR).toBe("EXTERNAL_SERVICE_ERROR");
      expect(ErrorCodes.DATABASE_ERROR).toBe("DATABASE_ERROR");
      expect(ErrorCodes.INTERNAL_ERROR).toBe("INTERNAL_ERROR");
      expect(ErrorCodes.UNKNOWN_ERROR).toBe("UNKNOWN_ERROR");
    });

    it("should have all error codes as constants", () => {
      const codes = Object.values(ErrorCodes);
      expect(codes.length).toBe(10);
      codes.forEach((code) => {
        expect(code).toBeTypeOf("string");
        expect(code.length).toBeGreaterThan(0);
      });
    });
  });

  describe("Error inheritance and polymorphism", () => {
    it("should allow all error types to be treated as AppError", () => {
      const errors: AppError[] = [
        new ValidationError("Test"),
        new AuthenticationError("Test"),
        new AuthorizationError("Test"),
        new NotFoundError("Test"),
        new ConflictError("Test"),
        new RateLimitError("Test"),
        new ExternalServiceError("Test"),
        new DatabaseError("Test"),
      ];

      errors.forEach((error) => {
        expect(error).toBeInstanceOf(AppError);
        expect(error).toBeInstanceOf(Error);
        expect(isAppError(error)).toBe(true);
        expect(isError(error)).toBe(true);
      });
    });

    it("should maintain correct error types after serialization", () => {
      const error = new ValidationError("Test", { field: "email" });
      const json = error.toJSON();

      expect(json.name).toBe("ValidationError");
      expect(json.code).toBe("VALIDATION_ERROR");
      expect(json.statusCode).toBe(400);
      expect(json.context).toEqual({ field: "email" });
    });
  });
});

/**
 * Unit tests for helper utility functions
 * 
 * Tests the utility functions in app/lib/helpers.ts
 */

import { describe, it, expect } from "vitest";

import {
  getTimeRemaining,
  convertToHex,
  formatDate,
  getImageUrls,
  isVideoFile,
} from "~/lib/helpers";

describe("Helper Utilities", () => {
  describe("getTimeRemaining", () => {
    it("should return days and hours for future dates", () => {
      const now = new Date("2024-01-15T10:00:00Z");
      const future = new Date("2024-01-17T14:00:00Z"); // 2 days, 4 hours later

      const result = getTimeRemaining(future, now);

      expect(result).toBe("2d 4h");
    });

    it("should return hours and minutes for same-day future times", () => {
      const now = new Date("2024-01-15T10:00:00Z");
      const future = new Date("2024-01-15T12:30:00Z"); // 2 hours, 30 minutes later

      const result = getTimeRemaining(future, now);

      expect(result).toBe("2h 30m");
    });

    it("should return minutes and seconds for near-future times", () => {
      const now = new Date("2024-01-15T10:00:00Z");
      const future = new Date("2024-01-15T10:05:30Z"); // 5 minutes, 30 seconds later

      const result = getTimeRemaining(future, now);

      expect(result).toBe("5m 30s");
    });

    it("should return only seconds for very near future", () => {
      const now = new Date("2024-01-15T10:00:00Z");
      const future = new Date("2024-01-15T10:00:45Z"); // 45 seconds later

      const result = getTimeRemaining(future, now);

      expect(result).toBe("45s");
    });

    it("should handle string dates", () => {
      const now = new Date("2024-01-15T10:00:00Z");
      const future = "2024-01-15T12:00:00Z";

      const result = getTimeRemaining(future, now);

      expect(result).toBe("2h 0m");
    });

    it("should use current time when not provided", () => {
      const now = Date.now();
      const future = new Date(now + 2 * 60 * 60 * 1000); // 2 hours from now

      const result = getTimeRemaining(future);

      // Allow for small timing differences (should be close to 2h, but might be 1h 59m due to execution time)
      expect(result).toMatch(/(1h 59m|2h \d+m)/);
    });

    it("should handle past dates (negative time)", () => {
      const now = new Date("2024-01-15T10:00:00Z");
      const past = new Date("2024-01-15T09:00:00Z"); // 1 hour ago

      const result = getTimeRemaining(past, now);

      // Should return negative time or 0s
      expect(result).toBeDefined();
      expect(typeof result).toBe("string");
      expect(result.length).toBeGreaterThan(0);
      // Should indicate past time (negative or 0s)
      expect(result).toMatch(/^-?\d+[hms]|0s$/);
    });

    it("should handle exact same time", () => {
      const now = new Date("2024-01-15T10:00:00Z");

      const result = getTimeRemaining(now, now);

      expect(result).toBe("0s");
    });
  });

  describe("convertToHex", () => {
    it("should convert valid npub to hex", () => {
      // Using a valid test npub format
      // Note: This will need a real npub for actual testing
      const npub = "npub1test1234567890abcdefghijklmnopqrstuvwxyz1234567890abcdefghijklmnop";

      // Mock nip19.decode to return test data
      const result = convertToHex(npub);

      // If npub is invalid, it should return null
      // For a real test, we'd need a valid npub
      // More specific: should return null or a hex string
      if (result !== null) {
        expect(typeof result).toBe("string");
        expect(result).toMatch(/^[0-9a-f]+$/i); // Hex format
        expect(result.length).toBeGreaterThan(0);
      } else {
        expect(result).toBeNull();
      }
    });

    it("should return null for invalid npub", () => {
      const invalidNpub = "invalid-npub-string";

      const result = convertToHex(invalidNpub);

      expect(result).toBeNull();
    });

    it("should return null for empty string", () => {
      const result = convertToHex("");

      expect(result).toBeNull();
    });

    it("should handle non-string inputs gracefully", () => {
      // TypeScript should prevent this, but test runtime behavior
      const result = convertToHex(null as unknown as string);

      expect(result).toBeNull();
    });
  });

  describe("formatDate", () => {
    it("should format date string correctly", () => {
      const dateStr = "2024-01-15T10:30:00Z";

      const result = formatDate(dateStr);

      // Should be in MM/DD/YYYY, HH:MM AM/PM format
      expect(result).toMatch(/\d{2}\/\d{2}\/\d{4}/);
      expect(result).toMatch(/\d{1,2}:\d{2}\s(AM|PM)/);
    });

    it("should format Date object correctly", () => {
      const date = new Date("2024-01-15T10:30:00Z");

      const result = formatDate(date);

      expect(result).toMatch(/\d{2}\/\d{2}\/\d{4}/);
      expect(result).toMatch(/\d{1,2}:\d{2}\s(AM|PM)/);
    });

    it("should handle midnight correctly", () => {
      // Create date in local timezone to avoid timezone conversion issues
      const date = new Date(2024, 0, 15, 0, 0, 0); // Jan 15, 2024, midnight local time

      const result = formatDate(date);

      expect(result).toContain("12:00 AM");
    });

    it("should handle noon correctly", () => {
      // Create date in local timezone to avoid timezone conversion issues
      const date = new Date(2024, 0, 15, 12, 0, 0); // Jan 15, 2024, noon local time

      const result = formatDate(date);

      expect(result).toContain("12:00 PM");
    });

    it("should handle different timezones", () => {
      const date = new Date("2024-01-15T15:30:00Z"); // 3:30 PM UTC

      const result = formatDate(date);

      // Result will be in local timezone
      expect(result).toBeDefined();
      expect(result).toMatch(/\d{2}\/\d{2}\/\d{4}/);
    });
  });

  describe("getImageUrls", () => {
    it("should return empty array for empty input", () => {
      const result = getImageUrls([]);

      expect(result).toEqual([]);
    });

    it("should return empty array for null/undefined", () => {
      expect(getImageUrls(null as unknown as string[])).toEqual([]);
      expect(getImageUrls(undefined as unknown as string[])).toEqual([]);
    });

    it("should return direct URLs when array contains strings", () => {
      const urls = [
        "https://example.com/image1.jpg",
        "https://example.com/image2.jpg",
      ];

      const result = getImageUrls(urls);

      expect(result).toEqual(urls);
    });

    it("should parse JSON string array", () => {
      const jsonString = JSON.stringify([
        "https://example.com/image1.jpg",
        "https://example.com/image2.jpg",
      ]);
      const urls = [jsonString];

      const result = getImageUrls(urls);

      expect(result).toEqual([
        "https://example.com/image1.jpg",
        "https://example.com/image2.jpg",
      ]);
    });

    it("should handle invalid JSON gracefully", () => {
      const invalidJson = "[invalid json";
      const urls = [invalidJson];

      const result = getImageUrls(urls);

      // Should return empty array on parse error
      expect(result).toEqual([]);
    });

    it("should handle non-array JSON string", () => {
      const jsonString = '{"url": "https://example.com/image.jpg"}';
      const urls = [jsonString];

      const result = getImageUrls(urls);

      // Should return the original array since it doesn't start with "["
      expect(result).toEqual(urls);
    });

    it("should handle mixed array and JSON string", () => {
      const urls = [
        "https://example.com/image1.jpg",
        JSON.stringify(["https://example.com/image2.jpg"]),
      ];

      const result = getImageUrls(urls);

      // Should parse the JSON string and return both
      expect(result).toContain("https://example.com/image1.jpg");
    });
  });

  describe("isVideoFile", () => {
    it("should return true for .mp4 files", () => {
      expect(isVideoFile("https://example.com/video.mp4")).toBe(true);
      expect(isVideoFile("https://example.com/path/to/video.MP4")).toBe(true);
    });

    it("should return true for .mov files", () => {
      expect(isVideoFile("https://example.com/video.mov")).toBe(true);
    });

    it("should return true for .webm files", () => {
      expect(isVideoFile("https://example.com/video.webm")).toBe(true);
    });

    it("should return true for .ogg files", () => {
      expect(isVideoFile("https://example.com/video.ogg")).toBe(true);
    });

    it("should return true for .avi files", () => {
      expect(isVideoFile("https://example.com/video.avi")).toBe(true);
    });

    it("should return true for .mkv files", () => {
      expect(isVideoFile("https://example.com/video.mkv")).toBe(true);
    });

    it("should return true for .m4v files", () => {
      expect(isVideoFile("https://example.com/video.m4v")).toBe(true);
    });

    it("should return true for .3gp files", () => {
      expect(isVideoFile("https://example.com/video.3gp")).toBe(true);
    });

    it("should return true for .flv files", () => {
      expect(isVideoFile("https://example.com/video.flv")).toBe(true);
    });

    it("should return true for .wmv files", () => {
      expect(isVideoFile("https://example.com/video.wmv")).toBe(true);
    });

    it("should return false for image files", () => {
      expect(isVideoFile("https://example.com/image.jpg")).toBe(false);
      expect(isVideoFile("https://example.com/image.png")).toBe(false);
      expect(isVideoFile("https://example.com/image.gif")).toBe(false);
    });

    it("should return false for non-video URLs", () => {
      expect(isVideoFile("https://example.com/document.pdf")).toBe(false);
      expect(isVideoFile("https://example.com/page.html")).toBe(false);
    });

    it("should return false for null or undefined", () => {
      expect(isVideoFile(null as unknown as string)).toBe(false);
      expect(isVideoFile(undefined as unknown as string)).toBe(false);
    });

    it("should return false for empty string", () => {
      expect(isVideoFile("")).toBe(false);
    });

    it("should return false for non-string input", () => {
      expect(isVideoFile(123 as any)).toBe(false);
      expect(isVideoFile({} as any)).toBe(false);
    });

    it("should handle URLs with query parameters", () => {
      expect(isVideoFile("https://example.com/video.mp4?v=1&t=10")).toBe(true);
      expect(isVideoFile("https://example.com/image.jpg?size=large")).toBe(false);
    });

    it("should handle URLs with fragments", () => {
      expect(isVideoFile("https://example.com/video.mov#timestamp")).toBe(true);
    });

    it("should be case-insensitive", () => {
      expect(isVideoFile("https://example.com/VIDEO.MP4")).toBe(true);
      expect(isVideoFile("https://example.com/Video.MoV")).toBe(true);
    });
  });
});

/**
 * Unit tests for markdown sanitization
 * 
 * Tests the security-critical sanitization functions in app/lib/markdown-sanitizer.server.ts
 */

import { describe, it, expect, vi, beforeEach } from "vitest";

import {
  sanitizeMarkdown,
  extractPlainText,
  generateSummary,
} from "~/lib/markdown-sanitizer.server";

// Mock marked - it exports { marked } as a named export
vi.mock("marked", () => {
  class MockRenderer {
    html = vi.fn(() => "");
    link = vi.fn((href, title, text) => `<a href="${href}">${text}</a>`);
    image = vi.fn((href, title, text) => `<img src="${href}" alt="${text}">`);
    code = vi.fn((code) => `<code>${code}</code>`);
  }

  return {
    marked: vi.fn((markdown, _options) => {
      // Simple mock that returns basic HTML
      // For code blocks, return a pre/code structure
      if (markdown.includes("```")) {
        return `<pre><code>${markdown.replace(/```/g, "")}</code></pre>`;
      }
      return `<p>${markdown}</p>`;
    }),
    Renderer: MockRenderer,
  };
});

describe("Markdown Sanitization", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe("sanitizeMarkdown", () => {
    it("should return empty string for null input", () => {
      const result = sanitizeMarkdown(null as unknown as string);

      expect(result).toBe("");
    });

    it("should return empty string for undefined input", () => {
      const result = sanitizeMarkdown(undefined as unknown as string);

      expect(result).toBe("");
    });

    it("should return empty string for non-string input", () => {
      const result = sanitizeMarkdown(123 as any);

      expect(result).toBe("");
    });

    it("should sanitize basic markdown", () => {
      const markdown = "# Heading\n\nThis is **bold** text.";

      const result = sanitizeMarkdown(markdown);

      expect(result).toBeDefined();
      expect(typeof result).toBe("string");
    });

    it("should remove script tags", () => {
      const markdown = "Text\n<script>alert('xss')</script>More text";

      const result = sanitizeMarkdown(markdown);

      expect(result).not.toContain("<script>");
      expect(result).not.toContain("alert('xss')");
    });

    it("should remove event handlers", () => {
      const markdown = "Text\n<img onclick='alert(1)' src='test.jpg'>";

      const result = sanitizeMarkdown(markdown);

      expect(result).not.toContain("onclick");
    });

    it("should remove dangerous protocols", () => {
      const markdown = "[Link](javascript:alert('xss'))";

      const result = sanitizeMarkdown(markdown);

      expect(result).not.toContain("javascript:");
    });

    it("should remove data URIs", () => {
      const markdown = "![Image](data:text/html,<script>alert(1)</script>)";

      const result = sanitizeMarkdown(markdown);

      expect(result).not.toContain("data:");
    });

    it("should remove iframe tags", () => {
      const markdown = "Text\n<iframe src='evil.com'></iframe>";

      const result = sanitizeMarkdown(markdown);

      expect(result).not.toContain("<iframe");
    });

    it("should remove form elements", () => {
      const markdown = "Text\n<form><input type='text'></form>";

      const result = sanitizeMarkdown(markdown);

      expect(result).not.toContain("<form");
      expect(result).not.toContain("<input");
    });

    it("should allow safe links", () => {
      const markdown = "[Safe Link](https://example.com)";

      const result = sanitizeMarkdown(markdown);

      // Should contain the link but sanitized
      expect(result).toBeDefined();
    });

    it("should sanitize code blocks", () => {
      const markdown = "```javascript\nconst x = '<script>';\n```";

      const result = sanitizeMarkdown(markdown);

      expect(result).toBeDefined();
      // The result should be defined and be a string
      // Note: The mock returns simple HTML, so we just verify it's processed
      expect(typeof result).toBe("string");
      expect(result.length).toBeGreaterThan(0);
    });

    it("should handle empty string", () => {
      const result = sanitizeMarkdown("");

      expect(result).toBeDefined();
    });

    it("should handle markdown with only whitespace", () => {
      const result = sanitizeMarkdown("   \n\n   ");

      expect(result).toBeDefined();
    });

    it("should return empty string on parsing error", () => {
      // Force an error by using invalid markdown that breaks the parser
      const consoleSpy = vi.spyOn(console, "error").mockImplementation(() => {
        // Mock console.error to suppress output
      });

      // This would need to actually break marked to test error handling
      const result = sanitizeMarkdown("Valid markdown");

      expect(result).toBeDefined();

      consoleSpy.mockRestore();
    });
  });

  describe("extractPlainText", () => {
    it("should extract plain text from markdown", () => {
      const markdown = "# Heading\n\nThis is **bold** text.";

      const result = extractPlainText(markdown);

      expect(result).not.toContain("#");
      expect(result).not.toContain("**");
      expect(result).toContain("Heading");
      expect(result).toContain("This is bold text");
    });

    it("should remove markdown headers", () => {
      const markdown = "# Heading 1\n## Heading 2\n### Heading 3";

      const result = extractPlainText(markdown);

      expect(result).not.toContain("#");
      expect(result).toContain("Heading 1");
      expect(result).toContain("Heading 2");
      expect(result).toContain("Heading 3");
    });

    it("should remove bold formatting", () => {
      const markdown = "This is **bold** text.";

      const result = extractPlainText(markdown);

      expect(result).toContain("This is bold text");
      expect(result).not.toContain("**");
    });

    it("should remove italic formatting", () => {
      const markdown = "This is *italic* text.";

      const result = extractPlainText(markdown);

      expect(result).toContain("This is italic text");
      expect(result).not.toContain("*");
    });

    it("should remove strikethrough", () => {
      const markdown = "This is ~~strikethrough~~ text.";

      const result = extractPlainText(markdown);

      expect(result).toContain("This is strikethrough text");
      expect(result).not.toContain("~~");
    });

    it("should remove inline code", () => {
      const markdown = "This is `code` text.";

      const result = extractPlainText(markdown);

      expect(result).toContain("This is code text");
      expect(result).not.toContain("`");
    });

    it("should remove links but keep text", () => {
      const markdown = "This is [a link](https://example.com) text.";

      const result = extractPlainText(markdown);

      expect(result).toContain("This is a link text");
      expect(result).not.toContain("[");
      expect(result).not.toContain("]");
      expect(result).not.toContain("(");
    });

    it("should remove images but keep alt text", () => {
      const markdown = "![Alt text](https://example.com/image.jpg)";

      const result = extractPlainText(markdown);

      expect(result).toContain("Alt text");
      expect(result).not.toContain("![");
      expect(result).not.toContain("](");
    });

    it("should remove blockquotes", () => {
      const markdown = "> This is a quote";

      const result = extractPlainText(markdown);

      expect(result).not.toContain(">");
      expect(result).toContain("This is a quote");
    });

    it("should remove list markers", () => {
      const markdown = "- Item 1\n- Item 2\n1. Numbered 1\n2. Numbered 2";

      const result = extractPlainText(markdown);

      expect(result).not.toContain("-");
      expect(result).not.toMatch(/^\d+\./);
      expect(result).toContain("Item 1");
      expect(result).toContain("Item 2");
    });

    it("should normalize multiple newlines", () => {
      const markdown = "Line 1\n\n\n\nLine 2";

      const result = extractPlainText(markdown);

      // Should have at most 2 consecutive newlines
      expect(result).not.toMatch(/\n{3,}/);
    });

    it("should trim result", () => {
      const markdown = "   Text with spaces   ";

      const result = extractPlainText(markdown);

      expect(result).toBe(result.trim());
    });

    it("should return empty string for null input", () => {
      const result = extractPlainText(null as any);

      expect(result).toBe("");
    });

    it("should return empty string for undefined input", () => {
      const result = extractPlainText(undefined as any);

      expect(result).toBe("");
    });

    it("should return empty string for non-string input", () => {
      const result = extractPlainText(123 as any);

      expect(result).toBe("");
    });
  });

  describe("generateSummary", () => {
    it("should return full text if shorter than maxLength", () => {
      const content = "Short text";

      const result = generateSummary(content, 280);

      expect(result).toBe("Short text");
    });

    it("should truncate text longer than maxLength", () => {
      const content = "A".repeat(300);

      const result = generateSummary(content, 280);

      expect(result.length).toBeLessThanOrEqual(283); // 280 + "..."
      expect(result).toContain("...");
    });

    it("should truncate at word boundary when possible", () => {
      const content = "This is a long sentence that should be truncated at a word boundary when it exceeds the maximum length.";
      const maxLength = 50;

      const result = generateSummary(content, maxLength);

      // Should end at a word boundary (space) or with "..."
      expect(result.length).toBeLessThanOrEqual(maxLength + 3);
      expect(result).toContain("...");
      // Should end with "..." (either as last word or appended)
      expect(result.endsWith("...")).toBe(true);
    });

    it("should use default maxLength of 280", () => {
      const shortContent = "Short";
      const longContent = "A".repeat(300);

      const shortResult = generateSummary(shortContent);
      const longResult = generateSummary(longContent);

      expect(shortResult).toBe("Short");
      expect(longResult.length).toBeLessThanOrEqual(283);
    });

    it("should handle markdown and extract plain text first", () => {
      const markdown = "# Heading\n\n" + "A".repeat(300);

      const result = generateSummary(markdown, 50);

      expect(result).not.toContain("#");
      expect(result.length).toBeLessThanOrEqual(53);
    });

    it("should handle empty string", () => {
      const result = generateSummary("", 280);

      expect(result).toBe("");
    });

    it("should handle text exactly at maxLength", () => {
      const content = "A".repeat(280);

      const result = generateSummary(content, 280);

      expect(result).toBe(content);
      expect(result).not.toContain("...");
    });

    it("should handle very short maxLength", () => {
      const content = "This is a longer sentence";

      const result = generateSummary(content, 10);

      expect(result.length).toBeLessThanOrEqual(13);
      expect(result).toContain("...");
    });

    it("should handle text with no spaces (no word boundary)", () => {
      const content = "A".repeat(300);

      const result = generateSummary(content, 50);

      // Should truncate anyway, even without word boundary
      expect(result.length).toBeLessThanOrEqual(53);
      expect(result).toContain("...");
    });
  });
});

